def _workspace_root_for_map(map_path: str | Path) -> Path:
    resolved = Path(map_path).expanduser().resolve()
    for candidate in (resolved.parent, *resolved.parents):
        if (
            (candidate / "00.GOVERNANCE").is_dir()
            and (candidate / "10.PRODUCT").is_dir()
        ):
            return candidate
    raise InvalidCell("ArchHub workspace root is unavailable")


class DesktopAuthenticationSession:
    """Renewable process trust bound to a visible graph session root.

    The graph describes the session and its scope. The credential itself stays
    in the trusted process and cannot be serialized into, or forged by, cells.
    """

    __slots__ = (
        "root_id", "broker", "subject_root", "principal_roots",
        "tenant_root", "assurance_root", "lifetime_seconds", "_context",
        "_lock",
    )

    def __init__(
        self,
        root_id: str,
        broker: AuthenticationBroker,
        subject_root: str,
        principal_roots: tuple[str, ...],
        tenant_root: str,
        assurance_root: str,
        *,
        lifetime_seconds: float = 3600.0,
    ) -> None:
        self.root_id = root_id
        self.broker = broker
        self.subject_root = subject_root
        self.principal_roots = principal_roots
        self.tenant_root = tenant_root
        self.assurance_root = assurance_root
        self.lifetime_seconds = lifetime_seconds
        self._context = None
        self._lock = threading.RLock()

    def context(self):
        """Return a live context, renewing only from this trusted session."""
        with self._lock:
            if self._context is not None:
                try:
                    self.broker.resolve(self._context)
                    return self._context
                except AuthorizationDenied:
                    self._context = None
            self._context = self.broker.mint_authenticated_context(
                self.subject_root,
                # Principal power is resolved from live signed relationships
                # for every request.  The session relation may describe its
                # intended principals, but it must never cache or bypass them.
                principal_roots=(),
                tenant_root=self.tenant_root,
                assurance_root=self.assurance_root,
                lifetime_seconds=self.lifetime_seconds,
            )
            return self._context


