def _application_cognition_definitions() -> AgentCognitionDefinitions:
    prefix = _AGENT_COGNITION_LIBRARY_V3_PREFIX + ":definition:"
    return AgentCognitionDefinitions(
        prefix + "model-descriptor",
        prefix + "model-binding",
        prefix + "cognition-request",
        prefix + "proposal",
        _AGENT_COGNITION_LIBRARY_V3_PREFIX + ":status-ledger:root",
    )


def _ensure_application_cognition_catalogue(
    store: CellStore,
    assembly: AssemblyProtocol,
    base_library: StandardLibraryBuild,
) -> tuple[
    StandardLibraryBuild,
    AgentCognitionProtocol,
    AgentCognitionDefinitions,
]:
    """Append or verify revocable graph cognition and the exact v5 catalogue."""
    snapshot = store.snapshot()
    protocol_root = _AGENT_COGNITION_PROTOCOL_PREFIX + ":root"
    cognition = (
        open_agent_cognition_protocol(
            snapshot, prefix=_AGENT_COGNITION_PROTOCOL_PREFIX
        )
        if protocol_root in snapshot.cells
        else bootstrap_agent_cognition_protocol(
            store, prefix=_AGENT_COGNITION_PROTOCOL_PREFIX
        )
    )
    definitions = _application_cognition_definitions()
    present = tuple(root for root in definitions.roots if root in store.snapshot().cells)
    if present and len(present) != len(definitions.roots):
        raise InvalidCell("application cognition definitions are partial")
    if not present:
        built = build_agent_cognition_definitions(
            store,
            assembly,
            cognition,
            prefix=_AGENT_COGNITION_LIBRARY_V3_PREFIX,
        )
        if built != definitions:
            raise InvalidCell("application cognition definition identities drifted")
    snapshot = store.snapshot()
    if _STANDARD_CATALOG_V5 not in snapshot.cells:
        build_catalog(
            store,
            assembly,
            (*base_library.definition_roots, *definitions.roots),
            catalog_id=_STANDARD_CATALOG_V5,
            version="5.0.0",
        )
        snapshot = store.snapshot()
    governed_work = build_governed_domain_definition(
        store,
        assembly,
        base_library.lifecycle_protocol,
        base_library.state_machine_protocol,
        "governed-work",
        prefix="app:standard-library:governed-domains",
    )
    governed = dict(base_library.governed_domains.definitions)
    governed["governed-work"] = governed_work
    active_definition_roots = (
        *base_library.definition_roots[:3],
        *(
            governed[spec["key"]].definition_root
            for spec in DOMAIN_SPECS
        ),
        *definitions.roots,
    )
    snapshot = store.snapshot()
    if _STANDARD_CATALOG_V6 not in snapshot.cells:
        build_catalog(
            store,
            assembly,
            active_definition_roots,
            catalog_id=_STANDARD_CATALOG_V6,
            version="6.0.0",
        )
        snapshot = store.snapshot()
    library = project_standard_library(
        snapshot,
        assembly,
        prefix="app:standard-library",
        catalog_root=_STANDARD_CATALOG_V6,
        required_domain_keys=tuple(spec["key"] for spec in DOMAIN_SPECS),
        additional_definition_roots=definitions.roots,
    )
    return library, cognition, definitions


def _node_library_section_specs(
    standard_library: StandardLibraryBuild,
    cognition_definitions: AgentCognitionDefinitions,
) -> tuple[tuple[str, str, tuple[str, ...]], ...]:
    definition_groups = (
        standard_library.definition_roots[:3],
        standard_library.governed_domains.definition_roots,
        cognition_definitions.roots,
    )
    ordered = tuple(
        definition
        for definitions in definition_groups
        for definition in definitions
    )
    if ordered != standard_library.definition_roots:
        raise InvalidCell(
            "node library sections do not exactly cover catalogue order"
        )
    return tuple(
        (root_id, label, tuple(definitions))
        for (root_id, label), definitions in zip(
            _NODE_LIBRARY_SECTION_IDENTITIES,
            definition_groups,
            strict=True,
        )
    )


def _node_library_entry_root(definition_root: str) -> str:
    token = hashlib.sha256(definition_root.encode("utf-8")).hexdigest()[:24]
    return "app:node-library:entry:%s" % token


def _node_library_entry_facts(
    snapshot: Snapshot,
    assembly: AssemblyProtocol,
    *,
    section_root: str,
    section_label_root: str,
    definition_root: str,
    order: int,
    icon_root: str,
) -> dict[str, object]:
    definition = read_definition(snapshot, assembly, definition_root)
    documentation_roots: list[str] = []
    search_roots: list[str] = [definition.name_root, section_label_root]
    for interface_root in definition.interface_roots:
        members = read_relation(snapshot, interface_root, budget=256)
        for role_name in (
            "name", "interface-documentation", "interface-contract",
            "interface-presentation",
        ):
            roots = tuple(
                member.participant_id for member in members
                if member.role_id == assembly.role(role_name)
            )
            search_roots.extend(roots)
            if role_name == "interface-documentation":
                documentation_roots.extend(roots)
    documentation_roots = list(dict.fromkeys(documentation_roots))
    search_roots = list(dict.fromkeys(search_roots))
    if not documentation_roots:
        raise InvalidCell("catalogue definition has no graph documentation")
    if not set(documentation_roots).issubset(search_roots):
        raise InvalidCell("catalogue documentation is absent from graph search")
    return {
        "root": _node_library_entry_root(definition_root),
        "definition": definition_root,
        "category": section_root,
        "documentation": tuple(documentation_roots),
        "search": tuple(search_roots),
        "icon": icon_root,
        "order": order,
        "order_root": _node_library_entry_root(definition_root) + ":order",
    }


def _compose_node_library_entry(
    batch: CellBatch,
    facts: Mapping[str, object],
) -> str:
    order_root = str(facts["order_root"])
    batch.add(Cell(
        order_root,
        NULL_CELL_ID,
        NULL_CELL_ID,
        str(facts["order"]).encode("ascii"),
    ))
    root_id = str(facts["root"])
    batch.relation((
        (_NODE_LIBRARY_ENTRY_ROLE_ROOTS["contract"],
         _NODE_LIBRARY_ENTRY_CONTRACT_ROOT),
        (_NODE_LIBRARY_ENTRY_ROLE_ROOTS["definition"],
         str(facts["definition"])),
        (_NODE_LIBRARY_ENTRY_ROLE_ROOTS["category"],
         str(facts["category"])),
        *((_NODE_LIBRARY_ENTRY_ROLE_ROOTS["search-term"], root)
          for root in facts["search"]),
        *((_NODE_LIBRARY_ENTRY_ROLE_ROOTS["documentation"], root)
          for root in facts["documentation"]),
        (_NODE_LIBRARY_ENTRY_ROLE_ROOTS["icon"], str(facts["icon"])),
        (_NODE_LIBRARY_ENTRY_ROLE_ROOTS["order"], order_root),
        (_NODE_LIBRARY_ENTRY_ROLE_ROOTS["favourite"],
         _NODE_LIBRARY_NOT_FAVOURITE_ROOT),
    ), relation_id=root_id)
    return root_id


def _compose_node_library_entry_support(batch: CellBatch) -> None:
    batch.add(Cell(
        _NODE_LIBRARY_ENTRY_CONTRACT_ROOT,
        NULL_CELL_ID,
        NULL_CELL_ID,
        _NODE_LIBRARY_ENTRY_CONTRACT_ATOM,
    ))
    for name, root_id in _NODE_LIBRARY_ENTRY_ROLE_ROOTS.items():
        batch.add(Cell(
            root_id, NULL_CELL_ID, NULL_CELL_ID, name.encode("utf-8")
        ))
    batch.add(Cell(
        _NODE_LIBRARY_NOT_FAVOURITE_ROOT,
        NULL_CELL_ID,
        NULL_CELL_ID,
        b"false",
    ))


def _compose_node_library_sections(
    batch: CellBatch,
    roles: Mapping[str, str],
    standard_library: StandardLibraryBuild,
    cognition_definitions: AgentCognitionDefinitions,
    snapshot: Snapshot,
    assembly: AssemblyProtocol,
    icon_root: str,
) -> tuple[str, ...]:
    specs = _node_library_section_specs(
        standard_library, cognition_definitions
    )
    batch.add(Cell(
        _NODE_LIBRARY_SECTION_CONTRACT_ROOT,
        NULL_CELL_ID,
        NULL_CELL_ID,
        _NODE_LIBRARY_SECTION_CONTRACT_ATOM,
    ))
    _compose_node_library_entry_support(batch)
    for section_root, label, definitions in specs:
        label_root = section_root + ":label"
        batch.add(Cell(
            label_root, NULL_CELL_ID, NULL_CELL_ID, label.encode("utf-8")
        ))
        entry_roots = tuple(
            _compose_node_library_entry(
                batch,
                _node_library_entry_facts(
                    snapshot,
                    assembly,
                    section_root=section_root,
                    section_label_root=label_root,
                    definition_root=definition_root,
                    order=order,
                    icon_root=icon_root,
                ),
            )
            for order, definition_root in enumerate(definitions)
        )
        batch.relation(
            (
                (roles["contract"], _NODE_LIBRARY_SECTION_CONTRACT_ROOT),
                (roles["label"], label_root),
                *((roles["member"], definition) for definition in definitions),
                *((roles["authority"], entry) for entry in entry_roots),
            ),
            relation_id=section_root,
        )
    return tuple(section[0] for section in specs)


def _validate_node_library_sections(
    snapshot: Snapshot,
    roles: Mapping[str, str],
    standard_library: StandardLibraryBuild,
    *,
    library_root: str,
) -> tuple[dict[str, object], ...]:
    library_members = read_relation(
        snapshot, library_root, budget=100_000
    )
    section_roots = tuple(
        member.participant_id for member in library_members
        if member.role_id == roles["relation"]
    )
    if not section_roots or len(section_roots) != len(set(section_roots)):
        raise InvalidCell("node library has no unique section relations")
    projected = []
    seen_definitions: list[str] = []
    released_definitions = set(standard_library.definition_roots)
    for section_root in section_roots:
        members = read_relation(snapshot, section_root, budget=256)
        contracts = tuple(
            member.participant_id for member in members
            if member.role_id == roles["contract"]
        )
        labels = tuple(
            member.participant_id for member in members
            if member.role_id == roles["label"]
        )
        definitions = tuple(
            member.participant_id for member in members
            if member.role_id == roles["member"]
        )
        entries = tuple(
            member.participant_id for member in members
            if member.role_id == roles["authority"]
        )
        if (
            contracts != (_NODE_LIBRARY_SECTION_CONTRACT_ROOT,)
            or len(labels) != 1
            or not definitions
            or any(definition not in released_definitions for definition in definitions)
            or len(entries) != len(definitions)
            or any(member.role_id not in {
                roles["contract"], roles["label"], roles["member"],
                roles["authority"],
            } for member in members)
        ):
            raise InvalidCell("node library section graph drifted")
        label = _text(snapshot, labels[0])
        if not label.strip() or len(label) > 80:
            raise InvalidCell("node library section label is invalid")
        seen_definitions.extend(definitions)
        entry_projections = []
        for order, (definition_root, entry_root) in enumerate(
            zip(definitions, entries, strict=True)
        ):
            entry_members = read_relation(snapshot, entry_root, budget=256)
            by_role: dict[str, list[str]] = {}
            for member in entry_members:
                by_role.setdefault(member.role_id, []).append(
                    member.participant_id
                )
            allowed_entry_roles = set(_NODE_LIBRARY_ENTRY_ROLE_ROOTS.values())
            if any(member.role_id not in allowed_entry_roles for member in entry_members):
                raise InvalidCell("node library entry metadata has an unknown role")

            def exactly_one(role_name: str) -> str:
                values = by_role.get(
                    _NODE_LIBRARY_ENTRY_ROLE_ROOTS[role_name], []
                )
                if len(values) != 1:
                    raise InvalidCell(
                        "node library entry metadata requires one %s" % role_name
                    )
                return values[0]

            contract_root = exactly_one("contract")
            entry_definition = exactly_one("definition")
            category_root = exactly_one("category")
            icon_root = exactly_one("icon")
            order_root = exactly_one("order")
            favourite_root = exactly_one("favourite")
            documentation_roots = tuple(by_role.get(
                _NODE_LIBRARY_ENTRY_ROLE_ROOTS["documentation"], []
            ))
            search_roots = tuple(by_role.get(
                _NODE_LIBRARY_ENTRY_ROLE_ROOTS["search-term"], []
            ))
            if (
                contract_root != _NODE_LIBRARY_ENTRY_CONTRACT_ROOT
                or entry_definition != definition_root
                or category_root != section_root
                or _text(snapshot, order_root) != str(order)
                or _text(snapshot, favourite_root) not in {"true", "false"}
                or not documentation_roots
                or not search_roots
                or not set(documentation_roots).issubset(search_roots)
                or any(root not in snapshot.cells for root in search_roots)
                or icon_root not in snapshot.cells
            ):
                raise InvalidCell("node library entry metadata graph drifted")
            entry_projections.append({
                "root": entry_root,
                "definition": entry_definition,
                "category": category_root,
                "documentation": list(documentation_roots),
                "search_roots": list(search_roots),
                "icon_root": icon_root,
                "order": order,
                "favourite": _text(snapshot, favourite_root) == "true",
            })
        projected.append({
            "id": section_root,
            "label": label,
            "definitions": list(definitions),
            "entries": entry_projections,
        })
    if tuple(seen_definitions) != standard_library.definition_roots:
        raise InvalidCell(
            "node library sections do not exactly cover catalogue order"
        )
    return tuple(projected)


def _project_node_library_catalogue_metadata(
    snapshot: Snapshot,
    assembly: AssemblyProtocol,
    sections: Iterable[Mapping[str, object]],
) -> Mapping[str, Mapping[str, object]]:
    projected: dict[str, Mapping[str, object]] = {}
    for section in sections:
        section_root = str(section["id"])
        section_label = str(section["label"])
        for entry in section["entries"]:
            definition_root = str(entry["definition"])
            if definition_root in projected:
                raise InvalidCell("catalogue definition has duplicate metadata")
            definition = read_definition(
                snapshot, assembly, definition_root
            )
            interfaces = []
            for interface_root in definition.interface_roots:
                members = read_relation(
                    snapshot, interface_root, budget=256
                )
                name_root = _one_for_role(
                    members, assembly.role("name")
                )
                contract_root = _one_for_role(
                    members, assembly.role("interface-contract")
                )
                presentation_root = _one_for_role(
                    members, assembly.role("interface-presentation")
                )
                documentation_root = _one_for_role(
                    members, assembly.role("interface-documentation")
                )
                interfaces.append({
                    "root": interface_root,
                    "name": _text(snapshot, name_root) if name_root else "Interface",
                    "name_root": name_root,
                    "contract": (
                        _text(snapshot, contract_root)
                        if contract_root else ""
                    ),
                    "contract_root": contract_root,
                    "presentation": (
                        _text(snapshot, presentation_root)
                        if presentation_root else ""
                    ),
                    "presentation_root": presentation_root,
                    "documentation": (
                        _text(snapshot, documentation_root)
                        if documentation_root else ""
                    ),
                    "documentation_root": documentation_root,
                })
            documentation = list(dict.fromkeys(
                _text(snapshot, root)
                for root in entry["documentation"]
                if _text(snapshot, root).strip()
            ))
            search_values = list(dict.fromkeys(
                _text(snapshot, root).strip()
                for root in entry["search_roots"]
                if _text(snapshot, root).strip()
            ))
            projected[definition_root] = MappingProxyType({
                "metadata_root": str(entry["root"]),
                "category_root": section_root,
                "category": section_label,
                "documentation": documentation,
                "description": documentation[0],
                "search_roots": list(entry["search_roots"]),
                "search_text": " ".join(search_values).casefold(),
                "icon_root": str(entry["icon_root"]),
                "order": int(entry["order"]),
                "favourite": bool(entry["favourite"]),
                "interface_details": interfaces,
            })
    return MappingProxyType(projected)


def _ensure_node_library_sections(
    store: CellStore,
    assembly: AssemblyProtocol,
    roles: Mapping[str, str],
    standard_library: StandardLibraryBuild,
    cognition_definitions: AgentCognitionDefinitions,
    *,
    library_root: str,
) -> tuple[dict[str, object], ...]:
    specs = _node_library_section_specs(
        standard_library, cognition_definitions
    )
    required_roots = {
        _NODE_LIBRARY_SECTION_CONTRACT_ROOT,
        *(section_root for section_root, _label, _members in specs),
        *(section_root + ":label" for section_root, _label, _members in specs),
    }
    snapshot = store.snapshot()
    present = required_roots.intersection(snapshot.cells)
    if present and present != required_roots:
        raise InvalidCell("node library section migration is incomplete")
    icon_root = ensure_archhub_icon_catalog(store).icon_roots["plus"]
    snapshot = store.snapshot()
    if not present:
        batch = CellBatch(store)
        _compose_node_library_sections(
            batch,
            roles,
            standard_library,
            cognition_definitions,
            snapshot,
            assembly,
            icon_root,
        )
        batch.commit()
        snapshot = store.snapshot()
    else:
        current_contract = snapshot.cells[_NODE_LIBRARY_SECTION_CONTRACT_ROOT]
        if current_contract.atom != _NODE_LIBRARY_SECTION_CONTRACT_ATOM:
            store.commit(snapshot.revision, replace=(Cell(
                current_contract.id,
                current_contract.link0,
                current_contract.link1,
                _NODE_LIBRARY_SECTION_CONTRACT_ATOM,
            ),))
            snapshot = store.snapshot()
        support_roots = {
            _NODE_LIBRARY_ENTRY_CONTRACT_ROOT,
            _NODE_LIBRARY_NOT_FAVOURITE_ROOT,
            *_NODE_LIBRARY_ENTRY_ROLE_ROOTS.values(),
        }
        support_present = support_roots.intersection(snapshot.cells)
        if support_present and support_present != support_roots:
            raise InvalidCell("node library entry metadata migration is incomplete")
        batch = CellBatch(store)
        pending = False
        if not support_present:
            _compose_node_library_entry_support(batch)
            pending = True
        section_entries: dict[str, tuple[str, ...]] = {}
        for section_root, _label, definitions in specs:
            label_root = section_root + ":label"
            entry_roots = []
            for order, definition_root in enumerate(definitions):
                facts = _node_library_entry_facts(
                    snapshot,
                    assembly,
                    section_root=section_root,
                    section_label_root=label_root,
                    definition_root=definition_root,
                    order=order,
                    icon_root=icon_root,
                )
                entry_root = str(facts["root"])
                entry_roots.append(entry_root)
                if entry_root not in snapshot.cells:
                    _compose_node_library_entry(batch, facts)
                    pending = True
            section_entries[section_root] = tuple(entry_roots)
        if pending:
            batch.commit()
            snapshot = store.snapshot()
        for section_root, entry_roots in section_entries.items():
            members = read_relation(snapshot, section_root, budget=100_000)
            linked_entries = tuple(
                member.participant_id for member in members
                if member.role_id == roles["authority"]
            )
            missing_entries = tuple(
                root for root in entry_roots if root not in linked_entries
            )
            if missing_entries:
                patch = prepare_append_relation_members(
                    snapshot,
                    section_root,
                    ((roles["authority"], root) for root in missing_entries),
                    budget=100_000,
                )
                store.commit(
                    snapshot.revision,
                    create=patch.create,
                    replace=patch.replace,
                )
                snapshot = store.snapshot()
    members = read_relation(snapshot, library_root, budget=100_000)
    linked_sections = tuple(
        member.participant_id for member in members
        if member.role_id == roles["relation"]
    )
    expected_sections = tuple(section[0] for section in specs)
    missing_sections = tuple(
        root for root in expected_sections if root not in linked_sections
    )
    if missing_sections:
        patch = prepare_append_relation_members(
            snapshot,
            library_root,
            ((roles["relation"], root) for root in missing_sections),
            budget=100_000,
        )
        store.commit(
            snapshot.revision,
            create=patch.create,
            replace=patch.replace,
        )
        snapshot = store.snapshot()
        linked_sections = tuple(
            member.participant_id
            for member in read_relation(snapshot, library_root, budget=100_000)
            if member.role_id == roles["relation"]
        )
    return _validate_node_library_sections(
        store.snapshot(),
        roles,
        standard_library,
        library_root=library_root,
    )


def _ensure_baboom_model_execution_authority(
    store: CellStore,
    adapter_protocol: AdapterProtocol,
    roles: Mapping[str, str],
    models_domain_root: str,
    application_root: str,
) -> tuple[BaboomModelExecutionProtocol, str, Mapping[str, str]]:
    """Release bounded model-provider adapters and BABOOM delegation roots.

    The existing v3 adapter catalog remains the composer/device-custody
    authority. v4 is a separate immutable execution catalog so a provider
    release cannot silently expand older custody or composer permissions.
    """
    protocol = bootstrap_baboom_model_execution_protocol(
        store, prefix=_BABOOM_MODEL_EXECUTION_PROTOCOL_PREFIX
    )
    adapter_roots = [_DEVICE_CUSTODY_ADAPTER_V2]
    provider_roots: dict[str, str] = {}
    for provider, adapter_root, name, location, datatypes in (
        _BABOOM_MODEL_ADAPTER_SPECS
    ):
        snapshot = store.snapshot()
        if adapter_root not in snapshot.cells:
            adapter = build_adapter_definition(
                store,
                adapter_protocol,
                adapter_id=adapter_root,
                name=name,
                actions=("analyze-readonly",),
                locations=(location,),
                datatypes=datatypes,
                evidence=(
                    "BABOOM explicit model delegation; bounded input; "
                    "read-only host effect; redacted receipt"
                ),
            )
            release_adapter_definition(store, adapter_protocol, adapter.root_id)
        projection = verify_released_adapter(
            store.snapshot(), adapter_protocol, adapter_root
        )
        action_roots = tuple(
            root for root in projection.action_roots
            if _text(store.snapshot(), root) == "analyze-readonly"
        )
        location_roots = tuple(
            root for root in projection.location_roots
            if _text(store.snapshot(), root) == location
        )
        datatype_roots = tuple(
            root for root in projection.datatype_roots
            if _text(store.snapshot(), root) in datatypes
        )
        if (
            len(action_roots) != 1
            or len(location_roots) != 1
            or len(datatype_roots) != len(datatypes)
        ):
            raise InvalidCell("BABOOM model adapter release binding drifted")
        provider_root = _BABOOM_MODEL_PROVIDER_PREFIX + provider
        register_model_provider(
            store,
            protocol,
            adapter_protocol,
            provider_id=provider_root,
            adapter_root=adapter_root,
            action_root=action_roots[0],
            location_root=location_roots[0],
            datatype_roots=datatype_roots,
        )
        provider_roots[provider] = provider_root
        adapter_roots.append(adapter_root)
    snapshot = store.snapshot()
    if _ADAPTER_CATALOG_V4 not in snapshot.cells:
        build_adapter_catalog(
            store,
            adapter_protocol,
            tuple(adapter_roots),
            catalog_id=_ADAPTER_CATALOG_V4,
            version="4.0.0",
        )
    catalog = verify_adapter_catalog(
        store.snapshot(), adapter_protocol, _ADAPTER_CATALOG_V4
    )
    if catalog.adapter_roots != tuple(adapter_roots):
        raise InvalidCell("BABOOM model-execution adapter catalog drifted")
    snapshot = store.snapshot()
    requested = (
        (models_domain_root, (
            (roles["member"], protocol.root_id),
            (roles["member"], _ADAPTER_CATALOG_V4),
            *((roles["member"], root) for root in provider_roots.values()),
        )),
        (application_root, (
            (roles["member"], protocol.root_id),
            (roles["member"], _ADAPTER_CATALOG_V4),
            *((roles["member"], root) for root in provider_roots.values()),
        )),
    )
    patches = []
    for relation_root, members in requested:
        requested_members = tuple(members)
        if len(requested_members) != len(set(requested_members)):
            raise InvalidCell(
                "BABOOM execution authority requests duplicate memberships"
            )
        existing_members = tuple(
            (member.role_id, member.participant_id)
            for member in read_relation(
                snapshot, relation_root, budget=100_000
            )
        )
        for member in requested_members:
            if existing_members.count(member) > 1:
                raise InvalidCell(
                    "BABOOM execution authority membership is duplicated"
                )
        missing_members = tuple(
            member for member in requested_members
            if member not in existing_members
        )
        if missing_members:
            patches.append(prepare_append_relation_members(
                snapshot, relation_root, missing_members, budget=100_000
            ))
    replacements = {}
    for patch in patches:
        for cell in patch.replace:
            if cell.id in replacements and replacements[cell.id] != cell:
                raise InvalidCell("BABOOM execution authority patches conflict")
            replacements[cell.id] = cell
    if patches:
        store.commit(
            snapshot.revision,
            create=tuple(cell for patch in patches for cell in patch.create),
            replace=tuple(replacements.values()),
        )
    for provider, root in provider_roots.items():
        projection = read_model_provider(
            store.snapshot(), protocol, adapter_protocol, root
        )
        if projection.root_id != root:
            raise InvalidCell("BABOOM model provider projection drifted")
    return protocol, _ADAPTER_CATALOG_V4, MappingProxyType(provider_roots)


def _ensure_baboom_cognition_planner_authority(
    store: CellStore,
    adapter_protocol: AdapterProtocol,
    roles: Mapping[str, str],
    models_domain_root: str,
    application_root: str,
) -> str:
    """Publish the empty, append-only allowlist for proposal-only planners.

    This catalogue is intentionally separate from model execution. A planner
    adapter appears only after a founder-declared provider/model identity is
    sealed into a Cognition Request, and it can never grant an execution
    effect by itself.
    """
    snapshot = store.snapshot()
    if _ADAPTER_CATALOG_V6 not in snapshot.cells:
        build_adapter_catalog(
            store,
            adapter_protocol,
            (),
            catalog_id=_ADAPTER_CATALOG_V6,
            version="6.0.0",
        )
    catalog = verify_adapter_catalog(
        store.snapshot(), adapter_protocol, _ADAPTER_CATALOG_V6
    )
    snapshot = store.snapshot()
    patches = []
    for relation_root in (models_domain_root, application_root):
        members = tuple(
            member
            for member in read_relation(snapshot, relation_root, budget=100_000)
            if member.role_id == roles["member"]
            and member.participant_id == _ADAPTER_CATALOG_V6
        )
        if len(members) > 1:
            raise InvalidCell("BABOOM cognition planner catalog membership is duplicated")
        if not members:
            patches.append(prepare_append_relation_members(
                snapshot,
                relation_root,
                ((roles["member"], _ADAPTER_CATALOG_V6),),
                budget=100_000,
            ))
    if patches:
        replacements = {
            cell.id: cell
            for patch in patches
            for cell in patch.replace
        }
        store.commit(
            snapshot.revision,
            create=tuple(cell for patch in patches for cell in patch.create),
            replace=tuple(replacements.values()),
        )
    return catalog.root_id


def _ensure_baboom_connector_execution_authority(
    store: CellStore,
    adapter_protocol: AdapterProtocol,
    roles: Mapping[str, str],
    connectors_domain_root: str,
    application_root: str,
) -> tuple[BaboomConnectorExecutionProtocol, str, Mapping[str, str]]:
    """Release the bounded connector effects that BABOOM may request.

    The adapter contract remains graph-held. The actual API token and the
    raw meeting/note payload stay in the local connector runtime and are never
    imported into the Universal Cell graph.
    """
    protocol = bootstrap_baboom_connector_execution_protocol(
        store, prefix=_BABOOM_CONNECTOR_EXECUTION_PROTOCOL_PREFIX
    )
    adapter_roots = []
    provider_roots: dict[str, str] = {}
    for provider, adapter_root, name, action, location, datatypes, operation in (
        _BABOOM_CONNECTOR_ADAPTER_SPECS
    ):
        snapshot = store.snapshot()
        if adapter_root not in snapshot.cells:
            adapter = build_adapter_definition(
                store,
                adapter_protocol,
                adapter_id=adapter_root,
                name=name,
                actions=(action,),
                locations=(location,),
                datatypes=datatypes,
                evidence=(
                    "BABOOM explicit connector delegation; bounded input; "
                    "credential stays in local connector runtime; redacted receipt"
                ),
            )
            release_adapter_definition(store, adapter_protocol, adapter.root_id)
        projection = verify_released_adapter(
            store.snapshot(), adapter_protocol, adapter_root
        )
        action_roots = tuple(
            root for root in projection.action_roots
            if _text(store.snapshot(), root) == action
        )
        location_roots = tuple(
            root for root in projection.location_roots
            if _text(store.snapshot(), root) == location
        )
        datatype_roots = tuple(
            root for root in projection.datatype_roots
            if _text(store.snapshot(), root) in datatypes
        )
        if (
            len(action_roots) != 1
            or len(location_roots) != 1
            or len(datatype_roots) != len(datatypes)
        ):
            raise InvalidCell("BABOOM connector adapter release binding drifted")
        provider_root = _BABOOM_CONNECTOR_PROVIDER_PREFIX + provider
        register_connector_provider(
            store,
            protocol,
            adapter_protocol,
            provider_id=provider_root,
            adapter_root=adapter_root,
            action_root=action_roots[0],
            location_root=location_roots[0],
            datatype_roots=datatype_roots,
            operation=operation,
        )
        provider_roots[provider] = provider_root
        adapter_roots.append(adapter_root)
    snapshot = store.snapshot()
    if _ADAPTER_CATALOG_V5 not in snapshot.cells:
        build_adapter_catalog(
            store,
            adapter_protocol,
            tuple(adapter_roots),
            catalog_id=_ADAPTER_CATALOG_V5,
            version="5.0.0",
        )
    catalog = extend_adapter_catalog(
        store, adapter_protocol, _ADAPTER_CATALOG_V5, tuple(adapter_roots)
    )
    if catalog.adapter_roots != tuple(adapter_roots):
        raise InvalidCell("BABOOM connector execution adapter catalog drifted")
    snapshot = store.snapshot()
    requested = (
        (connectors_domain_root, (
            (roles["member"], protocol.root_id),
            (roles["member"], _ADAPTER_CATALOG_V5),
            *((roles["member"], root) for root in provider_roots.values()),
        )),
        (application_root, (
            (roles["member"], protocol.root_id),
            (roles["member"], _ADAPTER_CATALOG_V5),
            *((roles["member"], root) for root in provider_roots.values()),
        )),
    )
    patches = []
    for relation_root, members in requested:
        existing_members = tuple(
            (member.role_id, member.participant_id)
            for member in read_relation(snapshot, relation_root, budget=100_000)
        )
        for member in members:
            if existing_members.count(member) > 1:
                raise InvalidCell(
                    "BABOOM connector execution authority membership is duplicated"
                )
        missing_members = tuple(member for member in members if member not in existing_members)
        if missing_members:
            patches.append(prepare_append_relation_members(
                snapshot, relation_root, missing_members, budget=100_000
            ))
    replacements = {}
    for patch in patches:
        for cell in patch.replace:
            if cell.id in replacements and replacements[cell.id] != cell:
                raise InvalidCell("BABOOM connector execution authority patches conflict")
            replacements[cell.id] = cell
    if patches:
        store.commit(
            snapshot.revision,
            create=tuple(cell for patch in patches for cell in patch.create),
            replace=tuple(replacements.values()),
        )
    for root in provider_roots.values():
        read_connector_provider(store.snapshot(), protocol, adapter_protocol, root)
    return protocol, _ADAPTER_CATALOG_V5, MappingProxyType(provider_roots)


def _ensure_mcp_broker_authority(
    store: CellStore,
    adapter_protocol: AdapterProtocol,
    roles: Mapping[str, str],
    connectors_domain_root: str,
    application_root: str,
) -> tuple[McpBrokerProtocol, str, Mapping[str, str]]:
    """Release MCP transport contracts without importing local configuration.

    Each individual MCP server is enrolled later by a founder-authorized
    fingerprint-only request. The graph never receives an endpoint, command,
    credential, raw tool manifest, or live connection handle.
    """
    protocol = bootstrap_mcp_broker_protocol(
        store, prefix=_MCP_BROKER_PROTOCOL_PREFIX
    )
    adapter_roots: list[str] = []
    transport_adapters: dict[str, str] = {}
    for transport, adapter_root, name, action, location, datatypes in (
        _MCP_BROKER_ADAPTER_SPECS
    ):
        snapshot = store.snapshot()
        if adapter_root not in snapshot.cells:
            adapter = build_adapter_definition(
                store,
                adapter_protocol,
                adapter_id=adapter_root,
                name=name,
                actions=(action,),
                locations=(location,),
                datatypes=datatypes,
                evidence=(
                    "MCP server is fingerprint-only; negotiated tool identity "
                    "is digest-bound; credentials and raw payloads remain local"
                ),
            )
            release_adapter_definition(store, adapter_protocol, adapter.root_id)
        projection = verify_released_adapter(
            store.snapshot(), adapter_protocol, adapter_root
        )
        action_roots = tuple(
            root for root in projection.action_roots
            if _text(store.snapshot(), root) == action
        )
        location_roots = tuple(
            root for root in projection.location_roots
            if _text(store.snapshot(), root) == location
        )
        datatype_roots = tuple(
            root for root in projection.datatype_roots
            if _text(store.snapshot(), root) in datatypes
        )
        if (
            len(action_roots) != 1
            or len(location_roots) != 1
            or len(datatype_roots) != len(datatypes)
        ):
            raise InvalidCell("MCP broker adapter release binding drifted")
        transport_adapters[transport] = adapter_root
        adapter_roots.append(adapter_root)
    snapshot = store.snapshot()
    if _ADAPTER_CATALOG_V7 not in snapshot.cells:
        build_adapter_catalog(
            store,
            adapter_protocol,
            tuple(adapter_roots),
            catalog_id=_ADAPTER_CATALOG_V7,
            version="7.0.0",
        )
    catalog = extend_adapter_catalog(
        store, adapter_protocol, _ADAPTER_CATALOG_V7, tuple(adapter_roots)
    )
    if catalog.adapter_roots != tuple(adapter_roots):
        raise InvalidCell("MCP broker adapter catalog drifted")
    snapshot = store.snapshot()
    requested = (
        (connectors_domain_root, (
            (roles["member"], protocol.root_id),
            (roles["member"], _ADAPTER_CATALOG_V7),
            *((roles["member"], root) for root in adapter_roots),
        )),
        (application_root, (
            (roles["member"], protocol.root_id),
            (roles["member"], _ADAPTER_CATALOG_V7),
            *((roles["member"], root) for root in adapter_roots),
        )),
    )
    patches = []
    for relation_root, members in requested:
        existing_members = tuple(
            (member.role_id, member.participant_id)
            for member in read_relation(snapshot, relation_root, budget=100_000)
        )
        for member in members:
            if existing_members.count(member) > 1:
                raise InvalidCell("MCP broker authority membership is duplicated")
        missing_members = tuple(member for member in members if member not in existing_members)
        if missing_members:
            patches.append(prepare_append_relation_members(
                snapshot, relation_root, missing_members, budget=100_000
            ))
    replacements = {}
    for patch in patches:
        for cell in patch.replace:
            if cell.id in replacements and replacements[cell.id] != cell:
                raise InvalidCell("MCP broker authority patches conflict")
            replacements[cell.id] = cell
    if patches:
        store.commit(
            snapshot.revision,
            create=tuple(cell for patch in patches for cell in patch.create),
            replace=tuple(replacements.values()),
        )
    for root in adapter_roots:
        verify_released_adapter(store.snapshot(), adapter_protocol, root)
    return protocol, _ADAPTER_CATALOG_V7, MappingProxyType(transport_adapters)

