def _edit_value_control_root(
    subject_root: str,
    authority_scope_root: str,
    target_root: str,
) -> str:
    token = hashlib.sha256(
        (subject_root + "\0" + authority_scope_root + "\0" + target_root).encode(
            "utf-8"
        )
    ).hexdigest()[:32]
    return "app:edit-value-control:%s" % token


