def _property_index(
    snapshot: Snapshot,
    registry: UniversalApplicationRegistry,
    relation_roots: tuple[str, ...],
) -> dict[str, tuple[PropertyProjection, ...]]:
    """Read every wired property relation once and index its explicit owner."""
    indexed: dict[str, list[PropertyProjection]] = {}
    for relation_root in relation_roots:
        members = read_relation(snapshot, relation_root, budget=8)
        owner = _one_for_role(members, registry.roles["owner"])
        value = _one_for_role(members, registry.roles["value"])
        label = _one_for_role(members, registry.roles["label"])
        if owner is None or value is None or label is None:
            continue
        indexed.setdefault(owner, []).append(PropertyProjection(
            relation_root, owner, value, label
        ))
    return {owner: tuple(rows) for owner, rows in indexed.items()}


def _project_inspector_lenses(
    snapshot: Snapshot,
    registry: UniversalApplicationRegistry,
    view_session: ApplicationViewSession,
    principal_roots: tuple[str, ...],
) -> dict[str, object]:
    """Project only progressive-disclosure lenses admitted to this identity."""
    binding_members = read_relation(
        snapshot, view_session.inspector_lens_binding_root, budget=16
    )
    active_root = _one_for_role(binding_members, registry.roles["focus"])
    if active_root is None:
        raise InvalidCell("view inspector lens has no active focus")
    principals = set(principal_roots)
    lenses = []
    for name, root_id in registry.inspector_lens_roots.items():
        members = read_relation(snapshot, root_id, budget=64)
        authorities = tuple(
            member.participant_id for member in members
            if member.role_id == registry.roles["authority"]
        )
        if authorities and principals.isdisjoint(authorities):
            continue
        label_root = _one_for_role(members, registry.roles["label"])
        if label_root is None:
            raise InvalidCell("inspector lens has no label")
        sections = tuple(
            _text(snapshot, member.participant_id)
            for member in members
            if member.role_id == registry.roles["member"]
        )
        lenses.append({
            "id": root_id,
            "name": name,
            "label": _text(snapshot, label_root),
            "sections": list(sections),
            "active": root_id == active_root,
        })
    admitted = {lens["id"] for lens in lenses}
    if active_root not in admitted:
        raise InvalidCell("active inspector lens is outside identity authority")
    return {
        "binding": view_session.inspector_lens_binding_root,
        "active": active_root,
        "lenses": lenses,
    }


def _properties_available_components(
    registry: UniversalApplicationRegistry,
    *,
    properties: list[dict[str, object]],
    connections: list[dict[str, object]],
    has_attached_relations: bool,
    selected_relation: dict[str, object] | None,
    selected_assembly: dict[str, object] | None,
    selected_interfaces: list[dict[str, object]] | None,
    can_add_property: bool,
    can_add_interface: bool,
    selected_settings: bool,
    has_history: bool,
    has_access: bool,
    has_evidence: bool,
) -> set[str]:
    """Return content bindings applicable to the selected graph subject."""
    available = {registry.properties_component_roots["focus"]}
    if properties or can_add_property:
        available.add(registry.properties_component_roots["properties"])
    if selected_interfaces or (
        selected_assembly and selected_assembly.get("interfaces")
    ) or can_add_interface:
        available.add(registry.properties_component_roots["interfaces"])
    if connections or has_attached_relations or selected_relation is not None:
        available.add(registry.properties_component_roots["relations"])
    if selected_assembly and any((
        selected_assembly.get("operational"),
        selected_assembly.get("status"),
        selected_assembly.get("errors"),
    )):
        available.add(registry.properties_component_roots["logic"])
    if selected_settings or any(
        row.get("label") in {"color", "icon", "presentation"}
        for row in properties
    ):
        available.add(registry.properties_component_roots["presentation"])
    if has_history:
        available.add(registry.properties_component_roots["history"])
    if has_access:
        available.add(registry.properties_component_roots["access"])
    if has_evidence:
        available.add(registry.properties_component_roots["evidence"])
    available.add(registry.properties_component_roots["floor"])
    return available


def _project_properties_presentation(
    snapshot: Snapshot,
    registry: UniversalApplicationRegistry,
    view_session: ApplicationViewSession,
    inspector_projection: Mapping[str, object],
    principal_roots: tuple[str, ...],
    *,
    properties: list[dict[str, object]],
    connections: list[dict[str, object]],
    has_attached_relations: bool,
    selected_relation: dict[str, object] | None,
    selected_assembly: dict[str, object] | None,
    selected_interfaces: list[dict[str, object]] | None,
    can_add_property: bool,
    can_add_interface: bool,
    selected_settings: bool,
    has_history: bool,
    has_access: bool,
    has_evidence: bool,
) -> dict[str, object]:
    """Resolve graph-authored, applicable Properties tabs and bindings."""
    available = _properties_available_components(
        registry,
        properties=properties,
        connections=connections,
        has_attached_relations=has_attached_relations,
        selected_relation=selected_relation,
        selected_assembly=selected_assembly,
        selected_interfaces=selected_interfaces,
        can_add_property=can_add_property,
        can_add_interface=can_add_interface,
        selected_settings=selected_settings,
        has_history=has_history,
        has_access=has_access,
        has_evidence=has_evidence,
    )

    projected = project_presentation(
        snapshot,
        registry.properties_presentation_protocol,
        registry.properties_presentation_root,
        active_lens_root=str(inspector_projection["active"]),
        focus_binding_root=view_session.properties_panel_binding_root,
        available_component_roots=available,
        principal_roots=principal_roots,
    )
    return {
        "root": projected.root_id,
        "binding": view_session.properties_panel_binding_root,
        "active": projected.active_panel_root,
        "panels": [
            {
                "id": panel.root_id,
                "label": _text(snapshot, panel.label_root),
                "active": panel.root_id == projected.active_panel_root,
                "components": [
                    _project_presenter_component(
                        snapshot, registry, component
                    )
                    for component in (
                        projected.components[root]
                        for root in panel.component_roots
                    )
                ] if panel.root_id == projected.active_panel_root else [],
            }
            for panel in projected.panels
        ],
    }


def _project_presenter_component(
    snapshot: Snapshot,
    registry: UniversalApplicationRegistry,
    component,
) -> dict[str, object]:
    presenter = read_presenter(
        snapshot,
        registry.properties_presenter_protocol,
        component.presenter_root,
    )
    graph_projector = is_view_template(
        snapshot,
        registry.view_template_protocol,
        presenter.projector_root,
    )
    return {
        "id": component.root_id,
        "label": _text(snapshot, component.label_root),
        "source": component.source_root,
        "presenter": presenter.root_id,
        "projector": presenter.projector_root,
        "projector_graph": graph_projector,
        "presenter_name": (
            "graph-template" if graph_projector
            else _text(snapshot, presenter.projector_root)
        ),
        "presenter_label": _text(snapshot, presenter.label_root),
        "presenter_contract": presenter.contract_root,
        "presenter_members": [
            {
                "root": root,
                "label": _text(snapshot, root),
            }
            for root in presenter.member_roots
        ],
    }


def _rows_by_label(snapshot: Snapshot, rows: tuple[PropertyProjection, ...]):
    return {_text(snapshot, row.label_root): row for row in rows}


def _unique_property_rows_by_label(
    snapshot: Snapshot,
    rows: tuple[PropertyProjection, ...],
) -> dict[str, PropertyProjection]:
    """Index only unambiguous property labels for multi-selection editing."""
    grouped: dict[str, list[PropertyProjection]] = {}
    for row in rows:
        key = _text(snapshot, row.label_root).strip().casefold()
        grouped.setdefault(key, []).append(row)
    return {
        key: candidates[0] for key, candidates in grouped.items()
        if key and len(candidates) == 1
    }


def _property_batch_control_root(
    subject_root: str,
    owners: tuple[str, ...],
    relation_roots: tuple[str, ...],
    value_roots: tuple[str, ...],
    label_roots: tuple[str, ...],
) -> str:
    """Derive one stable graph identity for one shared-property selection."""
    if not (
        len(owners)
        == len(relation_roots)
        == len(value_roots)
        == len(label_roots)
        and len(owners) > 1
    ):
        raise InvalidCell("batch property control requires aligned participants")
    token = hashlib.sha256("\0".join((
        subject_root,
        *(
            "\x1f".join(parts) for parts in zip(
                owners, relation_roots, value_roots, label_roots
            )
        ),
    )).encode("utf-8")).hexdigest()[:24]
    return "app:property-batch-control:%s:%s" % (_part(subject_root), token)


def _property_batch_control_members(
    registry: UniversalApplicationRegistry,
    owners: tuple[str, ...],
    relation_roots: tuple[str, ...],
    value_roots: tuple[str, ...],
    label_roots: tuple[str, ...],
) -> tuple[tuple[str, str], ...]:
    """Expose every batch participant through one inspectable relation."""
    if not (
        len(owners)
        == len(relation_roots)
        == len(value_roots)
        == len(label_roots)
        and len(owners) > 1
    ):
        raise InvalidCell("batch property relation requires aligned participants")
    return (
        (registry.roles["contract"], _PROPERTY_OPERATION_ROOTS["batch-edit"]),
        *((registry.roles["selected"], root) for root in owners),
        *((registry.roles["property"], root) for root in relation_roots),
        *((registry.roles["value"], root) for root in value_roots),
        *((registry.roles["label"], root) for root in label_roots),
    )


def _domain_canvas_interface_root(domain_root: str, side: str) -> str:
    """Return the retired v1 generic domain-interface identity."""
    if side not in ("source", "target"):
        raise InvalidCell("canvas interface side is invalid")
    return "app:canvas-interface:%s:%s" % (_part(domain_root), side)


def _relation_canvas_interface_root(relation_root: str, side: str) -> str:
    """Return one exact interface identity for one relation incidence."""
    if side not in ("source", "target"):
        raise InvalidCell("canvas interface side is invalid")
    return "app:canvas-interface:relation:%s:%s" % (
        _part(relation_root), side
    )


def _domain_canvas_public_interface_root(domain_root: str, side: str) -> str:
    """Return one graph-owned multi-incidence domain boundary identity."""
    if side not in ("source", "target"):
        raise InvalidCell("canvas interface side is invalid")
    return "app:canvas-interface:domain-boundary:%s:%s:v3" % (
        _part(domain_root), side
    )


_GOVERNED_WORK_SCOPE_INTERFACE_NAME = "Scope for Governed Work"


def _with_canvas_interface_projection_scope(function):
    """Share exact interface projections only inside one interpreter call."""
    @wraps(function)
    def wrapped(*args, **kwargs):
        existing = _CANVAS_INTERFACE_PROJECTION_CACHE.get()
        if existing is not None:
            return function(*args, **kwargs)
        token = _CANVAS_INTERFACE_PROJECTION_CACHE.set({})
        try:
            return function(*args, **kwargs)
        finally:
            _CANVAS_INTERFACE_PROJECTION_CACHE.reset(token)
    return wrapped


def with_session_canvas_roots_scope(function):
    """Share revision-exact visible scope only inside one interpreter request."""
    @wraps(function)
    def wrapped(*args, **kwargs):
        existing = _SESSION_CANVAS_ROOTS_CACHE.get()
        if existing is not None:
            return function(*args, **kwargs)
        token = _SESSION_CANVAS_ROOTS_CACHE.set({})
        try:
            return function(*args, **kwargs)
        finally:
            _SESSION_CANVAS_ROOTS_CACHE.reset(token)
    return wrapped


def _project_standard_catalog(
    store: CellStore,
    snapshot: Snapshot,
    registry: UniversalApplicationRegistry,
) -> tuple[dict[str, object], ...]:
    """Reuse one verified catalogue projection while its graph is unchanged."""
    protocol = registry.assembly_protocol
    catalog_root = registry.standard_library.catalog_root
    verified_catalog = verify_released_catalog_stable(
        store, snapshot, protocol, catalog_root
    )
    if snapshot.revision != store.revision:
        return project_catalog(snapshot, protocol, catalog_root)
    cache_key = (
        protocol.root_id,
        catalog_root,
        str(id(verified_catalog)),
    )
    with _STANDARD_CATALOG_PROJECTION_CACHE_LOCK:
        cached = _STANDARD_CATALOG_PROJECTION_CACHE.get(store)
        if cached is not None and cached[0] == cache_key:
            return cached[1]

    projection = project_catalog(snapshot, protocol, catalog_root)
    if snapshot.revision == store.revision:
        with _STANDARD_CATALOG_PROJECTION_CACHE_LOCK:
            _STANDARD_CATALOG_PROJECTION_CACHE[store] = (
                cache_key, projection
            )
    return projection


def _governed_work_scope_interface_root(domain_root: str) -> str:
    """Return the released source interface used by governed Work scope."""
    return "app:canvas-interface:governed-work-scope:%s" % _part(domain_root)


def _project_canvas_interface_uncached(
    snapshot: Snapshot,
    protocol: AssemblyProtocol,
    interface_root: str,
) -> dict[str, object] | None:
    """Resolve one graph-declared visual interface without ID conventions."""
    try:
        members = read_relation(snapshot, interface_root, budget=100_000)
    except (InvalidCell, MatchBudgetExceeded):
        return None
    owner = _one_for_role(members, protocol.role("interface-target"))
    presentation = _one_for_role(
        members, protocol.role("interface-presentation")
    )
    if owner is None or presentation is None:
        return None
    side = _text(snapshot, presentation)
    if side not in ("source", "target"):
        return None
    name_root = _one_for_role(members, protocol.role("name"))
    contract_root = _one_for_role(
        members, protocol.role("interface-contract")
    )
    if contract_root is None:
        return None
    endpoint_incidences = tuple(
        member.participant_id for member in members
        if _scope_role_name(snapshot, member.role_id) == "authority"
    )
    relation_roots = tuple(
        member.participant_id for member in members
        if _scope_role_name(snapshot, member.role_id) == "seed"
    )
    previous_roots = tuple(
        member.participant_id for member in members
        if _scope_role_name(snapshot, member.role_id) == "previous"
    )
    return {
        "id": interface_root,
        "owner": owner,
        "target": owner,
        "side": side,
        "name": _text(snapshot, name_root) if name_root else "Interface",
        "name_root": name_root,
        "contract_root": contract_root,
        "contract": (
            _text(snapshot, contract_root)
            or _humanize_root_id(contract_root)
        ),
        "presentation_root": presentation,
        "presentation": side,
        "mode": "connection",
        "value": "",
        "editable": False,
        "endpoint_incidences": list(endpoint_incidences),
        "relation_roots": list(relation_roots),
        "previous_roots": list(previous_roots),
        "read_only": any(
            _scope_role_name(snapshot, member.role_id) == "read-only"
            for member in members
        ),
        "items": [],
    }


def _project_canvas_interface(
    snapshot: Snapshot,
    protocol: AssemblyProtocol,
    interface_root: str,
) -> dict[str, object] | None:
    cache = _CANVAS_INTERFACE_PROJECTION_CACHE.get()
    if cache is None:
        return _project_canvas_interface_uncached(
            snapshot, protocol, interface_root
        )
    if interface_root not in cache:
        cache[interface_root] = _project_canvas_interface_uncached(
            snapshot, protocol, interface_root
        )
    return cache[interface_root]


def _registered_canvas_interfaces(
    snapshot: Snapshot,
    registry: UniversalApplicationRegistry,
) -> tuple[dict[str, object], ...]:
    """Read canvas sockets from explicit application graph membership."""
    interface_role = registry.assembly_protocol.role("interface")
    registered = tuple(
        member.participant_id
        for member in read_relation(
            snapshot, registry.application_root, budget=100_000
        )
        if member.role_id == interface_role
    )
    if len(registered) != len(set(registered)):
        raise InvalidCell("canvas interface is registered more than once")
    projected = []
    for interface_root in registered:
        interface = _project_canvas_interface(
            snapshot, registry.assembly_protocol, interface_root
        )
        if interface is None:
            raise InvalidCell("registered canvas interface is invalid")
        if interface["owner"] not in snapshot.cells:
            raise InvalidCell("registered canvas interface owner is missing")
        projected.append(interface)
    return tuple(projected)


def _visible_canvas_interface_roots(
    snapshot: Snapshot,
    registry: UniversalApplicationRegistry,
    visible_roots: tuple[str, ...],
) -> frozenset[str]:
    """Return only interface identities exposed by the active canvas level."""
    visible = set(visible_roots)
    roots = {
        str(interface["id"])
        for interface in _registered_canvas_interfaces(snapshot, registry)
        if interface["owner"] in visible
    }
    for owner_root in visible_roots:
        assembly = _instance_projection(snapshot, registry, owner_root)
        if assembly is not None:
            roots.update(
                str(interface["id"])
                for interface in assembly["interfaces"]
            )
            roots.update(
                str(item["incidence"])
                for interface in assembly["interfaces"]
                for item in interface.get("items", ())
                if item.get("incidence") in snapshot.cells
            )
        if not _is_universal_composition(snapshot, registry, owner_root):
            continue
        roots.update(
            member.participant_id
            for member in read_relation(
                snapshot, owner_root, budget=_SCOPE_MEMBER_LIMIT
            )
            if member.role_id == registry.assembly_protocol.role("interface")
        )
    return frozenset(roots)


def _interface_contract_root(
    snapshot: Snapshot,
    protocol: AssemblyProtocol,
    interface_root: str,
) -> str | None:
    members = _relation_members_or_none(snapshot, interface_root)
    if not members:
        return None
    return _one_for_role(members, protocol.role("interface-contract"))


def _interface_contracts_compatible(
    protocol: AssemblyProtocol,
    source_contract: str | None,
    target_contract: str | None,
) -> bool:
    """The assembly protocol is the explicit universal-Cell contract."""
    if source_contract is None or target_contract is None:
        return False
    return (
        source_contract == target_contract
        or source_contract == protocol.root_id
        or target_contract == protocol.root_id
    )


def _is_derived_composition_interface(
    snapshot: Snapshot,
    registry: UniversalApplicationRegistry,
    interface_root: str,
) -> bool:
    members = _relation_members_or_none(snapshot, interface_root)
    if not members:
        return False
    return (
        any(
            member.role_id == registry.roles["read-only"]
            for member in members
        )
        and _one_for_role(members, registry.roles["seed"]) is not None
        and _one_for_role(members, registry.roles["authority"]) is not None
        and _one_for_role(members, registry.roles["relation"]) is not None
    )


def _compose_interface_backed_canvas_relation_cells(
    snapshot: Snapshot,
    protocol: AssemblyProtocol,
    roles: Mapping[str, str],
    *,
    relation_id: str,
    source_root: str,
    target_root: str,
    additional_members: tuple[tuple[str, str], ...] = (),
) -> tuple[tuple[Cell, ...], tuple[str, ...]]:
    """Compose a binary relation and its exact graph-owned canvas endpoints.

    A visible relation never borrows a decorative port.  Its source and target
    incidences either retain an already-valid interface or receive one exact,
    read-only interface whose authority is that incidence.  Callers commit the
    returned Cells with their own graph transaction and register new interfaces
    on the application root in that same transaction.
    """
    if any(role in {roles["source"], roles["target"]}
           for role, _participant in additional_members):
        raise InvalidCell("canvas relation cannot repeat a binary endpoint")
    relation = compose_relation_cells(
        (
            (roles["source"], source_root),
            (roles["target"], target_root),
            *additional_members,
        ),
        relation_id=relation_id,
    )
    cells = {cell.id: cell for cell in relation.cells}
    source_cell = next(
        cell for cell in relation.cells if cell.link0 == roles["source"]
    )
    target_cell = next(
        cell for cell in relation.cells if cell.link0 == roles["target"]
    )
    created_interfaces: list[str] = []

    def add(cell: Cell) -> None:
        existing = cells.get(cell.id)
        if existing is not None and existing != cell:
            raise InvalidCell("canvas interface creation identity collision")
        cells[cell.id] = cell

    def endpoint(
        *,
        side: str,
        participant_root: str,
        incidence: Cell,
        peer_root: str,
    ) -> str:
        existing = _project_canvas_interface(snapshot, protocol, participant_root)
        if existing is not None:
            if existing["side"] != side:
                raise InvalidCell("canvas relation endpoint has the wrong side")
            return participant_root

        interface_root = _relation_canvas_interface_root(relation_id, side)
        if interface_root in snapshot.cells:
            raise InvalidCell("new canvas relation reuses an existing interface")
        name_root = interface_root + ":name"
        add(Cell(
            name_root,
            NULL_CELL_ID,
            NULL_CELL_ID,
            (
                "%s %s" % (
                    "To" if side == "source" else "From",
                    _humanize_root_id(peer_root),
                )
            ).encode("utf-8"),
        ))
        presentation_root = "app:canvas-interface:presentation:%s" % side
        if presentation_root not in snapshot.cells:
            add(Cell(
                presentation_root,
                NULL_CELL_ID,
                NULL_CELL_ID,
                side.encode("ascii"),
            ))
        interface = compose_relation_cells(
            (
                (protocol.role("interface-target"), participant_root),
                (protocol.role("name"), name_root),
                (protocol.role("interface-contract"), protocol.root_id),
                (protocol.role("interface-presentation"), presentation_root),
                (roles["seed"], relation_id),
                (roles["authority"], incidence.id),
                (roles["read-only"], roles["read-only"]),
            ),
            relation_id=interface_root,
        )
        for cell in interface.cells:
            add(cell)
        created_interfaces.append(interface_root)
        return interface_root

    source_interface = endpoint(
        side="source",
        participant_root=source_root,
        incidence=source_cell,
        peer_root=target_root,
    )
    target_interface = endpoint(
        side="target",
        participant_root=target_root,
        incidence=target_cell,
        peer_root=source_root,
    )
    cells[source_cell.id] = Cell(
        source_cell.id,
        source_cell.link0,
        source_interface,
        source_cell.atom,
    )
    cells[target_cell.id] = Cell(
        target_cell.id,
        target_cell.link0,
        target_interface,
        target_cell.atom,
    )
    return tuple(cells.values()), tuple(created_interfaces)


def _migrate_legacy_canvas_scope_interfaces(
    store: CellStore,
    protocol: AssemblyProtocol,
    roles: Mapping[str, str],
    application_root: str,
    scope_root: str,
) -> None:
    """Upgrade only direct legacy endpoints within one openable composition.

    Modern relations already point at exact interface Cells and therefore cause
    no write.  Older persisted compositions may still point directly at their
    owners; the established generic incidence migrator upgrades those only.
    """
    snapshot = store.snapshot()
    scope_members = read_relation(snapshot, scope_root, budget=_SCOPE_MEMBER_LIMIT)
    roots = tuple(
        member.participant_id for member in scope_members
        if member.role_id == roles["member"]
    )
    relation_roots = tuple(
        member.participant_id for member in scope_members
        if member.role_id == roles["relation"]
    )
    if not roots or not relation_roots:
        return
    needs_migration = False
    for relation_root in relation_roots:
        members = read_relation(snapshot, relation_root, budget=256)
        for side in ("source", "target"):
            endpoint = next((
                member for member in members
                if member.role_id == roles[side]
            ), None)
            if endpoint is None:
                continue
            if _project_canvas_interface(
                snapshot, protocol, endpoint.participant_id
            ) is None:
                needs_migration = True
                break
        if needs_migration:
            break
    if not needs_migration:
        return
    _ensure_canvas_domain_interfaces(
        store,
        protocol,
        roles,
        application_root,
        roots,
        relation_roots,
    )


def _ensure_canvas_domain_interfaces(
    store: CellStore,
    protocol: AssemblyProtocol,
    roles: Mapping[str, str],
    application_root: str,
    domain_roots: tuple[str, ...],
    relation_roots: tuple[str, ...],
) -> None:
    """Migrate generic domain dots to exact relation-incidence interfaces.

    Each projected cable receives a dedicated source and target interface.
    The interface graph records its owner, relation root, and exact incidence;
    the retired Provides/Requires interfaces and their former registration
    incidences remain connected through graph-held migration evidence while
    no longer being registered as current application interfaces.
    """
    snapshot = store.snapshot()
    original_cell_ids = frozenset(snapshot.cells)
    support = {
        "source-presentation": (
            "app:canvas-interface:presentation:source", b"source"
        ),
        "target-presentation": (
            "app:canvas-interface:presentation:target", b"target"
        ),
    }
    create: dict[str, Cell] = {}

    def add(cell: Cell) -> None:
        if cell.id in snapshot.cells:
            return
        existing = create.get(cell.id)
        if existing is not None and existing != cell:
            raise InvalidCell("canvas interface migration identity collision")
        create[cell.id] = cell

    for root_id, atom in support.values():
        add(Cell(root_id, NULL_CELL_ID, NULL_CELL_ID, atom))

    domain_set = set(domain_roots)
    legacy_roots = {
        _domain_canvas_interface_root(domain_root, side)
        for domain_root in domain_roots
        for side in ("source", "target")
    }
    interfaces: list[tuple[str, str, str, str, str, str, str | None]] = []
    for relation_root in relation_roots:
        members = read_relation(snapshot, relation_root, budget=256)
        source_members = tuple(
            member for member in members if member.role_id == roles["source"]
        )
        target_members = tuple(
            member for member in members if member.role_id == roles["target"]
        )
        if len(source_members) != 1 or len(target_members) != 1:
            continue
        source_member, target_member = source_members[0], target_members[0]

        def owner(member) -> str:
            projected = _project_canvas_interface(
                snapshot, protocol, member.participant_id
            )
            return str(projected["owner"]) if projected else member.participant_id

        source_owner = owner(source_member)
        target_owner = owner(target_member)
        if source_owner not in domain_set or target_owner not in domain_set:
            continue
        interfaces.extend((
            (
                _relation_canvas_interface_root(relation_root, "source"),
                "source", source_owner, target_owner, source_member.incidence_id,
                relation_root,
                (
                    _domain_canvas_interface_root(source_owner, "source")
                    if _domain_canvas_interface_root(
                        source_owner, "source"
                    ) in snapshot.cells else None
                ),
            ),
            (
                _relation_canvas_interface_root(relation_root, "target"),
                "target", target_owner, source_owner, target_member.incidence_id,
                relation_root,
                (
                    _domain_canvas_interface_root(target_owner, "target")
                    if _domain_canvas_interface_root(
                        target_owner, "target"
                    ) in snapshot.cells else None
                ),
            ),
        ))

    interface_roots: list[str] = []
    for (
        interface_root, side, owner_root, peer_root, incidence_root,
        relation_root, legacy_root,
    ) in interfaces:
        interface_roots.append(interface_root)
        name_root = interface_root + ":name"
        name = "%s %s" % (
            "To" if side == "source" else "From",
            _humanize_root_id(peer_root),
        )
        add(Cell(name_root, NULL_CELL_ID, NULL_CELL_ID, name.encode("utf-8")))
        if interface_root in snapshot.cells:
            projected = _project_canvas_interface(
                snapshot, protocol, interface_root
            )
            if (
                projected is None
                or projected["owner"] != owner_root
                or projected["side"] != side
                or projected["endpoint_incidences"] != [incidence_root]
                or projected["relation_roots"] != [relation_root]
                or any(
                    previous != legacy_root
                    for previous in projected["previous_roots"]
                )
                or len(projected["previous_roots"]) > 1
            ):
                raise InvalidCell("persisted exact canvas interface drifted")
            continue
        relation_members = [
            (protocol.role("interface-target"), owner_root),
            (protocol.role("name"), name_root),
            (protocol.role("interface-contract"), protocol.root_id),
            (
                protocol.role("interface-presentation"),
                support[side + "-presentation"][0],
            ),
            (roles["seed"], relation_root),
            (roles["authority"], incidence_root),
            (roles["read-only"], roles["read-only"]),
        ]
        if legacy_root is not None:
            relation_members.append((roles["previous"], legacy_root))
        composed = compose_relation_cells(
            relation_members, relation_id=interface_root
        )
        for cell in composed.cells:
            add(cell)

    application_members = read_relation(
        snapshot, application_root, budget=100_000
    )
    application_interface_roots = {
        member.participant_id for member in application_members
        if member.role_id == protocol.role("interface")
    }
    legacy_members = tuple(
        member for member in application_members
        if member.role_id == protocol.role("interface")
        and member.participant_id in legacy_roots
    )
    legacy_registered = bool(legacy_members)
    legacy_present = tuple(sorted(
        root for root in legacy_roots if root in snapshot.cells
    ))
    migration_required = bool(legacy_present)
    if migration_required:
        add(Cell(
            _CANVAS_INTERFACE_MIGRATION_REASON_ROOT,
            NULL_CELL_ID,
            NULL_CELL_ID,
            b"replace generic domain dots with exact relation incidences",
        ))
        legacy_registration_incidences = tuple(sorted(
            cell.id for cell in snapshot.cells.values()
            if cell.link0 == protocol.role("interface")
            and cell.link1 in legacy_roots
        ))
        migration_members = [
            (roles["why"], _CANVAS_INTERFACE_MIGRATION_REASON_ROOT),
            *((roles["source"], root) for root in legacy_present),
            *((roles["target"], interface_root) for (
                interface_root, _side, _owner, _peer, _incidence,
                _relation, legacy_root,
            ) in interfaces if legacy_root is not None),
            *((roles["authority"], incidence_root)
              for incidence_root in legacy_registration_incidences),
        ]
        if _CANVAS_INTERFACE_MIGRATION_ROOT not in snapshot.cells:
            migration = compose_relation_cells(
                migration_members,
                relation_id=_CANVAS_INTERFACE_MIGRATION_ROOT,
            )
            for cell in migration.cells:
                add(cell)
        else:
            actual = read_relation(
                snapshot, _CANVAS_INTERFACE_MIGRATION_ROOT, budget=100_000
            )
            expected = sorted(migration_members)
            observed = sorted(
                (member.role_id, member.participant_id) for member in actual
            )
            if observed != expected:
                raise InvalidCell("canvas interface migration evidence drifted")
    public_migrated_roots = {
        interface_root
        for (
            interface_root, side, owner_root, _peer_root, _incidence_root,
            _relation_root, _legacy_root,
        ) in interfaces
        if _domain_canvas_public_interface_root(owner_root, side)
        in snapshot.cells
    }
    missing_members = tuple(
        root for root in interface_roots
        if root not in application_interface_roots
        and root not in public_migrated_roots
    )
    migration_registered = any(
        member.role_id == roles["migration"]
        and member.participant_id == _CANVAS_INTERFACE_MIGRATION_ROOT
        for member in application_members
    )
    application_additions = [
        (protocol.role("interface"), root) for root in missing_members
    ]
    if migration_required and not migration_registered:
        application_additions.append((
            roles["migration"], _CANVAS_INTERFACE_MIGRATION_ROOT
        ))
    application_patch = None
    if application_additions:
        application_patch = prepare_append_relation_members(
            snapshot,
            application_root,
            application_additions,
            budget=100_000,
        )
        for cell in application_patch.create:
            add(cell)

    replace: dict[str, Cell] = {}
    for interface_root in interface_roots:
        if interface_root not in snapshot.cells:
            continue
        members = read_relation(snapshot, interface_root, budget=32)
        contract_members = tuple(
            member for member in members
            if member.role_id == protocol.role("interface-contract")
        )
        if len(contract_members) != 1:
            raise InvalidCell("persisted canvas interface contract drifted")
        contract_member = contract_members[0]
        if contract_member.participant_id != protocol.root_id:
            incidence = snapshot.cells[contract_member.incidence_id]
            replace[incidence.id] = Cell(
                incidence.id,
                incidence.link0,
                protocol.root_id,
                incidence.atom,
            )
    for (
        interface_root, side, owner_root, _peer, incidence_root,
        _relation_root, _legacy_root,
    ) in interfaces:
        incidence = snapshot.cells[incidence_root]
        public_root = _domain_canvas_public_interface_root(owner_root, side)
        if incidence.link1 not in (interface_root, public_root):
            replace[incidence.id] = Cell(
                incidence.id,
                incidence.link0,
                interface_root,
                incidence.atom,
            )

    if (
        not create and not replace and application_patch is None
        and not legacy_registered
    ):
        return
    if application_patch is not None:
        for cell in application_patch.replace:
            replace[cell.id] = cell
    if create or replace:
        store.commit(
            snapshot.revision,
            create=tuple(create.values()),
            replace=tuple(replace.values()),
        )

    # Exact interfaces created by the first v2 migration predate explicit
    # predecessor links.  Append those links in one atomic, idempotent patch.
    snapshot = store.snapshot()
    predecessor_create: dict[str, Cell] = {}
    predecessor_replace: dict[str, Cell] = {}
    for (
        interface_root, _side, _owner, _peer, _incidence,
        _relation_root, legacy_root,
    ) in interfaces:
        if legacy_root is None:
            continue
        members = read_relation(snapshot, interface_root, budget=32)
        previous = tuple(
            member.participant_id for member in members
            if member.role_id == roles["previous"]
        )
        if previous == (legacy_root,):
            continue
        if previous:
            raise InvalidCell("canvas interface predecessor drifted")
        patch = prepare_append_relation_members(
            snapshot,
            interface_root,
            ((roles["previous"], legacy_root),),
            budget=32,
        )
        for cell in patch.create:
            predecessor_create[cell.id] = cell
        for cell in patch.replace:
            predecessor_replace[cell.id] = cell
    if predecessor_create or predecessor_replace:
        store.commit(
            snapshot.revision,
            create=tuple(predecessor_create.values()),
            replace=tuple(predecessor_replace.values()),
        )
    while True:
        application_members = read_relation(
            store.snapshot(), application_root, budget=100_000
        )
        legacy_member = next((
            member for member in application_members
            if member.role_id == protocol.role("interface")
            and member.participant_id in legacy_roots
        ), None)
        if legacy_member is None:
            break
        remove_relation_member(
            store,
            application_root,
            legacy_member.incidence_id,
            budget=100_000,
        )
    if not original_cell_ids.issubset(store.snapshot().cells):
        raise InvalidCell("canvas interface migration deleted Cell history")


def _is_domain_public_interface(
    snapshot: Snapshot,
    protocol: AssemblyProtocol,
    interface_root: str,
) -> bool:
    projected = _project_canvas_interface(snapshot, protocol, interface_root)
    return bool(
        projected is not None
        and interface_root == _domain_canvas_public_interface_root(
            str(projected["owner"]), str(projected["side"])
        )
    )


def _ensure_canvas_domain_public_interfaces(
    store: CellStore,
    protocol: AssemblyProtocol,
    roles: Mapping[str, str],
    application_root: str,
    domain_roots: tuple[str, ...],
    relation_roots: tuple[str, ...],
) -> None:
    """Expose exact domain incidences through graph-owned public boundaries."""
    snapshot = store.snapshot()
    original_cell_ids = frozenset(snapshot.cells)
    domain_set = set(domain_roots)
    application_members = read_relation(
        snapshot, application_root, budget=100_000
    )
    interface_role = protocol.role("interface")
    registered_interfaces = {
        member.participant_id: member.incidence_id
        for member in application_members
        if member.role_id == interface_role
    }
    grouped: dict[
        tuple[str, str], list[tuple[str, str, tuple[str, ...]]]
    ] = {}
    exact_roots: set[str] = set()
    for relation_root in relation_roots:
        members = read_relation(snapshot, relation_root, budget=256)
        endpoints = (
            (
                "source",
                next((
                    member for member in members
                    if member.role_id == roles["source"]
                ), None),
            ),
            (
                "target",
                next((
                    member for member in members
                    if member.role_id == roles["target"]
                ), None),
            ),
        )
        for side, endpoint in endpoints:
            if endpoint is None:
                continue
            interface = _project_canvas_interface(
                snapshot, protocol, endpoint.participant_id
            )
            if interface is None:
                continue
            owner_root = str(interface["owner"])
            if owner_root not in domain_set or interface["side"] != side:
                continue
            public_root = _domain_canvas_public_interface_root(
                owner_root, side
            )
            previous = tuple(str(root) for root in (
                interface["previous_roots"]
                if endpoint.participant_id == public_root
                else (endpoint.participant_id,)
            ))
            exact_roots.update(previous)
            grouped.setdefault((owner_root, side), []).append((
                relation_root, endpoint.incidence_id, previous
            ))

    create: dict[str, Cell] = {}

    def add(cell: Cell) -> None:
        if cell.id in snapshot.cells:
            return
        existing = create.get(cell.id)
        if existing is not None and existing != cell:
            raise InvalidCell("public canvas interface identity collision")
        create[cell.id] = cell

    relation_replacements: dict[str, Cell] = {}

    def write_relation(relation_root: str, members: tuple[tuple[str, str], ...]) -> None:
        composed = compose_relation_cells(members, relation_id=relation_root)
        for cell in composed.cells:
            current = snapshot.cells.get(cell.id)
            if current is None:
                add(cell)
            elif current != cell:
                existing = relation_replacements.get(cell.id)
                if existing is not None and existing != cell:
                    raise InvalidCell(
                        "public canvas interface rewrite collision"
                    )
                relation_replacements[cell.id] = cell

    public_roots: list[str] = []
    expected_by_root: dict[str, tuple[tuple[str, str], ...]] = {}
    endpoint_replacements: dict[str, Cell] = {}
    for (owner_root, side), entries in grouped.items():
        public_root = _domain_canvas_public_interface_root(owner_root, side)
        public_roots.append(public_root)
        name_root = public_root + ":name"
        name = "Outgoing relations" if side == "source" else "Incoming relations"
        add(Cell(name_root, NULL_CELL_ID, NULL_CELL_ID, name.encode("ascii")))
        relation_roots_for_interface = tuple(dict.fromkeys(
            relation_root for relation_root, _incidence, _previous in entries
        ))
        incidence_roots = tuple(dict.fromkeys(
            incidence for _relation, incidence, _previous in entries
        ))
        previous_roots = tuple(dict.fromkeys(
            previous
            for _relation, _incidence, predecessors in entries
            for previous in predecessors
        ))
        expected_members = (
            (protocol.role("interface-target"), owner_root),
            (protocol.role("name"), name_root),
            (protocol.role("interface-contract"), protocol.root_id),
            (
                protocol.role("interface-presentation"),
                "app:canvas-interface:presentation:%s" % side,
            ),
            *((roles["seed"], root) for root in relation_roots_for_interface),
            *((roles["authority"], root) for root in incidence_roots),
            *((roles["previous"], root) for root in previous_roots),
        )
        expected_by_root[public_root] = expected_members
        if public_root in snapshot.cells:
            actual = tuple(
                (member.role_id, member.participant_id)
                for member in read_relation(
                    snapshot, public_root, budget=100_000
                )
            )
            if actual != expected_members:
                write_relation(public_root, expected_members)
        else:
            composed = compose_relation_cells(
                expected_members, relation_id=public_root
            )
            for cell in composed.cells:
                add(cell)
        for _relation_root, incidence_root, _previous in entries:
            incidence = snapshot.cells[incidence_root]
            if incidence.link1 != public_root:
                endpoint_replacements[incidence.id] = Cell(
                    incidence.id,
                    incidence.link0,
                    public_root,
                    incidence.atom,
                )

    migration_sources = tuple(dict.fromkeys(
        root
        for public_root in public_roots
        for role_id, root in expected_by_root[public_root]
        if role_id == roles["previous"]
    ))
    migration_targets = tuple(dict.fromkeys(public_roots))
    migration_registration_incidences = tuple(
        registered_interfaces[root]
        for root in migration_sources
        if root in registered_interfaces
    )
    migration_exists = _CANVAS_PUBLIC_INTERFACE_MIGRATION_ROOT in snapshot.cells
    if migration_sources:
        add(Cell(
            _CANVAS_PUBLIC_INTERFACE_MIGRATION_REASON_ROOT,
            NULL_CELL_ID,
            NULL_CELL_ID,
            b"replace per-relation card sockets with exact public boundaries",
        ))
    if migration_sources and not migration_exists:
        migration = compose_relation_cells((
            (roles["why"], _CANVAS_PUBLIC_INTERFACE_MIGRATION_REASON_ROOT),
            *((roles["source"], root) for root in migration_sources),
            *((roles["target"], root) for root in migration_targets),
            *((roles["authority"], root)
              for root in migration_registration_incidences),
        ), relation_id=_CANVAS_PUBLIC_INTERFACE_MIGRATION_ROOT)
        for cell in migration.cells:
            add(cell)
    elif migration_exists:
        migration_members = read_relation(
            snapshot,
            _CANVAS_PUBLIC_INTERFACE_MIGRATION_ROOT,
            budget=100_000,
        )
        existing_authorities = tuple(dict.fromkeys(
            member.participant_id
            for member in migration_members
            if member.role_id == roles["authority"]
            and member.participant_id in snapshot.cells
        ))
        expected_migration_members = (
            (roles["why"], _CANVAS_PUBLIC_INTERFACE_MIGRATION_REASON_ROOT),
            *((roles["source"], root) for root in migration_sources),
            *((roles["target"], root) for root in migration_targets),
            *((roles["authority"], root) for root in existing_authorities),
            *((roles["authority"], root)
              for root in migration_registration_incidences
              if root not in existing_authorities),
        )
        if tuple(
            (member.role_id, member.participant_id)
            for member in migration_members
        ) != expected_migration_members:
            write_relation(
                _CANVAS_PUBLIC_INTERFACE_MIGRATION_ROOT,
                expected_migration_members,
            )

    application_interface_roots = set(registered_interfaces)
    application_additions = [
        (interface_role, root) for root in public_roots
        if root not in application_interface_roots
    ]
    if migration_sources and not any(
        member.role_id == roles["migration"]
        and member.participant_id == _CANVAS_PUBLIC_INTERFACE_MIGRATION_ROOT
        for member in application_members
    ):
        application_additions.append((
            roles["migration"], _CANVAS_PUBLIC_INTERFACE_MIGRATION_ROOT
        ))
    application_patch = (
        prepare_append_relation_members(
            snapshot,
            application_root,
            application_additions,
            budget=100_000,
        )
        if application_additions else None
    )
    replacements = dict(relation_replacements)
    replacements.update(endpoint_replacements)
    if application_patch is not None:
        for cell in application_patch.replace:
            replacements[cell.id] = cell
    if create or replacements:
        store.commit(
            snapshot.revision,
            create=(
                *create.values(),
                *(application_patch.create if application_patch else ()),
            ),
            replace=tuple(replacements.values()),
        )

    current = store.snapshot()
    current_application = read_relation(
        current, application_root, budget=100_000
    )
    retired_registration_ids = tuple(
        member.incidence_id for member in current_application
        if member.role_id == interface_role
        and member.participant_id in exact_roots
    )
    if retired_registration_ids:
        removal = prepare_remove_relation_members(
            current,
            application_root,
            retired_registration_ids,
            budget=100_000,
        )
        store.commit(current.revision, replace=removal.replace)
    if not original_cell_ids.issubset(store.snapshot().cells):
        raise InvalidCell("public canvas interface migration deleted Cell history")


def _ensure_governed_work_scope_interfaces(
    store: CellStore,
    protocol: AssemblyProtocol,
    application_root: str,
    domain_roots: tuple[str, ...],
) -> None:
    """Declare one exact, public scope source for each Grand Map domain.

    Relation-specific source interfaces describe existing composition cables.
    A governed Work scope instead records the selected domain itself, so it has
    its own released source interface rather than selecting an arbitrary cable.
    """
    snapshot = store.snapshot()
    source_presentation_root = "app:canvas-interface:presentation:source"
    expected_source_atom = b"source"
    existing_presentation = snapshot.cells.get(source_presentation_root)
    if (
        existing_presentation is not None
        and existing_presentation.atom != expected_source_atom
    ):
        raise InvalidCell("governed Work scope presentation drifted")

    create: dict[str, Cell] = {}

    def add(cell: Cell) -> None:
        if cell.id in snapshot.cells:
            return
        existing = create.get(cell.id)
        if existing is not None and existing != cell:
            raise InvalidCell("governed Work scope interface identity collision")
        create[cell.id] = cell

    add(Cell(
        source_presentation_root,
        NULL_CELL_ID,
        NULL_CELL_ID,
        expected_source_atom,
    ))
    interface_roots: list[str] = []
    for domain_root in domain_roots:
        interface_root = _governed_work_scope_interface_root(domain_root)
        name_root = interface_root + ":name"
        interface_roots.append(interface_root)
        if interface_root in snapshot.cells:
            projected = _project_canvas_interface(
                snapshot, protocol, interface_root
            )
            if (
                projected is None
                or projected["owner"] != domain_root
                or projected["side"] != "source"
                or projected["name"] != _GOVERNED_WORK_SCOPE_INTERFACE_NAME
                or projected["contract_root"] != protocol.root_id
                or projected["endpoint_incidences"]
                or projected["relation_roots"]
                or projected["read_only"]
            ):
                raise InvalidCell("persisted governed Work scope interface drifted")
            continue
        if name_root in snapshot.cells:
            raise InvalidCell("partial governed Work scope interface exists")
        add(Cell(
            name_root,
            NULL_CELL_ID,
            NULL_CELL_ID,
            _GOVERNED_WORK_SCOPE_INTERFACE_NAME.encode("ascii"),
        ))
        composed = compose_relation_cells((
            (protocol.role("interface-target"), domain_root),
            (protocol.role("name"), name_root),
            (protocol.role("interface-contract"), protocol.root_id),
            (
                protocol.role("interface-presentation"),
                source_presentation_root,
            ),
        ), relation_id=interface_root)
        for cell in composed.cells:
            add(cell)

    application_members = read_relation(
        snapshot, application_root, budget=100_000
    )
    application_interface_roots = tuple(
        member.participant_id for member in application_members
        if member.role_id == protocol.role("interface")
    )
    if len(application_interface_roots) != len(set(application_interface_roots)):
        raise InvalidCell("governed Work scope interface is registered twice")
    missing_members = tuple(
        root for root in interface_roots
        if root not in application_interface_roots
    )
    if not missing_members:
        return
    application_patch = prepare_append_relation_members(
        snapshot,
        application_root,
        (
            (protocol.role("interface"), root)
            for root in missing_members
        ),
        budget=100_000,
    )
    for cell in application_patch.create:
        add(cell)
    store.commit(
        snapshot.revision,
        create=tuple(create.values()),
        replace=application_patch.replace,
    )


def _governed_work_scope_source_interface(
    snapshot: Snapshot,
    registry: UniversalApplicationRegistry,
    domain_root: str,
) -> str:
    """Resolve the declared scope interface without guessing among cables."""
    expected_root = _governed_work_scope_interface_root(domain_root)
    matches = tuple(
        interface for interface in _registered_canvas_interfaces(snapshot, registry)
        if interface["id"] == expected_root
        and interface["owner"] == domain_root
        and interface["side"] == "source"
        and interface["name"] == _GOVERNED_WORK_SCOPE_INTERFACE_NAME
        and interface["contract_root"] == registry.assembly_protocol.root_id
        and not interface["endpoint_incidences"]
        and not interface["relation_roots"]
        and not interface["read_only"]
    )
    if len(matches) != 1:
        raise InvalidCell("governed Work scope source interface is invalid")
    return expected_root


def _ensure_canvas_card_presentation(
    store: CellStore,
    roles: Mapping[str, str],
    authorization: ApplicationAuthorization,
    application_root: str,
    canvas_root: str,
    visible_roots: tuple[str, ...],
    default_color: str,
) -> None:
    """Append the editable card-colour relation to older durable graphs."""
    snapshot = store.snapshot()
    canvas_members = read_relation(snapshot, canvas_root, budget=100_000)
    existing = {}
    for member in canvas_members:
        if member.role_id != roles["property"]:
            continue
        try:
            property_members = read_relation(
                snapshot, member.participant_id, budget=16
            )
        except InvalidCell:
            continue
        owner = _one_for_role(property_members, roles["owner"])
        label = _one_for_role(property_members, roles["label"])
        if owner is not None and label is not None:
            existing[(owner, _text(snapshot, label))] = member.participant_id

    missing = tuple(
        root for root in visible_roots if (root, "color") not in existing
    )
    if not missing:
        return
    label_root = "app:label:color"
    create: dict[str, Cell] = {}
    if label_root not in snapshot.cells:
        create[label_root] = Cell(
            label_root, NULL_CELL_ID, NULL_CELL_ID, b"color"
        )
    property_roots = []
    property_root_by_owner = {}
    for owner_root in missing:
        token = "%s:presentation:color" % _part(owner_root)
        value_root = "app:value:%s" % token
        relation_root = "app:property:%s" % token
        if value_root in snapshot.cells or relation_root in snapshot.cells:
            raise InvalidCell("partial card presentation migration exists")
        create[value_root] = Cell(
            value_root,
            NULL_CELL_ID,
            NULL_CELL_ID,
            default_color.encode("ascii"),
        )
        relation = compose_relation_cells((
            (roles["owner"], owner_root),
            (roles["value"], value_root),
            (roles["label"], label_root),
        ), relation_id=relation_root)
        for cell in relation.cells:
            create[cell.id] = cell
        property_roots.append(relation_root)
        property_root_by_owner[owner_root] = relation_root

    patches = [prepare_append_relation_members(
        snapshot,
        canvas_root,
        ((roles["property"], root) for root in property_roots),
        budget=100_000,
    )]
    application_members = read_relation(
        snapshot, application_root, budget=100_000
    )
    for application_member in application_members:
        if application_member.role_id != roles["member"]:
            continue
        try:
            session_members = read_relation(
                snapshot, application_member.participant_id, budget=100_000
            )
        except InvalidCell:
            continue
        if _one_for_role(
            session_members, authorization.session_owner_role_root
        ) is None:
            continue
        lens_roots = tuple(
            member.participant_id for member in session_members
            if member.role_id == roles["lens"]
        )
        visible_owners: set[str] = set()
        property_lenses = []
        for lens_root in lens_roots:
            lens_members = read_relation(
                snapshot, lens_root, budget=100_000
            )
            visible_owners.update(
                member.participant_id for member in lens_members
                if member.role_id == roles["visible"]
            )
            if not any(
                member.role_id == roles["focus"] for member in lens_members
            ):
                continue
            property_lenses.append(lens_root)
        scoped_property_roots = tuple(
            property_root_by_owner[owner]
            for owner in visible_roots
            if owner in visible_owners and owner in property_root_by_owner
        )
        for lens_root in property_lenses:
            if not scoped_property_roots:
                continue
            patches.append(prepare_append_relation_members(
                snapshot,
                lens_root,
                (
                    (roles["scope"], root)
                    for root in scoped_property_roots
                ),
                budget=100_000,
            ))

    replace: dict[str, Cell] = {}
    for patch in patches:
        for cell in patch.create:
            if cell.id in create:
                raise InvalidCell("card presentation patch identity collision")
            create[cell.id] = cell
        for cell in patch.replace:
            replace[cell.id] = cell
    store.commit(
        snapshot.revision,
        create=tuple(create.values()),
        replace=tuple(replace.values()),
    )


def _canvas_endpoint(
    snapshot: Snapshot,
    registry: UniversalApplicationRegistry,
    member,
    owner_roots: tuple[str, ...] = (),
    *,
    interface_cache: dict[str, dict[str, object] | None] | None = None,
) -> tuple[str, dict[str, object] | None]:
    def project(interface_root: str):
        if interface_cache is None:
            return _project_canvas_interface(
                snapshot, registry.assembly_protocol, interface_root
            )
        if interface_root not in interface_cache:
            interface_cache[interface_root] = _project_canvas_interface(
                snapshot, registry.assembly_protocol, interface_root
            )
        return interface_cache[interface_root]

    expected_side = (
        "source"
        if member.role_id == registry.roles["source"]
        else "target"
        if member.role_id == registry.roles["target"]
        else None
    )
    interface = project(member.participant_id)
    if interface is not None:
        if expected_side is not None and interface["side"] != expected_side:
            raise InvalidCell("canvas interface is wired on the wrong side")
        if not owner_roots or interface["owner"] in owner_roots:
            return interface["owner"], interface
        for owner_root in owner_roots:
            owner_members = _relation_members_or_none(snapshot, owner_root)
            if not owner_members or not any(
                owner_member.role_id == registry.roles["member"]
                and owner_member.participant_id == interface["owner"]
                for owner_member in owner_members
            ):
                continue
            boundary_roots = tuple(
                owner_member.participant_id
                for owner_member in owner_members
                if owner_member.role_id
                == registry.assembly_protocol.role("interface")
            )
            for boundary_root in boundary_roots:
                boundary_members = read_relation(
                    snapshot, boundary_root, budget=64
                )
                seeds = {
                    boundary_member.participant_id
                    for boundary_member in boundary_members
                    if boundary_member.role_id == registry.roles["seed"]
                }
                incidences = {
                    boundary_member.participant_id
                    for boundary_member in boundary_members
                    if boundary_member.role_id == registry.roles["authority"]
                }
                if (
                    member.participant_id not in seeds
                    or member.incidence_id not in incidences
                ):
                    continue
                boundary = project(boundary_root)
                if boundary is None or boundary["side"] != expected_side:
                    raise InvalidCell("composition boundary interface drifted")
                return owner_root, boundary
        return interface["owner"], interface
    interface_role = registry.assembly_protocol.role("interface")
    for owner_root in owner_roots:
        try:
            owner_members = read_relation(
                snapshot, owner_root, budget=100_000
            )
        except (InvalidCell, MatchBudgetExceeded):
            continue
        if not any(
            owner_member.role_id == interface_role
            and owner_member.participant_id == member.participant_id
            for owner_member in owner_members
        ):
            continue
        interface_members = read_relation(
            snapshot, member.participant_id, budget=100_000
        )
        name_root = _one_for_role(
            interface_members, registry.assembly_protocol.role("name")
        )
        return owner_root, {
            "id": member.participant_id,
            "owner": owner_root,
            "side": expected_side or "target",
            "name": _text(snapshot, name_root) if name_root else "Interface",
        }
    return member.participant_id, None


def _canvas_roots(
    snapshot: Snapshot,
    registry: UniversalApplicationRegistry,
) -> tuple[tuple[str, ...], tuple[str, ...], tuple[str, ...]]:
    members = read_relation(snapshot, registry.canvas_root, budget=100_000)
    return (
        tuple(member.participant_id for member in members
              if member.role_id == registry.roles["member"]),
        tuple(member.participant_id for member in members
              if member.role_id == registry.roles["relation"]),
        tuple(member.participant_id for member in members
              if member.role_id == registry.roles["property"]),
    )


def _require_resource_audience_authority(
    snapshot: Snapshot,
    registry: UniversalApplicationRegistry,
    subject_root: str,
    resource_roots: tuple[str, ...],
    *,
    authority_snapshot: VerifiedAuthoritySnapshot | None = None,
) -> dict[str, tuple[str, str, str, str | None]]:
    """Resolve signed object attributes before a resource enters a view."""
    authority = registry.authorization
    requested = set(resource_roots)
    read_root = authority.protocol.actions["read"]
    lifecycle_states = set(
        registry.standard_library.lifecycle_protocol.states.values()
    )
    verified = authority_snapshot or verify_relationship_authority_snapshot(
        snapshot,
        authority.identity_protocol,
        authority.relationship_broker,
    )
    bindings: dict[str, tuple[str, str, str, str | None]] = {}
    for relationship in verified.active_relationships:
        if (
            relationship.source_root not in requested
            or relationship.kind_root
            != authority.identity_protocol.kinds["audience-binding"]
            or relationship.target_root != authority.audience_root
            or relationship.tenant_root != authority.tenant_root
            or relationship.scope_root != authority.classification_root
            or relationship.action_roots != (read_root,)
        ):
            continue
        evidence = relationship.evidence_roots
        if (
            len(evidence) not in (2, 3)
            or evidence[0] not in lifecycle_states
        ):
            raise InvalidCell(
                "resource audience binding has an invalid release contract"
            )
        lifecycle_root, owner_root = evidence[:2]
        release_root = evidence[2] if len(evidence) == 3 else None
        if relationship.source_root in bindings:
            raise InvalidCell("resource has duplicate active audience bindings")
        bindings[relationship.source_root] = (
            relationship.root_id,
            lifecycle_root,
            owner_root,
            release_root,
        )
    for resource_root in resource_roots:
        try:
            _binding_root, lifecycle_root, owner_root, _release_root = (
                bindings[resource_root]
            )
        except KeyError as exc:
            raise InvalidCell(
                "view resource lacks an active signed audience binding"
            ) from exc
        if (
            lifecycle_root
            == registry.standard_library.lifecycle_protocol.states["wip"]
            and subject_root not in (owner_root, authority.subject_root)
        ):
            raise InvalidCell("WIP resource is outside this subject's authority")
        if (
            lifecycle_root
            == registry.standard_library.lifecycle_protocol.states["archived"]
            and subject_root != authority.subject_root
        ):
            raise InvalidCell("archived resource is founder-only")
    return bindings


def _session_canvas_roots(
    snapshot: Snapshot,
    registry: UniversalApplicationRegistry,
    view_session: ApplicationViewSession,
    *,
    authority_snapshot: VerifiedAuthoritySnapshot | None = None,
    include_trail: bool = False,
) -> tuple:
    """Project only canvas roots explicitly assigned to this view session."""
    cache = _SESSION_CANVAS_ROOTS_CACHE.get()
    cache_key = (
        id(registry),
        snapshot.revision,
        id(snapshot.cells),
        view_session.root_id,
        include_trail,
        id(authority_snapshot),
    )
    if cache is not None and cache_key in cache:
        return cache[cache_key]
    snapshot = dense_read_snapshot(snapshot)
    assigned = tuple(
        member.participant_id
        for member in read_relation(
            snapshot, view_session.visibility_root, budget=100_000
        )
        if member.role_id == registry.roles["visible"]
    )
    authority = registry.authorization
    read_root = authority.protocol.actions["read"]
    verified = authority_snapshot or verify_relationship_authority_snapshot(
        snapshot,
        authority.identity_protocol,
        authority.relationship_broker,
    )
    exposure_entries = _view_scope_exposures(
        snapshot, registry, view_session
    )
    active_exposure_roots = {
        entry_root for entry_root, _visible in exposure_entries.values()
    }
    signed_targets: dict[str, str] = {}
    exposure_targets: dict[str, str] = {}
    for relationship in verified.active_relationships:
        if (
            relationship.source_root
            == authority.resource_reader_principal_root
            and relationship.target_root == view_session.subject_root
            and relationship.kind_root
            == authority.identity_protocol.kinds["delegation"]
            and relationship.tenant_root == authority.tenant_root
            and relationship.scope_root is not None
            and relationship.action_roots == (read_root,)
        ):
            if view_session.visibility_root in relationship.evidence_roots:
                target_index = signed_targets
            elif active_exposure_roots.intersection(
                relationship.evidence_roots
            ):
                target_index = exposure_targets
            else:
                continue
            if relationship.scope_root in target_index:
                raise InvalidCell("view has duplicate active projection grants")
            target_index[relationship.scope_root] = relationship.root_id
    if set(assigned) != set(signed_targets):
        raise InvalidCell("view visibility differs from signed projection grants")
    exposure_compositions = _active_exposure_composition_roots(
        snapshot, registry, view_session
    )
    if set(exposure_compositions) != set(exposure_targets):
        raise InvalidCell(
            "scope exposure differs from signed composition grants"
        )
    _require_resource_audience_authority(
        snapshot,
        registry,
        view_session.subject_root,
        tuple(dict.fromkeys((*assigned, *exposure_compositions))),
        authority_snapshot=verified,
    )
    top_scope = _canvas_scope_for_assigned(snapshot, registry, assigned)
    trail = _read_view_scope_trail(
        snapshot,
        registry,
        view_session,
        assigned_roots=assigned,
        top_scope=top_scope,
    )
    if trail[-1] == registry.canvas_root:
        base_scope = top_scope
    else:
        base_scope = _nested_canvas_scope(snapshot, registry, trail[-1])
    scoped = _apply_view_scope_exposure(
        snapshot,
        registry,
        view_session,
        trail[-1],
        base_scope,
    )
    result = (*scoped, trail) if include_trail else scoped
    if cache is not None:
        cache[cache_key] = result
    return result


def _session_machine_canvas_roots(
    snapshot: Snapshot,
    registry: UniversalApplicationRegistry,
    view_session: ApplicationViewSession,
    *,
    authority_snapshot: VerifiedAuthoritySnapshot | None = None,
) -> tuple[tuple[str, ...], tuple[str, ...], tuple[str, ...], tuple[str, ...]]:
    """Project the signed visible canvas roots without browser interface walks."""
    assigned = tuple(
        member.participant_id
        for member in read_relation(
            snapshot, view_session.visibility_root, budget=100_000
        )
        if member.role_id == registry.roles["visible"]
    )
    authority = registry.authorization
    read_root = authority.protocol.actions["read"]
    verified = authority_snapshot or verify_relationship_authority_snapshot(
        snapshot,
        authority.identity_protocol,
        authority.relationship_broker,
    )
    signed_targets: dict[str, str] = {}
    for relationship in verified.active_relationships:
        if (
            relationship.source_root
            == authority.resource_reader_principal_root
            and relationship.target_root == view_session.subject_root
            and relationship.kind_root
            == authority.identity_protocol.kinds["delegation"]
            and relationship.tenant_root == authority.tenant_root
            and relationship.scope_root is not None
            and relationship.action_roots == (read_root,)
            and view_session.visibility_root in relationship.evidence_roots
        ):
            if relationship.scope_root in signed_targets:
                raise InvalidCell("view has duplicate active projection grants")
            signed_targets[relationship.scope_root] = relationship.root_id
    if set(assigned) != set(signed_targets):
        raise InvalidCell("view visibility differs from signed projection grants")
    _require_resource_audience_authority(
        snapshot,
        registry,
        view_session.subject_root,
        assigned,
        authority_snapshot=verified,
    )
    if any(root not in snapshot.cells for root in assigned):
        raise InvalidCell("view visibility references a missing canvas root")
    visible = tuple(dict.fromkeys(assigned))
    visible_set = set(visible)
    interface_owner: dict[str, str] = {}
    interface_role = registry.assembly_protocol.role("interface")
    for owner_root in visible:
        members = _relation_members_or_none(snapshot, owner_root)
        if not members:
            continue
        for member in members:
            if member.role_id == interface_role:
                interface_owner[member.participant_id] = owner_root

    def owner_for(participant_id: str | None) -> str | None:
        if participant_id in visible_set:
            return participant_id
        if participant_id is None:
            return None
        return interface_owner.get(participant_id)

    relations = []
    for relation_root in registry.relation_roots:
        members = read_relation(snapshot, relation_root, budget=256)
        source = _one_for_role(members, registry.roles["source"])
        target = _one_for_role(members, registry.roles["target"])
        if owner_for(source) in visible_set and owner_for(target) in visible_set:
            relations.append(relation_root)
    return visible, tuple(relations), (), (registry.canvas_root,)


def _machine_node_library_sections(
    snapshot: Snapshot,
    roles: Mapping[str, str],
    *,
    library_root: str,
    limit: int,
) -> tuple[dict[str, object], ...]:
    """Return a bounded catalog summary for machine canvas reads.

    Full catalog conformance is guarded by build and browser courts. The machine
    route is a fast bounded read model, so it should not audit the whole catalog
    just to expose section labels.
    """
    if limit <= 0:
        return ()
    library_members = read_relation(snapshot, library_root, budget=100_000)
    section_roots = tuple(
        member.participant_id for member in library_members
        if member.role_id == roles["relation"]
    )[:limit]
    sections: list[dict[str, object]] = []
    for section_root in section_roots:
        members = read_relation(snapshot, section_root, budget=256)
        labels = tuple(
            member.participant_id for member in members
            if member.role_id == roles["label"]
        )
        if len(labels) != 1:
            raise InvalidCell("node library section graph drifted")
        label = _text(snapshot, labels[0])
        if not label.strip() or len(label) > 80:
            raise InvalidCell("node library section label is invalid")
        sections.append({
            "id": section_root,
            "label": label,
            "definitions": [],
        })
    return tuple(sections)


def _canvas_scope_for_assigned(
    snapshot: Snapshot,
    registry: UniversalApplicationRegistry,
    assigned: tuple[str, ...],
) -> tuple[tuple[str, ...], tuple[str, ...], tuple[str, ...]]:
    all_roots, all_relations, all_properties = _canvas_roots(
        snapshot, registry
    )
    if len(assigned) != len(set(assigned)):
        raise InvalidCell("view visibility repeats a canvas root")
    available = set(all_roots)
    if any(root not in available for root in assigned):
        raise InvalidCell("view visibility references a root outside the canvas")
    allowed = set(assigned)
    contained = set(allowed)
    pending = list(allowed)
    while pending:
        root = pending.pop()
        try:
            members = read_relation(snapshot, root, budget=100_000)
        except InvalidCell:
            continue
        for member in members:
            if (
                member.role_id == registry.roles["member"]
                and member.participant_id not in contained
            ):
                contained.add(member.participant_id)
                pending.append(member.participant_id)
        if len(contained) > 100_000:
            raise InvalidCell("view visibility containment exceeds its budget")
    relations = []
    interface_cache = _CANVAS_INTERFACE_PROJECTION_CACHE.get()
    if interface_cache is None:
        interface_cache = {}
    for relation_root in all_relations:
        members = read_relation(snapshot, relation_root, budget=256)
        source_members = tuple(
            member for member in members
            if member.role_id == registry.roles["source"]
        )
        target_members = tuple(
            member for member in members
            if member.role_id == registry.roles["target"]
        )
        if len(source_members) != 1 or len(target_members) != 1:
            continue
        source, _ = _canvas_endpoint(
            snapshot,
            registry,
            source_members[0],
            all_roots,
            interface_cache=interface_cache,
        )
        target, _ = _canvas_endpoint(
            snapshot,
            registry,
            target_members[0],
            all_roots,
            interface_cache=interface_cache,
        )
        if source in allowed and target in allowed:
            relations.append(relation_root)
    owners = contained | set(relations)
    properties = []
    for relation_root in all_properties:
        members = read_relation(snapshot, relation_root, budget=8)
        owner = _one_for_role(members, registry.roles["owner"])
        if owner in owners:
            properties.append(relation_root)
    return assigned, tuple(relations), tuple(properties)


def _view_scope_exposures(
    snapshot: Snapshot,
    registry: UniversalApplicationRegistry,
    view_session: ApplicationViewSession,
) -> dict[str, tuple[str, tuple[str, ...]]]:
    entries: dict[str, tuple[str, tuple[str, ...]]] = {}
    for member in read_relation(
        snapshot, view_session.scope_exposure_root, budget=100_000
    ):
        if member.role_id != registry.roles["relation"]:
            raise InvalidCell("scope exposure registry contains a non-relation")
        exposure_members = read_relation(
            snapshot, member.participant_id, budget=_SCOPE_MEMBER_LIMIT
        )
        if any(
            item.role_id not in (
                registry.roles["scope"], registry.roles["visible"]
            )
            for item in exposure_members
        ):
            raise InvalidCell("scope exposure contains an undeclared role")
        parent = _one_for_role(exposure_members, registry.roles["scope"])
        if parent is None or parent in entries:
            raise InvalidCell("scope exposure parent is missing or repeated")
        visible = tuple(
            item.participant_id for item in exposure_members
            if item.role_id == registry.roles["visible"]
        )
        if not visible or len(visible) != len(set(visible)):
            raise InvalidCell("scope exposure visible roots are invalid")
        entries[parent] = (member.participant_id, visible)
    return entries


def _is_universal_composition(
    snapshot: Snapshot,
    registry: UniversalApplicationRegistry,
    root_id: str,
) -> bool:
    members = _relation_members_or_none(snapshot, root_id)
    return bool(members) and any(
        member.role_id == registry.roles["seed"]
        and member.participant_id == _COMPOSITION_MARKER_ROOT
        for member in members
    )


def _active_exposure_composition_roots(
    snapshot: Snapshot,
    registry: UniversalApplicationRegistry,
    view_session: ApplicationViewSession,
) -> tuple[str, ...]:
    roots = []
    for _entry_root, visible_roots in _view_scope_exposures(
        snapshot, registry, view_session
    ).values():
        roots.extend(
            root_id for root_id in visible_roots
            if _is_universal_composition(snapshot, registry, root_id)
        )
    return tuple(dict.fromkeys(roots))


def _composition_leaf_roots(
    snapshot: Snapshot,
    registry: UniversalApplicationRegistry,
    root_id: str,
    direct_roots: frozenset[str],
    *,
    trail: tuple[str, ...] = (),
) -> frozenset[str]:
    if root_id in direct_roots:
        return frozenset((root_id,))
    if root_id in trail:
        raise InvalidCell("composition exposure contains a recursive boundary")
    members = _relation_members_or_none(snapshot, root_id)
    if not members:
        raise InvalidCell("scope exposure invents a non-composition root")
    children = tuple(
        member.participant_id for member in members
        if member.role_id == registry.roles["member"]
    )
    if not children or len(children) != len(set(children)):
        raise InvalidCell("composition has invalid direct members")
    leaves: set[str] = set()
    for child in children:
        child_leaves = _composition_leaf_roots(
            snapshot,
            registry,
            child,
            direct_roots,
            trail=(*trail, root_id),
        )
        if leaves.intersection(child_leaves):
            raise InvalidCell("composition exposure duplicates a direct root")
        leaves.update(child_leaves)
    return frozenset(leaves)


def _apply_view_scope_exposure(
    snapshot: Snapshot,
    registry: UniversalApplicationRegistry,
    view_session: ApplicationViewSession,
    parent_root: str,
    base_scope: tuple[tuple[str, ...], tuple[str, ...], tuple[str, ...]],
) -> tuple[tuple[str, ...], tuple[str, ...], tuple[str, ...]]:
    entry = _view_scope_exposures(
        snapshot, registry, view_session
    ).get(parent_root)
    if entry is None:
        return base_scope
    _entry_root, visible_roots = entry
    direct_roots, relation_roots, property_roots = base_scope
    direct = frozenset(direct_roots)
    covered: set[str] = set()
    for root_id in visible_roots:
        leaves = _composition_leaf_roots(
            snapshot, registry, root_id, direct
        )
        if covered.intersection(leaves):
            raise InvalidCell("scope exposure overlaps composition members")
        covered.update(leaves)
    if covered != direct:
        raise InvalidCell("scope exposure is not a lossless parent partition")

    visible_set = set(visible_roots)
    projected_relations = []
    for relation_root in relation_roots:
        members = read_relation(snapshot, relation_root, budget=256)
        source_member = next((
            member for member in members
            if member.role_id == registry.roles["source"]
        ), None)
        target_member = next((
            member for member in members
            if member.role_id == registry.roles["target"]
        ), None)
        if source_member is None or target_member is None:
            continue
        source, _ = _canvas_endpoint(
            snapshot, registry, source_member, visible_roots
        )
        target, _ = _canvas_endpoint(
            snapshot, registry, target_member, visible_roots
        )
        if (
            source in visible_set
            and target in visible_set
            and source != target
        ):
            projected_relations.append(relation_root)

    all_properties = _canvas_roots(snapshot, registry)[2]
    projected_properties = []
    for property_root in dict.fromkeys((*property_roots, *all_properties)):
        members = read_relation(snapshot, property_root, budget=16)
        owner = _one_for_role(members, registry.roles["owner"])
        if owner in visible_set:
            projected_properties.append(property_root)
    return (
        visible_roots,
        tuple(projected_relations),
        tuple(projected_properties),
    )


_SCOPE_TRAIL_MAX_DEPTH = 32
_SCOPE_MEMBER_LIMIT = 2_000


def _relation_members_or_none(
    snapshot: Snapshot,
    root_id: str,
):
    try:
        return read_relation(snapshot, root_id, budget=_SCOPE_MEMBER_LIMIT)
    except (InvalidCell, MatchBudgetExceeded):
        return None


def _scope_role_name(snapshot: Snapshot, role_id: str) -> str:
    try:
        return _text(snapshot, role_id).strip().lower()
    except (InvalidCell, UnicodeDecodeError):
        return ""


def _nested_canvas_scope(
    snapshot: Snapshot,
    registry: UniversalApplicationRegistry,
    scope_root: str,
) -> tuple[tuple[str, ...], tuple[str, ...], tuple[str, ...]]:
    """Interpret one direct relation level without projecting its descendants."""
    members = _relation_members_or_none(snapshot, scope_root)
    if not members:
        raise InvalidCell("canvas scope is not an openable relation")
    if len(members) > _SCOPE_MEMBER_LIMIT:
        raise InvalidCell("canvas scope exceeds its bounded projection limit")

    is_composition = _is_universal_composition(
        snapshot, registry, scope_root
    )
    structural = []
    scoped_relations = []
    direct_participants = []
    for member in members:
        participant = member.participant_id
        if participant not in snapshot.cells or participant == scope_root:
            continue
        direct_participants.append(participant)
        role_name = _scope_role_name(snapshot, member.role_id)
        if (
            role_name == "member"
            if is_composition
            else (
                role_name in {"member", "part", "seed", "catalog"}
                or role_name.endswith("-member")
            )
        ):
            structural.append(participant)
        if role_name in {"scope", "relation", "property"}:
            scoped_relations.append(participant)

    # Relations such as a wire or property have no structural-member role. In
    # that case their direct participants are the visible next level.
    roots = tuple(dict.fromkeys(structural or direct_participants))
    if not roots:
        raise InvalidCell("canvas scope has no visible direct participants")
    root_set = set(roots)

    # The opened relation is the scope authority. Its explicit scope,
    # relation, and property incidences are the only relations admitted into
    # this level. Owner-indexed properties below cover application additions
    # that were wired directly to a visible member after the map import.
    relation_candidates = tuple(dict.fromkeys(scoped_relations))
    relation_roots = []
    property_roots = []
    seen_properties = set()
    interface_cache: dict[str, dict[str, object] | None] = {}
    for relation_root in relation_candidates:
        relation_members = _relation_members_or_none(snapshot, relation_root)
        if relation_members is None:
            continue
        source_member = next((
            member for member in relation_members
            if member.role_id == registry.roles["source"]
        ), None)
        target_member = next((
            member for member in relation_members
            if member.role_id == registry.roles["target"]
        ), None)
        if source_member is None or target_member is None:
            continue
        source, _source_interface = _canvas_endpoint(
            snapshot,
            registry,
            source_member,
            roots,
            interface_cache=interface_cache,
        )
        target, _target_interface = _canvas_endpoint(
            snapshot,
            registry,
            target_member,
            roots,
            interface_cache=interface_cache,
        )
        if source in root_set and target in root_set:
            relation_roots.append(relation_root)
        owner = _one_for_role(relation_members, registry.roles["owner"])
        value = _one_for_role(relation_members, registry.roles["value"])
        label = _one_for_role(relation_members, registry.roles["label"])
        if owner in root_set and value is not None and label is not None:
            property_roots.append(relation_root)
            seen_properties.add(relation_root)
    for root_id in roots:
        for property_root in registry.root_properties.get(root_id, ()):
            if property_root not in seen_properties:
                property_roots.append(property_root)
                seen_properties.add(property_root)
    return roots, tuple(dict.fromkeys(relation_roots)), tuple(property_roots)


def _read_view_scope_trail_structure(
    snapshot: Snapshot,
    registry: UniversalApplicationRegistry,
    view_session: ApplicationViewSession,
) -> tuple[str, ...]:
    """Read the bounded structural scope trail without reprojecting its levels."""
    members = read_relation(
        snapshot, view_session.scope_trail_root, budget=_SCOPE_TRAIL_MAX_DEPTH + 1
    )
    if any(member.role_id != registry.roles["scope"] for member in members):
        raise InvalidCell("view scope trail contains a non-scope incidence")
    trail = tuple(member.participant_id for member in members)
    if (
        not trail
        or trail[0] != registry.canvas_root
        or len(trail) > _SCOPE_TRAIL_MAX_DEPTH
        or len(trail) != len(set(trail))
    ):
        raise InvalidCell("view scope trail is invalid")
    return trail


def _read_view_scope_trail(
    snapshot: Snapshot,
    registry: UniversalApplicationRegistry,
    view_session: ApplicationViewSession,
    *,
    assigned_roots: tuple[str, ...] | None = None,
    top_scope: tuple[
        tuple[str, ...], tuple[str, ...], tuple[str, ...]
    ] | None = None,
) -> tuple[str, ...]:
    trail = _read_view_scope_trail_structure(
        snapshot, registry, view_session
    )
    if assigned_roots is None:
        assigned_roots = tuple(
            member.participant_id
            for member in read_relation(
                snapshot, view_session.visibility_root, budget=100_000
            )
            if member.role_id == registry.roles["visible"]
        )
    if top_scope is None:
        top_scope = _canvas_scope_for_assigned(
            snapshot, registry, assigned_roots
        )
    allowed = set(_apply_view_scope_exposure(
        snapshot,
        registry,
        view_session,
        registry.canvas_root,
        top_scope,
    )[0])
    for depth, child_root in enumerate(trail[1:], start=1):
        parent_root = trail[depth - 1]
        if child_root not in allowed:
            raise InvalidCell("view scope trail leaves its direct graph level")
        child_members = _relation_members_or_none(snapshot, child_root)
        if not child_members:
            raise InvalidCell("view scope trail enters a terminal cell")
        child_scope = _nested_canvas_scope(snapshot, registry, child_root)
        allowed = set(_apply_view_scope_exposure(
            snapshot,
            registry,
            view_session,
            child_root,
            child_scope,
        )[0])
    return trail


def _scope_label(
    snapshot: Snapshot,
    registry: UniversalApplicationRegistry,
    root_id: str,
) -> str:
    if root_id == registry.canvas_root:
        return "ArchHub"
    property_roots = list(registry.root_properties.get(root_id, ()))
    if not property_roots:
        for relation_root in _canvas_roots(snapshot, registry)[2]:
            members = read_relation(snapshot, relation_root, budget=16)
            if _one_for_role(
                members, registry.roles["owner"]
            ) == root_id:
                property_roots.append(relation_root)
    rows = _property_index(
        snapshot,
        registry,
        tuple(property_roots),
    ).get(root_id, ())
    labelled = _rows_by_label(snapshot, rows)
    title = labelled.get("title") or labelled.get("key") or labelled.get("label")
    if title is not None:
        return _text(snapshot, title.value_root)
    members = _relation_members_or_none(snapshot, root_id)
    if members:
        by_role: dict[str, list[str]] = {}
        for member in members:
            role_name = _scope_role_name(snapshot, member.role_id)
            by_role.setdefault(role_name, []).append(member.participant_id)
        for preferred_role in ("label", "name", "text", "class", "tag"):
            candidates = by_role.get(preferred_role, ())
            if len(candidates) != 1:
                continue
            candidate = snapshot.cells.get(candidates[0])
            if candidate is None:
                continue
            value = _text(snapshot, candidates[0]).strip()
            if not value:
                continue
            if preferred_role == "class":
                value = value.split()[0].replace("-", " ").replace("_", " ")
                value = value[:1].upper() + value[1:]
            return value
    cell = snapshot.cells[root_id]
    if cell.link0 == NULL_CELL_ID and cell.link1 == NULL_CELL_ID:
        value = _text(snapshot, root_id).strip()
        if value:
            return value
    return _humanize_root_id(root_id)


_COMPOSER_ACTIONS = MappingProxyType({
    "canvas.select": "inspect",
    "canvas.arrange": "edit",
    "catalog.instantiate": "create",
    "catalog.connect": "connect",
    "catalog.configure": "edit",
    "floor.edit": "edit",
})


def _active_authentication_context(
    authority: ApplicationAuthorization,
    authentication_context: object | None,
):
    return (
        authority.session.context()
        if authentication_context is None else authentication_context
    )


def _view_session_for_context(
    registry: UniversalApplicationRegistry,
    authentication_context: object | None,
) -> tuple[ApplicationViewSession, object]:
    authority = registry.authorization
    context = _active_authentication_context(authority, authentication_context)
    identity = authority.broker.resolve(context)
    try:
        return registry.view_sessions[identity.subject_root], context
    except KeyError as exc:
        raise AuthorizationDenied(
            "authenticated subject has no provisioned application view"
        ) from exc


def _cached_authority_snapshot(
    snapshot: Snapshot,
    authority: ApplicationAuthorization,
    *,
    now: float | None = None,
) -> VerifiedAuthoritySnapshot:
    current = time.time() if now is None else float(now)
    key = id(authority)
    with _AUTHORITY_SNAPSHOT_CACHE_LOCK:
        cached = _AUTHORITY_SNAPSHOT_CACHE.get(key)
        if cached is not None:
            cached_authority, revision, expires_at, verified = cached
            if (
                cached_authority is authority
                and revision == snapshot.revision
                and current < expires_at
            ):
                return verified
    verified = verify_relationship_authority_snapshot(
        snapshot,
        authority.identity_protocol,
        authority.relationship_broker,
        now=current,
    )
    cache_expires_at = current + _AUTHORITY_SNAPSHOT_CACHE_TTL_SECONDS
    for relationship in verified.active_relationships:
        if relationship.expires_at_root is None:
            continue
        try:
            relationship_expires_at = float(
                _text(snapshot, relationship.expires_at_root)
            )
        except (TypeError, ValueError) as exc:
            raise InvalidCell(
                "authority relationship expiry is invalid"
            ) from exc
        cache_expires_at = min(cache_expires_at, relationship_expires_at)
    if cache_expires_at > current:
        with _AUTHORITY_SNAPSHOT_CACHE_LOCK:
            _AUTHORITY_SNAPSHOT_CACHE[key] = (
                authority, snapshot.revision, cache_expires_at, verified
            )
    return verified


def _commit_universal_user_change(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    view_session: ApplicationViewSession,
    authentication_context: object,
    snapshot: Snapshot,
    *,
    route: str,
    command_name: str,
    authorization_scope_root: str,
    additional_authorization_scope_roots: tuple[str, ...] = (),
    authorization_interface_root: str | None = None,
    create: Iterable[Cell] = (),
    replace: Iterable[Cell] = (),
) -> int:
    """Publish one editor mutation and its graph receipt in one revision."""
    operation_root = registry.application_http_route_roots.get(
        "POST %s" % route
    )
    if operation_root is None:
        raise InvalidCell("editor mutation route has no graph authority")
    actor_root = registry.authorization.broker.resolve(
        authentication_context
    ).subject_root
    if actor_root != view_session.subject_root:
        raise InvalidCell("editor mutation actor differs from its view session")
    authorization_scope_roots = tuple(dict.fromkeys((
        authorization_scope_root,
        *additional_authorization_scope_roots,
    )))
    for scope_root in authorization_scope_roots:
        _authorize(
            snapshot,
            registry,
            command_name,
            object_root=scope_root,
            interface_root=authorization_interface_root,
            authentication_context=authentication_context,
        )
    return commit_tracked_change(
        store,
        registry.change_history_protocol,
        history_root=view_session.action_history_root,
        actor_root=actor_root,
        session_root=view_session.root_id,
        operation_root=operation_root,
        authority_root=registry.composer_protocol.command(command_name),
        scope_roots=authorization_scope_roots,
        interface_root=authorization_interface_root,
        create=create,
        replace=replace,
        expected_revision=snapshot.revision,
    ).revision


def _inspectable_authority_relationship_roots(
    snapshot: Snapshot,
    registry: UniversalApplicationRegistry,
    subject_root: str,
    *,
    authority_snapshot: VerifiedAuthoritySnapshot | None = None,
) -> tuple[str, ...]:
    """Return signed authority nodes inside one subject's Properties lens."""
    authority = registry.authorization
    verified = authority_snapshot or verify_relationship_authority_snapshot(
        snapshot,
        authority.identity_protocol,
        authority.relationship_broker,
    )
    memberships = active_membership_roots(
        snapshot,
        authority.identity_protocol,
        authority.relationship_broker,
        subject_root,
        authority.tenant_root,
        now=verified.evaluated_at,
        authority_snapshot=verified,
    )
    participants = {subject_root, *memberships}
    roots = []
    for relationship in verified.relationships.values():
        if (
            subject_root == authority.subject_root
            or relationship.source_root in participants
            or relationship.target_root in participants
        ):
            roots.append(relationship.root_id)
    return tuple(roots)


def _inspectable_browser_session_roots(
    snapshot: Snapshot,
    registry: UniversalApplicationRegistry,
    subject_root: str,
) -> tuple[str, ...]:
    """Return session relations visible to their subject or the founder."""
    founder = subject_root == registry.authorization.subject_root
    roots = []
    for session_root in list_browser_session_roots(
        snapshot, registry.browser_session_protocol
    ):
        session = read_browser_session(
            snapshot, registry.browser_session_protocol, session_root
        )
        if founder or session.subject_root == subject_root:
            roots.append(session_root)
    return tuple(roots)


def _inspectable_view_focus_roots(
    snapshot: Snapshot,
    registry: UniversalApplicationRegistry,
    view_session: ApplicationViewSession,
) -> tuple[str, ...]:
    """Return the active focus and its user-visible explanation roots."""
    pointer = snapshot.cells[view_session.focus_incidence]
    focus = read_focus(snapshot, registry.attention_protocol, pointer.link1)
    if (
        focus.session_root != view_session.root_id
        or focus.actor_root != view_session.subject_root
        or focus.state_root != registry.attention_protocol.state("active")
    ):
        raise InvalidCell("view focus explanation is not active")
    return tuple(dict.fromkeys((
        focus.root_id,
        *focus.selected_roots,
        *focus.reason_roots,
        *focus.attention_roots,
        *(focus.consent_evidence_roots or ()),
        *((focus.previous_root,) if focus.previous_root else ()),
    )))


def _require_application_authorization(
    snapshot: Snapshot,
    registry: UniversalApplicationRegistry,
    action_name: str,
    object_root: str,
    *,
    authentication_context: object | None = None,
    interface_root: str | None = None,
    resource_lineage_roots: tuple[str, ...] = (),
    authority_snapshot: VerifiedAuthoritySnapshot | None = None,
):
    authority = registry.authorization
    if action_name not in authority.protocol.actions:
        raise InvalidCell("application authorization action is unknown")
    if authority_snapshot is None:
        authority_snapshot = _cached_authority_snapshot(snapshot, authority)
    lineage = tuple(dict.fromkeys((
        *resource_lineage_roots,
        authority.scope_root,
    )))
    request = AuthorizationRequest(
        action_root=authority.protocol.actions[action_name],
        object_root=object_root,
        resource_lineage_roots=lineage,
        interface_root=interface_root,
        purpose_root=authority.purpose_root,
        classification_root=authority.classification_root,
        audience_root=authority.audience_root,
        now=(
            authority_snapshot.evaluated_at
            if authority_snapshot is not None else None
        ),
    )
    return require_authorization(
        snapshot,
        authority.protocol,
        authority.policy_root,
        authority.broker,
        _active_authentication_context(authority, authentication_context),
        request,
        resolver_state=authority_snapshot,
    )


def _authorize(
    snapshot: Snapshot,
    registry: UniversalApplicationRegistry,
    command_name: str,
    *,
    object_root: str | None = None,
    interface_root: str | None = None,
    authentication_context: object | None = None,
    definition_root: str | None = None,
    resource_usage: Mapping[str, tuple[int, int]] | None = None,
    resource_lineage_roots: tuple[str, ...] = (),
    authority_snapshot: VerifiedAuthoritySnapshot | None = None,
):
    try:
        action_name = _COMPOSER_ACTIONS[command_name]
    except KeyError as exc:
        raise InvalidCell("composer command lacks an authorization action") from exc
    decision = _require_application_authorization(
        snapshot,
        registry,
        action_name,
        object_root or registry.application_root,
        authentication_context=authentication_context,
        interface_root=interface_root,
        resource_lineage_roots=resource_lineage_roots,
        authority_snapshot=authority_snapshot,
    )
    composer_decision = authorize_composer_command(
        snapshot,
        registry.composer_protocol,
        registry.assembly_protocol,
        registry.adapter_protocol,
        registry.composer_authority.root_id,
        command_name,
        definition_root=definition_root,
        resource_usage=resource_usage,
    )
    return decision, composer_decision


def _instance_projection(
    snapshot: Snapshot,
    registry: UniversalApplicationRegistry,
    root_id: str,
    *,
    release_scope: tuple[str, str | None] | None = None,
    interaction_subject_root: str | None = None,
) -> dict[str, object] | None:
    protocol = registry.assembly_protocol
    try:
        members = read_relation(snapshot, root_id, budget=100_000)
    except InvalidCell:
        return None
    definition_root = _one_for_role(members, protocol.role("provenance"))
    if definition_root is None:
        return None
    definition = read_definition(snapshot, protocol, definition_root)
    name = _text(snapshot, definition.name_root)
    relation_authority = None
    relation_protocol_roots = []
    for capability_root in definition.capability_roots:
        try:
            open_relation_contract_protocol(
                snapshot, capability_root, budget=100_000
            )
        except InvalidCell:
            continue
        relation_protocol_roots.append(capability_root)
    if relation_protocol_roots:
        relation_authority = resolve_relation_contract_authority(
            snapshot,
            capability_roots=definition.capability_roots,
            rule_roots=definition.rule_roots,
            budget=100_000,
        )
    relation_constraints = {
        item.participant_role: item
        for item in (
            relation_authority.contract.constraints
            if relation_authority is not None else ()
        )
    }
    version_root = _one_for_role(members, protocol.role("version"))
    state_roots = frozenset(
        member.participant_id for member in members
        if member.role_id == protocol.role("state")
    )
    part_roots = frozenset(
        member.participant_id for member in members
        if member.role_id == protocol.role("part")
    )
    capabilities = {
        member.participant_id for member in members
        if member.role_id == protocol.role("capability")
    }
    lifecycle = registry.standard_library.lifecycle_protocol
    active_lifecycle = None
    scoped_release = None
    if lifecycle.root_id in capabilities:
        active_lifecycle = read_lifecycle_instance(
            snapshot, protocol, lifecycle, root_id
        )
        if release_scope is not None:
            release_state_root, release_source_root = release_scope
            if release_source_root is None:
                raise InvalidCell(
                    "resource release projection lacks an exact revision"
                )
            release_heads = state_heads(
                snapshot,
                lifecycle,
                active_lifecycle.state_pointers[release_state_root],
            )
            if release_state_root == lifecycle.states["wip"]:
                candidates = tuple(
                    root for root in release_heads
                    if root == release_source_root
                )
            else:
                candidates = tuple(
                    root for root in release_heads
                    if release_source_root in read_revision(
                        snapshot, lifecycle, root
                    ).predecessor_roots
                )
            if len(candidates) != 1:
                raise InvalidCell(
                    "resource release projection is missing or ambiguous"
                )
            scoped_release = read_revision(
                snapshot, lifecycle, candidates[0]
            )
    interfaces = []
    for interface_root in (
        member.participant_id for member in members
        if member.role_id == protocol.role("interface")
    ):
        interface = read_relation(snapshot, interface_root, budget=100_000)
        target = _one_for_role(interface, protocol.role("interface-target"))
        if target is None:
            raise InvalidCell("assembly interface has no target")
        if (
            scoped_release is not None
            and active_lifecycle is not None
            and interface_root == active_lifecycle.content_interface_root
        ):
            target = scoped_release.content_root
        name_root = _one_for_role(interface, protocol.role("name"))
        contract_root = _one_for_role(
            interface, protocol.role("interface-contract")
        )
        documentation_root = _one_for_role(
            interface, protocol.role("interface-documentation")
        )
        presentation_root = _one_for_role(
            interface, protocol.role("interface-presentation")
        )
        target_member = next(
            member for member in interface
            if member.role_id == protocol.role("interface-target")
        )
        member_role = _one_for_role(
            interface, protocol.role("interface-member-role")
        )
        relation_constraint = (
            relation_constraints.get(member_role)
            if (
                relation_authority is not None
                and contract_root == relation_authority.contract.root_id
            ) else None
        )
        item_rows = []
        if member_role is not None:
            for member in read_relation(snapshot, target, budget=100_000):
                if member.role_id != member_role:
                    continue
                item_rows.append({
                    "incidence": member.incidence_id,
                    "role": member.role_id,
                    "participant": member.participant_id,
                    "value_root": member.participant_id,
                    "value": _text(snapshot, member.participant_id),
                })
        interfaces.append({
            "id": interface_root,
            "name": _text(snapshot, name_root) if name_root else "interface",
            "target": target,
            "value": _text(snapshot, target),
            "target_incidence": target_member.incidence_id,
            "editable": (
                target in part_roots
                and (
                    relation_constraint is None
                    or relation_constraint.fixed_participant_root is None
                )
            ),
            "mode": (
                "relation-role" if relation_constraint is not None
                else "collection" if member_role is not None
                else "state" if (
                    target in state_roots
                    or (
                        active_lifecycle is not None
                        and interface_root
                        == active_lifecycle.content_interface_root
                    )
                )
                else "connection"
            ),
            "member_role": member_role,
            "contract_root": contract_root,
            "contract": _text(snapshot, contract_root) if contract_root else "",
            "constraint": (
                relation_constraint.root_id
                if relation_constraint is not None else None
            ),
            "minimum": (
                relation_constraint.minimum
                if relation_constraint is not None else None
            ),
            "maximum": (
                relation_constraint.maximum
                if relation_constraint is not None else None
            ),
            "fixed_participant": (
                relation_constraint.fixed_participant_root
                if relation_constraint is not None else None
            ),
            "terminal_atom_maximum": (
                relation_constraint.terminal_atom_maximum
                if relation_constraint is not None else None
            ),
            "documentation": (
                _text(snapshot, documentation_root)
                if documentation_root else ""
            ),
            "presentation": (
                _text(snapshot, presentation_root)
                if presentation_root else ""
            ),
            "items": item_rows,
        })
    def values(role_name: str) -> list[dict[str, str]]:
        matched = [
            member for member in members
            if member.role_id == protocol.role(role_name)
        ]
        return [{
            "id": member.participant_id,
            "label": role_name if len(matched) == 1
            else "%s %s" % (role_name, index + 1),
            "value": _text(snapshot, member.participant_id),
        } for index, member in enumerate(matched)]
    projected = {
        "definition": definition_root,
        "name": name,
        "version": _text(snapshot, version_root) if version_root else "",
        "interfaces": interfaces,
        "states": values("state"),
        "rules": values("rule"),
        "status": values("status"),
        "errors": values("error"),
        "part_count": len(part_roots),
    }
    if lifecycle.root_id in capabilities:
        active = active_lifecycle
        if active is None:
            raise InvalidCell("lifecycle capability has no active instance")
        all_state_rows = []
        for state_name, state_root in lifecycle.states.items():
            pointer_root = active.state_pointers[state_root]
            revision_roots = state_heads(
                snapshot, lifecycle, pointer_root
            )
            heads = []
            for revision_root in revision_roots:
                revision = read_revision(
                    snapshot, lifecycle, revision_root
                )
                evidence_details = []
                for evidence_root in revision.evidence_roots:
                    try:
                        evidence_details.append(_court_evidence_summary(
                            snapshot, registry, evidence_root
                        ))
                    except InvalidCell:
                        evidence_details.append({
                            "root": evidence_root,
                            "court": None,
                            "result": "untyped evidence",
                            "checks": {},
                        })
                heads.append({
                    "revision": revision.root_id,
                    "content": revision.content_root,
                    "content_digest": _text(
                        snapshot, revision.content_digest_root
                    ),
                    "content_bytes": len(
                        snapshot.cells[revision.content_root].atom
                    ),
                    "branch": revision.branch_root,
                    "branch_label": _text(snapshot, revision.branch_root),
                    "parents": list(revision.predecessor_roots),
                    "actor": revision.actor_root,
                    "timestamp": (
                        _text(snapshot, revision.timestamp_root)
                        if revision.timestamp_root else None
                    ),
                    "evidence": list(revision.evidence_roots),
                    "evidence_details": evidence_details,
                })
            sole = heads[0] if len(heads) == 1 else None
            all_state_rows.append({
                "name": state_name.upper(),
                "state": state_root,
                "pointer": pointer_root,
                "head_count": len(heads),
                "heads": heads,
                "revision": sole["revision"] if sole else None,
                "content": sole["content"] if sole else None,
                "content_bytes": sole["content_bytes"] if sole else 0,
            })
        state_rows = (
            [
                row for row in all_state_rows
                if scoped_release is None
                or row["state"] == scoped_release.state_root
            ]
        )
        history_rows = []
        for revision_root in lifecycle_history(
            snapshot, lifecycle, active
        ):
            revision = read_revision(snapshot, lifecycle, revision_root)
            if (
                scoped_release is not None
                and revision.root_id != scoped_release.root_id
            ):
                continue
            history_rows.append({
                "revision": revision_root,
                "state": _text(snapshot, revision.state_root),
                "content": revision.content_root,
                "branch": revision.branch_root,
                "branch_label": _text(snapshot, revision.branch_root),
                "parents": list(revision.predecessor_roots),
                "actor": revision.actor_root,
                "timestamp": (
                    _text(snapshot, revision.timestamp_root)
                    if revision.timestamp_root else None
                ),
                "evidence": list(revision.evidence_roots),
            })
        rows_by_state = {
            row["state"]: row for row in all_state_rows
        }
        state_names = {
            root: name for name, root in lifecycle.states.items()
        }
        transition_rows = []
        for transition_root in (
            active.transition_roots if scoped_release is None else ()
        ):
            transition = read_relation(
                snapshot, transition_root, budget=16
            )
            source_state = _one_for_role(
                transition, lifecycle.role("from-state")
            )
            target_state = _one_for_role(
                transition, lifecycle.role("to-state")
            )
            if source_state is None or target_state is None:
                raise InvalidCell("lifecycle transition is incomplete")
            source_heads = rows_by_state[source_state]["heads"]
            target_heads = rows_by_state[target_state]["heads"]
            source_revision = (
                source_heads[0]["revision"]
                if len(source_heads) == 1 else None
            )
            already_promoted = source_revision is not None and any(
                source_revision in head["parents"] for head in target_heads
            )
            transition_rows.append({
                "relation": transition_root,
                "source_state": source_state,
                "source_name": state_names[source_state],
                "target_state": target_state,
                "target_name": state_names[target_state],
                "source_revision": source_revision,
                "ready": (
                    source_revision is not None and not already_promoted
                ),
                "already_promoted": already_promoted,
                "required_evidence": [
                    member.participant_id for member in transition
                    if member.role_id
                    == lifecycle.role("required-evidence")
                ],
                "court": registry.resource_lifecycle_court_root,
            })
        projected["lifecycle"] = {
            "manifest": active.manifest_root,
            "content_interface": active.content_interface_root,
            "release_scoped": scoped_release is not None,
            "history": history_rows,
            "states": state_rows,
            "transitions": transition_rows,
        }
    else:
        projected["lifecycle"] = None
    operational = registry.standard_library.state_machine_protocol
    if operational.root_id in capabilities:
        machine = read_instance_state_machine(
            snapshot, protocol, operational, root_id
        )
        admitted = []
        for transition_root in machine.transition_roots:
            transition = read_transition(
                snapshot, operational, transition_root
            )
            if transition.from_state_root != machine.current_state_root:
                continue
            evidence_types = [
                {
                    "root": evidence_type,
                    "label": _text(snapshot, evidence_type),
                }
                for evidence_type in transition.required_evidence_type_roots
            ]
            evidence_admissions = [
                {
                    "root": admission.root_id,
                    "evidence_type": admission.evidence_type_root,
                    "evidence_label": _text(
                        snapshot, admission.evidence_type_root
                    ),
                    "issuer": admission.issuer_root,
                    "issuer_label": _text(snapshot, admission.issuer_root),
                }
                for admission in (
                    read_evidence_admission(snapshot, operational, root)
                    for root in transition.required_evidence_admission_roots
                )
            ]
            event_label = _text(snapshot, transition.event_root)
            permission_definition = (
                registry.standard_library.governed_domains.definitions[
                    "permission-request"
                ].definition_root
            )
            user_decision = (
                definition_root == permission_definition
                and event_label in {"approve", "reject", "cancel"}
                and [item["label"] for item in evidence_types]
                == ["user decision"]
            )
            adapter_execute = (
                definition_root == permission_definition
                and event_label == "execute"
                and [item["label"] for item in evidence_types]
                == ["execution admission"]
            )
            control_root = None
            if (
                interaction_subject_root is not None
                and (not evidence_types or user_decision)
            ):
                control_root = _operational_transition_control_root(
                    interaction_subject_root,
                    root_id,
                    transition.event_root,
                    machine.current_state_root,
                )
            admitted.append({
                "transition": transition.root_id,
                "event": transition.event_root,
                "event_label": event_label,
                "to_state": transition.to_state_root,
                "to_state_label": _text(snapshot, transition.to_state_root),
                "required_evidence_types": evidence_types,
                "required_evidence_admissions": evidence_admissions,
                "user_decision": user_decision,
                "adapter_execute": adapter_execute,
                "control": control_root,
            })
        events = machine_history(snapshot, operational, machine.root_id)
        projected["operational"] = {
            "machine": machine.root_id,
            "current_state": machine.current_state_root,
            "current_state_label": _text(
                snapshot, machine.current_state_root
            ),
            "admitted_transitions": admitted,
            "history": [
                {
                    "root": event.root_id,
                    "event": event.event_root,
                    "event_label": _text(snapshot, event.event_root),
                    "from_state": event.from_state_root,
                    "from_state_label": _text(snapshot, event.from_state_root),
                    "to_state": event.to_state_root,
                    "to_state_label": _text(snapshot, event.to_state_root),
                    "actor": event.actor_root,
                    "context": list(event.context_roots),
                    "timestamp": _text(snapshot, event.timestamp_root),
                    "evidence": list(event.evidence_roots),
                }
                for event in events
            ],
        }
    else:
        projected["operational"] = None
    return projected


def _relation_backed_canvas_roots(
    snapshot: Snapshot,
    registry: UniversalApplicationRegistry,
    visible_roots: tuple[str, ...],
) -> frozenset[str]:
    """Resolve internal relation roots exposed by visible role interfaces."""
    owners: dict[str, str] = {}
    for owner_root in visible_roots:
        assembly = _instance_projection(snapshot, registry, owner_root)
        if assembly is None:
            continue
        for interface in assembly["interfaces"]:
            if interface["mode"] != "relation-role":
                continue
            relation_root = str(interface["target"])
            previous = owners.setdefault(relation_root, owner_root)
            if previous != owner_root:
                raise InvalidCell(
                    "one relation-backed root is exposed by multiple assemblies"
                )
    return frozenset(owners)


def _project_relation_definition_contract(
    snapshot: Snapshot,
    registry: UniversalApplicationRegistry,
    definition_root: str,
    visible_roots: tuple[str, ...],
    visible_labels: Mapping[str, str],
) -> dict[str, object] | None:
    """Project a released generic relation contract into Build-lens controls."""
    definition = read_definition(
        snapshot, registry.assembly_protocol, definition_root
    )
    protocol_roots = []
    for capability_root in definition.capability_roots:
        try:
            open_relation_contract_protocol(
                snapshot, capability_root, budget=100_000
            )
        except InvalidCell:
            continue
        protocol_roots.append(capability_root)
    if not protocol_roots:
        return None
    authority = resolve_relation_contract_authority(
        snapshot,
        capability_roots=definition.capability_roots,
        rule_roots=definition.rule_roots,
        budget=100_000,
    )
    choices = []
    for root_id in visible_roots:
        cell = snapshot.cells[root_id]
        choices.append({
            "id": root_id,
            "label": visible_labels.get(root_id, _humanize_root_id(root_id)),
            "terminal": (
                cell.link0 == NULL_CELL_ID and cell.link1 == NULL_CELL_ID
            ),
            "atom_bytes": len(cell.atom),
        })
    roles = []
    fixed_bindings = []
    for constraint in authority.contract.constraints:
        fixed = constraint.fixed_participant_root
        eligible = []
        if fixed is None:
            for choice in choices:
                if (
                    constraint.terminal_atom_maximum is not None
                    and (
                        not choice["terminal"]
                        or choice["atom_bytes"]
                        > constraint.terminal_atom_maximum
                    )
                ):
                    continue
                eligible.append({
                    "id": choice["id"],
                    "label": choice["label"],
                })
        else:
            fixed_bindings.append({
                "role": constraint.participant_role,
                "participant": fixed,
            })
        roles.append({
            "constraint": constraint.root_id,
            "role": constraint.participant_role,
            "label": _text(
                snapshot, constraint.participant_role
            ).replace("-", " ").replace("_", " ").capitalize(),
            "minimum": constraint.minimum,
            "maximum": constraint.maximum,
            "fixed": (
                {
                    "id": fixed,
                    "label": (
                        _text(snapshot, fixed)
                        if snapshot.cells[fixed].atom
                        else _humanize_root_id(fixed)
                    ),
                }
                if fixed is not None else None
            ),
            "terminal_atom_maximum": constraint.terminal_atom_maximum,
            "choices": eligible,
        })
    return {
        "protocol": authority.protocol.root_id,
        "contract": authority.contract.root_id,
        "roles": roles,
        "fixed_bindings": fixed_bindings,
        "complete": all(
            constraint.minimum == 0
            or constraint.fixed_participant_root is not None
            for constraint in authority.contract.constraints
        ),
    }


def _relation_composer_default_entries(
    contract: Mapping[str, object],
    *,
    session_root: str,
    definition_root: str,
) -> tuple[RelationComposerEntry, ...]:
    entries = []
    for role in contract["roles"]:
        if bool(role["fixed"]):
            continue
        for role_index in range(int(role["minimum"])):
            identity = hashlib.sha256("|".join((
                session_root,
                definition_root,
                str(role["role"]),
                str(role_index),
            )).encode("utf-8")).hexdigest()[:32]
            entries.append(RelationComposerEntry(
                "app:relation-composer-entry:%s" % identity,
                str(role["role"]),
                None,
                len(entries),
            ))
    return tuple(entries)


def _relation_composer_control_root(
    session_root: str,
    definition_root: str,
    operation: str,
    *argument_roots: str,
) -> str:
    if operation not in _RELATION_COMPOSER_OPERATION_ROOTS:
        raise InvalidCell("relation-composer control operation is invalid")
    digest = hashlib.sha256("\0".join((
        session_root, definition_root, operation, *argument_roots,
    )).encode("utf-8")).hexdigest()[:32]
    return "app:relation-composer-control:%s:%s" % (operation, digest)


def _project_relation_composer(
    snapshot: Snapshot,
    registry: UniversalApplicationRegistry,
    definition: Mapping[str, object],
    view_session: ApplicationViewSession,
) -> dict[str, object]:
    """Render one session-owned relation draft through the released template."""
    contract = definition.get("composition_contract")
    if not isinstance(contract, Mapping):
        raise InvalidCell("relation composer definition has no contract")
    draft = read_relation_composer_draft(
        snapshot, registry.relation_composer_protocol, view_session.root_id
    )
    if draft is None or draft.definition_root != definition["id"]:
        entries = _relation_composer_default_entries(
            contract,
            session_root=view_session.root_id,
            definition_root=str(definition["id"]),
        )
        draft_root = None
        draft_x = draft_y = None
    else:
        entries = draft.entries
        draft_root = draft.root_id
        draft_x, draft_y = draft.x, draft.y

    roles_by_root = {
        str(role["role"]): role for role in contract["roles"]
    }
    if any(entry.role_root not in roles_by_root for entry in entries):
        raise InvalidCell("relation-composer draft uses an undeclared role")
    by_role: dict[str, list[RelationComposerEntry]] = {
        role_root: [] for role_root in roles_by_root
    }
    for entry in entries:
        by_role[entry.role_root].append(entry)

    role_projections = []
    bindings = list(contract["fixed_bindings"])
    complete = True
    for role in contract["roles"]:
        role_root = str(role["role"])
        minimum = int(role["minimum"])
        maximum = int(role["maximum"])
        role_entries = by_role[role_root]
        if role["fixed"] is not None:
            if role_entries:
                raise InvalidCell("fixed relation role has editable draft entries")
            count = 1
        else:
            count = sum(
                entry.participant_root is not None for entry in role_entries
            )
            if len(role_entries) < minimum or len(role_entries) > maximum:
                raise InvalidCell("relation-composer draft cardinality drifted")
        if count < minimum or count > maximum:
            complete = False
        choice_index = {
            str(choice["id"]): str(choice["label"])
            for choice in role["choices"]
        }
        projected_entries = []
        for role_index, entry in enumerate(role_entries):
            participant = entry.participant_root
            if participant is not None and participant not in choice_index:
                raise InvalidCell(
                    "relation-composer participant left the authorized scope"
                )
            if participant is not None:
                bindings.append({
                    "role": role_root,
                    "participant": participant,
                })
            entry_key = "relation-composer:entry:%s" % entry.root_id
            projected_entries.append({
                "id": entry.root_id,
                "key": entry_key,
                "definition": definition["id"],
                "role": role_root,
                "value": participant or "",
                "label": "%s participant %s" % (
                    role["label"], role_index + 1
                ),
                "placeholder_selected": participant is None,
                "remove_disabled": len(role_entries) <= minimum,
                "remove_control": _relation_composer_control_root(
                    view_session.root_id,
                    str(definition["id"]),
                    "remove",
                    role_root,
                    entry.root_id,
                ),
                "select_control": _relation_composer_control_root(
                    view_session.root_id,
                    str(definition["id"]),
                    "select",
                    role_root,
                    entry.root_id,
                ),
                "choices": tuple({
                    "id": str(choice["id"]),
                    "key": "relation-composer:choice:%s:%s" % (
                        entry.root_id, choice["id"]
                    ),
                    "label": str(choice["label"]),
                    "selected": str(choice["id"]) == participant,
                } for choice in role["choices"]),
            })
        requirement = (
            str(minimum) if minimum == maximum
            else "%s-%s" % (minimum, maximum)
        )
        role_projections.append({
            "role": role_root,
            "key": "relation-composer:role:%s" % role_root,
            "requirement": "%s  /  %s" % (role["label"], requirement),
            "minimum": minimum,
            "maximum": maximum,
            "fixed": role["fixed"] is not None,
            "fixed_label": (
                str(role["fixed"]["label"])
                if role["fixed"] is not None else ""
            ),
            "entries": tuple(projected_entries),
            "can_add": role["fixed"] is None and len(role_entries) < maximum,
            "add_control": _relation_composer_control_root(
                view_session.root_id,
                str(definition["id"]),
                "add",
                role_root,
            ),
            "unavailable": role["fixed"] is None and not role["choices"],
        })
    projection = {
        "definition": definition["id"],
        "draft": draft_root,
        "x": draft_x,
        "y": draft_y,
        "name": definition["name"],
        "roles": tuple(role_projections),
        "complete": complete,
        "bindings": tuple(bindings),
        "position_control": str(definition["id"]),
        "create_control": _relation_composer_control_root(
            view_session.root_id,
            str(definition["id"]),
            "create",
        ),
    }
    projection["descriptor"] = render_view_template(
        snapshot,
        registry.view_template_protocol,
        RELATION_COMPOSER_VIEW_TEMPLATE_ROOT,
        projection,
    )
    return projection


def _project_current_relation_composer(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    view_session: ApplicationViewSession,
    definition_root: str,
) -> dict[str, object]:
    snapshot = store.snapshot()
    visible_roots, _relation_roots, property_roots = _session_canvas_roots(
        snapshot, registry, view_session
    )
    property_index = _property_index(snapshot, registry, property_roots)
    labels = {}
    for root_id in visible_roots:
        labelled = _rows_by_label(
            snapshot, property_index.get(root_id, ())
        )
        title_row = labelled.get("title") or labelled.get("key")
        labels[root_id] = (
            _text(snapshot, title_row.value_root)
            if title_row is not None
            else _scope_label(snapshot, registry, root_id)
        )
    catalog = {
        item["id"]: item for item in _project_standard_catalog(
            store, snapshot, registry
        )
    }
    definition = catalog.get(definition_root)
    if definition is None:
        raise InvalidCell("relation composer definition is not released")
    contract = _project_relation_definition_contract(
        snapshot,
        registry,
        definition_root,
        visible_roots,
        labels,
    )
    if contract is None:
        raise InvalidCell("definition has no relation-composition contract")
    return _project_relation_composer(
        snapshot,
        registry,
        {**definition, "composition_contract": contract},
        view_session,
    )


def update_universal_relation_composer(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    definition_root: str,
    action: str,
    *,
    role_root: str | None = None,
    entry_root: str | None = None,
    participant_root: str | None = None,
    x: float | None = None,
    y: float | None = None,
    mutation_route: str = "/api/universal/interaction",
    authentication_context: object | None = None,
) -> tuple[dict[str, object], int]:
    """Commit one bounded relation-draft edit and return its graph view."""
    if action not in {
        "initialize", "add", "remove", "select", "position", "reset"
    }:
        raise InvalidCell("relation-composer action is not admitted")
    snapshot = store.snapshot()
    view_session, context = _view_session_for_context(
        registry, authentication_context
    )
    _authorize(
        snapshot,
        registry,
        "catalog.configure",
        object_root=definition_root,
        authentication_context=context,
        definition_root=definition_root,
    )
    base = _project_current_relation_composer(
        store, registry, view_session, definition_root
    )
    snapshot = store.snapshot()
    draft = read_relation_composer_draft(
        snapshot, registry.relation_composer_protocol, view_session.root_id
    )
    if draft is None or draft.definition_root != definition_root:
        entries = list(_relation_composer_default_entries(
            {"roles": base["roles"]},
            session_root=view_session.root_id,
            definition_root=definition_root,
        ))
        draft_x = draft_y = None
    else:
        entries = list(draft.entries)
        draft_x, draft_y = draft.x, draft.y

    role_projection = next((
        role for role in base["roles"] if role["role"] == role_root
    ), None)
    if action in {"add", "remove", "select"} and role_projection is None:
        raise InvalidCell("relation-composer role is not in the contract")
    if action == "reset":
        entries = list(_relation_composer_default_entries(
            {"roles": base["roles"]},
            session_root=view_session.root_id,
            definition_root=definition_root,
        ))
    elif action == "add":
        if not role_projection["can_add"]:
            raise InvalidCell("relation-composer role is already at maximum")
        entries.append(new_relation_composer_entry(role_root, len(entries)))
    elif action in {"remove", "select"}:
        matched = next((
            entry for entry in entries if entry.root_id == entry_root
        ), None)
        if matched is None or matched.role_root != role_root:
            raise InvalidCell("relation-composer entry is outside its role")
        if action == "remove":
            if len(role_projection["entries"]) <= role_projection["minimum"]:
                raise InvalidCell("relation-composer role is already at minimum")
            entries.remove(matched)
        else:
            admitted = {
                choice["id"] for entry in role_projection["entries"]
                for choice in entry["choices"]
            }
            if participant_root in (None, ""):
                selected_participant = None
            elif participant_root not in admitted:
                raise InvalidCell(
                    "relation-composer participant is not an authorized choice"
                )
            else:
                selected_participant = participant_root
            entries[entries.index(matched)] = RelationComposerEntry(
                matched.root_id,
                matched.role_root,
                selected_participant,
                matched.order,
            )
    elif action == "position":
        if x is None or y is None:
            raise InvalidCell("relation-composer position is incomplete")
        draft_x, draft_y = float(x), float(y)
    entries = [
        RelationComposerEntry(
            entry.root_id, entry.role_root, entry.participant_root, index
        )
        for index, entry in enumerate(entries)
    ]
    patch = prepare_relation_composer_draft(
        snapshot,
        registry.relation_composer_protocol,
        view_session.root_id,
        definition_root,
        entries,
        x=draft_x,
        y=draft_y,
    )
    create = list(patch.create)
    replacements = {cell.id: cell for cell in patch.replace}
    if patch.root_id not in snapshot.cells:
        session_patch = prepare_append_relation_members(
            snapshot,
            view_session.root_id,
            ((registry.roles["relation"], patch.root_id),),
            budget=100_000,
        )
        application_patch = prepare_append_relation_members(
            snapshot,
            registry.application_root,
            ((registry.roles["member"], patch.root_id),),
            budget=100_000,
        )
        create.extend((*session_patch.create, *application_patch.create))
        for cell in (*session_patch.replace, *application_patch.replace):
            if cell.id in replacements and replacements[cell.id] != cell:
                raise InvalidCell("relation-composer attachment patches conflict")
            replacements[cell.id] = cell
    if not create and not replacements:
        revision = snapshot.revision
    else:
        revision = _commit_universal_user_change(
            store,
            registry,
            view_session,
            context,
            snapshot,
            route=mutation_route,
            command_name="catalog.configure",
            authorization_scope_root=definition_root,
            create=create,
            replace=replacements.values(),
        )
    return (
        _project_current_relation_composer(
            store, registry, view_session, definition_root
        ),
        revision,
    )


@_with_canvas_interface_projection_scope
@with_relation_projection_scope
@with_catalog_verification_scope
def _project_session_action_history(
    snapshot: Snapshot,
    registry: UniversalApplicationRegistry,
    view_session: ApplicationViewSession,
) -> dict[str, object]:
    """Project the session's inspectable transactions without exposing IDs by default."""
    state = history_state(
        snapshot,
        registry.change_history_protocol,
        view_session.action_history_root,
    )
    members = read_relation(
        snapshot, view_session.action_history_root, budget=100_000
    )
    if any(
        member.role_id != registry.change_history_protocol.role("transaction")
        for member in members
    ):
        raise InvalidCell("action history contains a non-transaction member")
    route_keys = {
        root: key for key, root in registry.application_http_route_roots.items()
    }
    transactions = {
        member.participant_id: read_change_transaction(
            snapshot,
            registry.change_history_protocol,
            member.participant_id,
        )
        for member in members
    }
    rows = []
    for transaction_root in reversed(tuple(transactions)):
        transaction = transactions[transaction_root]
        route = route_keys.get(transaction.operation_root, "")
        path = route.split(" ", 1)[-1] if route else ""
        operation = (
            path.rsplit("/", 1)[-1].replace("-", " ").strip().title()
            if path else "Graph change"
        )
        if transaction.undo_of is not None:
            state_label = "undo"
        elif transaction.redo_of is not None:
            state_label = "redo"
        elif transaction.root_id in state.applied_roots:
            state_label = "applied"
        elif transaction.root_id in state.redo_roots:
            state_label = "undone"
        else:
            raise InvalidCell("action history transaction has no derived state")
        rows.append({
            "root": transaction.root_id,
            "operation": operation,
            "route": route,
            "state": state_label,
            "timestamp": transaction.timestamp,
            "change_count": len(transaction.changes),
            "capability": (
                _text(snapshot, transaction.authority_root)
                if transaction.authority_root is not None else "legacy"
            ),
            "scope_count": len(transaction.scope_roots),
            "interface": transaction.interface_root,
        })
    return {
        "root": view_session.action_history_root,
        "can_undo": state.undo_root is not None,
        "can_redo": state.redo_root is not None,
        "transactions": rows,
    }


@_with_canvas_interface_projection_scope
@with_relation_projection_scope
@with_catalog_verification_scope
@with_view_template_projection_scope
def _project_universal_canvas_interpreter(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    *,
    authentication_context: object | None = None,
    scope_materialization: UniversalScopeMaterialization | None = None,
) -> dict[str, object]:
    """Interpret the graph-defined canvas and Properties lens for the browser."""
    snapshot = store.dense_snapshot()
    verify_released_catalog_stable(
        store,
        snapshot,
        registry.assembly_protocol,
        registry.standard_library.catalog_root,
    )
    authority = registry.authorization
    authority_snapshot = verify_relationship_authority_snapshot(
        snapshot,
        authority.identity_protocol,
        authority.relationship_broker,
        now=time.time(),
    )
    view_session, context = _view_session_for_context(
        registry, authentication_context
    )
    if scope_materialization is None:
        (
            visible_roots,
            relation_roots,
            property_scopes,
            scope_trail,
        ) = _session_canvas_roots(
            snapshot,
            registry,
            view_session,
            authority_snapshot=authority_snapshot,
            include_trail=True,
        )
    else:
        if (
            type(scope_materialization) is not UniversalScopeMaterialization
            or scope_materialization.revision != snapshot.revision
            or scope_materialization.session_root != view_session.root_id
            or scope_materialization.subject_root != view_session.subject_root
        ):
            raise InvalidCell(
                "scope materialization is outside the exact view revision"
            )
        structural_trail = _read_view_scope_trail_structure(
            snapshot, registry, view_session
        )
        if scope_materialization.trail != structural_trail:
            raise InvalidCell("scope materialization trail drifted")
        visible_roots = scope_materialization.visible_roots
        relation_roots = scope_materialization.relation_roots
        property_scopes = scope_materialization.property_roots
        scope_trail = scope_materialization.trail
        projected_roots = (
            *visible_roots,
            *relation_roots,
            *property_scopes,
        )
        if (
            len(projected_roots) != len(set(projected_roots))
            or any(root_id not in snapshot.cells for root_id in projected_roots)
        ):
            raise InvalidCell(
                "scope materialization contains invalid graph identities"
            )
    if len(scope_trail) == 1:
        resource_bindings = _require_resource_audience_authority(
            snapshot,
            registry,
            view_session.subject_root,
            visible_roots,
            authority_snapshot=authority_snapshot,
        )
    else:
        inherited_root = scope_trail[1]
        inherited_binding = _require_resource_audience_authority(
            snapshot,
            registry,
            view_session.subject_root,
            (inherited_root,),
            authority_snapshot=authority_snapshot,
        )[inherited_root]
        composition_roots = {
            root_id for root_id in visible_roots
            if _is_universal_composition(snapshot, registry, root_id)
        }
        composition_bindings = _require_resource_audience_authority(
            snapshot,
            registry,
            view_session.subject_root,
            tuple(composition_roots),
            authority_snapshot=authority_snapshot,
        ) if composition_roots else {}
        active_relationship_roots = {
            relationship.root_id
            for relationship in authority_snapshot.active_relationships
        }
        exact_resource_roots = tuple(
            root_id for root_id in visible_roots
            if _resource_audience_binding_root(root_id)
            in active_relationship_roots
        )
        exact_resource_bindings = _require_resource_audience_authority(
            snapshot,
            registry,
            view_session.subject_root,
            exact_resource_roots,
            authority_snapshot=authority_snapshot,
        ) if exact_resource_roots else {}
        resource_bindings = {
            root_id: (
                exact_resource_bindings[root_id]
                if root_id in exact_resource_bindings
                else composition_bindings[root_id]
                if root_id in composition_roots
                else inherited_binding
            )
            for root_id in visible_roots
        }

    def release_scope_for(root_id: str):
        _binding, state_root, owner_root, release_root = resource_bindings[
            root_id
        ]
        if view_session.subject_root in (
            owner_root, authority.subject_root
        ):
            return None
        return state_root, release_root
    require_authorizations(
        snapshot,
        authority.protocol,
        authority.policy_root,
        authority.broker,
        context,
        (
            AuthorizationRequest(
                action_root=authority.protocol.actions["read"],
                object_root=authority.shell_scope_root,
                resource_lineage_roots=(authority.scope_root,),
                purpose_root=authority.purpose_root,
                classification_root=authority.classification_root,
                audience_root=authority.audience_root,
                now=authority_snapshot.evaluated_at,
            ),
            AuthorizationRequest(
                action_root=authority.protocol.actions["inspect"],
                object_root=view_session.root_id,
                resource_lineage_roots=(
                    authority.personal_view_scope_root,
                    authority.scope_root,
                ),
                purpose_root=authority.purpose_root,
                classification_root=authority.classification_root,
                audience_root=authority.audience_root,
                now=authority_snapshot.evaluated_at,
            ),
            *(
            AuthorizationRequest(
                action_root=authority.protocol.actions["read"],
                object_root=resource_root,
                resource_lineage_roots=tuple(dict.fromkeys((
                    *scope_trail[1:], authority.scope_root,
                ))),
                purpose_root=authority.purpose_root,
                classification_root=authority.classification_root,
                audience_root=authority.audience_root,
                now=authority_snapshot.evaluated_at,
            )
            for resource_root in visible_roots
            ),
        ),
        resolver_state=authority_snapshot,
    )
    lens_members = read_relation(
        snapshot, view_session.properties_lens_root, budget=100_000
    )
    focus_root = _one_for_role(lens_members, registry.roles["focus"])
    focus_projection = read_focus(
        snapshot, registry.attention_protocol, focus_root
    )
    if (
        focus_projection.session_root != view_session.root_id
        or focus_projection.actor_root != view_session.subject_root
        or focus_projection.state_root
        != registry.attention_protocol.state("active")
    ):
        raise InvalidCell("Properties lens does not point to the active view focus")
    selected_root = focus_projection.primary_root
    selection_members = read_relation(
        snapshot, view_session.selection_state_root, budget=100_000
    )
    selected_roots = frozenset(
        member.participant_id
        for member in selection_members
        if member.role_id == registry.roles["selected"]
    )
    lens_property_scopes = tuple(
        member.participant_id
        for member in lens_members
        if member.role_id == registry.roles["scope"]
    )
    if not set(property_scopes).issubset(lens_property_scopes):
        raise InvalidCell("active canvas properties leave the Properties lens")
    property_index = _property_index(
        snapshot,
        registry,
        (
            property_scopes
            if scope_materialization is not None
            else lens_property_scopes
        ),
    )
    personal_presentation_bindings = _personal_presentation_bindings(
        snapshot, registry, view_session
    )
    presentation_by_property = {
        (binding.owner_root, binding.label_root): binding
        for binding in personal_presentation_bindings
    }

    def effective_property_value(row: PropertyProjection) -> str:
        binding = presentation_by_property.get((
            row.owner_root, row.label_root
        ))
        if binding is None:
            return _text(snapshot, row.value_root)
        if binding.source_root != row.relation_root:
            raise InvalidCell("personal presentation source left its property")
        return binding.value or _text(snapshot, row.value_root)

    viewport = {
        name: float(_text(snapshot, reference.value_root))
        for name, reference in view_session.viewport_properties.items()
    }
    registered_interfaces = _registered_canvas_interfaces(snapshot, registry)
    selected_canvas_interface = next((
        interface for interface in registered_interfaces
        if interface["id"] == selected_root
    ), None)
    interfaces_by_owner: dict[str, list[dict[str, object]]] = {}
    for interface in registered_interfaces:
        interfaces_by_owner.setdefault(
            str(interface["owner"]), []
        ).append(interface)

    nodes = []
    for index, root_id in enumerate(visible_roots):
        rows = property_index.get(root_id, ())
        labelled = _rows_by_label(snapshot, rows)
        title_row = labelled.get("title") or labelled.get("key")
        title = (
            _text(snapshot, title_row.value_root)
            if title_row else _scope_label(snapshot, registry, root_id)
        )
        x_row = labelled.get("position_x")
        y_row = labelled.get("position_y")
        color_row = labelled.get("color")
        assembly = _instance_projection(
            snapshot,
            registry,
            root_id,
            release_scope=release_scope_for(root_id),
        )
        declared_ports = [
            {
                **interface,
                "connectable": (
                    interface["side"] == "source"
                    and not interface["read_only"]
                ),
            }
            for interface in interfaces_by_owner.get(root_id, ())
        ]
        composition = _is_universal_composition(
            snapshot, registry, root_id
        )
        composition_members = (
            read_relation(snapshot, root_id, budget=_SCOPE_MEMBER_LIMIT)
            if composition else ()
        )
        composition_ports = []
        for member in composition_members:
            if (
                member.role_id
                != registry.assembly_protocol.role("interface")
            ):
                continue
            interface = _project_canvas_interface(
                snapshot,
                registry.assembly_protocol,
                member.participant_id,
            )
            if (
                interface is None
                or interface["owner"] != root_id
                or not _is_derived_composition_interface(
                    snapshot, registry, member.participant_id
                )
            ):
                raise InvalidCell(
                    "composition boundary is not an exact derived interface"
                )
            composition_ports.append({
                **interface,
                "connectable": False,
                "derived": True,
            })
        nodes.append({
            "id": root_id,
            "label": title,
            "x": (
                float(_text(snapshot, x_row.value_root))
                if x_row else 60.0 + (index % 5) * 244.0
            ),
            "y": (
                float(_text(snapshot, y_row.value_root))
                if y_row else 92.0 + (index // 5) * 174.0
            ),
            "color": (
                effective_property_value(color_row)
                if color_row else _DEFAULT_NODE_PRESENTATION_COLOR
            ),
            "selected": root_id in selected_roots,
            "composition": composition,
            "openable": bool(_relation_members_or_none(snapshot, root_id)),
            "physical": {
                "link0": snapshot.cells[root_id].link0,
                "link1": snapshot.cells[root_id].link1,
                "atom_bytes": len(snapshot.cells[root_id].atom),
            },
            "assembly": assembly,
            "ports": [
                {
                    **interface,
                    "side": "target",
                    "connectable": interface["mode"] == "connection",
                }
                for interface in (assembly["interfaces"] if assembly else [])
            ] + declared_ports + composition_ports,
            "member_count": (
                sum(
                    member.role_id == registry.roles["member"]
                    for member in composition_members
                )
                if composition else (
                    len(_relation_members_or_none(snapshot, root_id) or ())
                    if assembly is None else assembly["part_count"]
                )
            ),
        })

    node_index = {node["id"]: node for node in nodes}

    def enrich_relation_role_interface(
        interface: dict[str, object],
    ) -> None:
        """Attach exact visible candidates to one released role interface."""
        maximum_atom = interface["terminal_atom_maximum"]
        fixed_participant = interface["fixed_participant"]
        interface["choices"] = (
            [{
                "id": fixed_participant,
                "label": _scope_label(
                    snapshot, registry, str(fixed_participant)
                ),
            }]
            if fixed_participant is not None else [
                {
                    "id": node["id"],
                    "label": node["label"],
                }
                for node in nodes
                if (
                    maximum_atom is None
                    or (
                        node["physical"]["link0"] == NULL_CELL_ID
                        and node["physical"]["link1"] == NULL_CELL_ID
                        and node["physical"]["atom_bytes"] <= maximum_atom
                    )
                )
            ]
        )
        interface.update({
            "owner": selected_root,
            "append_control": _relation_member_control_root(
                view_session.subject_root,
                str(interface["id"]),
                _RELATION_MEMBER_OPERATION_ROOTS["append"],
            ),
            "append_event_fact_input": _EVENT_FACT_ROOTS[
                "participant_index"
            ],
        })
        for item in interface["items"]:
            participant = node_index.get(item["participant"])
            item["label"] = (
                participant["label"]
                if participant is not None
                else _humanize_root_id(item["participant"])
            )
            item.update({
                "replace_control": _relation_member_control_root(
                    view_session.subject_root,
                    str(item["incidence"]),
                    _RELATION_MEMBER_OPERATION_ROOTS["replace"],
                ),
                "replace_event_fact_input": _EVENT_FACT_ROOTS[
                    "participant_index"
                ],
                "remove_control": _relation_member_control_root(
                    view_session.subject_root,
                    str(item["incidence"]),
                    _RELATION_MEMBER_OPERATION_ROOTS["remove"],
                ),
            })

    relation_backed_interfaces: dict[
        str, list[tuple[str, Mapping[str, object]]]
    ] = {}
    for node in nodes:
        assembly = node["assembly"]
        if assembly is None:
            continue
        for interface in assembly["interfaces"]:
            if interface["mode"] != "relation-role":
                continue
            enrich_relation_role_interface(interface)
            matching_port = next(
                port for port in node["ports"]
                if port["id"] == interface["id"]
            )
            matching_port.update(interface)
            relation_backed_interfaces.setdefault(
                str(interface["target"]), []
            ).append((node["id"], interface))
    for relation_root, exposed in relation_backed_interfaces.items():
        if len({owner for owner, _interface in exposed}) != 1:
            raise InvalidCell(
                "one relation-backed root is exposed by multiple canvas nodes"
            )

    wires = []
    for root_id in relation_roots:
        members = read_relation(snapshot, root_id, budget=256)
        source_members = tuple(
            member for member in members
            if member.role_id == registry.roles["source"]
        )
        target_members = tuple(
            member for member in members
            if member.role_id == registry.roles["target"]
        )
        if len(source_members) != 1 or len(target_members) != 1:
            continue
        source_member = source_members[0]
        target_member = target_members[0]
        source, source_interface = _canvas_endpoint(
            snapshot, registry, source_member, visible_roots
        )
        target, target_interface = _canvas_endpoint(
            snapshot, registry, target_member, visible_roots
        )
        if source not in visible_roots or target not in visible_roots:
            continue
        authorities = [
            member.participant_id
            for member in members if member.role_id == registry.roles["authority"]
        ]
        rows = property_index.get(root_id, ())
        labelled = _rows_by_label(snapshot, rows)
        wires.append({
            "id": root_id,
            "source": source,
            "target": target,
            "source_interface": (
                source_interface["id"] if source_interface else None
            ),
            "target_interface": (
                target_interface["id"] if target_interface else None
            ),
            "source_incidence": source_member.incidence_id,
            "target_incidence": target_member.incidence_id,
            "selected": root_id == selected_root,
            "authority_roots": authorities,
            "color": (
                effective_property_value(labelled["color"])
                if "color" in labelled else "#5fb3b3"
            ),
            "width": (
                float(_text(snapshot, labelled["width"].value_root))
                if "width" in labelled else 1.35
            ),
            "dash": (
                _text(snapshot, labelled["dash"].value_root)
                if "dash" in labelled else ""
            ),
            "context": (
                root_id == selected_root
                or source == selected_root
                or target == selected_root
                or (
                    source_interface is not None
                    and source_interface["id"] == selected_root
                )
                or (
                    target_interface is not None
                    and target_interface["id"] == selected_root
                )
            ),
            "directed": True,
            "nary": False,
            "segment": root_id,
            "role": None,
        })

    for relation_root, exposed in relation_backed_interfaces.items():
        owner_root = exposed[0][0]
        owner = node_index[owner_root]
        for _owner_root, interface in exposed:
            for item in interface["items"]:
                participant_root = item["participant"]
                if participant_root not in node_index:
                    continue
                wires.append({
                    "id": relation_root,
                    "segment": item["incidence"],
                    "source": participant_root,
                    "target": owner_root,
                    "source_interface": item["incidence"],
                    "target_interface": interface["id"],
                    "source_incidence": item["incidence"],
                    "target_incidence": item["incidence"],
                    "selected": relation_root == selected_root,
                    "authority_roots": [interface["contract_root"]],
                    "color": owner["color"],
                    "width": 1.35,
                    "dash": "",
                    "context": (
                        relation_root == selected_root
                        or participant_root == selected_root
                        or owner_root == selected_root
                    ),
                    "directed": False,
                    "nary": True,
                    "role": interface["member_role"],
                    "role_label": interface["name"],
                })

                participant = node_index[participant_root]
                if not any(
                    port["id"] == item["incidence"]
                    for port in participant["ports"]
                ):
                    participant["ports"].append({
                        "id": item["incidence"],
                        "name": interface["name"],
                        "side": "source",
                        "mode": "relation-incidence",
                        "connectable": interface["editable"],
                        "owner": owner_root,
                        "relation": relation_root,
                        "interface": interface["id"],
                        "member_role": interface["member_role"],
                        "incidence": item["incidence"],
                        "choices": interface.get("choices", ()),
                    })

    for wire in wires:
        for owner_key, interface_key, side in (
            ("source", "source_interface", "source"),
            ("target", "target_interface", "target"),
        ):
            interface_root = wire[interface_key]
            if not interface_root:
                continue
            node = node_index[wire[owner_key]]
            if any(port["id"] == interface_root for port in node["ports"]):
                continue
            interface = _project_canvas_interface(
                snapshot, registry.assembly_protocol, interface_root
            )
            if interface is None:
                raise InvalidCell("canvas wire interface is not projectable")
            node["ports"].append({
                "id": interface_root,
                "name": interface["name"],
                "side": side,
                "mode": "relation",
                "connectable": side == "source",
            })

    binary_wires = tuple(wire for wire in wires if not wire["nary"])
    port_index = {
        str(port["id"]): (str(node["id"]), port)
        for node in nodes
        for port in node["ports"]
        if type(port.get("id")) is str
    }
    derived_composition_interfaces = frozenset(
        interface_root
        for interface_root in port_index
        if _is_derived_composition_interface(
            snapshot, registry, interface_root
        )
    )
    target_attachment_roots: dict[str, set[str]] = {}
    connection_roots: dict[tuple[str, str], set[str]] = {}
    for wire in binary_wires:
        relation_root = str(wire["id"])
        target_interface = wire.get("target_interface")
        if type(target_interface) is str:
            target_attachment_roots.setdefault(
                target_interface, set()
            ).add(relation_root)
        source_interface = wire.get("source_interface")
        if (
            type(source_interface) is str
            and type(target_interface) is str
        ):
            connection_roots.setdefault(
                (source_interface, target_interface), set()
            ).add(relation_root)

    def topology_choice(owner_root: str, port: Mapping[str, object]):
        return {
            "id": str(port["id"]),
            "owner": owner_root,
            "label": "%s / %s" % (
                node_index[owner_root]["label"], port.get("name") or "Interface"
            ),
        }

    def target_is_available(
        target_port: Mapping[str, object], relation_root: str | None = None
    ) -> bool:
        if target_port.get("target_incidence") is None:
            return True
        attached = target_attachment_roots.get(
            str(target_port.get("id")), set()
        )
        return not attached or attached == {relation_root}

    def connection_exists(
        source_interface: str,
        target_interface: str,
        *,
        except_relation: str | None = None,
    ) -> bool:
        attached = connection_roots.get(
            (source_interface, target_interface), set()
        )
        return bool(
            attached
            if except_relation is None
            else attached - {except_relation}
        )

    def compatible_port_choices(
        *,
        side: str,
        fixed_owner: str,
        fixed_interface: str,
        relation_root: str | None = None,
    ) -> list[dict[str, object]]:
        fixed = port_index.get(fixed_interface)
        if fixed is None:
            return []
        _fixed_port_owner, fixed_port = fixed
        fixed_contract = fixed_port.get("contract_root")
        choices = []
        for candidate_owner, candidate in port_index.values():
            if (
                candidate.get("side") != side
                or candidate_owner == fixed_owner
                or candidate.get("mode") != "connection"
                or str(candidate["id"])
                in derived_composition_interfaces
            ):
                continue
            candidate_contract = candidate.get("contract_root")
            source_contract, target_contract = (
                (candidate_contract, fixed_contract)
                if side == "source" else (fixed_contract, candidate_contract)
            )
            if not _interface_contracts_compatible(
                registry.assembly_protocol,
                str(source_contract) if source_contract is not None else None,
                str(target_contract) if target_contract is not None else None,
            ):
                continue
            source_interface, target_interface = (
                (str(candidate["id"]), fixed_interface)
                if side == "source" else (fixed_interface, str(candidate["id"]))
            )
            if (
                side == "target"
                and not target_is_available(candidate, relation_root)
            ) or connection_exists(
                source_interface,
                target_interface,
                except_relation=relation_root,
            ):
                continue
            choices.append(topology_choice(candidate_owner, candidate))
        choices.sort(key=lambda item: (str(item["label"]), str(item["id"])))
        return choices

    connect_operation = _TOPOLOGY_OPERATION_ROOTS["connect"]
    disconnect_operation = _TOPOLOGY_OPERATION_ROOTS["disconnect"]
    rewire_operation = _TOPOLOGY_OPERATION_ROOTS["rewire"]
    topology_fact_root = _EVENT_FACT_ROOTS["topology_candidate_index"]
    for node in nodes:
        for port in node["ports"]:
            if (
                port.get("side") != "source"
                or port.get("mode") != "connection"
                or port.get("connectable") is not True
                or str(port["id"])
                in derived_composition_interfaces
            ):
                continue
            choices = compatible_port_choices(
                side="target",
                fixed_owner=str(node["id"]),
                fixed_interface=str(port["id"]),
            )
            port.update({
                "connect_control": _topology_control_root(
                    view_session.subject_root,
                    str(port["id"]),
                    connect_operation,
                ),
                "connect_event_fact_input": topology_fact_root,
                "connect_choices": choices,
            })

    for wire in binary_wires:
        wire["disconnect_control"] = _topology_control_root(
            view_session.subject_root,
            str(wire["id"]),
            disconnect_operation,
        )
        for side, fixed_side in (("source", "target"), ("target", "source")):
            incidence_root = wire.get(side + "_incidence")
            interface_root = wire.get(side + "_interface")
            fixed_interface = wire.get(fixed_side + "_interface")
            fixed_owner = wire.get(fixed_side)
            if not all(type(value) is str and value for value in (
                incidence_root, interface_root, fixed_interface, fixed_owner
            )):
                continue
            choices = compatible_port_choices(
                side=side,
                fixed_owner=str(fixed_owner),
                fixed_interface=str(fixed_interface),
                relation_root=str(wire["id"]),
            )
            current = port_index.get(str(interface_root))
            if current is not None and not any(
                choice["id"] == interface_root for choice in choices
            ):
                choices.append(topology_choice(current[0], current[1]))
                choices.sort(
                    key=lambda item: (str(item["label"]), str(item["id"]))
                )
            wire.update({
                side + "_rewire_control": _topology_control_root(
                    view_session.subject_root,
                    str(incidence_root),
                    rewire_operation,
                ),
                side + "_rewire_event_fact_input": topology_fact_root,
                side + "_rewire_choices": choices,
            })
    for node in nodes:
        node["ports"].sort(key=lambda port: (
            0 if port["side"] == "target" else 1,
            port["name"],
            port["id"],
        ))

    contextual_interfaces = {
        interface_root
        for wire in wires
        if wire["context"] or wire["selected"]
        for interface_root in (
            wire.get("source_interface"), wire.get("target_interface")
        )
        if interface_root
    }
    for node in nodes:
        node["connection_count"] = sum(
            wire["source"] == node["id"] or wire["target"] == node["id"]
            for wire in wires
        )
        node["card_descriptor"] = render_view_template(
            snapshot,
            registry.view_template_protocol,
            CANVAS_CARD_TEMPLATE_ROOT,
            node,
        )
        for port in node["ports"]:
            port["descriptor"] = render_view_template(
                snapshot,
                registry.view_template_protocol,
                CANVAS_PORT_TEMPLATE_ROOT,
                {
                    **port,
                    "node_id": node["id"],
                    "selected": port["id"] == selected_root,
                    "context": port["id"] in contextual_interfaces,
                },
            )

    property_rows = property_index.get(selected_root, ())
    properties = []
    if len(selected_roots) > 1:
        owner_order = tuple(sorted(selected_roots))
        rows_by_owner = {
            owner: _unique_property_rows_by_label(
                snapshot, property_index.get(owner, ())
            )
            for owner in owner_order
        }
        common_labels = set.intersection(
            *(set(rows) for rows in rows_by_owner.values())
        ) if rows_by_owner else set()
        primary_owner = (
            selected_root if selected_root in rows_by_owner else owner_order[0]
        )
        ordered_labels = [
            _text(snapshot, row.label_root).strip().casefold()
            for row in property_index.get(primary_owner, ())
        ]
        ordered_labels = list(dict.fromkeys(
            label for label in ordered_labels if label in common_labels
        ))
        ordered_labels.extend(sorted(common_labels - set(ordered_labels)))
        for label_key in ordered_labels:
            rows = tuple(rows_by_owner[owner][label_key] for owner in owner_order)
            relation_roots = tuple(row.relation_root for row in rows)
            value_roots = tuple(row.value_root for row in rows)
            label_roots = tuple(row.label_root for row in rows)
            values = tuple(effective_property_value(row) for row in rows)
            label = _text(snapshot, rows[0].label_root)
            read_only = any(
                member.role_id == registry.roles["read-only"]
                for row in rows
                for member in read_relation(
                    snapshot, row.relation_root, budget=64
                )
            )
            control_root = _property_batch_control_root(
                view_session.subject_root,
                owner_order,
                relation_roots,
                value_roots,
                label_roots,
            )
            editable_property = label != "color" and not read_only
            mixed = len(set(values)) != 1
            properties.append({
                "relation": control_root,
                "relations": list(relation_roots),
                "owner": None,
                "owners": list(owner_order),
                "label": label,
                "label_roots": list(label_roots),
                "value": "Varies" if mixed else values[0],
                "value_root": None,
                "value_roots": list(value_roots),
                "mixed": mixed,
                "batch": True,
                "operation": _PROPERTY_OPERATION_ROOTS["batch-edit"],
                "editable": editable_property,
                "control": control_root if editable_property else None,
                "event_fact_input": (
                    _EVENT_FACT_ROOTS["submitted_value"]
                    if editable_property else None
                ),
                "presentation_editable": False,
                "presentation_control": None,
                "presentation_event_fact_input": None,
                "presentation_binding": None,
                "presentation_source": "Multiple selection",
                "presentation_source_root": control_root,
                "presentation_source_mode": "selection",
                "presentation_revision": None,
                "presentation_reset": False,
                "presentation_reset_control": None,
                "presentation_history": [],
            })
    else:
        for row in property_rows:
            members = read_relation(snapshot, row.relation_root, budget=64)
            label = _text(snapshot, row.label_root)
            presentation_binding = presentation_by_property.get((
                row.owner_root, row.label_root
            ))
            editable_property = label != "color" and not any(
                member.role_id == registry.roles["read-only"]
                for member in members
            )
            presentation_editable = label == "color"
            presentation_control = (
                _appearance_control_root(
                    view_session.subject_root,
                    row.relation_root,
                    _APPEARANCE_OPERATION_ROOTS["preview"],
                )
                if presentation_editable else None
            )
            presentation_reset = bool(
                presentation_binding and presentation_binding.value
            )
            properties.append({
                "relation": row.relation_root,
                "owner": row.owner_root,
                "label": label,
                "value": effective_property_value(row),
                "value_root": row.value_root,
                "mixed": False,
                "batch": False,
                "editable": editable_property,
                "control": row.relation_root if editable_property else None,
                "event_fact_input": (
                    _EVENT_FACT_ROOTS["submitted_value"]
                    if editable_property else None
                ),
                "presentation_editable": presentation_editable,
                "presentation_control": presentation_control,
                "presentation_event_fact_input": (
                    _EVENT_FACT_ROOTS["submitted_value"]
                    if presentation_editable else None
                ),
                "presentation_binding": (
                    presentation_binding.root_id
                    if presentation_binding else None
                ),
                "presentation_source": (
                    "Personal appearance draft"
                    if presentation_binding and presentation_binding.value
                    else "Inherited node appearance"
                ),
                "presentation_source_root": row.relation_root,
                "presentation_source_mode": (
                    "personal-wip"
                    if presentation_binding and presentation_binding.value
                    else "inherited"
                ),
                "presentation_revision": (
                    presentation_binding.revision_root
                    if presentation_binding else None
                ),
                "presentation_reset": presentation_reset,
                "presentation_reset_control": (
                    _appearance_control_root(
                        view_session.subject_root,
                        row.relation_root,
                        _APPEARANCE_OPERATION_ROOTS["reset"],
                    )
                    if presentation_reset else None
                ),
                "presentation_history": (
                    list(presentation_binding.history)
                    if presentation_binding else []
                ),
            })

    selected_identity = registry.authorization.broker.resolve(context)
    authority_focus_roots = _inspectable_authority_relationship_roots(
        snapshot,
        registry,
        selected_identity.subject_root,
        authority_snapshot=authority_snapshot,
    )
    browser_session_focus_roots = _inspectable_browser_session_roots(
        snapshot, registry, selected_identity.subject_root
    )
    view_focus_roots = _inspectable_view_focus_roots(
        snapshot, registry, view_session
    )
    participant_labels = {
        node["id"]: node["label"] for node in nodes
    }
    catalog_sections = list(_validate_node_library_sections(
        snapshot,
        registry.roles,
        registry.standard_library,
        library_root=registry.library_root,
    ))
    catalog_sections = [{
        **section,
        "descriptor": render_view_template(
            snapshot,
            registry.view_template_protocol,
            LIBRARY_SECTION_TEMPLATE_ROOT,
            section,
        ),
    } for section in catalog_sections]
    participant_labels.update({
        str(section["id"]): str(section["label"])
        for section in catalog_sections
    })
    node_labels = {
        node["id"]: node["label"] for node in nodes
    }
    wire_labels = {}
    for wire in wires:
        flow_label = "%s to %s" % (
            node_labels.get(wire["source"], _humanize_root_id(wire["source"])),
            node_labels.get(wire["target"], _humanize_root_id(wire["target"])),
        )
        wire_labels[wire["id"]] = flow_label
        participant_labels[wire["id"]] = flow_label
        if wire.get("source_incidence"):
            participant_labels[wire["source_incidence"]] = (
                "Source endpoint / " + flow_label
            )
        if wire.get("target_incidence"):
            participant_labels[wire["target_incidence"]] = (
                "Target endpoint / " + flow_label
            )
    for interface in registered_interfaces:
        for previous_root in interface.get("previous_roots", ()):
            previous = _project_canvas_interface(
                snapshot, registry.assembly_protocol, previous_root
            )
            if previous is None:
                raise InvalidCell(
                    "public interface predecessor is not projectable"
                )
            related = tuple(previous.get("relation_roots", ()))
            relation_label = (
                wire_labels.get(related[0])
                if len(related) == 1 else None
            )
            participant_labels[previous_root] = (
                "Exact %s endpoint / %s" % (
                    previous["side"],
                    relation_label or previous["name"],
                )
            )
    participant_labels.update({
        registry.application_root: "ArchHub",
        registry.library_root: "Node Library",
        registry.canvas_root: "Canvas",
        registry.map.grand_map_root: "Grand Map",
        registry.assembly_protocol.root_id: "Assembly protocol",
        registry.standard_library.catalog_root: "Released node catalogue",
        registry.adapter_protocol.root_id: "Adapter protocol",
        registry.adapter_catalog_root: "Adapter allowlist",
        registry.device_custody_adapter_root: (
            "Windows hardware device-key custody adapter"
        ),
        registry.attestation_protocol.root_id: "Court attestation protocol",
        registry.resource_lifecycle_court_root: "Resource lifecycle court",
        registry.theme_court_root: "Theme sharing court",
        registry.theme_publish_court_root: "Browser publication court",
        registry.composer_protocol.root_id: "Composer protocol",
        registry.composer_authority.root_id: "Released composer authority",
        registry.authorization.protocol.root_id: "Authorization protocol",
        registry.authorization.policy_root: "Released authorization policy",
        registry.authorization.identity_protocol.root_id: "Identity protocol",
        registry.tenant_configuration_protocol.root_id: (
            "Tenant configuration protocol"
        ),
        registry.tenant_authority_court_root: "Tenant authority court",
        registry.tenant_authority.configuration_root: (
            "Published tenant configuration"
        ),
        registry.tenant_authority.lifecycle_instance_root: (
            "Tenant configuration lifecycle"
        ),
        registry.tenant_authority.published_revision_root: (
            "Published tenant revision"
        ),
        registry.tenant_release_selection.root_id: (
            "Selected tenant release"
        ),
        registry.cloud_route_protocol.root_id: "Cloud route protocol",
        registry.cloud_session_protocol.root_id: "Cloud session protocol",
        registry.browser_session_protocol.root_id: (
            "Browser session protocol"
        ),
        registry.device_custody_protocol.root_id: (
            "Device key custody protocol"
        ),
        registry.native_authentication_protocol.root_id: (
            "Native authentication protocol"
        ),
        registry.attention_protocol.root_id: "Attention and focus protocol",
        registry.ui_protocol.root_id: "Interface protocol",
    })
    if registry.authority_migration_root is not None:
        participant_labels[registry.authority_migration_root] = (
            "Authority generation migration"
        )
    participant_labels.update({
        root: key
        for key, root in registry.application_http_route_roots.items()
    })
    participant_labels.update({
        root: "Browser session"
        for root in browser_session_focus_roots
    })
    participant_labels.update({
        root: (
            "Current focus" if root == focus_projection.root_id
            else _text(snapshot, root)
            if snapshot.cells[root].link0 == NULL_CELL_ID
            and snapshot.cells[root].link1 == NULL_CELL_ID
            else _humanize_root_id(root)
        )
        for root in view_focus_roots
        if root in snapshot.cells
    })
    authority_label_index = _property_index(
        snapshot,
        registry,
        tuple(
            relation_root
            for authority_root in (
                selected_identity.subject_root,
                selected_identity.tenant_root,
                selected_identity.assurance_root,
            )
            for relation_root in registry.root_properties.get(
                authority_root, ()
            )
        ),
    )
    for authority_root in (
        selected_identity.subject_root,
        selected_identity.tenant_root,
        selected_identity.assurance_root,
    ):
        labelled = _rows_by_label(
            snapshot,
            property_index.get(authority_root, ())
            or authority_label_index.get(authority_root, ()),
        )
        title_row = labelled.get("title") or labelled.get("key")
        if title_row is not None:
            participant_labels[authority_root] = _text(
                snapshot, title_row.value_root
            )
        elif (
            authority_root in snapshot.cells
            and snapshot.cells[authority_root].link0 == NULL_CELL_ID
            and snapshot.cells[authority_root].link1 == NULL_CELL_ID
        ):
            value = _text(snapshot, authority_root)
            if value and not value.startswith("external-object-reference:"):
                participant_labels[authority_root] = value
    is_founder = (
        selected_identity.subject_root == registry.authorization.subject_root
    )
    connections = []
    parent_scope_root = scope_trail[-1]
    if selected_root != parent_scope_root:
        parent_members = read_relation(
            snapshot, parent_scope_root, budget=100_000
        )
        for member in parent_members:
            if member.participant_id != selected_root:
                continue
            connections.append({
                "incidence": member.incidence_id,
                "role": _text(snapshot, member.role_id),
                "participant": parent_scope_root,
                "participant_label": _scope_label(
                    snapshot, registry, parent_scope_root
                ),
                "participant_owner": None,
                "participant_interface": None,
                "direction": "inbound",
                "relation": parent_scope_root,
                "editable": False,
                "navigable": (
                    is_founder and parent_scope_root in snapshot.cells
                ),
            })
    registered_obligations = {
        item.root_id: item for item in list_obligations(
            snapshot, registry.attention_protocol
        )
    }
    if not set(registry.core_value_obligation_roots).issubset(
        registered_obligations
    ):
        raise InvalidCell("application Core Value obligations are incomplete")
    core_value_obligations = []
    if is_founder:
        for root in registry.core_value_obligation_roots:
            obligation = registered_obligations[root]
            gap_members = read_relation(
                snapshot, obligation.subject_root, budget=64
            )
            reason_root = _one_for_role(
                gap_members, registry.core_values.roles["why"]
            )
            if reason_root is None:
                raise InvalidCell("Core Value obligation subject has no reason")
            subject_label = _text(snapshot, reason_root)
            priority_label = _text(snapshot, obligation.priority_root)
            state_label = _text(snapshot, obligation.state_root)
            participant_labels[root] = subject_label
            core_value_obligations.append({
                "root": root,
                "subject": obligation.subject_root,
                "label": subject_label,
                "owner": obligation.owner_root,
                "reviewer": obligation.reviewer_root,
                "policy": obligation.policy_root,
                "priority": obligation.priority_root,
                "priority_label": priority_label,
                "state": state_label,
                "dependencies": list(obligation.dependency_roots),
                "courts": list(obligation.court_roots),
                "required_evidence": list(
                    obligation.required_evidence_roots
                ),
            })
    inspectable_containers = (
        set(registry.container_roots)
        if is_founder
        else set()
    )
    inspectable_focus = (
        selected_root in relation_roots
        or selected_root in relation_backed_interfaces
        or selected_root in authority_focus_roots
        or selected_root in browser_session_focus_roots
        or (
            selected_root in view_focus_roots
            and selected_root not in registry.container_roots
        )
        or selected_root in inspectable_containers
        or selected_root == view_session.root_id
        or is_founder
    )
    relation_members = None
    if inspectable_focus:
        try:
            relation_members = read_relation(snapshot, selected_root)
        except (InvalidCell, MatchBudgetExceeded):
            relation_members = None
    if relation_members is not None:
        for member in relation_members:
            role_label = _text(snapshot, member.role_id)
            participant_label = participant_labels.get(
                member.participant_id
            )
            participant_owner = None
            participant_interface = None
            if role_label in ("source", "target"):
                owner_root, interface = _canvas_endpoint(
                    snapshot, registry, member, visible_roots
                )
                if owner_root in visible_roots:
                    participant_owner = owner_root
                    participant_interface = (
                        interface["id"] if interface is not None else None
                    )
                    participant_label = participant_labels.get(
                        owner_root, _humanize_root_id(owner_root)
                    )
            if role_label in ("token-digest", "csrf-digest"):
                participant_label = "Protected credential digest"
            elif role_label in ("issued-at", "expires-at"):
                raw_time = _text(snapshot, member.participant_id)
                try:
                    participant_label = datetime.fromtimestamp(
                        float(raw_time), timezone.utc
                    ).isoformat().replace("+00:00", "Z")
                except ValueError:
                    participant_label = "Invalid session time"
            elif participant_label is None and (
                member.participant_id in snapshot.cells
                and snapshot.cells[member.participant_id].link0
                == NULL_CELL_ID
                and snapshot.cells[member.participant_id].link1
                == NULL_CELL_ID
            ):
                participant_label = _text(
                    snapshot, member.participant_id
                )
            connections.append({
                "incidence": member.incidence_id,
                "role": role_label,
                "participant": member.participant_id,
                "participant_label": (
                    participant_label
                    or _humanize_root_id(member.participant_id)
                ),
                "participant_owner": participant_owner,
                "participant_interface": participant_interface,
                "direction": "outbound",
                "relation": selected_root,
                "editable": (
                    selected_root in relation_roots
                    and role_label in ("source", "target")
                ),
                "navigable": (
                    is_founder and member.participant_id in snapshot.cells
                ),
            })

    topology_by_incidence = {
        str(wire[side + "_incidence"]): {
            "rewire_control": wire.get(side + "_rewire_control"),
            "rewire_event_fact_input": wire.get(
                side + "_rewire_event_fact_input"
            ),
            "rewire_choices": wire.get(side + "_rewire_choices", []),
        }
        for wire in binary_wires
        for side in ("source", "target")
        if type(wire.get(side + "_incidence")) is str
    }
    for connection in connections:
        topology = topology_by_incidence.get(str(connection["incidence"]))
        if topology is not None:
            connection.update(topology)

    selected_wire = next(
        (wire for wire in wires if wire["id"] == selected_root), None
    )
    selected_relation = None
    if selected_wire is not None:
        if selected_wire["nary"]:
            relation_participants = [
                item for item in connections
                if item["direction"] == "outbound"
            ]
            selected_relation = {
                "id": selected_wire["id"],
                "nary": True,
                "source": None,
                "target": None,
                "participants": relation_participants,
                "participant_count": len(relation_participants),
                "gates": [],
                "presentation_property_roots": [],
                "observed_revision": snapshot.revision,
            }
        else:
            connection_roles = {
                role: next(
                    (item for item in connections if item["role"] == role), None
                )
                for role in ("source", "target")
            }
            selected_relation = {
                "id": selected_wire["id"],
                "nary": False,
                "disconnect_control": selected_wire.get("disconnect_control"),
                "source": connection_roles["source"],
                "target": connection_roles["target"],
                "participants": [],
                "participant_count": 2,
                "gates": [
                    item for item in connections
                    if item["direction"] == "outbound"
                    if item["role"] not in ("source", "target")
                ],
                "presentation_property_roots": [
                    row.relation_root for row in property_rows
                ],
                "observed_revision": snapshot.revision,
            }

    title = next(
        (node["label"] for node in nodes if node["id"] == selected_root),
        None,
    )
    if title is None and selected_relation is not None:
        if selected_relation["nary"]:
            title = "Relation / %s participants" % (
                selected_relation["participant_count"],
            )
        else:
            title = "%s -> %s" % (
                selected_relation["source"]["participant_label"],
                selected_relation["target"]["participant_label"],
            )
    if title is None and selected_canvas_interface is not None:
        title = str(selected_canvas_interface["name"])
    if title is None and selected_root in authority_focus_roots:
        relationship = read_authority_relationship(
            snapshot,
            registry.authorization.identity_protocol,
            selected_root,
        )
        source_label = (
            participant_labels.get(relationship.source_root)
            or _text(snapshot, relationship.source_root)
            or _humanize_root_id(relationship.source_root)
        )
        target_label = (
            participant_labels.get(relationship.target_root)
            or _text(snapshot, relationship.target_root)
            or _humanize_root_id(relationship.target_root)
        )
        title = "%s: %s -> %s" % (
            _text(snapshot, relationship.kind_root),
            source_label,
            target_label,
        )
    if title is None and selected_root in browser_session_focus_roots:
        browser_session = read_browser_session(
            snapshot, registry.browser_session_protocol, selected_root
        )
        title = "Browser session / %s" % _text(
            snapshot, browser_session.state_root
        )
    catalogue_metadata = _project_node_library_catalogue_metadata(
        snapshot,
        registry.assembly_protocol,
        catalog_sections,
    )
    catalogue = tuple(
        {
            **item,
            **catalogue_metadata[item["id"]],
            "composition_contract": _project_relation_definition_contract(
                snapshot,
                registry,
                item["id"],
                visible_roots,
                {node["id"]: node["label"] for node in nodes},
            ),
        }
        for item in _project_standard_catalog(store, snapshot, registry)
    )
    if set(catalogue_metadata) != {item["id"] for item in catalogue}:
        raise InvalidCell("node library metadata does not cover the catalogue")
    definitions = {item["id"]: item for item in catalogue}
    if title is None and selected_root in definitions:
        title = definitions[selected_root]["name"]
    if selected_root == registry.primitive_root:
        title = "Universal cell"
    if title is None:
        title = participant_labels.get(
            selected_root, _humanize_root_id(selected_root)
        )
    selected_cell = snapshot.cells[selected_root]
    composer = verify_composer_authority(
        snapshot,
        registry.composer_protocol,
        registry.assembly_protocol,
        registry.adapter_protocol,
        registry.composer_authority.root_id,
    )
    adapters = verify_adapter_catalog(
        snapshot, registry.adapter_protocol, registry.adapter_catalog_root
    )
    authority = registry.authorization
    authorization_policy = verify_authorization_policy(
        snapshot, authority.protocol, authority.policy_root
    )
    authorization_identity = selected_identity
    live_memberships = active_membership_roots(
        snapshot,
        authority.identity_protocol,
        authority.relationship_broker,
        authorization_identity.subject_root,
        authorization_identity.tenant_root,
        now=authority_snapshot.evaluated_at,
        authority_snapshot=authority_snapshot,
    )
    live_principals = tuple(dict.fromkeys((
        *authorization_identity.principal_roots,
        *live_memberships,
    )))
    inspector_projection = _project_inspector_lenses(
        snapshot, registry, view_session, live_principals
    )
    authority_relationships = []
    visible_authority_participants = {
        authorization_identity.subject_root,
        *live_memberships,
    }
    for relationship_root in authority_snapshot.registered_roots:
        relationship = authority_snapshot.relationships.get(relationship_root)
        if relationship is None:
            relationship = read_authority_relationship(
                snapshot, authority.identity_protocol, relationship_root
            )
        if (
            authorization_identity.subject_root != authority.subject_root
            and relationship.source_root not in visible_authority_participants
            and relationship.target_root not in visible_authority_participants
        ):
            continue
        verified = True
        authority_reason = "verified"
        try:
            verify_authority_relationship(
                snapshot,
                authority.identity_protocol,
                authority.relationship_broker,
                relationship.root_id,
                require_active=False,
                authority_snapshot=authority_snapshot,
            )
        except RelationshipAuthorityDenied as exc:
            verified = False
            authority_reason = str(exc)
        authority_relationships.append({
            "root": relationship.root_id,
            "source": relationship.source_root,
            "target": relationship.target_root,
            "kind": _text(snapshot, relationship.kind_root),
            "state": _text(snapshot, relationship.state_root),
            "scope": relationship.scope_root,
            "actions": list(relationship.action_roots),
            "issuer": relationship.issuer_root,
            "changed_by": relationship.changed_by_root,
            "changed_at": _text(snapshot, relationship.changed_at_root),
            "reason": _text(snapshot, relationship.reason_root),
            "verified": verified,
            "authority_reason": authority_reason,
        })
    browser_sessions = []
    for browser_session_root in browser_session_focus_roots:
        browser_session = read_browser_session(
            snapshot,
            registry.browser_session_protocol,
            browser_session_root,
        )
        browser_sessions.append({
            "root": browser_session.root_id,
            "subject": browser_session.subject_root,
            "view": browser_session.view_root,
            "tenant": browser_session.tenant_root,
            "assurance": browser_session.assurance_root,
            "issued_at": datetime.fromtimestamp(
                float(_text(snapshot, browser_session.issued_at_root)),
                timezone.utc,
            ).isoformat().replace("+00:00", "Z"),
            "expires_at": datetime.fromtimestamp(
                float(_text(snapshot, browser_session.expires_at_root)),
                timezone.utc,
            ).isoformat().replace("+00:00", "Z"),
            "state": _text(snapshot, browser_session.state_root),
            "revocation_reason": (
                _text(
                    snapshot,
                    browser_session.revocation_reason_roots[0],
                )
                if browser_session.revocation_reason_roots else None
            ),
        })
    personal_settings_instance, _, personal_settings_heads = _theme_revision(
        snapshot, registry, view_session
    )
    (
        settings_owner,
        _,
        settings_revision,
        settings_heads,
        settings_binding_mode,
    ) = _bound_theme_revision(snapshot, registry, view_session)
    settings_theme = _decode_theme_document(
        snapshot, registry, settings_revision.content_root
    )
    settings_theme_fields = [{
        "key": name,
        "value": value,
        "token_root": registry.presentation.theme_roots[name],
        "control": _appearance_control_root(
            view_session.subject_root,
            registry.presentation.theme_roots[name],
            _APPEARANCE_OPERATION_ROOTS["theme-preview"],
        ),
        "event_fact_input": _EVENT_FACT_ROOTS["submitted_value"],
    } for name, value in settings_theme.items()]
    design_token_system = open_archhub_design_token_system(
        snapshot, registry.presentation.theme_roots
    )
    design_system_runtime = project_design_system_runtime(
        snapshot,
        design_token_system,
        theme_overrides=settings_theme,
    )
    icon_catalog_projection = project_icon_catalog(
        snapshot, registry.icon_protocol, registry.icon_catalog_root
    )
    design_system_runtime["icon_catalog"] = {
        "root": icon_catalog_projection.root_id,
        "source": {
            "root": icon_catalog_projection.source.root_id,
            "package": icon_catalog_projection.source.package,
            "version": icon_catalog_projection.source.version,
            "license": icon_catalog_projection.source.license,
            "homepage": icon_catalog_projection.source.homepage,
            "repository": icon_catalog_projection.source.repository,
            "source_sha256": icon_catalog_projection.source.source_sha256,
            "selected_geometry_sha256": (
                icon_catalog_projection.source.selected_geometry_sha256
            ),
        },
        "icons": {
            name: {
                "root": icon.root_id,
                "name": icon.name,
                "view_box": icon.view_box,
                "primitives": [
                    {
                        "root": primitive.root_id,
                        "tag": primitive.tag,
                        "attributes": dict(primitive.attributes),
                    }
                    for primitive in icon.primitives
                ],
            }
            for name, icon in icon_catalog_projection.icons.items()
        },
    }
    control_catalog_projection = project_control_catalog(
        snapshot,
        registry.control_presentation_protocol,
        registry.icon_protocol,
        registry.control_catalog_root,
    )
    control_binding_projection = project_control_binding_catalog(
        snapshot,
        registry.control_binding_protocol,
        registry.control_binding_catalog_root,
    )
    if set(control_binding_projection.bindings) != set(
        control_catalog_projection.controls
    ):
        raise InvalidCell("visible controls and activation bindings diverged")
    action_history_projection = _project_session_action_history(
        snapshot, registry, view_session
    )
    control_facts = {
        FACT_SCOPE_PARENT: len(scope_trail) > 1,
        FACT_SELECTION_COUNT: len(selected_roots),
        FACT_FOCUS_COMPOSITION: _is_universal_composition(
            snapshot, registry, selected_root
        ),
        FACT_CAN_UNDO: bool(action_history_projection["can_undo"]),
        FACT_CAN_REDO: bool(action_history_projection["can_redo"]),
    }
    control_runtime = []
    for control in control_catalog_projection.controls.values():
        binding = control_binding_projection.bindings[control.owner_root]
        control_runtime.append({
            "root": control.root_id,
            "owner": control.owner_root,
            "label": control.label,
            "title": control.title,
            "zone": control.zone,
            "order": control.order,
            "icon_assignment": control.icon_assignment_root,
            "icon": control.icon_root,
            "activation": {
                "root": binding.activation_root,
                "binding": binding.root_id,
                "capability": binding.capability_root,
                "arguments": dict(binding.arguments),
            },
            "condition": binding.condition_root,
            "applicable": evaluate_control_condition(
                snapshot,
                registry.control_binding_protocol,
                binding.condition_root,
                control_facts,
            ),
        })
    library_place_control = next(
        (
            control for control in control_runtime
            if control["owner"] == "app:control:library:place"
            and control["zone"] == "library"
            and control["applicable"]
        ),
        None,
    )
    if library_place_control is None:
        raise InvalidCell("released Node Library place control is unavailable")
    property_form_binding = read_relation_form_binding(
        snapshot,
        registry.relation_form_protocol,
        registry.relation_form_roots["property"],
    )
    property_form_control = next((
        control for control in control_runtime
        if control["owner"] == property_form_binding.control_root
        and control["zone"] == "inspector-properties"
        and control["applicable"]
    ), None)
    if (
        property_form_control is None
        or property_form_control["activation"]["capability"]
        != CAPABILITY_RELATION_FORM
        or property_form_control["activation"]["arguments"].get("form")
        != property_form_binding.root_id
    ):
        raise InvalidCell("released Property relation-form control is unavailable")
    if property_form_binding.operation_root != CAPABILITY_RELATION_FORM:
        raise InvalidCell("released Property relation-form operation drifted")
    property_form_projection = {
        "root": property_form_binding.root_id,
        "command": property_form_binding.command_root,
        "operation": property_form_binding.operation_root,
        "operation_path": "/api/universal/interaction",
        "control": property_form_control["owner"],
        "control_label": property_form_control["label"],
        "control_title": property_form_control["title"],
        "control_binding": property_form_control["activation"]["binding"],
        "control_capability": property_form_control["activation"]["capability"],
        "control_icon": property_form_control["icon"],
        "inputs": {
            spec.key: spec.root_id for spec in property_form_binding.input_specs
        },
    }
    interface_form_binding = read_relation_form_binding(
        snapshot,
        registry.relation_form_protocol,
        registry.relation_form_roots["interface"],
    )
    interface_form_control = next((
        control for control in control_runtime
        if control["owner"] == interface_form_binding.control_root
        and control["zone"] == "inspector-interfaces"
        and control["applicable"]
    ), None)
    if (
        interface_form_control is None
        or interface_form_control["activation"]["capability"]
        != CAPABILITY_RELATION_FORM
        or interface_form_control["activation"]["arguments"].get("form")
        != interface_form_binding.root_id
    ):
        raise InvalidCell("released Interface relation-form control is unavailable")
    if interface_form_binding.operation_root != CAPABILITY_RELATION_FORM:
        raise InvalidCell("released Interface relation-form operation drifted")
    interface_form_projection = {
        "root": interface_form_binding.root_id,
        "command": interface_form_binding.command_root,
        "operation": interface_form_binding.operation_root,
        "operation_path": "/api/universal/interaction",
        "control": interface_form_control["owner"],
        "control_label": interface_form_control["label"],
        "control_title": interface_form_control["title"],
        "control_binding": interface_form_control["activation"]["binding"],
        "control_capability": interface_form_control["activation"]["capability"],
        "control_icon": interface_form_control["icon"],
        "inputs": {
            spec.key: spec.root_id for spec in interface_form_binding.input_specs
        },
    }
    catalogue = tuple({
        **item,
        "descriptor": render_view_template(
            snapshot,
            registry.view_template_protocol,
            LIBRARY_DEFINITION_TEMPLATE_ROOT,
            {
                **item,
                "selected": item["id"] == selected_root,
                "control": library_place_control,
            },
        ),
    } for item in catalogue)
    definitions = {item["id"]: item for item in catalogue}
    design_system_runtime["control_catalog"] = {
        "root": control_catalog_projection.root_id,
        "activation_catalog": control_binding_projection.root_id,
        "controls": control_runtime,
    }
    if selected_root == view_session.settings_root:
        title = "Personal Settings"
    settings_history = []
    for revision_root in lifecycle_history(
        snapshot,
        registry.standard_library.lifecycle_protocol,
        personal_settings_instance,
    ):
        revision = read_revision(
            snapshot,
            registry.standard_library.lifecycle_protocol,
            revision_root,
        )
        current_revision = revision.root_id == settings_revision.root_id
        settings_history.append({
            "revision": revision.root_id,
            "digest": _text(snapshot, revision.content_digest_root),
            "state": _text(snapshot, revision.state_root),
            "actor": revision.actor_root,
            "timestamp": (
                _text(snapshot, revision.timestamp_root)
                if revision.timestamp_root else None
            ),
            "parents": list(revision.predecessor_roots),
            "reason": (
                _text(snapshot, revision.reason_root)
                if revision.reason_root else None
            ),
            "evidence": [
                _court_evidence_summary(
                    snapshot, registry, evidence_root
                )
                for evidence_root in revision.evidence_roots
            ],
            "current": current_revision,
            "restore_control": (
                None if current_revision else _appearance_control_root(
                    view_session.subject_root,
                    revision.root_id,
                    _APPEARANCE_OPERATION_ROOTS["theme-restore"],
                )
            ),
        })
    lifecycle = registry.standard_library.lifecycle_protocol
    personal_shared_heads = state_heads(
        snapshot,
        lifecycle,
        personal_settings_instance.state_pointers[lifecycle.states["shared"]],
    )
    active_wip_promotions = tuple(
        revision_root for revision_root in personal_shared_heads
        if settings_revision.root_id in read_revision(
            snapshot, lifecycle, revision_root
        ).predecessor_roots
    )
    active_wip_was_shared = bool(active_wip_promotions)
    active_shared_revision = (
        active_wip_promotions[0] if len(active_wip_promotions) == 1 else None
    )
    personal_published_heads = state_heads(
        snapshot,
        lifecycle,
        personal_settings_instance.state_pointers[
            lifecycle.states["published"]
        ],
    )
    active_published_promotions = tuple(
        revision_root for revision_root in personal_published_heads
        if active_shared_revision is not None
        and active_shared_revision in read_revision(
            snapshot, lifecycle, revision_root
        ).predecessor_roots
    )
    native_auth_members = read_relation(
        snapshot,
        registry.native_authentication_protocol.root_id,
        budget=100_000,
    )
    native_auth_counts = {
        name: sum(
            member.role_id
            == registry.native_authentication_protocol.role(role_name)
            for member in native_auth_members
        )
        for name, role_name in (
            ("configured_clients", "client-member"),
            ("transactions", "transaction-member"),
            ("completions", "completion-member"),
        )
    }
    custody_roots = list_device_custody_roots(
        snapshot, registry.device_custody_protocol
    )
    custody_records = tuple(
        read_device_custody(
            snapshot, registry.device_custody_protocol, custody_root
        )
        for custody_root in custody_roots
    )
    device_custody_counts = {
        "registered": len(custody_records),
        "active": sum(
            custody.state_root
            == registry.device_custody_protocol.states["active"]
            for custody in custody_records
        ),
        "hardware_backed": sum(
            _text(snapshot, custody.hardware_backed_root) == "true"
            for custody in custody_records
        ),
    }
    device_adapter = verify_released_adapter(
        snapshot,
        registry.adapter_protocol,
        registry.device_custody_adapter_root,
    )
    tenant_release_state = _text(
        snapshot,
        registry.standard_library.lifecycle_protocol.states["published"],
    )
    authority_stack = [
        {
            "root": registry.standard_library.catalog_root,
            "label": "Standard assembly catalogue",
            "role": "catalogue",
            "state": "released",
        },
        {
            "root": registry.adapter_catalog_root,
            "label": "Adapter allowlist",
            "role": "adapter catalogue",
            "state": _text(snapshot, adapters.lifecycle_root),
        },
        {
            "root": registry.device_custody_adapter_root,
            "label": "Windows device-key custody",
            "role": "allowlisted adapter",
            "state": _text(snapshot, device_adapter.lifecycle_root),
        },
        {
            "root": registry.composer_authority.root_id,
            "label": "Agent composer authority",
            "role": "composer gate",
            "state": _text(snapshot, composer.lifecycle_root),
        },
        {
            "root": registry.tenant_authority.configuration_root,
            "label": "Tenant configuration",
            "role": "configuration",
            "state": tenant_release_state,
        },
        {
            "root": registry.tenant_authority.published_revision_root,
            "label": "Tenant revision",
            "role": "published revision",
            "state": tenant_release_state,
        },
        {
            "root": registry.tenant_release_selection.root_id,
            "label": "Selected tenant release",
            "role": "release selection",
            "state": "selected",
        },
    ]
    if registry.authority_migration_root is not None:
        read_relation(
            snapshot, registry.authority_migration_root, budget=100_000
        )
        authority_stack.append({
            "root": registry.authority_migration_root,
            "label": "Authority generation migration",
            "role": "migration evidence",
            "state": "recorded",
        })
    scope_projection = {
        "current": scope_trail[-1],
        "current_label": _scope_label(
            snapshot, registry, scope_trail[-1]
        ),
        "parent": scope_trail[-2] if len(scope_trail) > 1 else None,
        "trail": [
            {
                "root": root_id,
                "label": _scope_label(snapshot, registry, root_id),
                "current": root_id == scope_trail[-1],
            }
            for root_id in scope_trail
        ],
    }
    selected_binding = resource_bindings.get(selected_root)
    selected_binding_is_exact = bool(
        selected_binding
        and authority_snapshot.relationships[
            selected_binding[0]
        ].source_root == selected_root
    )
    can_add_property = bool(
        selected_binding_is_exact
        and selected_binding[1]
        == registry.standard_library.lifecycle_protocol.states["wip"]
        and selected_identity.subject_root in (
            selected_binding[2], registry.authorization.subject_root
        )
    )
    selected_assembly_projection = _instance_projection(
        snapshot,
        registry,
        selected_root,
        release_scope=(
            release_scope_for(selected_root)
            if selected_root in resource_bindings else None
        ),
        interaction_subject_root=view_session.subject_root,
    )
    if selected_assembly_projection is not None:
        for interface in selected_assembly_projection["interfaces"]:
            if interface["mode"] != "relation-role":
                continue
            enrich_relation_role_interface(interface)
    selected_node_projection = next(
        (node for node in nodes if node["id"] == selected_root), None
    )
    selected_interfaces = list(
        selected_node_projection["ports"]
        if selected_node_projection is not None
        else (
            (selected_canvas_interface,)
            if selected_canvas_interface is not None else ()
        )
    )
    assembly_interfaces = {
        str(interface["id"]): interface
        for interface in (
            selected_assembly_projection["interfaces"]
            if selected_assembly_projection is not None else ()
        )
    }
    enriched_interfaces = []
    for projected_interface in selected_interfaces:
        interface = dict(projected_interface)
        authority_interface = assembly_interfaces.get(str(interface.get("id")))
        interface.update({
            "owner": selected_root,
            "control": None,
            "event_fact_input": None,
            "append_control": interface.get("append_control"),
            "append_event_fact_input": interface.get(
                "append_event_fact_input"
            ),
        })
        if (
            authority_interface is not None
            and authority_interface["mode"] == "connection"
            and authority_interface["editable"] is True
        ):
            interface.update({
                "control": _edit_value_control_root(
                    view_session.subject_root,
                    str(interface["id"]),
                    str(interface["target"]),
                ),
                "event_fact_input": _EVENT_FACT_ROOTS["submitted_value"],
            })
        if (
            authority_interface is not None
            and authority_interface["mode"] == "collection"
            and authority_interface["editable"] is True
        ):
            interface.update({
                "append_control": _relation_member_control_root(
                    view_session.subject_root,
                    str(interface["id"]),
                    _RELATION_MEMBER_OPERATION_ROOTS["append"],
                ),
                "append_event_fact_input": _EVENT_FACT_ROOTS[
                    "submitted_value"
                ],
            })
            interface["items"] = [
                {
                    **item,
                    "control": _edit_value_control_root(
                        view_session.subject_root,
                        str(item["incidence"]),
                        str(item["value_root"]),
                    ),
                    "event_fact_input": _EVENT_FACT_ROOTS[
                        "submitted_value"
                    ],
                    "up_control": _relation_member_control_root(
                        view_session.subject_root,
                        str(item["incidence"]),
                        _RELATION_MEMBER_OPERATION_ROOTS["move-up"],
                    ),
                    "down_control": _relation_member_control_root(
                        view_session.subject_root,
                        str(item["incidence"]),
                        _RELATION_MEMBER_OPERATION_ROOTS["move-down"],
                    ),
                    "remove_control": _relation_member_control_root(
                        view_session.subject_root,
                        str(item["incidence"]),
                        _RELATION_MEMBER_OPERATION_ROOTS["remove"],
                    ),
                }
                for item in interface.get("items", ())
            ]
        enriched_interfaces.append(interface)
    selected_interfaces = enriched_interfaces
    presentation_options = []
    seen_presentations: set[str] = set()
    for interface in registered_interfaces:
        presentation_root = str(interface["presentation_root"])
        if presentation_root in seen_presentations:
            continue
        seen_presentations.add(presentation_root)
        side = str(interface["side"])
        presentation_options.append({
            "id": presentation_root,
            "label": "Output" if side == "source" else "Input",
            "side": side,
        })
    contract_roots = {registry.assembly_protocol.root_id}
    contract_roots.update(
        str(port["contract_root"])
        for node in nodes for port in node["ports"]
        if port.get("contract_root") in snapshot.cells
    )
    contract_options = [
        {
            "id": contract_root,
            "label": (
                "Universal Cell"
                if contract_root == registry.assembly_protocol.root_id
                else _text(snapshot, contract_root)
                or _humanize_root_id(contract_root)
            ),
        }
        for contract_root in sorted(contract_roots)
    ]
    inspector_projection["presentation"] = (
        _project_properties_presentation(
            snapshot,
            registry,
            view_session,
            inspector_projection,
            live_principals,
            properties=properties,
            connections=connections,
            has_attached_relations=any(
                wire["source"] == selected_root
                or wire["target"] == selected_root
                or wire["source_interface"] == selected_root
                or wire["target_interface"] == selected_root
                for wire in wires
            ),
            selected_relation=selected_relation,
            selected_assembly=selected_assembly_projection,
            selected_interfaces=selected_interfaces,
            can_add_property=can_add_property,
            can_add_interface=can_add_property,
            selected_settings=selected_root == view_session.settings_root,
            has_history=bool(
                selected_root == view_session.settings_root
                or action_history_projection["transactions"]
                or selected_assembly_projection
                and selected_assembly_projection.get("lifecycle")
            ),
            has_access=is_founder,
            has_evidence=bool(
                is_founder and (
                    definitions.get(selected_root)
                    or selected_assembly_projection
                    and selected_assembly_projection.get("lifecycle")
                    and any(
                        head.get("evidence_details")
                        for state in selected_assembly_projection[
                            "lifecycle"
                        ]["states"]
                        for head in state["heads"]
                    )
                )
            ),
        )
    )
    floor_lens_members = read_relation(
        snapshot, registry.inspector_lens_roots["floor"], budget=64
    )
    floor_lens_label_root = _one_for_role(
        floor_lens_members, registry.roles["label"]
    )
    if floor_lens_label_root is None:
        raise InvalidCell("floor inspector lens has no graph label")
    floor_lens_label = _text(snapshot, floor_lens_label_root)
    library_labels = _rows_by_label(
        snapshot, property_index.get(registry.library_root, ())
    )
    library_title_row = library_labels.get("title")
    if library_title_row is None:
        # The Node Library is a graph-owned lens, not a member-visible canvas
        # node. Its title relation may therefore be absent from a member's
        # personal property scopes after container migration. Read that known
        # graph-owned relation directly without adding the container to the
        # member canvas or widening any personal projection.
        library_properties = tuple(
            registry.root_properties.get(registry.library_root, ())
        )
        library_labels = _rows_by_label(
            snapshot,
            _property_index(snapshot, registry, library_properties).get(
                registry.library_root, ()
            ),
        )
        library_title_row = library_labels.get("title")
    if library_title_row is None:
        raise InvalidCell("node library has no graph title property")
    library_title = effective_property_value(library_title_row)
    physical_atom_property = next((
        row for row in properties
        if row["editable"] is True
        and row["value_root"] == selected_cell.id
    ), None)
    interaction_policy = canvas_interaction_policy_payload(
        project_canvas_interaction_policy(
            snapshot,
            registry.canvas_interaction_policy_protocol,
            registry.canvas_interaction_policy_root,
        )
    )
    projected_canvas = {
        "revision": snapshot.revision,
        "application_root": registry.application_root,
        "canvas_root": registry.canvas_root,
        "properties_lens_root": view_session.properties_lens_root,
        "selected": selected_root,
        "selection": sorted(selected_roots),
        "selected_title": title or selected_root,
        "focus": {
            "root": focus_projection.root_id,
            "actor": focus_projection.actor_root,
            "session": focus_projection.session_root,
            "scope": focus_projection.scope_root,
            "selected": list(focus_projection.selected_roots),
            "primary": focus_projection.primary_root,
            "origin": _text(snapshot, focus_projection.origin_root),
            "state": _text(snapshot, focus_projection.state_root),
            "reasons": [
                {
                    "root": root,
                    "label": _text(snapshot, root),
                }
                for root in focus_projection.reason_roots
            ],
            "attention": list(focus_projection.attention_roots),
            "authority": focus_projection.authority_root,
            "consent_evidence": list(
                focus_projection.consent_evidence_roots
            ),
            "previous": focus_projection.previous_root,
            "created_at": focus_projection.created_at,
        },
        "obligations": core_value_obligations,
        "scope": scope_projection,
        "authoring": {
            "add_property": can_add_property,
            "add_interface": can_add_property,
            "owner": selected_root if can_add_property else None,
            "property_form": property_form_projection,
            "interface_form": interface_form_projection,
            "interface_presentations": presentation_options,
            "interface_contracts": contract_options,
        },
        "action_history": action_history_projection,
        "inspector": inspector_projection,
        "nodes": nodes,
        "wires": wires,
        "properties": properties,
        "connections": connections,
        "selected_relation": selected_relation,
        "selected_interface": selected_canvas_interface,
        "selected_interfaces": selected_interfaces,
        "viewport": viewport,
        "interaction_policy": interaction_policy,
        "catalog": list(catalogue),
        "catalog_sections": catalog_sections,
        "library": {
            "root": registry.library_root,
            "title": library_title,
            "count_text": "%s nodes" % len(catalogue),
        },
        "authority_stack": authority_stack,
        "composer": {
            "authority": composer.root_id,
            "actor": composer.actor_root,
            "catalogue": composer.catalogue_root,
            "adapter_catalogue": composer.adapter_catalogue_root,
            "admitted_adapters": len(adapters.adapter_roots),
            "state": _text(snapshot, composer.lifecycle_root),
            "allowed_commands": [
                _text(snapshot, root) for root in composer.allowed_command_roots
            ],
            "limits": dict(composer.limits),
            "extension_mode": "proposal-only",
        },
        "authorization": {
            "policy": authorization_policy.root_id,
            "version": _text(snapshot, authorization_policy.version_root),
            "state": _text(snapshot, authorization_policy.lifecycle_root),
            "digest": _text(snapshot, authorization_policy.digest_root),
            "default": "deny",
            "subject": authorization_identity.subject_root,
            "subject_label": _text(snapshot, authorization_identity.subject_root),
            "principals": list(live_principals),
            "tenant": authorization_identity.tenant_root,
            "tenant_label": _text(snapshot, authorization_identity.tenant_root),
            "assurance": authorization_identity.assurance_root,
            "assurance_label": _text(snapshot, authorization_identity.assurance_root),
            "scope": authority.scope_root,
            "scope_label": _text(snapshot, authority.scope_root),
            "rule_count": len(authorization_policy.rule_roots),
            "session": view_session.root_id,
            "browser_sessions": browser_sessions,
            "visibility": view_session.visibility_root,
            "assigned_canvas_roots": len(visible_roots),
            "tenant_membership": view_session.tenant_membership_root,
            "tenant_role_membership": (
                view_session.tenant_role_membership_root
            ),
            "principal_membership": view_session.principal_membership_root,
            "relationships": authority_relationships,
            "native_identity": {
                "protocol": registry.native_authentication_protocol.root_id,
                **native_auth_counts,
                "device_custody": {
                    "protocol": registry.device_custody_protocol.root_id,
                    **device_custody_counts,
                    "production_requirement": "TPM-backed",
                },
                "provider_status": (
                    "configured"
                    if native_auth_counts["configured_clients"]
                    else "not-configured"
                ),
            },
        },
        "configuration": {
            "asset": settings_owner.settings_root,
            "personal_asset": view_session.settings_root,
            "binding": view_session.theme_binding_root,
            "binding_mode": settings_binding_mode,
            "state": _text(snapshot, settings_revision.state_root),
            "preview_revision": settings_revision.root_id,
            "digest": _text(snapshot, settings_revision.content_digest_root),
            "heads": list(settings_heads),
            "personal_wip_heads": list(personal_settings_heads),
            "parents": list(settings_revision.predecessor_roots),
            "actor": settings_revision.actor_root,
            "theme": settings_theme,
            "theme_fields": settings_theme_fields,
            "design_system": design_system_runtime,
            "history": settings_history,
            "shared_revision": (
                active_shared_revision
            ),
            "published_revision": (
                active_published_promotions[0]
                if len(active_published_promotions) == 1 else None
            ),
            "can_promote": (
                authority.principal_root
                in authorization_identity.principal_roots
                and settings_binding_mode == "personal-wip"
                and settings_revision.state_root
                == lifecycle.states["wip"]
                and not active_wip_was_shared
            ),
            "can_publish": (
                authority.principal_root
                in authorization_identity.principal_roots
                and settings_binding_mode == "personal-wip"
                and active_shared_revision is not None
                and not active_published_promotions
                and registry.browser_publish_court.endpoint is not None
            ),
            "court": {
                "root": registry.theme_court_root,
                "state": _text(
                    snapshot,
                    verify_court_definition(
                        snapshot,
                        registry.attestation_protocol,
                        registry.theme_court_root,
                    ).lifecycle_root,
                ),
                "publish_root": registry.theme_publish_court_root,
                "publish_state": _text(
                    snapshot,
                    verify_court_definition(
                        snapshot,
                        registry.attestation_protocol,
                        registry.theme_publish_court_root,
                    ).lifecycle_root,
                ),
            },
        },
        "selected_definition": definitions.get(selected_root),
        "selected_assembly": selected_assembly_projection,
        "primitive": {
            "id": registry.primitive_root,
            "label": _text(snapshot, registry.primitive_root),
            "kicker": floor_lens_label,
            "fields": ["identity", "link 0", "link 1", "atom"],
            "visible": (
                inspector_projection["active"]
                == registry.inspector_lens_roots["floor"]
            ),
        },
        "physical": {
            "identity": selected_cell.id,
            "link0": selected_cell.link0,
            "link1": selected_cell.link1,
            "atom": _text(snapshot, selected_cell.id),
            "editable": physical_atom_property is not None,
            "control": (
                physical_atom_property["control"]
                if physical_atom_property is not None else None
            ),
            "event_fact_input": (
                physical_atom_property["event_fact_input"]
                if physical_atom_property is not None else None
            ),
        },
    }
    projected_canvas["toolbar_descriptor"] = render_view_template(
        snapshot,
        registry.view_template_protocol,
        CANVAS_TOOLBAR_TEMPLATE_ROOT,
        {
            "trail": tuple({
                **item,
                "key": "toolbar:scope:item:%s" % item["root"],
                "show_divider": bool(index),
            } for index, item in enumerate(projected_canvas["scope"]["trail"])),
            "controls": tuple(sorted(
                (
                    control for control in control_runtime
                    if control["zone"] == "canvas-toolbar"
                    and control["applicable"]
                ),
                key=lambda control: control["order"],
            )),
            "zoom_percent": round(
                float(projected_canvas["viewport"]["zoom"]) * 100
            ),
            "selection_count": len(projected_canvas["selection"]),
        },
    )
    projected_canvas["canvas_heading_descriptor"] = render_view_template(
        snapshot,
        registry.view_template_protocol,
        CANVAS_HEADING_TEMPLATE_ROOT,
        {
            "root": projected_canvas["scope"]["current"],
            "label": projected_canvas["scope"]["current_label"],
        },
    )
    canvas_signature_payload = {
        "scope": projected_canvas["scope"]["current"],
        "viewport": projected_canvas["viewport"],
        "selection": projected_canvas["selection"],
        "nodes": projected_canvas["nodes"],
        "wires": projected_canvas["wires"],
    }
    projected_canvas["canvas_signature"] = "v1:" + hashlib.sha256(
        json.dumps(
            canvas_signature_payload,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()
    projected_canvas["library"]["descriptor"] = render_view_template(
        snapshot,
        registry.view_template_protocol,
        LIBRARY_SHELL_TEMPLATE_ROOT,
        projected_canvas["library"],
    )
    projected_canvas["primitive"]["descriptor"] = render_view_template(
        snapshot,
        registry.view_template_protocol,
        LIBRARY_PRIMITIVE_TEMPLATE_ROOT,
        {
            **projected_canvas["primitive"],
            "selected": selected_root == registry.primitive_root,
        },
    )
    selected_definition_projection = projected_canvas["selected_definition"]
    if (
        isinstance(selected_definition_projection, Mapping)
        and selected_definition_projection.get("composition_contract")
    ):
        projected_canvas["selected_definition"] = {
            **selected_definition_projection,
            "composer": _project_relation_composer(
                snapshot,
                registry,
                selected_definition_projection,
                view_session,
            ),
        }
    projected_canvas["inspector"]["header_descriptor"] = (
        render_view_template(
            snapshot,
            registry.view_template_protocol,
            INSPECTOR_HEADER_TEMPLATE_ROOT,
            projected_canvas,
        )
    )
    projected_canvas["inspector"]["controls_descriptor"] = (
        render_view_template(
            snapshot,
            registry.view_template_protocol,
            INSPECTOR_CONTROLS_TEMPLATE_ROOT,
            projected_canvas,
        )
    )
    presentation_panels = projected_canvas[
        "inspector"
    ]["presentation"]["panels"]
    projected_canvas["inspector"]["shell_descriptor"] = (
        render_view_template(
            snapshot,
            registry.view_template_protocol,
            INSPECTOR_SHELL_TEMPLATE_ROOT,
            {
                "selected": projected_canvas["selected"],
                "panels": tuple({
                    "id": panel["id"],
                    "key": "inspector-tabpanel:%s" % panel["id"],
                    "panel_id": "inspector-panel-%s" % index,
                    "tab_id": "inspector-tab-%s" % index,
                    "active": panel["active"],
                } for index, panel in enumerate(presentation_panels)),
            },
        )
    )
    for presentation_panel in presentation_panels:
        for component in presentation_panel["components"]:
            projector_root = str(component["projector"])
            if is_view_template(
                snapshot,
                registry.view_template_protocol,
                projector_root,
            ):
                descriptor_projection = render_view_template(
                    snapshot,
                    registry.view_template_protocol,
                    projector_root,
                    projected_canvas,
                )
            else:
                raise InvalidCell(
                    "admitted presenter projector is not a graph template"
                )
            component["descriptor"] = descriptor_projection
    return projected_canvas


def project_universal_canvas(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    *,
    authentication_context: object | None = None,
) -> dict[str, object]:
    """Exhaustively interpret the current canonical canvas."""
    return _project_universal_canvas_interpreter(
        store,
        registry,
        authentication_context=authentication_context,
    )


def project_universal_scope_transition(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    *,
    authentication_context: object | None,
    scope_materialization: UniversalScopeMaterialization,
    previous_projection: Mapping[str, object],
    expected_base_revision: int,
) -> dict[str, object]:
    """Interpret one exact committed session scope without the generic entry."""
    if type(expected_base_revision) is not int:
        raise InvalidCell("scope transition base revision is invalid")
    if not isinstance(previous_projection, Mapping):
        raise InvalidCell("scope transition base projection is missing")
    if previous_projection.get("revision") != expected_base_revision:
        raise InvalidCell("scope transition base projection revision drifted")
    if (
        type(scope_materialization) is not UniversalScopeMaterialization
        or scope_materialization.revision != store.revision
        or scope_materialization.revision != expected_base_revision + 1
    ):
        raise InvalidCell("scope transition materialization revision drifted")
    return _project_universal_canvas_interpreter(
        store,
        registry,
        authentication_context=authentication_context,
        scope_materialization=scope_materialization,
    )


def _compose_property(
    registry: UniversalApplicationRegistry,
    owner_root: str,
    key: str,
    value: object,
    *,
    read_only: bool = False,
) -> tuple[PropertyRef, tuple[Cell, ...]]:
    token = uuid.uuid4().hex
    value_root = "app:dynamic:value:%s" % token
    label_root = "app:dynamic:label:%s" % token
    relation_root = "app:dynamic:property:%s" % token
    members = [
        (registry.roles["owner"], owner_root),
        (registry.roles["value"], value_root),
        (registry.roles["label"], label_root),
    ]
    if read_only:
        members.append((
            registry.roles["read-only"], registry.roles["read-only"]
        ))
    relation = compose_relation_cells(members, relation_id=relation_root)
    return (
        PropertyRef(relation_root, value_root, label_root),
        (
            Cell(value_root, NULL_CELL_ID, NULL_CELL_ID, _atom(value)),
            Cell(label_root, NULL_CELL_ID, NULL_CELL_ID, _atom(key)),
            *relation.cells,
        ),
    )


def _compose_bound_property(
    registry: UniversalApplicationRegistry,
    owner_root: str,
    key: str,
    value_root: str,
) -> tuple[PropertyRef, tuple[Cell, ...]]:
    """Expose an existing Cell atom through one explicit property relation."""
    token = uuid.uuid4().hex
    label_root = "app:dynamic:label:%s" % token
    relation_root = "app:dynamic:property:%s" % token
    relation = compose_relation_cells((
        (registry.roles["owner"], owner_root),
        (registry.roles["value"], value_root),
        (registry.roles["label"], label_root),
    ), relation_id=relation_root)
    return (
        PropertyRef(relation_root, value_root, label_root),
        (
            Cell(label_root, NULL_CELL_ID, NULL_CELL_ID, _atom(key)),
            *relation.cells,
        ),
    )


def issue_universal_authority_relationship(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    *,
    source_root: str,
    target_root: str,
    kind: str,
    scope_root: str | None = None,
    action_roots: tuple[str, ...] | list[str] = (),
    expires_at: float | None = None,
    reason: str,
    evidence_roots: tuple[str, ...] | list[str] = (),
    relationship_root: str | None = None,
    authentication_context: object | None = None,
) -> tuple[str, int]:
    """Issue one signed relation under the released application policy.

    No user/group/project classes are introduced here. Any existing universal
    cell may be a source, target, scope, or evidence participant when the
    trusted administrator explicitly authorizes that exact relationship.
    """
    authority = registry.authorization
    context = _active_authentication_context(authority, authentication_context)
    snapshot = store.snapshot()
    _require_application_authorization(
        snapshot,
        registry,
        "manage-policy",
        registry.application_root,
        authentication_context=context,
    )
    referenced = tuple(root for root in (
        source_root,
        target_root,
        scope_root,
        *action_roots,
        *evidence_roots,
    ) if root is not None)
    if any(root not in snapshot.cells for root in referenced):
        raise InvalidCell("authority relationship references a missing cell")
    administrator_root = authority.broker.resolve(context).subject_root
    if relationship_root is None:
        identity = "|".join((
            authority.tenant_root,
            kind,
            source_root,
            target_root,
            scope_root or "",
            *sorted(action_roots),
        ))
        relationship_root = "app:authority:relationship:%s" % uuid.uuid5(
            uuid.NAMESPACE_URL, identity
        ).hex
    current = store.snapshot()
    if relationship_root in current.cells:
        existing = verify_authority_relationship(
            current,
            authority.identity_protocol,
            authority.relationship_broker,
            relationship_root,
        )
        expected_kind = authority.identity_protocol.kinds.get(kind)
        if (
            expected_kind is None
            or existing.source_root != source_root
            or existing.target_root != target_root
            or existing.kind_root != expected_kind
            or existing.tenant_root != authority.tenant_root
            or existing.scope_root != scope_root
            or set(existing.action_roots) != set(action_roots)
        ):
            raise InvalidCell("existing authority relationship has different scope")
        return relationship_root, current.revision
    grant_authority_relationship(
        store,
        authority.identity_protocol,
        authority.relationship_broker,
        authority.relationship_broker.mint_from_trusted_administrator(
            administrator_root
        ),
        relationship_id=relationship_root,
        source_root=source_root,
        target_root=target_root,
        kind=kind,
        tenant_root=authority.tenant_root,
        administrator_root=administrator_root,
        scope_root=scope_root,
        action_roots=action_roots,
        expires_at=expires_at,
        reason=reason,
        evidence_roots=evidence_roots,
    )
    return relationship_root, store.revision


def revoke_universal_authority_relationship(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    relationship_root: str,
    *,
    reason: str,
    authentication_context: object | None = None,
) -> int:
    """Revoke one exact relation; the next request sees the new authority."""
    authority = registry.authorization
    context = _active_authentication_context(authority, authentication_context)
    snapshot = store.snapshot()
    _require_application_authorization(
        snapshot,
        registry,
        "manage-policy",
        registry.application_root,
        authentication_context=context,
    )
    administrator_root = authority.broker.resolve(context).subject_root
    return revoke_authority_relationship(
        store,
        authority.identity_protocol,
        authority.relationship_broker,
        authority.relationship_broker.mint_from_trusted_administrator(
            administrator_root
        ),
        relationship_root,
        administrator_root=administrator_root,
        reason=reason,
    )


def provision_universal_view_session(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    subject_root: str,
    *,
    principal_root: str | None = None,
    visible_roots: tuple[str, ...] | list[str] = (),
    authentication_context: object | None = None,
) -> tuple[ApplicationViewSession, int]:
    """Provision graph-held personal view state under founder authority."""
    existing = registry.view_sessions.get(subject_root)
    if existing is not None:
        return existing, store.revision
    authority = registry.authorization
    context = _active_authentication_context(authority, authentication_context)
    snapshot = store.snapshot()
    _require_application_authorization(
        snapshot,
        registry,
        "manage-policy",
        registry.application_root,
        authentication_context=context,
    )
    if subject_root not in snapshot.cells:
        raise InvalidCell("view-session subject is missing")
    principal_root = principal_root or authority.member_principal_root
    if principal_root not in snapshot.cells:
        raise InvalidCell("view-session principal is missing")
    assigned_roots = tuple(dict.fromkeys(visible_roots))
    _, _, property_scopes = _canvas_scope_for_assigned(
        snapshot, registry, assigned_roots
    )
    _require_resource_audience_authority(
        snapshot, registry, subject_root, assigned_roots
    )

    administrator_root = authority.broker.resolve(context).subject_root
    token = _part(subject_root)
    tenant_membership_root = "app:authority:%s:tenant-membership" % token
    tenant_role_membership_root = (
        "app:authority:%s:tenant-role-membership" % token
    )
    principal_membership_root = "app:authority:%s:principal-membership" % token

    def ensure_membership(
        relationship_root: str,
        target_root: str,
        reason: str,
    ) -> None:
        current = store.snapshot()
        if relationship_root in current.cells:
            relationship = verify_authority_relationship(
                current,
                authority.identity_protocol,
                authority.relationship_broker,
                relationship_root,
            )
            if (
                relationship.source_root != subject_root
                or relationship.target_root != target_root
                or relationship.kind_root
                != authority.identity_protocol.kinds["membership"]
                or relationship.tenant_root != authority.tenant_root
            ):
                raise InvalidCell("existing view membership has the wrong authority")
            return
        grant_authority_relationship(
            store,
            authority.identity_protocol,
            authority.relationship_broker,
            authority.relationship_broker.mint_from_trusted_administrator(
                administrator_root
            ),
            relationship_id=relationship_root,
            source_root=subject_root,
            target_root=target_root,
            kind="membership",
            tenant_root=authority.tenant_root,
            administrator_root=administrator_root,
            reason=reason,
        )

    ensure_membership(
        tenant_membership_root,
        authority.tenant_root,
        "subject admitted to the application tenant",
    )
    ensure_membership(
        tenant_role_membership_root,
        registry.tenant_authority.role_roots["member"],
        "subject assigned the Published tenant member role",
    )
    ensure_membership(
        principal_membership_root,
        principal_root,
        "subject assigned an application principal",
    )
    snapshot = store.snapshot()
    session_root = "app:view-session:%s" % token
    selection_root = session_root + ":selection"
    lens_root = session_root + ":properties-lens"
    visibility_root = session_root + ":visibility"
    scope_trail_root = session_root + ":scope-trail"
    scope_exposure_root = session_root + ":scope-exposure"
    composition_history_root = session_root + ":composition-history"
    action_history_root = session_root + ":action-history"
    inspector_lens_binding_root = session_root + ":inspector-lens"
    properties_panel_binding_root = session_root + ":properties-panel"
    theme_binding_root = session_root + ":theme-binding"

    versioned_definition_root = next(
        item["id"] for item in _project_standard_catalog(
            store, snapshot, registry
        )
        if item["name"] == "Versioned Asset"
    )
    initial_theme = {
        name: _text(snapshot, root)
        for name, root in registry.presentation.theme_roots.items()
    }
    settings = seed_composed_lifecycle_content(
        snapshot,
        registry.assembly_protocol,
        registry.standard_library.lifecycle_protocol,
        compose_catalog_instance(
            snapshot,
            registry.assembly_protocol,
            registry.standard_library.catalog_root,
            versioned_definition_root,
            token="view-settings-" + uuid.uuid5(
                uuid.NAMESPACE_URL, subject_root
            ).hex,
        ),
        json.dumps(
            initial_theme, sort_keys=True, separators=(",", ":")
        ).encode("utf-8"),
    )

    viewport: dict[str, PropertyRef] = {}
    viewport_cells: list[Cell] = []
    for name, value in (("pan_x", 18.0), ("pan_y", 18.0), ("zoom", 0.82)):
        reference, cells = _compose_property(
            registry, session_root, name, value
        )
        viewport[name] = reference
        viewport_cells.extend(cells)

    selection = compose_relation_cells(
        ((registry.roles["available"], root) for root in assigned_roots),
        relation_id=selection_root,
    )
    lens = compose_relation_cells((
        (registry.roles["focus"], (
            assigned_roots[0] if assigned_roots else registry.primitive_root
        )),
        *((registry.roles["scope"], root) for root in property_scopes),
    ), relation_id=lens_root)
    visibility = compose_relation_cells(
        ((registry.roles["visible"], root) for root in assigned_roots),
        relation_id=visibility_root,
    )
    scope_trail = compose_relation_cells((
        (registry.roles["scope"], registry.canvas_root),
    ), relation_id=scope_trail_root)
    scope_exposure = compose_relation_cells((), relation_id=scope_exposure_root)
    composition_history = compose_relation_cells(
        (), relation_id=composition_history_root
    )
    action_history = compose_relation_cells((), relation_id=action_history_root)
    inspector_lens_binding = compose_relation_cells((
        (registry.roles["focus"], registry.inspector_lens_roots["use"]),
    ), relation_id=inspector_lens_binding_root)
    properties_panel_binding = compose_relation_cells((
        (
            registry.properties_presentation_protocol.role("focus"),
            registry.properties_panel_roots["properties"],
        ),
    ), relation_id=properties_panel_binding_root)
    theme_binding = compose_relation_cells((
        (registry.roles["source"], settings.instance.root_id),
        (registry.roles["target"], settings.instance.root_id),
        (
            registry.roles["binding-mode"],
            registry.theme_binding_modes["audience-release"],
        ),
    ), relation_id=theme_binding_root)
    session = compose_relation_cells((
        (authority.session_owner_role_root, subject_root),
        (authority.protocol.role("principal"), principal_root),
        (authority.protocol.role("tenant"), authority.tenant_root),
        (authority.protocol.role("assurance"), authority.assurance_root),
        (authority.protocol.role("purpose"), authority.purpose_root),
        (authority.protocol.role("audience"), authority.audience_root),
        (registry.roles["scope"], registry.application_root),
        (registry.roles["scope"], registry.canvas_root),
        (registry.roles["scope"], authority.personal_view_scope_root),
        (registry.roles["lens"], lens_root),
        (registry.roles["lens"], selection_root),
        (registry.roles["lens"], visibility_root),
        (registry.roles["relation"], scope_trail_root),
        (registry.roles["lens"], scope_exposure_root),
        (registry.roles["relation"], composition_history_root),
        (registry.roles["relation"], action_history_root),
        (registry.roles["relation"], inspector_lens_binding_root),
        (registry.roles["relation"], properties_panel_binding_root),
        (registry.roles["relation"], theme_binding_root),
        (registry.roles["relation"], tenant_membership_root),
        (registry.roles["relation"], tenant_role_membership_root),
        (registry.roles["relation"], principal_membership_root),
        (registry.roles["member"], settings.instance.root_id),
        *((registry.roles["property"], ref.relation_root)
          for ref in viewport.values()),
    ), relation_id=session_root)
    app_patch = prepare_append_relation_members(
        snapshot,
        registry.application_root,
        (
            (registry.roles["member"], session_root),
            (registry.roles["member"], scope_trail_root),
            (registry.roles["member"], scope_exposure_root),
            (registry.roles["member"], composition_history_root),
            (registry.roles["member"], action_history_root),
            (registry.roles["member"], inspector_lens_binding_root),
            (registry.roles["member"], properties_panel_binding_root),
        ),
        budget=100_000,
    )
    revision = store.commit(
        snapshot.revision,
        create=(
            *viewport_cells,
            *selection.cells,
            *lens.cells,
            *visibility.cells,
            *scope_trail.cells,
            *scope_exposure.cells,
            *composition_history.cells,
            *action_history.cells,
            *inspector_lens_binding.cells,
            *properties_panel_binding.cells,
            *settings.cells,
            *theme_binding.cells,
            *session.cells,
            *app_patch.create,
        ),
        replace=app_patch.replace,
    )
    focus_snapshot = store.snapshot()
    initial_primary = (
        assigned_roots[0] if assigned_roots else registry.primitive_root
    )
    initial_focus = prepare_accepted_focus_transition(
        focus_snapshot,
        registry.attention_protocol,
        focus_id=session_root + ":focus:initial",
        actor_root=subject_root,
        session_root=session_root,
        scope_root=registry.canvas_root,
        selected_roots=(initial_primary,),
        primary_root=initial_primary,
        origin="user",
        reason_roots=(_FOCUS_REASON_INITIAL,),
        attention_roots=(),
        authority_root=registry.authorization.policy_root,
        consent_evidence_root=session_root,
        created_at=datetime.now(timezone.utc).isoformat(),
    )
    focus_pointer = focus_snapshot.cells[lens.build.incidence_ids[0]]
    revision = store.commit(
        focus_snapshot.revision,
        create=initial_focus.create,
        replace=(
            *initial_focus.replace,
            Cell(
                focus_pointer.id,
                focus_pointer.link0,
                initial_focus.root_id,
                focus_pointer.atom,
            ),
        ),
    )
    projection_grants = _issue_view_projection_grants(
        store,
        authority,
        subject_root=subject_root,
        visibility_root=visibility_root,
        target_roots=assigned_roots,
        administrator_root=administrator_root,
    )
    if projection_grants:
        grant_snapshot = store.snapshot()
        session_patch = prepare_append_relation_members(
            grant_snapshot,
            session_root,
            (
                (registry.roles["relation"], root)
                for root in projection_grants
            ),
            budget=100_000,
        )
        revision = store.commit(
            grant_snapshot.revision,
            create=session_patch.create,
            replace=session_patch.replace,
        )
    view = ApplicationViewSession(
        root_id=session_root,
        subject_root=subject_root,
        visibility_root=visibility_root,
        settings_root=settings.instance.root_id,
        theme_binding_root=theme_binding_root,
        theme_binding_source_incidence=theme_binding.build.incidence_ids[0],
        theme_binding_target_incidence=theme_binding.build.incidence_ids[1],
        theme_binding_mode_incidence=theme_binding.build.incidence_ids[2],
        tenant_membership_root=tenant_membership_root,
        tenant_role_membership_root=tenant_role_membership_root,
        principal_membership_root=principal_membership_root,
        properties_lens_root=lens_root,
        selection_state_root=selection_root,
        scope_trail_root=scope_trail_root,
        scope_exposure_root=scope_exposure_root,
        composition_history_root=composition_history_root,
        action_history_root=action_history_root,
        inspector_lens_binding_root=inspector_lens_binding_root,
        inspector_lens_incidence=(
            inspector_lens_binding.build.incidence_ids[0]
        ),
        properties_panel_binding_root=properties_panel_binding_root,
        properties_panel_incidence=(
            properties_panel_binding.build.incidence_ids[0]
        ),
        focus_incidence=lens.build.incidence_ids[0],
        selection_incidences=MappingProxyType({
            root: incidence
            for root, incidence in zip(
                assigned_roots, selection.build.incidence_ids
            )
        }),
        viewport_properties=MappingProxyType(viewport),
    )
    registry.view_sessions[subject_root] = view
    return view, revision


def _theme_revision(
    snapshot: Snapshot,
    registry: UniversalApplicationRegistry,
    view_session: ApplicationViewSession,
    revision_root: str | None = None,
):
    lifecycle = registry.standard_library.lifecycle_protocol
    instance = read_lifecycle_instance(
        snapshot,
        registry.assembly_protocol,
        lifecycle,
        view_session.settings_root,
    )
    heads = state_heads(
        snapshot,
        lifecycle,
        instance.state_pointers[lifecycle.states["wip"]],
    )
    if revision_root is None:
        if len(heads) != 1:
            raise InvalidCell(
                "personal settings have multiple WIP heads; select a preview"
            )
        revision_root = heads[0]
    if revision_root not in heads:
        raise InvalidCell("settings preview is not a current WIP head")
    return instance, read_revision(snapshot, lifecycle, revision_root), heads


def _theme_revision_owner(
    snapshot: Snapshot,
    registry: UniversalApplicationRegistry,
    revision_root: str,
):
    lifecycle = registry.standard_library.lifecycle_protocol
    matches = []
    for view in registry.view_sessions.values():
        instance = read_lifecycle_instance(
            snapshot,
            registry.assembly_protocol,
            lifecycle,
            view.settings_root,
        )
        if revision_root in lifecycle_history(snapshot, lifecycle, instance):
            matches.append((view, instance))
    if len(matches) != 1:
        raise InvalidCell("theme revision has no unique owning asset")
    view, instance = matches[0]
    return view, instance, read_revision(snapshot, lifecycle, revision_root)


def _bound_theme_revision(
    snapshot: Snapshot,
    registry: UniversalApplicationRegistry,
    view_session: ApplicationViewSession,
):
    members = read_relation(
        snapshot, view_session.theme_binding_root, budget=16
    )
    source_root = _one_for_role(members, registry.roles["source"])
    target_root = _one_for_role(members, registry.roles["target"])
    mode_root = _one_for_role(members, registry.roles["binding-mode"])
    if source_root is None or target_root is None or mode_root is None:
        raise InvalidCell("theme binding lacks source, target, or mode")
    if mode_root == registry.theme_binding_modes["personal"]:
        if source_root != view_session.settings_root:
            raise InvalidCell("personal WIP binding source has drifted")
        if target_root != view_session.settings_root:
            raise InvalidCell("personal WIP binding target has drifted")
        instance, revision, heads = _theme_revision(
            snapshot, registry, view_session
        )
        return view_session, instance, revision, heads, "personal-wip"
    if mode_root == registry.theme_binding_modes["audience-release"]:
        if (
            source_root != view_session.settings_root
            or target_root != view_session.settings_root
        ):
            raise InvalidCell("audience binding must retain the personal fallback")
        authority = registry.authorization
        audiences = {
            view_session.subject_root,
            *active_membership_roots(
                snapshot,
                authority.identity_protocol,
                authority.relationship_broker,
                view_session.subject_root,
                authority.tenant_root,
            ),
        }
        candidates = []
        for member in read_relation(
            snapshot, authority.identity_protocol.root_id, budget=100_000
        ):
            if member.role_id != authority.identity_protocol.roles[
                "relationship-member"
            ]:
                continue
            try:
                relation = verify_authority_relationship(
                    snapshot,
                    authority.identity_protocol,
                    authority.relationship_broker,
                    member.participant_id,
                )
            except RelationshipAuthorityDenied:
                continue
            if (
                relation.kind_root
                == authority.identity_protocol.kinds["audience-binding"]
                and relation.tenant_root == authority.tenant_root
                and relation.target_root in audiences
            ):
                candidates.append(relation)
        if len(candidates) > 1:
            raise InvalidCell(
                "theme audience resolves multiple active release bindings"
            )
        if not candidates:
            instance, revision, heads = _theme_revision(
                snapshot, registry, view_session
            )
            return (
                view_session,
                instance,
                revision,
                heads,
                "audience-fallback-personal",
            )
        binding = candidates[0]
        if binding.scope_root is None:
            raise InvalidCell("theme audience binding lacks a release revision")
        owner, instance, revision = _theme_revision_owner(
            snapshot, registry, binding.scope_root
        )
        if binding.source_root != owner.settings_root:
            raise InvalidCell("theme audience binding names the wrong source asset")
        _verify_released_theme_revision(
            snapshot, registry, owner, revision
        )
        lifecycle = registry.standard_library.lifecycle_protocol
        heads = state_heads(
            snapshot,
            lifecycle,
            instance.state_pointers[revision.state_root],
        )
        if revision.root_id not in heads:
            raise InvalidCell("theme audience revision is not a current state head")
        return owner, instance, revision, heads, "audience-release"
    if mode_root != registry.theme_binding_modes["direct-release"]:
        raise InvalidCell("theme binding mode is outside the released vocabulary")
    owner, instance, revision = _theme_revision_owner(
        snapshot, registry, target_root
    )
    lifecycle = registry.standard_library.lifecycle_protocol
    if source_root != owner.settings_root:
        raise InvalidCell("assigned theme binding names the wrong source asset")
    if revision.state_root not in (
        lifecycle.states["shared"], lifecycle.states["published"]
    ):
        raise InvalidCell("assigned theme revision is not Shared or Published")
    heads = state_heads(
        snapshot,
        lifecycle,
        instance.state_pointers[revision.state_root],
    )
    if revision.root_id not in heads:
        raise InvalidCell("assigned theme revision is not a current state head")
    _verify_released_theme_revision(snapshot, registry, owner, revision)
    return owner, instance, revision, heads, "direct-release"


def _activate_personal_theme_wip(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    view_session: ApplicationViewSession,
) -> int:
    """Rewire the visible binding back to this subject's personal WIP."""
    snapshot = store.snapshot()
    replacements = []
    desired = (
        (view_session.theme_binding_source_incidence, view_session.settings_root),
        (view_session.theme_binding_target_incidence, view_session.settings_root),
        (
            view_session.theme_binding_mode_incidence,
            registry.theme_binding_modes["personal"],
        ),
    )
    for incidence_id, participant_root in desired:
        incidence = snapshot.cells[incidence_id]
        if incidence.link1 != participant_root:
            replacements.append(Cell(
                incidence.id,
                incidence.link0,
                participant_root,
                incidence.atom,
            ))
    if not replacements:
        return snapshot.revision
    return store.commit(snapshot.revision, replace=replacements)


def _six_digit_color(value: str) -> bool:
    return (
        len(value) == 7
        and value.startswith("#")
        and all(
            character in "0123456789abcdefABCDEF"
            for character in value[1:]
        )
    )


def _versioned_asset_definition_root(
    store: CellStore,
    snapshot: Snapshot,
    registry: UniversalApplicationRegistry,
) -> str:
    matches = tuple(
        item["id"] for item in _project_standard_catalog(
            store, snapshot, registry
        )
        if item["name"] == "Versioned Asset"
    )
    if len(matches) != 1:
        raise InvalidCell("released Versioned Asset definition is ambiguous")
    return str(matches[0])


def _personal_presentation_bindings(
    snapshot: Snapshot,
    registry: UniversalApplicationRegistry,
    view_session: ApplicationViewSession,
) -> tuple[PersonalPresentationBinding, ...]:
    """Project exact personal presentation relations from one view session."""
    session_members = read_relation(
        snapshot, view_session.root_id, budget=100_000
    )
    binding_roots = tuple(
        member.participant_id for member in session_members
        if member.role_id == registry.roles["presentation-binding"]
    )
    if len(binding_roots) != len(set(binding_roots)):
        raise InvalidCell("view repeats a personal presentation binding")
    lifecycle = registry.standard_library.lifecycle_protocol
    projected = []
    keys: set[tuple[str, str]] = set()
    for binding_root in binding_roots:
        members = read_relation(snapshot, binding_root, budget=64)
        owner_root = _one_for_role(members, registry.roles["owner"])
        label_root = _one_for_role(members, registry.roles["label"])
        asset_root = _one_for_role(members, registry.roles["value"])
        source_root = _one_for_role(members, registry.roles["source"])
        scope_root = _one_for_role(members, registry.roles["scope"])
        authority_root = _one_for_role(members, registry.roles["authority"])
        mode_root = _one_for_role(members, registry.roles["binding-mode"])
        contract_root = _one_for_role(members, registry.roles["contract"])
        if None in (
            owner_root,
            label_root,
            asset_root,
            source_root,
            scope_root,
            authority_root,
            mode_root,
            contract_root,
        ):
            raise InvalidCell("personal presentation binding is incomplete")
        if scope_root != view_session.root_id:
            raise InvalidCell("personal presentation binding crossed its view")
        if authority_root != view_session.subject_root:
            raise InvalidCell("personal presentation binding authority drifted")
        if mode_root != _PRESENTATION_FALLBACK_MODE_ROOT:
            raise InvalidCell("personal presentation binding mode drifted")
        if contract_root != _PRESENTATION_COLOR_CONTRACT_ROOT:
            raise InvalidCell("personal presentation contract drifted")
        source_members = read_relation(snapshot, source_root, budget=64)
        source_owner = _one_for_role(
            source_members, registry.roles["owner"]
        )
        source_label = _one_for_role(
            source_members, registry.roles["label"]
        )
        source_value = _one_for_role(
            source_members, registry.roles["value"]
        )
        if (
            source_owner != owner_root
            or source_label != label_root
            or source_value is None
        ):
            raise InvalidCell("personal presentation source binding drifted")
        if _text(snapshot, label_root) != "color":
            raise InvalidCell("unsupported personal presentation contract")
        source_color = _text(snapshot, source_value)
        if not _six_digit_color(source_color):
            raise InvalidCell("base presentation color is invalid")
        key = (str(owner_root), str(label_root))
        if key in keys:
            raise InvalidCell("personal presentation binding is ambiguous")
        keys.add(key)
        instance = read_lifecycle_instance(
            snapshot,
            registry.assembly_protocol,
            lifecycle,
            str(asset_root),
        )
        heads = state_heads(
            snapshot,
            lifecycle,
            instance.state_pointers[lifecycle.states["wip"]],
        )
        if len(heads) != 1:
            raise InvalidCell(
                "personal presentation has multiple WIP heads; select a preview"
            )
        revision = read_revision(snapshot, lifecycle, heads[0])
        content = snapshot.cells[revision.content_root]
        if content.link0 != NULL_CELL_ID or content.link1 != NULL_CELL_ID:
            raise InvalidCell("personal presentation value is not scalar")
        try:
            value = content.atom.decode("ascii")
        except UnicodeDecodeError as exc:
            raise InvalidCell("personal presentation value is not ASCII") from exc
        if value and not _six_digit_color(value):
            raise InvalidCell("personal presentation color is invalid")
        history = []
        for historical_root in lifecycle_history(
            snapshot, lifecycle, instance
        ):
            historical = read_revision(
                snapshot, lifecycle, historical_root
            )
            historical_value = snapshot.cells[
                historical.content_root
            ].atom.decode("ascii")
            if historical_value and not _six_digit_color(historical_value):
                raise InvalidCell(
                    "personal presentation history contains invalid color"
                )
            history.append({
                "revision": historical.root_id,
                "state": _text(snapshot, historical.state_root),
                "value": historical_value,
                "actor": historical.actor_root,
                "timestamp": (
                    _text(snapshot, historical.timestamp_root)
                    if historical.timestamp_root else None
                ),
                "reason": (
                    _text(snapshot, historical.reason_root)
                    if historical.reason_root else None
                ),
                "digest": _text(snapshot, historical.content_digest_root),
                "parents": list(historical.predecessor_roots),
                "current": historical.root_id == revision.root_id,
            })
        projected.append(PersonalPresentationBinding(
            str(binding_root),
            str(owner_root),
            str(label_root),
            str(asset_root),
            str(source_root),
            str(scope_root),
            str(authority_root),
            str(mode_root),
            str(contract_root),
            revision.root_id,
            value,
            tuple(history),
        ))
    return tuple(projected)


def _personal_presentation_binding_for(
    snapshot: Snapshot,
    registry: UniversalApplicationRegistry,
    view_session: ApplicationViewSession,
    owner_root: str,
    label_root: str,
) -> PersonalPresentationBinding | None:
    matches = tuple(
        binding for binding in _personal_presentation_bindings(
            snapshot, registry, view_session
        )
        if binding.owner_root == owner_root
        and binding.label_root == label_root
    )
    if len(matches) > 1:
        raise InvalidCell("personal presentation binding is ambiguous")
    return matches[0] if matches else None


def _presentation_source_property(
    snapshot: Snapshot,
    registry: UniversalApplicationRegistry,
    view_session: ApplicationViewSession,
    owner_root: str,
    label: str,
) -> PropertyProjection:
    visible_roots, _, property_roots = _session_canvas_roots(
        snapshot, registry, view_session
    )
    if owner_root not in visible_roots:
        raise InvalidCell("presentation owner is outside the active canvas")
    matches = tuple(
        row for row in _property_index(
            snapshot, registry, property_roots
        ).get(owner_root, ())
        if _text(snapshot, row.label_root) == label
    )
    if len(matches) != 1:
        raise InvalidCell("presentation source property is not unique")
    if label == "color" and not _six_digit_color(
        _text(snapshot, matches[0].value_root)
    ):
        raise InvalidCell("base presentation color is invalid")
    return matches[0]


def preview_universal_presentation_color(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    owner_root: str,
    color: str,
    *,
    base_revision_root: str | None = None,
    authentication_context: object | None = None,
) -> str:
    """Append one subject-owned visual override without changing base data."""
    if type(owner_root) is not str or not owner_root:
        raise InvalidCell("presentation owner requires one exact Cell")
    if type(color) is not str or not _six_digit_color(color):
        raise InvalidCell("presentation color requires #RRGGBB")
    snapshot = store.snapshot()
    view_session, context = _view_session_for_context(
        registry, authentication_context
    )
    _require_application_authorization(
        snapshot,
        registry,
        "edit",
        view_session.root_id,
        authentication_context=context,
        resource_lineage_roots=(
            registry.authorization.personal_view_scope_root,
        ),
    )
    source = _presentation_source_property(
        snapshot, registry, view_session, owner_root, "color"
    )
    actor_root = registry.authorization.broker.resolve(context).subject_root
    binding = _personal_presentation_binding_for(
        snapshot, registry, view_session, owner_root, source.label_root
    )
    if binding is not None:
        if binding.authority_root != actor_root:
            raise InvalidCell("presentation binding is outside actor authority")
        revision_root = append_wip_revision(
            store,
            registry.assembly_protocol,
            registry.standard_library.lifecycle_protocol,
            binding.asset_root,
            content=color.lower().encode("ascii"),
            actor_root=actor_root,
            base_revision_root=base_revision_root,
            reason="personal presentation color preview",
        )
        return revision_root
    if base_revision_root is not None:
        raise InvalidCell("new presentation binding has no base revision")

    definition_root = _versioned_asset_definition_root(
        store, snapshot, registry
    )
    token = "presentation-" + uuid.uuid5(
        uuid.NAMESPACE_URL,
        "\0".join((view_session.root_id, owner_root, source.label_root)),
    ).hex
    composed = seed_composed_lifecycle_content(
        snapshot,
        registry.assembly_protocol,
        registry.standard_library.lifecycle_protocol,
        compose_catalog_instance(
            snapshot,
            registry.assembly_protocol,
            registry.standard_library.catalog_root,
            definition_root,
            token=token,
        ),
        color.lower().encode("ascii"),
        actor_root=actor_root,
    )
    binding_root = "app:presentation-binding:" + uuid.uuid5(
        uuid.NAMESPACE_URL,
        "\0".join((view_session.root_id, owner_root, source.label_root)),
    ).hex
    if binding_root in snapshot.cells:
        raise InvalidCell("partial personal presentation binding exists")
    relation = compose_relation_cells((
        (registry.roles["owner"], owner_root),
        (registry.roles["label"], source.label_root),
        (registry.roles["value"], composed.instance.root_id),
        (registry.roles["source"], source.relation_root),
        (registry.roles["scope"], view_session.root_id),
        (registry.roles["authority"], actor_root),
        (registry.roles["binding-mode"], _PRESENTATION_FALLBACK_MODE_ROOT),
        (registry.roles["contract"], _PRESENTATION_COLOR_CONTRACT_ROOT),
    ), relation_id=binding_root)
    session_patch = prepare_append_relation_members(
        snapshot,
        view_session.root_id,
        ((registry.roles["presentation-binding"], binding_root),),
        budget=100_000,
    )
    application_patch = prepare_append_relation_members(
        snapshot,
        registry.application_root,
        (
            (registry.roles["member"], binding_root),
            (registry.roles["member"], composed.instance.root_id),
        ),
        budget=100_000,
    )
    store.commit(
        snapshot.revision,
        create=(
            *composed.cells,
            *relation.cells,
            *session_patch.create,
            *application_patch.create,
        ),
        replace=(
            *session_patch.replace,
            *application_patch.replace,
        ),
    )
    instance = read_lifecycle_instance(
        store.snapshot(),
        registry.assembly_protocol,
        registry.standard_library.lifecycle_protocol,
        composed.instance.root_id,
    )
    heads = state_heads(
        store.snapshot(),
        registry.standard_library.lifecycle_protocol,
        instance.state_pointers[
            registry.standard_library.lifecycle_protocol.states["wip"]
        ],
    )
    if len(heads) != 1:
        raise InvalidCell("new personal presentation WIP is ambiguous")
    return heads[0]


def reset_universal_presentation_color(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    owner_root: str,
    *,
    base_revision_root: str | None = None,
    authentication_context: object | None = None,
) -> str:
    """Append a fallback WIP revision; history is never deleted."""
    snapshot = store.snapshot()
    view_session, context = _view_session_for_context(
        registry, authentication_context
    )
    _require_application_authorization(
        snapshot,
        registry,
        "edit",
        view_session.root_id,
        authentication_context=context,
        resource_lineage_roots=(
            registry.authorization.personal_view_scope_root,
        ),
    )
    source = _presentation_source_property(
        snapshot, registry, view_session, owner_root, "color"
    )
    binding = _personal_presentation_binding_for(
        snapshot, registry, view_session, owner_root, source.label_root
    )
    if binding is None or not binding.value:
        raise InvalidCell("presentation color has no personal override")
    actor_root = registry.authorization.broker.resolve(context).subject_root
    if binding.authority_root != actor_root:
        raise InvalidCell("presentation binding is outside actor authority")
    return append_wip_revision(
        store,
        registry.assembly_protocol,
        registry.standard_library.lifecycle_protocol,
        binding.asset_root,
        content=b"",
        actor_root=actor_root,
        base_revision_root=base_revision_root,
        reason="reset personal presentation color to source",
    )


def _decode_theme_document(
    snapshot: Snapshot,
    registry: UniversalApplicationRegistry,
    content_root: str,
) -> dict[str, str]:
    try:
        document = json.loads(
            snapshot.cells[content_root].atom.decode("utf-8")
        )
    except (KeyError, UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise InvalidCell("personal theme revision is invalid JSON") from exc
    expected = set(registry.presentation.theme_roots)
    if not isinstance(document, dict) or set(document) != expected:
        raise InvalidCell("personal theme revision has an invalid token set")
    if any(
        not isinstance(value, str)
        or not value
        or len(value) > 128
        or any(character in value for character in ";{}<>")
        for value in document.values()
    ):
        raise InvalidCell("personal theme revision has an unsafe token value")
    return {name: document[name] for name in sorted(document)}


def _court_evidence_summary(
    snapshot: Snapshot,
    registry: UniversalApplicationRegistry,
    evidence_root: str,
) -> dict[str, object]:
    evidence = read_court_attestation(
        snapshot, registry.attestation_protocol, evidence_root
    )
    try:
        statement = json.loads(
            snapshot.cells[evidence.payload_root].atom.decode("utf-8")
        )
        predicate = statement["predicate"]
        subject = statement["subject"][0]
        checks = predicate["checks"]
        builder = predicate["builder"]
    except (KeyError, IndexError, TypeError, UnicodeDecodeError,
            json.JSONDecodeError) as exc:
        raise InvalidCell("court evidence statement is invalid") from exc
    if not isinstance(checks, dict):
        raise InvalidCell("court evidence checks are invalid")
    return {
        "root": evidence_root,
        "court": evidence.court_root,
        "result": _text(snapshot, evidence.result_root),
        "subject": subject.get("name"),
        "digest": subject.get("digest", {}).get("sha256"),
        "predicate_type": statement.get("predicateType"),
        "builder": builder.get("id"),
        "runner_version": builder.get("version"),
        "duration_ms": predicate.get("durationMs"),
        "checks": {
            str(name): value is True
            for name, value in sorted(checks.items())
        },
    }


def read_universal_theme(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    *,
    authentication_context: object | None = None,
) -> tuple[dict[str, str], dict[str, object]]:
    snapshot = store.snapshot()
    view_session, context = _view_session_for_context(
        registry, authentication_context
    )
    _require_application_authorization(
        snapshot,
        registry,
        "inspect",
        view_session.root_id,
        authentication_context=context,
        resource_lineage_roots=(
            registry.authorization.personal_view_scope_root,
        ),
    )
    owner, _, revision, heads, binding_mode = _bound_theme_revision(
        snapshot, registry, view_session
    )
    return _decode_theme_document(
        snapshot, registry, revision.content_root
    ), {
        "asset": owner.settings_root,
        "personal_asset": view_session.settings_root,
        "binding": view_session.theme_binding_root,
        "binding_mode": binding_mode,
        "preview_revision": revision.root_id,
        "state": _text(snapshot, revision.state_root),
        "digest": _text(snapshot, revision.content_digest_root),
        "heads": list(heads),
        "wip_heads": list(heads) if binding_mode == "personal-wip" else [],
        "actor": revision.actor_root,
        "parents": list(revision.predecessor_roots),
    }


def preview_universal_theme(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    changes: Mapping[str, str],
    *,
    base_revision_root: str | None = None,
    authentication_context: object | None = None,
) -> str:
    """Append a subject-owned WIP theme revision; never broadcast it."""
    snapshot = store.snapshot()
    view_session, context = _view_session_for_context(
        registry, authentication_context
    )
    _require_application_authorization(
        snapshot,
        registry,
        "edit",
        view_session.root_id,
        authentication_context=context,
        resource_lineage_roots=(
            registry.authorization.personal_view_scope_root,
        ),
    )
    _, base, _ = _theme_revision(
        snapshot, registry, view_session, base_revision_root
    )
    theme = _decode_theme_document(snapshot, registry, base.content_root)
    if not changes or any(name not in theme for name in changes):
        raise InvalidCell("theme preview changes contain an unknown token")
    theme.update({name: str(value) for name, value in changes.items()})
    payload = json.dumps(
        theme, sort_keys=True, separators=(",", ":")
    ).encode("utf-8")
    # Validate the exact payload before it enters immutable history.
    if any(
        not value or len(value) > 128
        or any(character in value for character in ";{}<>")
        for value in theme.values()
    ):
        raise InvalidCell("theme preview contains an unsafe token value")
    identity = registry.authorization.broker.resolve(context)
    revision_root = append_wip_revision(
        store,
        registry.assembly_protocol,
        registry.standard_library.lifecycle_protocol,
        view_session.settings_root,
        content=payload,
        actor_root=identity.subject_root,
        base_revision_root=base.root_id,
        reason="personal theme preview",
    )
    _activate_personal_theme_wip(store, registry, view_session)
    return revision_root


def restore_universal_theme_revision(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    historical_revision_root: str,
    *,
    base_revision_root: str | None = None,
    authentication_context: object | None = None,
) -> str:
    """Restore historical theme content as a new subject-owned WIP revision."""
    snapshot = store.snapshot()
    view_session, context = _view_session_for_context(
        registry, authentication_context
    )
    _require_application_authorization(
        snapshot,
        registry,
        "edit",
        view_session.root_id,
        authentication_context=context,
        resource_lineage_roots=(
            registry.authorization.personal_view_scope_root,
        ),
    )
    identity = registry.authorization.broker.resolve(context)
    revision_root = restore_revision_as_wip(
        store,
        registry.assembly_protocol,
        registry.standard_library.lifecycle_protocol,
        view_session.settings_root,
        historical_revision_root,
        actor_root=identity.subject_root,
        base_revision_root=base_revision_root,
    )
    _activate_personal_theme_wip(store, registry, view_session)
    return revision_root


def promote_universal_theme_to_shared(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    *,
    source_revision_root: str | None = None,
    authentication_context: object | None = None,
) -> tuple[str, str]:
    """Run the admitted court, then promote one exact WIP revision to Shared.

    Promotion does not assign the revision to any audience and therefore does
    not broadcast the visual change.  Audience binding is a separate governed
    operation.
    """
    snapshot = store.snapshot()
    view_session, context = _view_session_for_context(
        registry, authentication_context
    )
    _require_application_authorization(
        snapshot,
        registry,
        "promote",
        view_session.settings_root,
        authentication_context=context,
        resource_lineage_roots=(
            registry.authorization.personal_view_scope_root,
        ),
    )
    instance, source, _ = _theme_revision(
        snapshot, registry, view_session, source_revision_root
    )
    lifecycle = registry.standard_library.lifecycle_protocol
    shared_heads = state_heads(
        snapshot,
        lifecycle,
        instance.state_pointers[lifecycle.states["shared"]],
    )
    if any(
        source.root_id in read_revision(
            snapshot, lifecycle, revision_root
        ).predecessor_roots
        for revision_root in shared_heads
    ):
        raise InvalidCell("theme WIP revision was already promoted to Shared")
    # Parsing before court execution fails closed on corrupt graph content.
    _decode_theme_document(snapshot, registry, source.content_root)
    subject_digest = _text(snapshot, source.content_digest_root)
    target_state = lifecycle.states["shared"]
    parameters = {
        "asset": view_session.settings_root,
        "targetState": target_state,
    }
    evidence_root = registry.attestation_broker.run(
        store,
        registry.attestation_protocol,
        registry.theme_court_root,
        subject_name=source.root_id,
        subject_content=snapshot.cells[source.content_root].atom,
        external_parameters=parameters,
    )
    evidence_receipt = registry.attestation_broker.consume(
        store.snapshot(),
        registry.attestation_protocol,
        evidence_root,
        purpose="promote:%s:%s" % (
            view_session.settings_root, target_state
        ),
        expected_court_root=registry.theme_court_root,
        expected_subject_name=source.root_id,
        expected_subject_digest=subject_digest,
        expected_parameters=parameters,
    )
    identity = registry.authorization.broker.resolve(context)
    promoted_root = promote_revision(
        store,
        registry.assembly_protocol,
        registry.standard_library.lifecycle_protocol,
        view_session.settings_root,
        target_state_root=target_state,
        source_revision_root=source.root_id,
        actor_root=identity.subject_root,
        evidence_roots=(evidence_root,),
        evidence_receipts=(evidence_receipt,),
        attestation_broker=registry.attestation_broker,
    )
    return promoted_root, evidence_root


def _verify_theme_promotion_evidence(
    snapshot: Snapshot,
    registry: UniversalApplicationRegistry,
    source_view: ApplicationViewSession,
    revision,
    *,
    expected_state_root: str,
    court_root: str,
    extra_parameters: Mapping[str, str] | None = None,
) -> None:
    if revision.state_root != expected_state_root:
        raise InvalidCell("theme revision is in the wrong lifecycle state")
    if len(revision.predecessor_roots) != 1 or not revision.evidence_roots:
        raise InvalidCell("theme revision lacks promotion provenance")
    parameters = {
        "asset": source_view.settings_root,
        "targetState": expected_state_root,
        **dict(extra_parameters or {}),
    }
    for evidence_root in revision.evidence_roots:
        try:
            registry.attestation_broker.verify(
                snapshot,
                registry.attestation_protocol,
                evidence_root,
                expected_court_root=court_root,
                expected_subject_name=revision.predecessor_roots[0],
                expected_subject_digest=_text(
                    snapshot, revision.content_digest_root
                ),
                expected_parameters=parameters,
            )
            return
        except (InvalidCell, PermissionError):
            continue
    raise InvalidCell("theme revision has no valid admitted court evidence")


def _verify_released_theme_revision(
    snapshot: Snapshot,
    registry: UniversalApplicationRegistry,
    source_view: ApplicationViewSession,
    revision,
) -> None:
    lifecycle = registry.standard_library.lifecycle_protocol
    if revision.state_root == lifecycle.states["shared"]:
        _verify_theme_promotion_evidence(
            snapshot,
            registry,
            source_view,
            revision,
            expected_state_root=lifecycle.states["shared"],
            court_root=registry.theme_court_root,
        )
        return
    if revision.state_root == lifecycle.states["published"]:
        endpoint = registry.browser_publish_court.endpoint
        if endpoint is None:
            raise InvalidCell("Published theme court endpoint is unavailable")
        _verify_theme_promotion_evidence(
            snapshot,
            registry,
            source_view,
            revision,
            expected_state_root=lifecycle.states["published"],
            court_root=registry.theme_publish_court_root,
            extra_parameters={"endpoint": endpoint},
        )
        return
    raise InvalidCell("theme revision is not a court-backed release")


def promote_universal_theme_to_published(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    *,
    source_revision_root: str | None = None,
    authentication_context: object | None = None,
) -> tuple[str, str]:
    """Run the independent browser court over Shared, then publish exactly it."""
    snapshot = store.snapshot()
    view_session, context = _view_session_for_context(
        registry, authentication_context
    )
    _require_application_authorization(
        snapshot,
        registry,
        "publish",
        view_session.settings_root,
        authentication_context=context,
        resource_lineage_roots=(
            registry.authorization.personal_view_scope_root,
        ),
    )
    lifecycle = registry.standard_library.lifecycle_protocol
    instance = read_lifecycle_instance(
        snapshot,
        registry.assembly_protocol,
        lifecycle,
        view_session.settings_root,
    )
    shared_heads = state_heads(
        snapshot,
        lifecycle,
        instance.state_pointers[lifecycle.states["shared"]],
    )
    if source_revision_root is None:
        if len(shared_heads) != 1:
            raise InvalidCell(
                "theme Shared state requires one explicitly selected head"
            )
        source_revision_root = shared_heads[0]
    if source_revision_root not in shared_heads:
        raise InvalidCell("theme publication source is not a Shared head")
    source = read_revision(snapshot, lifecycle, source_revision_root)
    _verify_theme_promotion_evidence(
        snapshot,
        registry,
        view_session,
        source,
        expected_state_root=lifecycle.states["shared"],
        court_root=registry.theme_court_root,
    )
    published_heads = state_heads(
        snapshot,
        lifecycle,
        instance.state_pointers[lifecycle.states["published"]],
    )
    if any(
        source.root_id in read_revision(
            snapshot, lifecycle, revision_root
        ).predecessor_roots
        for revision_root in published_heads
    ):
        raise InvalidCell("theme Shared revision was already Published")
    _, _, active, _, _ = _bound_theme_revision(
        snapshot, registry, view_session
    )
    source_digest = _text(snapshot, source.content_digest_root)
    if _text(snapshot, active.content_digest_root) != source_digest:
        raise InvalidCell(
            "active preview differs from the Shared revision under browser court"
        )
    endpoint = registry.browser_publish_court.endpoint
    if endpoint is None:
        raise InvalidCell("browser publication court is not attached")
    parameters = {
        "asset": view_session.settings_root,
        "targetState": lifecycle.states["published"],
        "endpoint": endpoint,
    }
    evidence_root = registry.attestation_broker.run(
        store,
        registry.attestation_protocol,
        registry.theme_publish_court_root,
        subject_name=source.root_id,
        subject_content=snapshot.cells[source.content_root].atom,
        external_parameters=parameters,
    )
    # The browser ran outside graph mutation authority. Recheck every exact
    # binding after it returns before consuming evidence or promoting.
    current = store.snapshot()
    current_instance = read_lifecycle_instance(
        current,
        registry.assembly_protocol,
        lifecycle,
        view_session.settings_root,
    )
    if source.root_id not in state_heads(
        current,
        lifecycle,
        current_instance.state_pointers[lifecycle.states["shared"]],
    ):
        raise InvalidCell("Shared theme head changed during browser court")
    current_source = read_revision(current, lifecycle, source.root_id)
    _, _, current_active, _, _ = _bound_theme_revision(
        current, registry, view_session
    )
    if (
        _text(current, current_source.content_digest_root) != source_digest
        or _text(current, current_active.content_digest_root) != source_digest
    ):
        raise InvalidCell("theme digest changed during browser court")
    evidence_receipt = registry.attestation_broker.consume(
        current,
        registry.attestation_protocol,
        evidence_root,
        purpose="promote:%s:%s" % (
            view_session.settings_root, lifecycle.states["published"]
        ),
        expected_court_root=registry.theme_publish_court_root,
        expected_subject_name=source.root_id,
        expected_subject_digest=source_digest,
        expected_parameters=parameters,
        max_age_seconds=300.0,
    )
    identity = registry.authorization.broker.resolve(context)
    promoted_root = promote_revision(
        store,
        registry.assembly_protocol,
        lifecycle,
        view_session.settings_root,
        target_state_root=lifecycle.states["published"],
        source_revision_root=source.root_id,
        actor_root=identity.subject_root,
        evidence_roots=(evidence_root,),
        evidence_receipts=(evidence_receipt,),
        attestation_broker=registry.attestation_broker,
    )
    return promoted_root, evidence_root


def assign_released_universal_theme(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    target_subject_root: str,
    release_revision_root: str,
    *,
    authentication_context: object | None = None,
) -> int:
    """Explicitly wire one court-backed Shared/Published release to one subject."""
    snapshot = store.snapshot()
    try:
        target_view = registry.view_sessions[target_subject_root]
    except KeyError as exc:
        raise InvalidCell("theme audience has no provisioned view session") from exc
    context = _active_authentication_context(
        registry.authorization, authentication_context
    )
    _require_application_authorization(
        snapshot,
        registry,
        "share",
        target_view.root_id,
        authentication_context=context,
        resource_lineage_roots=(
            registry.authorization.personal_view_scope_root,
        ),
    )
    source_view, _, revision = _theme_revision_owner(
        snapshot, registry, release_revision_root
    )
    _verify_released_theme_revision(snapshot, registry, source_view, revision)
    source_incidence = snapshot.cells[
        target_view.theme_binding_source_incidence
    ]
    target_incidence = snapshot.cells[
        target_view.theme_binding_target_incidence
    ]
    mode_incidence = snapshot.cells[
        target_view.theme_binding_mode_incidence
    ]
    return store.commit(snapshot.revision, replace=(
        Cell(
            source_incidence.id,
            source_incidence.link0,
            source_view.settings_root,
            source_incidence.atom,
        ),
        Cell(
            target_incidence.id,
            target_incidence.link0,
            release_revision_root,
            target_incidence.atom,
        ),
        Cell(
            mode_incidence.id,
            mode_incidence.link0,
            registry.theme_binding_modes["direct-release"],
            mode_incidence.atom,
        ),
    ))


def assign_shared_universal_theme(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    target_subject_root: str,
    shared_revision_root: str,
    *,
    authentication_context: object | None = None,
) -> int:
    """Compatibility name for an exact court-backed Shared assignment."""
    snapshot = store.snapshot()
    _, _, revision = _theme_revision_owner(
        snapshot, registry, shared_revision_root
    )
    if (
        revision.state_root
        != registry.standard_library.lifecycle_protocol.states["shared"]
    ):
        raise InvalidCell("theme assignment source is not Shared")
    return assign_released_universal_theme(
        store,
        registry,
        target_subject_root,
        shared_revision_root,
        authentication_context=authentication_context,
    )


def assign_released_universal_theme_to_audience(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    audience_root: str,
    release_revision_root: str,
    *,
    reason: str,
    authentication_context: object | None = None,
) -> tuple[str, int]:
    """Bind one tested release to a subject/group through one signed relation."""
    authority = registry.authorization
    context = _active_authentication_context(authority, authentication_context)
    snapshot = store.snapshot()
    if audience_root not in snapshot.cells:
        raise InvalidCell("theme audience is missing")
    _require_application_authorization(
        snapshot,
        registry,
        "share",
        audience_root,
        authentication_context=context,
    )
    source_view, _, revision = _theme_revision_owner(
        snapshot, registry, release_revision_root
    )
    _verify_released_theme_revision(snapshot, registry, source_view, revision)

    existing_roots = []
    for member in read_relation(
        snapshot, authority.identity_protocol.root_id, budget=100_000
    ):
        if member.role_id != authority.identity_protocol.roles[
            "relationship-member"
        ]:
            continue
        try:
            relationship = verify_authority_relationship(
                snapshot,
                authority.identity_protocol,
                authority.relationship_broker,
                member.participant_id,
            )
        except RelationshipAuthorityDenied:
            continue
        if (
            relationship.kind_root
            == authority.identity_protocol.kinds["audience-binding"]
            and relationship.tenant_root == authority.tenant_root
            and relationship.target_root == audience_root
        ):
            if (
                relationship.source_root == source_view.settings_root
                and relationship.scope_root == release_revision_root
            ):
                return relationship.root_id, store.revision
            existing_roots.append(relationship.root_id)
    for relationship_root in existing_roots:
        revoke_universal_authority_relationship(
            store,
            registry,
            relationship_root,
            reason="superseded audience release",
            authentication_context=context,
        )
    return issue_universal_authority_relationship(
        store,
        registry,
        source_root=source_view.settings_root,
        target_root=audience_root,
        kind="audience-binding",
        scope_root=release_revision_root,
        reason=reason,
        evidence_roots=revision.evidence_roots,
        authentication_context=context,
    )


def follow_universal_theme_audience(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    *,
    authentication_context: object | None = None,
) -> int:
    """Explicitly return one subject from personal WIP to audience resolution."""
    snapshot = store.snapshot()
    view_session, context = _view_session_for_context(
        registry, authentication_context
    )
    _require_application_authorization(
        snapshot,
        registry,
        "edit",
        view_session.root_id,
        authentication_context=context,
        resource_lineage_roots=(
            registry.authorization.personal_view_scope_root,
        ),
    )
    desired = (
        (view_session.theme_binding_source_incidence, view_session.settings_root),
        (view_session.theme_binding_target_incidence, view_session.settings_root),
        (
            view_session.theme_binding_mode_incidence,
            registry.theme_binding_modes["audience-release"],
        ),
    )
    replacements = []
    for incidence_root, participant_root in desired:
        incidence = snapshot.cells[incidence_root]
        if incidence.link1 != participant_root:
            replacements.append(Cell(
                incidence.id,
                incidence.link0,
                participant_root,
                incidence.atom,
            ))
    if not replacements:
        return snapshot.revision
    return store.commit(snapshot.revision, replace=replacements)


def _prepare_atomic_viewport_replacements(
    snapshot: Snapshot,
    view_session: ApplicationViewSession,
    viewport: Mapping[str, float] | None,
) -> tuple[Cell, ...]:
    if viewport is None:
        return ()
    if not isinstance(viewport, Mapping):
        raise InvalidCell("atomic placement viewport must be a mapping")
    if set(viewport) != {"pan_x", "pan_y", "zoom"}:
        raise InvalidCell("atomic placement viewport is incomplete")
    try:
        values = {
            name: float(viewport[name])
            for name in ("pan_x", "pan_y", "zoom")
        }
    except (KeyError, TypeError, ValueError) as exc:
        raise InvalidCell(
            "atomic placement viewport values must be numeric"
        ) from exc
    if not all(math.isfinite(value) for value in values.values()):
        raise InvalidCell("atomic placement viewport values must be finite")
    if not 0.1 <= values["zoom"] <= 4.0:
        raise InvalidCell("atomic placement zoom is outside the supported range")
    replacements = []
    for name, value in values.items():
        value_root = view_session.viewport_properties[name].value_root
        current = snapshot.cells[value_root]
        replacements.append(Cell(
            current.id, current.link0, current.link1, _atom(value)
        ))
    return tuple(replacements)


def _commit_atomic_visible_wip_resource(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    snapshot: Snapshot,
    view_session: ApplicationViewSession,
    context: object,
    *,
    route: str,
    command_name: str,
    authorization_scope_root: str,
    resource_root: str,
    resource_cells: tuple[Cell, ...],
    property_refs: tuple[PropertyRef, ...],
    property_cells: tuple[Cell, ...],
    audience_release_root: str | None = None,
    additional_create: tuple[Cell, ...] = (),
    additional_replace: tuple[Cell, ...] = (),
    viewport: Mapping[str, float] | None = None,
    activate_view: bool = True,
    leased_scope_root: str | None = None,
) -> int:
    """Commit one governed WIP resource, view, focus, and grants together."""
    if type(activate_view) is not bool:
        raise InvalidCell("atomic WIP view activation flag must be boolean")
    if viewport is not None and not activate_view:
        raise InvalidCell("atomic viewport edits require view activation")
    if leased_scope_root is None:
        active_scope_root = _read_view_scope_trail(
            snapshot,
            registry,
            view_session,
        )[-1]
    else:
        if type(leased_scope_root) is not str or not leased_scope_root:
            raise InvalidCell("leased placement scope is invalid")
        structural_trail = _read_view_scope_trail_structure(
            snapshot, registry, view_session
        )
        if structural_trail[-1] != leased_scope_root:
            raise InvalidCell("leased placement scope drifted")
        active_scope_root = leased_scope_root
    direct_view_assignment = (
        not activate_view or active_scope_root == registry.canvas_root
    )
    if activate_view:
        exposure_create, exposure_replace = (
            _prepare_active_top_scope_exposure_extension(
                snapshot,
                registry,
                view_session,
                resource_root,
                active_scope_root,
            )
        )
    else:
        exposure_create, exposure_replace = (), ()
    scope_patch = None
    if activate_view and active_scope_root != registry.canvas_root:
        if _relation_members_or_none(snapshot, active_scope_root) is None:
            raise InvalidCell(
                "active placement scope is not an openable relation"
            )
        scope_patch = prepare_append_relation_members(
            snapshot,
            active_scope_root,
            ((registry.roles["member"], resource_root),),
            budget=_SCOPE_MEMBER_LIMIT,
        )
    canvas_patch = prepare_append_relation_members(
        snapshot,
        registry.canvas_root,
        (
            *((
                (registry.roles["member"], resource_root),
            ) if direct_view_assignment else ()),
            *((registry.roles["property"], ref.relation_root)
              for ref in property_refs),
        ),
        budget=100_000,
    )
    lens_patch = prepare_append_relation_members(
        snapshot,
        view_session.properties_lens_root,
        ((registry.roles["scope"], ref.relation_root)
         for ref in property_refs),
        budget=100_000,
    )
    visibility_patch = (
        prepare_append_relation_members(
            snapshot,
            view_session.visibility_root,
            ((registry.roles["visible"], resource_root),),
            budget=100_000,
        )
        if direct_view_assignment
        else None
    )
    if activate_view:
        selection_patch = prepare_append_relation_members(
            snapshot,
            view_session.selection_state_root,
            ((registry.roles["selected"], resource_root),),
            budget=100_000,
        )
        selection_transition = _prepare_selection_transition(
            snapshot,
            registry,
            view_session,
            (resource_root,),
            resource_root,
            pending_roots=(resource_root,),
            scope_root=active_scope_root,
        )
        selection_transition_create = selection_transition.create
        selection_transition_replace = selection_transition.replace
        selection_patch_create = selection_patch.create
        selection_patch_replace = selection_patch.replace
    else:
        selection_transition_create = ()
        selection_transition_replace = ()
        selection_patch_create = ()
        selection_patch_replace = ()

    identity = registry.authorization.identity_protocol
    relationship_broker = registry.authorization.relationship_broker
    administrator_root = registry.authorization.broker.resolve(
        context
    ).subject_root
    if viewport is not None:
        _authorize(
            snapshot,
            registry,
            "canvas.select",
            object_root=view_session.root_id,
            authentication_context=context,
            resource_lineage_roots=(
                registry.authorization.personal_view_scope_root,
            ),
        )
    viewport_replacements = _prepare_atomic_viewport_replacements(
        snapshot, view_session, viewport
    )
    pending_cells = (
        *resource_cells,
        *property_cells,
        *additional_create,
        *exposure_create,
        *((scope_patch.create) if scope_patch is not None else ()),
        *selection_transition_create,
        *canvas_patch.create,
        *lens_patch.create,
        *selection_patch_create,
        *((visibility_patch.create) if visibility_patch is not None else ()),
    )
    pending_ids = tuple(cell.id for cell in pending_cells)
    if (
        len(pending_ids) != len(set(pending_ids))
        or any(root_id in snapshot.cells for root_id in pending_ids)
        or resource_root not in pending_ids
    ):
        raise InvalidCell("atomic WIP resource has invalid pending identities")
    read_root = registry.authorization.protocol.actions["read"]
    audience_grant = prepare_authority_relationship_grant(
        snapshot,
        identity,
        relationship_broker,
        relationship_broker.mint_from_trusted_administrator(
            administrator_root
        ),
        relationship_id=_resource_audience_binding_root(resource_root),
        source_root=resource_root,
        target_root=registry.authorization.audience_root,
        kind="audience-binding",
        tenant_root=registry.authorization.tenant_root,
        administrator_root=administrator_root,
        scope_root=registry.authorization.classification_root,
        action_roots=(read_root,),
        reason="resource is classified and released to this audience",
        evidence_roots=(
            registry.standard_library.lifecycle_protocol.states["wip"],
            view_session.subject_root,
            audience_release_root or resource_root,
        ),
        pending_roots=pending_ids,
    )
    projection_grant = (
        prepare_authority_relationship_grant(
            snapshot,
            identity,
            relationship_broker,
            relationship_broker.mint_from_trusted_administrator(
                administrator_root
            ),
            relationship_id=_projection_grant_root(
                view_session.subject_root, resource_root
            ),
            source_root=registry.authorization.resource_reader_principal_root,
            target_root=view_session.subject_root,
            kind="delegation",
            tenant_root=registry.authorization.tenant_root,
            administrator_root=administrator_root,
            scope_root=resource_root,
            action_roots=(read_root,),
            reason="subject receives this resource through the authorized view",
            evidence_roots=(view_session.visibility_root,),
            pending_roots=pending_ids,
        )
        if direct_view_assignment
        else None
    )
    grants = (
        (audience_grant, projection_grant)
        if projection_grant is not None
        else (audience_grant,)
    )
    identity_patch = prepare_append_relation_members(
        snapshot,
        identity.root_id,
        (
            (identity.role("relationship-member"), grant.root_id)
            for grant in grants
        ),
        budget=100_000,
    )
    session_patch = (
        prepare_append_relation_members(
            snapshot,
            view_session.root_id,
            ((registry.roles["relation"], projection_grant.root_id),),
            budget=100_000,
        )
        if projection_grant is not None
        else None
    )
    replacements = {cell.id: cell for cell in selection_transition_replace}
    for cell in (
        *canvas_patch.replace,
        *lens_patch.replace,
        *selection_patch_replace,
        *((visibility_patch.replace) if visibility_patch is not None else ()),
        *exposure_replace,
        *((scope_patch.replace) if scope_patch is not None else ()),
        *additional_replace,
        *viewport_replacements,
        *identity_patch.replace,
        *((session_patch.replace) if session_patch is not None else ()),
    ):
        if cell.id in replacements and replacements[cell.id] != cell:
            raise InvalidCell("atomic WIP resource has conflicting patches")
        replacements[cell.id] = cell
    revision = _commit_universal_user_change(
        store,
        registry,
        view_session,
        context,
        snapshot,
        route=route,
        command_name=command_name,
        authorization_scope_root=authorization_scope_root,
        additional_authorization_scope_roots=(
            (active_scope_root,)
            if activate_view and active_scope_root != registry.canvas_root
            else ()
        ),
        create=(
            *pending_cells,
            *(cell for grant in grants for cell in grant.cells),
            *identity_patch.create,
            *((session_patch.create) if session_patch is not None else ()),
        ),
        replace=tuple(replacements.values()),
    )
    for grant in grants:
        relationship_broker.record_generation(grant.root_id, grant.generation)
    return revision


def instantiate_universal_primitive(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    *,
    x: float,
    y: float,
    title: str = "Cell",
    atom: str = "",
    viewport: Mapping[str, float] | None = None,
    mutation_route: str = "/api/universal/instantiate",
    authentication_context: object | None = None,
    leased_scope_root: str | None = None,
) -> tuple[str, int]:
    """Create one editable WIP terminal Cell through explicit graph wiring."""
    if not math.isfinite(x) or not math.isfinite(y):
        raise InvalidCell("primitive position must be finite")
    if not isinstance(title, str) or not title.strip():
        raise InvalidCell("primitive title must be non-empty")
    if not isinstance(atom, str):
        raise InvalidCell("primitive atom must be text")
    if type(mutation_route) is not str or not mutation_route.startswith("/"):
        raise InvalidCell("primitive mutation route must be an absolute path")
    title_bytes = title.encode("utf-8")
    atom_bytes = atom.encode("utf-8")
    if len(title_bytes) > 512 or len(atom_bytes) > 65_536:
        raise InvalidCell("primitive text exceeds its bounded interface")
    snapshot = store.snapshot()
    view_session, context = _view_session_for_context(
        registry, authentication_context
    )
    visible_roots, _, _ = _session_canvas_roots(
        snapshot, registry, view_session
    )
    _authorize(
        snapshot,
        registry,
        "catalog.instantiate",
        object_root=registry.primitive_root,
        authentication_context=context,
        resource_usage={
            "max-instances": (len(visible_roots), 1),
            "max-atom-bytes": (0, len(atom_bytes)),
        },
    )
    root_id = "app:wip-cell:%s" % uuid.uuid4().hex
    root_cell = Cell(root_id, NULL_CELL_ID, NULL_CELL_ID, atom_bytes)
    property_refs: list[PropertyRef] = []
    property_cells: list[Cell] = []
    for key, value in (
        ("title", title.strip()),
        ("position_x", x),
        ("position_y", y),
        ("color", _DEFAULT_NODE_PRESENTATION_COLOR),
    ):
        reference, cells = _compose_property(
            registry, root_id, key, value
        )
        property_refs.append(reference)
        property_cells.extend(cells)
    value_reference, value_cells = _compose_bound_property(
        registry, root_id, "value", root_id
    )
    property_refs.append(value_reference)
    property_cells.extend(value_cells)
    revision = _commit_atomic_visible_wip_resource(
        store,
        registry,
        snapshot,
        view_session,
        context,
        route=mutation_route,
        command_name="catalog.instantiate",
        authorization_scope_root=registry.primitive_root,
        resource_root=root_id,
        resource_cells=(root_cell,),
        property_refs=tuple(property_refs),
        property_cells=tuple(property_cells),
        viewport=viewport,
        leased_scope_root=leased_scope_root,
    )
    return root_id, revision


def instantiate_universal_definition(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    definition_root: str,
    *,
    x: float,
    y: float,
    viewport: Mapping[str, float] | None = None,
    authentication_context: object | None = None,
    interface_values: Mapping[str, str] | None = None,
    title_override: str | None = None,
    activate_view: bool = True,
    mutation_route: str = "/api/universal/instantiate",
    leased_scope_root: str | None = None,
) -> tuple[str, int]:
    """Instantiate, place, expose, and select one catalogue assembly."""
    if not math.isfinite(x) or not math.isfinite(y):
        raise InvalidCell("assembly position must be finite")
    interface_values = dict(interface_values or {})
    if any(
        type(name) is not str
        or type(value) is not str
        for name, value in interface_values.items()
    ):
        raise InvalidCell("assembly interface overrides must be text")
    if title_override is not None and type(title_override) is not str:
        raise InvalidCell("assembly title override must be text")
    if type(activate_view) is not bool:
        raise InvalidCell("assembly view activation flag must be boolean")
    if type(mutation_route) is not str or not mutation_route.startswith("/"):
        raise InvalidCell("assembly mutation route must be an absolute path")
    snapshot = store.dense_snapshot()
    view_session, context = _view_session_for_context(
        registry, authentication_context
    )
    visible_roots, _, _ = _canvas_roots(snapshot, registry)
    instance_count = sum(
        _instance_projection(snapshot, registry, root_id) is not None
        for root_id in visible_roots
    )
    _authorize(
        snapshot,
        registry,
        "catalog.instantiate",
        object_root=definition_root,
        authentication_context=context,
        definition_root=definition_root,
        resource_usage={
            "max-instances": (instance_count, 1),
            "max-atom-bytes": (
                0,
                sum(
                    len(value.encode("utf-8"))
                    for value in interface_values.values()
                ),
            ),
        },
    )
    composed = compose_catalog_instance(
        snapshot,
        registry.assembly_protocol,
        registry.standard_library.catalog_root,
        definition_root,
    )
    definition = read_definition(
        snapshot, registry.assembly_protocol, definition_root
    )
    instance = composed.instance
    resource_cells = list(composed.cells)
    resource_index = {cell.id: index for index, cell in enumerate(resource_cells)}
    if interface_values:
        remaining = set(interface_values)
        protocol = registry.assembly_protocol
        for interface_root in definition.interface_roots:
            interface = read_relation(snapshot, interface_root, budget=100_000)
            name_root = _one_for_role(interface, protocol.role("name"))
            target_root = _one_for_role(
                interface, protocol.role("interface-target")
            )
            if name_root is None or target_root is None:
                raise InvalidCell("definition interface is incomplete")
            name = _text(snapshot, name_root)
            if name not in interface_values:
                continue
            try:
                instance_target = instance.cell_map[target_root]
                cell_index = resource_index[instance_target]
            except KeyError as exc:
                raise InvalidCell(
                    "assembly interface override target is not an instance part"
                ) from exc
            current = resource_cells[cell_index]
            resource_cells[cell_index] = Cell(
                current.id,
                current.link0,
                current.link1,
                interface_values[name].encode("utf-8"),
            )
            remaining.discard(name)
        if remaining:
            raise InvalidCell("assembly interface override is unknown")
    property_specs = (
        (
            "title",
            (
                title_override.strip()
                if title_override is not None and title_override.strip()
                else _text(snapshot, definition.name_root)
            ),
            False,
        ),
        ("position_x", x, False),
        ("position_y", y, False),
        ("color", _DEFAULT_NODE_PRESENTATION_COLOR, False),
        ("definition", definition_root, True),
        ("version", _text(snapshot, definition.version_root), True),
    )
    property_refs: list[PropertyRef] = []
    property_cells: list[Cell] = []
    for key, value, read_only in property_specs:
        reference, cells = _compose_property(
            registry,
            instance.root_id,
            key,
            value,
            read_only=read_only,
        )
        property_refs.append(reference)
        property_cells.extend(cells)

    candidate = _candidate_snapshot_for_atomic_commit(
        snapshot, create=composed.cells
    )
    instance_members = read_relation(
        candidate, instance.root_id, budget=100_000
    )
    capabilities = {
        member.participant_id for member in instance_members
        if member.role_id == registry.assembly_protocol.role("capability")
    }
    release_root = instance.root_id
    lifecycle = registry.standard_library.lifecycle_protocol
    if lifecycle.root_id in capabilities:
        lifecycle_instance = read_lifecycle_instance(
            candidate,
            registry.assembly_protocol,
            lifecycle,
            instance.root_id,
        )
        wip_heads = state_heads(
            candidate,
            lifecycle,
            lifecycle_instance.state_pointers[lifecycle.states["wip"]],
        )
        if len(wip_heads) != 1:
            raise InvalidCell(
                "new lifecycle resource requires one exact WIP release"
            )
        release_root = wip_heads[0]
    additional_create: tuple[Cell, ...] = ()
    additional_replace: tuple[Cell, ...] = ()
    if registry.standard_library.reaction_protocol.root_id in capabilities:
        registration = prepare_reaction_instance_registration(
            snapshot,
            registry.assembly_protocol,
            registry.standard_library.reaction_protocol,
            instance.root_id,
            pending_cells=composed.cells,
        )
        additional_create = registration.create
        additional_replace = registration.replace
    revision = _commit_atomic_visible_wip_resource(
        store,
        registry,
        snapshot,
        view_session,
        context,
        route=mutation_route,
        command_name="catalog.instantiate",
        authorization_scope_root=definition_root,
        resource_root=instance.root_id,
        resource_cells=tuple(resource_cells),
        property_refs=tuple(property_refs),
        property_cells=tuple(property_cells),
        audience_release_root=release_root,
        additional_create=additional_create,
        additional_replace=additional_replace,
        viewport=viewport,
        activate_view=activate_view,
        leased_scope_root=leased_scope_root,
    )
    return instance.root_id, revision


def _register_universal_governed_work(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    instance_root: str,
) -> str:
    """Attach one exact work assembly through a visible registry membership wire."""
    snapshot = store.snapshot()
    definition_root = registry.standard_library.governed_domains.definitions[
        "governed-work"
    ].definition_root
    instance_members = read_relation(snapshot, instance_root, budget=100_000)
    provenance = tuple(
        member.participant_id for member in instance_members
        if member.role_id == registry.assembly_protocol.role("provenance")
    )
    if provenance != (definition_root,):
        raise InvalidCell("only a Governed Work assembly can enter the work registry")

    registry_members = read_relation(
        snapshot, registry.governed_work_registry_root, budget=100_000
    )
    registered = {
        member.participant_id for member in registry_members
        if member.role_id == registry.roles["member"]
    }
    relation_root = "app:relation:governed-work:%s" % _part(instance_root)
    if instance_root in registered:
        if relation_root not in snapshot.cells:
            raise InvalidCell("governed work membership wire is missing")
        return relation_root
    if relation_root in snapshot.cells:
        raise InvalidCell("governed work membership identity collided")

    relation = compose_relation_cells((
        (registry.roles["source"], registry.governed_work_registry_root),
        (registry.roles["target"], instance_root),
        (registry.roles["authority"], definition_root),
    ), relation_id=relation_root)
    brain_root = registry.map.domains["brain"]
    required = (
        (
            registry.governed_work_registry_root,
            ((registry.roles["member"], instance_root),),
        ),
        (
            registry.application_root,
            (
                (registry.roles["member"], instance_root),
                (registry.roles["relation"], relation_root),
            ),
        ),
        (
            brain_root,
            (
                (registry.roles["member"], instance_root),
                (registry.roles["relation"], relation_root),
            ),
        ),
        (
            registry.workshop_workbench_root,
            ((registry.roles["member"], instance_root),),
        ),
        (
            registry.canvas_root,
            ((registry.roles["relation"], relation_root),),
        ),
    )
    patches = tuple(
        prepare_append_relation_members(
            snapshot, container_root, members, budget=100_000
        )
        for container_root, members in required
    )
    replacements: dict[str, Cell] = {}
    for patch in patches:
        for cell in patch.replace:
            if cell.id in replacements and replacements[cell.id] != cell:
                raise InvalidCell("governed work registration patch conflicted")
            replacements[cell.id] = cell
    store.commit(
        snapshot.revision,
        create=(
            *relation.cells,
            *(cell for patch in patches for cell in patch.create),
        ),
        replace=tuple(replacements.values()),
    )
    return relation_root


def _expose_universal_value_graphs(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    specifications: tuple[tuple[str, str, float, float], ...],
    *,
    mutation_route: str = "/api/universal/interaction",
    authentication_context: object | None,
) -> tuple[dict[str, str], int]:
    """Expose a bounded value-graph batch through one transaction per layer."""
    if (
        type(specifications) is not tuple
        or not specifications
        or len(specifications) > 256
    ):
        raise InvalidCell("value graph exposure requires a bounded tuple")
    roots = tuple(specification[0] for specification in specifications)
    if len(roots) != len(set(roots)):
        raise InvalidCell("value graph exposure contains duplicate roots")
    for specification in specifications:
        if type(specification) is not tuple or len(specification) != 4:
            raise InvalidCell("value graph exposure has an invalid shape")
        root_id, title, x, y = specification
        if (
            type(root_id) is not str
            or not root_id
            or type(title) is not str
            or not title.strip()
            or type(x) not in (int, float)
            or type(y) not in (int, float)
        ):
            raise InvalidCell("value graph exposure has invalid values")
    snapshot = store.snapshot()
    view_session, context = _view_session_for_context(
        registry, authentication_context
    )
    registered = tuple(
        member.participant_id for member in read_relation(
            snapshot, registry.value_graph_protocol.root_id, budget=100_000
        )
        if member.role_id == registry.value_graph_protocol.role("value-member")
    )
    if any(registered.count(root_id) != 1 for root_id in roots):
        raise InvalidCell("visible value graphs must be registered exactly once")
    canvas_members = []
    lens_members = []
    property_cells = []
    for root_id, title, x, y in specifications:
        canvas_members.append((registry.roles["member"], root_id))
        for key, value, read_only in (
            ("title", title.strip(), False),
            ("position_x", float(x), False),
            ("position_y", float(y), False),
            ("value_graph", registry.value_graph_protocol.root_id, True),
        ):
            reference, cells = _compose_property(
                registry, root_id, key, value, read_only=read_only
            )
            canvas_members.append(
                (registry.roles["property"], reference.relation_root)
            )
            lens_members.append(
                (registry.roles["scope"], reference.relation_root)
            )
            property_cells.extend(cells)
    requested = (
        (
            registry.canvas_root,
            tuple(canvas_members),
        ),
        (
            view_session.properties_lens_root,
            tuple(lens_members),
        ),
        (
            view_session.visibility_root,
            tuple((registry.roles["visible"], root_id) for root_id in roots),
        ),
        (
            registry.application_root,
            tuple((registry.roles["member"], root_id) for root_id in roots),
        ),
        (
            registry.map.domains["brain"],
            tuple((registry.roles["member"], root_id) for root_id in roots),
        ),
    )
    patches = tuple(
        prepare_append_relation_members(
            snapshot, relation_root, members, budget=100_000
        )
        for relation_root, members in requested
    )
    replacements = {}
    for patch in patches:
        for cell in patch.replace:
            if cell.id in replacements and replacements[cell.id] != cell:
                raise InvalidCell("value graph visibility patches conflict")
            replacements[cell.id] = cell
    store.commit(
        snapshot.revision,
        create=(
            *property_cells,
            *(cell for patch in patches for cell in patch.create),
        ),
        replace=tuple(replacements.values()),
    )
    administrator_root = registry.authorization.broker.resolve(
        context
    ).subject_root
    _issue_resource_audience_bindings(
        store,
        registry.authorization,
        resource_roots=roots,
        lifecycle_root=registry.standard_library.lifecycle_protocol.states["wip"],
        owner_root=view_session.subject_root,
        administrator_root=administrator_root,
        release_roots={root_id: root_id for root_id in roots},
    )
    projection_grants = _issue_view_projection_grants(
        store,
        registry.authorization,
        subject_root=view_session.subject_root,
        visibility_root=view_session.visibility_root,
        target_roots=roots,
        administrator_root=administrator_root,
    )
    grant_snapshot = store.snapshot()
    session_patch = prepare_append_relation_members(
        grant_snapshot,
        view_session.root_id,
        (
            (registry.roles["relation"], root)
            for root in projection_grants
        ),
        budget=100_000,
    )
    store.commit(
        grant_snapshot.revision,
        create=session_patch.create,
        replace=session_patch.replace,
    )
    interface_roots, revision = create_universal_interfaces(
        store,
        registry,
        tuple(
            (
                root_id,
                "value",
                "app:canvas-interface:presentation:source",
                registry.assembly_protocol.root_id,
            )
            for root_id in roots
        ),
        mutation_route=mutation_route,
        authentication_context=authentication_context,
    )
    return dict(zip(roots, interface_roots, strict=True)), revision


def attach_universal_assembly_structured_fields(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    instance_root: str,
    structured_fields: Mapping[str, object],
    *,
    x: float,
    y: float,
    mutation_route: str,
    authentication_context: object | None,
) -> dict[str, dict[str, str]]:
    """Wire structured Cell value graphs into declared assembly interfaces.

    The assembly remains generic: field names come from its released definition,
    while values are ordinary, registered value graphs linked by visible
    relations.  No structured payload is flattened into an assembly atom.
    """
    if not structured_fields:
        return {}
    if type(structured_fields) is not dict or len(structured_fields) > 32:
        raise InvalidCell("assembly structured fields must be a bounded mapping")
    if not math.isfinite(x) or not math.isfinite(y):
        raise InvalidCell("assembly structured field position must be finite")
    snapshot = store.snapshot()
    assembly = _instance_projection(snapshot, registry, instance_root)
    if assembly is None:
        raise InvalidCell("structured fields require an assembly instance")
    interfaces = {
        str(item["name"]): item
        for item in assembly.get("interfaces", [])
        if isinstance(item, Mapping)
    }
    values_by_root: dict[str, object] = {}
    targets: dict[str, dict[str, object]] = {}
    for name, value in structured_fields.items():
        if type(name) is not str or not name:
            raise InvalidCell("assembly structured field name is invalid")
        interface = interfaces.get(name)
        if interface is None or interface.get("mode") != "connection":
            raise InvalidCell("assembly structured field has no connection interface")
        root_id = "%s:data:%s" % (instance_root, _part(name))
        if root_id in snapshot.cells:
            raise InvalidCell("assembly structured field already has a value graph")
        values_by_root[root_id] = value
        targets[name] = {"value_root": root_id, "interface": interface}
    build_value_graphs(store, registry.value_graph_protocol, values_by_root)
    exposed, _ = _expose_universal_value_graphs(
        store,
        registry,
        tuple(
            (root_id, "%s / %s" % (
                str(assembly.get("title") or instance_root),
                name.replace("-", " ").title(),
            ), x - 360.0, y + (offset * 130.0))
            for offset, (name, root_id) in enumerate(
                (name, details["value_root"])
                for name, details in sorted(targets.items())
            )
        ),
        mutation_route=mutation_route,
        authentication_context=authentication_context,
    )
    attached: dict[str, dict[str, str]] = {}
    for name, details in targets.items():
        value_root = str(details["value_root"])
        interface = details["interface"]
        relation_root, _ = connect_universal_roots(
            store,
            registry,
            value_root,
            instance_root,
            source_interface=exposed[value_root],
            target_interface=str(interface["id"]),
            mutation_route=mutation_route,
            authentication_context=authentication_context,
        )
        attached[name] = {
            "value_root": value_root,
            "source_interface": exposed[value_root],
            "relation_root": relation_root,
        }
    return attached


def _expose_universal_value_graph(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    root_id: str,
    *,
    title: str,
    x: float,
    y: float,
    authentication_context: object | None,
) -> tuple[str, int]:
    """Make one already-persisted value graph visible and openable."""
    interfaces, revision = _expose_universal_value_graphs(
        store,
        registry,
        ((root_id, title, x, y),),
        authentication_context=authentication_context,
    )
    return interfaces[root_id], revision


def begin_universal_runtime_agent_session(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    *,
    session_root: str,
    runtime: str,
    external_session_fingerprint: str,
    catalog_entry_root: str | None = None,
    authentication_context: object | None = None,
) -> tuple[AgentSessionProjection, int]:
    """Create one visible Agent Session for an authenticated runtime client."""
    runtime = runtime.strip() if type(runtime) is str else ""
    if (
        type(session_root) is not str
        or not session_root.startswith("app:agent-session:runtime:")
        or len(session_root.encode("utf-8")) > 256
        or not runtime
        or len(runtime.encode("utf-8")) > 128
        or type(external_session_fingerprint) is not str
        or len(external_session_fingerprint) != 64
        or any(
            character not in "0123456789abcdef"
            for character in external_session_fingerprint
        )
    ):
        raise InvalidCell("runtime Agent Session identity is invalid")
    snapshot = store.snapshot()
    if session_root in snapshot.cells:
        raise InvalidCell("runtime Agent Session identity already exists")
    entry = _agent_body_catalog_entry_for_runtime(snapshot, registry, runtime)
    if (
        catalog_entry_root is not None
        and catalog_entry_root != entry.root_id
    ):
        raise AuthorizationDenied("runtime credential selected the wrong Agent Body")
    if (
        entry.credential_mode != "machine-transport"
        and catalog_entry_root != entry.root_id
    ):
        raise AuthorizationDenied("runtime Agent Body requires a verified credential")
    protocol = registry.agent_body.protocol
    entry_body = read_agent_body(
        snapshot,
        protocol,
        registry.authorization.protocol,
        entry.body_root,
    )
    view_session, context = _view_session_for_context(
        registry, authentication_context
    )
    identity = registry.authorization.broker.resolve(context)
    if identity.subject_root != entry_body.identity_root:
        raise AuthorizationDenied(
            "runtime Agent Session is outside the active Agent Body"
        )
    lifecycle_root = entry_body.lifecycle_root
    authority_snapshot = verify_relationship_authority_snapshot(
        snapshot,
        registry.authorization.identity_protocol,
        registry.authorization.relationship_broker,
    )
    session = begin_agent_session(
        store,
        protocol,
        registry.authorization.protocol,
        registry.authorization.broker,
        context,
        _agent_body_request(
            registry.authorization,
            protocol,
            lifecycle_root,
            "inspect",
            view_session.root_id,
        ),
        _agent_body_request(
            registry.authorization,
            protocol,
            lifecycle_root,
            "traverse",
            view_session.root_id,
        ),
        session_id=session_root,
        body_root=entry.body_root,
        subject_root=identity.subject_root,
        owner_role_root=registry.authorization.session_owner_role_root,
        view_session_root=view_session.root_id,
        scope_root=view_session.root_id,
        focus_root=protocol.state("unbound"),
        assignment_root=protocol.state("unbound"),
        resolver_state=authority_snapshot,
    )

    property_refs = []
    property_cells = []
    for key, value, read_only in (
        ("title", "%s Agent Session" % runtime, False),
        ("runtime", runtime, True),
        ("agent body", entry.body_root, True),
        ("agent body catalog entry", entry.root_id, True),
        ("credential mode", entry.credential_mode, True),
        ("session fingerprint", external_session_fingerprint, True),
        ("position_x", 1080.0, False),
        ("position_y", 180.0, False),
        (
            "color",
            _text(
                store.snapshot(),
                registry.presentation.theme_roots["ink_soft"],
            ),
            False,
        ),
    ):
        reference, cells = _compose_property(
            registry, session_root, key, value, read_only=read_only
        )
        property_refs.append(reference)
        property_cells.extend(cells)
    snapshot = store.snapshot()
    requested = (
        (
            registry.canvas_root,
            (
                (registry.roles["member"], session_root),
                *(
                    (registry.roles["property"], reference.relation_root)
                    for reference in property_refs
                ),
            ),
        ),
        (
            view_session.properties_lens_root,
            tuple(
                (registry.roles["scope"], reference.relation_root)
                for reference in property_refs
            ),
        ),
        (
            view_session.visibility_root,
            ((registry.roles["visible"], session_root),),
        ),
        (
            registry.application_root,
            ((registry.roles["member"], session_root),),
        ),
        (
            registry.map.domains["models"],
            ((registry.roles["member"], session_root),),
        ),
        (
            entry.control_root,
            ((registry.roles["member"], session_root),),
        ),
    )
    patches = tuple(
        prepare_append_relation_members(
            snapshot, relation_root, members, budget=100_000
        )
        for relation_root, members in requested
    )
    replacements = {}
    for patch in patches:
        for cell in patch.replace:
            if cell.id in replacements and replacements[cell.id] != cell:
                raise InvalidCell("runtime Agent Session patches conflict")
            replacements[cell.id] = cell
    store.commit(
        snapshot.revision,
        create=(
            *property_cells,
            *(cell for patch in patches for cell in patch.create),
        ),
        replace=tuple(replacements.values()),
    )
    _issue_resource_audience_bindings(
        store,
        registry.authorization,
        resource_roots=(session_root,),
        lifecycle_root=(
            registry.standard_library.lifecycle_protocol.states["wip"]
        ),
        owner_root=identity.subject_root,
        administrator_root=identity.subject_root,
        release_roots={session_root: session_root},
    )
    projection_grants = _issue_view_projection_grants(
        store,
        registry.authorization,
        subject_root=identity.subject_root,
        visibility_root=view_session.visibility_root,
        target_roots=(session_root,),
        administrator_root=identity.subject_root,
    )
    grant_snapshot = store.snapshot()
    session_patch = prepare_append_relation_members(
        grant_snapshot,
        view_session.root_id,
        (
            (registry.roles["relation"], root)
            for root in projection_grants
        ),
        budget=100_000,
    )
    revision = store.commit(
        grant_snapshot.revision,
        create=session_patch.create,
        replace=session_patch.replace,
    )
    return read_agent_session(
        store.snapshot(),
        protocol,
        registry.authorization.protocol,
        session_root,
    ), revision


def create_universal_governed_work(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    *,
    title: str,
    x: float,
    y: float,
    description: str = "",
    priority: int = 0,
    external_key: str = "unset",
    references: Mapping[str, str] | None = None,
    structured_references: Mapping[str, object] | None = None,
    authentication_context: object | None = None,
    compact_references: bool = False,
    select_created: bool = True,
) -> tuple[str, str, int]:
    """Create visible, registered work whose values and references stay Cells."""
    if type(compact_references) is not bool or type(select_created) is not bool:
        raise InvalidCell("governed work creation flags must be booleans")
    if type(title) is not str or not title.strip():
        raise InvalidCell("governed work requires a non-empty title")
    if type(description) is not str or type(external_key) is not str:
        raise InvalidCell("governed work scalar fields must be text")
    if type(priority) is not int:
        raise InvalidCell("governed work priority must be an integer")
    references = dict(references or {})
    structured_references = dict(structured_references or {})
    reference_names = {
        "plan", "scope", "cde-container", "requirements", "dependencies",
        "required-capabilities", "applicable-policy", "inputs", "outputs",
    }
    if set(references) - reference_names:
        raise InvalidCell("governed work contains an unknown reference interface")
    if set(structured_references) - reference_names:
        raise InvalidCell("governed work contains an unknown structured interface")
    if set(references) & set(structured_references):
        raise InvalidCell("governed work interface has two competing sources")
    snapshot = store.snapshot()
    if any(
        type(root) is not str or not root or root not in snapshot.cells
        for root in references.values()
    ):
        raise InvalidCell("governed work reference target is missing")
    scalar_values = {
        "title": title.strip(),
        "description": description,
        "priority": str(priority),
        "external-key": external_key,
    }

    definition_root = registry.standard_library.governed_domains.definitions[
        "governed-work"
    ].definition_root
    instance_root, _ = instantiate_universal_definition(
        store,
        registry,
        definition_root,
        x=x,
        y=y,
        authentication_context=authentication_context,
        mutation_route="/api/universal/work",
        interface_values=scalar_values if compact_references else None,
        title_override=title.strip() if compact_references else None,
        activate_view=select_created,
    )
    membership_wire = _register_universal_governed_work(
        store, registry, instance_root
    )

    assembly = _instance_projection(store.snapshot(), registry, instance_root)
    if assembly is None:
        raise InvalidCell("new Governed Work assembly is not projectable")
    interfaces = {item["name"]: item for item in assembly["interfaces"]}
    if not compact_references:
        for name, value in scalar_values.items():
            edit_universal_interface_value(
                store,
                registry,
                instance_root,
                str(interfaces[name]["id"]),
                value,
                mutation_route="/api/universal/work",
                authentication_context=authentication_context,
            )

        view_session, _ = _view_session_for_context(
            registry, authentication_context
        )
        title_property = _presentation_source_property(
            store.snapshot(), registry, view_session, instance_root, "title"
        )
        edit_universal_property(
            store,
            registry,
            title_property.relation_root,
            title.strip(),
            mutation_route="/api/universal/work",
            authentication_context=authentication_context,
        )

    structured_source_interfaces = {}
    structured_value_roots = {}
    exposure_specifications = []
    structured_value_inputs = {}
    for offset, (name, value) in enumerate(sorted(structured_references.items())):
        value_root = "%s:data:%s" % (instance_root, _part(name))
        structured_value_inputs[value_root] = value
        structured_value_roots[name] = value_root
        exposure_specifications.append((
            value_root,
            "%s / %s" % (title.strip(), name.replace("-", " ").title()),
            x - 360.0,
            y + (offset * 130.0),
        ))
    if structured_value_inputs:
        build_value_graphs(
            store,
            registry.value_graph_protocol,
            structured_value_inputs,
        )
    if exposure_specifications and not compact_references:
        exposed_interfaces, _ = _expose_universal_value_graphs(
            store,
            registry,
            tuple(exposure_specifications),
            mutation_route="/api/universal/work",
            authentication_context=authentication_context,
        )
        for name, value_root in structured_value_roots.items():
            source_interface = exposed_interfaces[value_root]
            references[name] = value_root
            structured_source_interfaces[name] = source_interface

    if compact_references:
        snapshot = store.snapshot()
        assembly = _instance_projection(snapshot, registry, instance_root)
        if assembly is None:
            raise InvalidCell("new Governed Work assembly is not projectable")
        compact_replacements: dict[str, Cell] = {}
        for name, source_root in {
            **references,
            **structured_value_roots,
        }.items():
            interface = interfaces.get(name)
            if interface is None:
                raise InvalidCell("governed work interface is missing")
            if source_root not in snapshot.cells:
                raise InvalidCell("governed work compact reference is missing")
            incidence = snapshot.cells[str(interface["target_incidence"])]
            compact_replacements[incidence.id] = Cell(
                incidence.id,
                incidence.link0,
                source_root,
                incidence.atom,
            )
        if compact_replacements:
            store.commit(
                snapshot.revision,
                replace=tuple(compact_replacements.values()),
            )
        if select_created:
            select_universal_root(
                store,
                registry,
                instance_root,
                authentication_context=authentication_context,
            )
        return instance_root, membership_wire, store.revision

    for name, source_root in references.items():
        source_interface = structured_source_interfaces.get(name)
        if (
            source_interface is None
            and name == "scope"
            and source_root in registry.map.domains.values()
        ):
            source_interface = _governed_work_scope_source_interface(
                store.snapshot(), registry, source_root
            )
        connect_universal_roots(
            store,
            registry,
            source_root,
            instance_root,
            source_interface=source_interface,
            target_interface=str(interfaces[name]["id"]),
            mutation_route="/api/universal/work",
            authentication_context=authentication_context,
        )
    if select_created:
        select_universal_root(
            store,
            registry,
            instance_root,
            authentication_context=authentication_context,
        )
    return instance_root, membership_wire, store.revision


_GRAND_MAP_WORK_PRIORITY_BY_STATUS = MappingProxyType({
    "red": 95,
    "open": 75,
    "partial": 60,
    "planned": 45,
    "vision": 35,
    "live": 0,
})


def _bounded_grand_map_work_limit(limit: object) -> int:
    if type(limit) is not int:
        raise InvalidCell("Grand Map Work limit must be an integer")
    if limit < 1 or limit > 100:
        raise InvalidCell("Grand Map Work limit must be between 1 and 100")
    return limit


def _grand_map_node_property_values(
    snapshot: Snapshot,
    registry: UniversalApplicationRegistry,
    node_key: str,
) -> dict[str, str]:
    values: dict[str, str] = {}
    for relation_root in registry.map.properties.get(node_key, ()):
        members = read_relation(snapshot, relation_root, budget=32)
        label_root = _one_for_role(members, registry.map.roles["label"])
        value_root = _one_for_role(members, registry.map.roles["value"])
        if label_root is None or value_root is None:
            raise InvalidCell("Grand Map node property is incomplete")
        values[_text(snapshot, label_root)] = _text(snapshot, value_root)
    return values


def _grand_map_node_domain_roots(
    snapshot: Snapshot,
    registry: UniversalApplicationRegistry,
) -> dict[str, tuple[str, str]]:
    by_node_root: dict[str, tuple[str, str]] = {}
    node_roots = set(registry.map.nodes.values())
    for domain_key, domain_root in registry.map.domains.items():
        members = read_relation(snapshot, domain_root, budget=100_000)
        for member in members:
            if (
                member.role_id == registry.map.roles["member"]
                and member.participant_id in node_roots
            ):
                by_node_root[member.participant_id] = (domain_key, domain_root)
    if set(registry.map.nodes.values()) - set(by_node_root):
        raise InvalidCell("Grand Map node domain membership is incomplete")
    return by_node_root


def _grand_map_work_candidates(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    *,
    include_live: bool,
    authentication_context: object | None,
) -> tuple[dict[str, object], ...]:
    snapshot = store.snapshot()
    _require_application_authorization(
        snapshot,
        registry,
        "read",
        registry.governed_work_registry_root,
        authentication_context=authentication_context,
    )
    domains_by_root = _grand_map_node_domain_roots(snapshot, registry)
    by_node_root = {
        root: key for key, root in registry.map.nodes.items()
    }
    index = project_universal_governed_work_index(
        store,
        registry,
        authentication_context=authentication_context,
    )
    existing = {
        str(item["interfaces"]["external-key"]["value"])
        for item in index["items"]
    }
    candidates = []
    for node_root in sorted(by_node_root):
        node_key = by_node_root[node_root]
        values = _grand_map_node_property_values(snapshot, registry, node_key)
        status = values.get("status", "").casefold()
        if status == "live" and not include_live:
            continue
        domain_key, domain_root = domains_by_root[node_root]
        external_key = "grand-map:%s" % node_key
        params = {
            name: _text(snapshot, reference.value_root)
            for name, reference in registry.map.params.get(node_key, {}).items()
        }
        title = values.get("title") or node_key
        cde_container = {
            "container_id": "GM.%s.%s" % (domain_key, node_key),
            "node_id": node_key,
            "node_root": node_root,
            "domain": domain_key,
            "domain_root": domain_root,
            "lifecycle_state": (
                "PRODUCTION" if status == "live" else "WIP"
            ),
            "map_status": values.get("status", ""),
            "evidence_ref": values.get("evidence_ref", ""),
            "last_verified": values.get("last_verified", ""),
            "authority_source": values.get("authority_source", ""),
            "bim_phase": values.get("bim_phase", ""),
            "standard": values.get("standard", ""),
            "sync_authority": registry.map.grand_map_root,
        }
        candidates.append({
            "external_key": external_key,
            "exists": external_key in existing,
            "title": "GM.%s.%s - %s" % (domain_key, node_key, title),
            "description": values.get("sub", ""),
            "priority": _GRAND_MAP_WORK_PRIORITY_BY_STATUS.get(status, 40),
            "scope": domain_root,
            "domain": domain_key,
            "node_id": node_key,
            "node_root": node_root,
            "status": values.get("status", ""),
            "params": params,
            "cde_container": cde_container,
            "requirements": {
                "gate": {
                    "kind": "grand-map-cell-sync",
                    "spec": {
                        "authority": registry.map.grand_map_root,
                        "node": node_root,
                        "domain": domain_root,
                        "status": values.get("status", ""),
                    },
                },
            },
            "applicable_policy": {
                "authority": "10.PRODUCT/13.NODE-LANGUAGE",
                "source": "Universal Cell Grand Map",
                "source_root": registry.map.grand_map_root,
                "promotion_allowed": False,
                "legacy_brain_meta_write": False,
            },
        })
    return tuple(candidates)


def project_universal_grand_map_work(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    *,
    limit: int = 50,
    include_live: bool = False,
    authentication_context: object | None = None,
) -> dict[str, object]:
    """Preview Grand Map requirements as application-owned Governed Work."""
    limit = _bounded_grand_map_work_limit(limit)
    if type(include_live) is not bool:
        raise InvalidCell("Grand Map Work live-inclusion flag must be boolean")
    candidates = _grand_map_work_candidates(
        store,
        registry,
        include_live=include_live,
        authentication_context=authentication_context,
    )
    missing = tuple(item for item in candidates if not item["exists"])
    return {
        "schema": "archhub-universal-grand-map-work/v1",
        "application": registry.application_root,
        "grand_map": registry.map.grand_map_root,
        "work_registry": registry.governed_work_registry_root,
        "revision": store.revision,
        "limit": limit,
        "include_live": include_live,
        "candidate_count": len(candidates),
        "existing_count": len(candidates) - len(missing),
        "missing_count": len(missing),
        "items": missing[:limit],
    }


def sync_universal_grand_map_work(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    *,
    limit: int = 25,
    include_live: bool = False,
    authentication_context: object | None = None,
) -> dict[str, object]:
    """Create missing Governed Work directly from the live Grand Map Cells."""
    limit = _bounded_grand_map_work_limit(limit)
    if type(include_live) is not bool:
        raise InvalidCell("Grand Map Work live-inclusion flag must be boolean")
    preview = project_universal_grand_map_work(
        store,
        registry,
        limit=limit,
        include_live=include_live,
        authentication_context=authentication_context,
    )
    created = []
    for offset, item in enumerate(preview["items"]):
        root, membership_wire, revision = create_universal_governed_work(
            store,
            registry,
            title=str(item["title"]),
            description=str(item["description"]),
            priority=int(item["priority"]),
            external_key=str(item["external_key"]),
            references={"scope": str(item["scope"])},
            structured_references={
                "requirements": item["requirements"],
                "cde-container": item["cde_container"],
                "required-capabilities": {
                    "source": "grand-map-cell-sync",
                    "params": item["params"],
                },
                "applicable-policy": item["applicable_policy"],
                "inputs": {
                    "source": {
                        "system": "universal-cell-grand-map",
                        "grand_map": registry.map.grand_map_root,
                        "node_root": item["node_root"],
                        "node_id": item["node_id"],
                        "domain": item["domain"],
                    },
                    "status": item["status"],
                },
            },
            x=1040.0 + ((offset % 3) * 420.0),
            y=520.0 + ((offset // 3) * 280.0),
            compact_references=True,
            select_created=False,
            authentication_context=authentication_context,
        )
        created.append({
            "external_key": item["external_key"],
            "node_id": item["node_id"],
            "work_root": root,
            "membership_wire": membership_wire,
            "revision": revision,
        })
    return {
        "schema": preview["schema"],
        "application": preview["application"],
        "grand_map": preview["grand_map"],
        "work_registry": preview["work_registry"],
        "started_revision": preview["revision"],
        "revision": store.revision,
        "limit": limit,
        "include_live": include_live,
        "candidate_count": preview["candidate_count"],
        "existing_count": preview["existing_count"],
        "missing_count_before": preview["missing_count"],
        "created_count": len(created),
        "remaining_missing_count": max(
            0, int(preview["missing_count"]) - len(created)
        ),
        "created": tuple(created),
    }


def _universal_roma_requirement_protocol(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    *,
    create: bool,
) -> object:
    prefix = "app:roma-requirement-protocol"
    snapshot = store.snapshot()
    if "%s:root" % prefix in snapshot.cells:
        protocol = open_roma_requirement_protocol(snapshot, prefix=prefix)
    elif create:
        protocol = bootstrap_roma_requirement_protocol(store, prefix=prefix)
    else:
        raise InvalidCell("ROMA requirement protocol is not installed")
    snapshot = store.snapshot()
    relation_requests = (
        (
            registry.application_root,
            (
                (registry.roles["member"], protocol.root_id),
                (registry.roles["member"], protocol.registry_root),
            ),
        ),
        (
            registry.map.domains["brain"],
            (
                (registry.roles["member"], protocol.root_id),
                (registry.roles["member"], protocol.registry_root),
            ),
        ),
    )
    replacements: dict[str, Cell] = {}
    creates: list[Cell] = []
    for relation_root, pairs in relation_requests:
        existing = {
            (member.role_id, member.participant_id)
            for member in read_relation(snapshot, relation_root, budget=100_000)
        }
        missing = tuple(pair for pair in pairs if pair not in existing)
        if not missing:
            continue
        patch = prepare_append_relation_members(
            snapshot, relation_root, missing, budget=100_000
        )
        creates.extend(patch.create)
        for cell in patch.replace:
            if cell.id in replacements and replacements[cell.id] != cell:
                raise InvalidCell("ROMA protocol membership patches conflict")
            replacements[cell.id] = cell
    if creates or replacements:
        store.commit(
            snapshot.revision,
            create=tuple(creates),
            replace=tuple(replacements.values()),
        )
    return protocol


def sync_universal_roma_requirement_tree(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    tree: Mapping[str, object],
    *,
    source: str = "brain.roma",
    authentication_context: object | None = None,
) -> dict[str, object]:
    """Synchronize a ROMA tree into the application-owned Universal Cell graph."""
    if type(source) is not str or not source.strip():
        raise InvalidCell("ROMA sync source is invalid")
    snapshot = store.snapshot()
    _require_application_authorization(
        snapshot,
        registry,
        "create",
        registry.map.domains["brain"],
        authentication_context=authentication_context,
    )
    protocol = _universal_roma_requirement_protocol(
        store, registry, create=True
    )
    result = sync_roma_requirement_tree(
        store,
        protocol,
        registry.value_graph_protocol,
        tree,
        source=source.strip(),
    )
    result.update({
        "ok": True,
        "application": registry.application_root,
        "brain_scope": registry.map.domains["brain"],
        "protocol": protocol.root_id,
        "registry": protocol.registry_root,
    })
    return result


def project_universal_roma_requirement_tree(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    *,
    tree_id: str,
    authentication_context: object | None = None,
) -> dict[str, object]:
    """Project one ROMA tree from the application-owned Universal Cell graph."""
    tree_root = roma_tree_root(tree_id)
    snapshot = store.snapshot()
    _require_application_authorization(
        snapshot,
        registry,
        "read",
        registry.map.domains["brain"],
        authentication_context=authentication_context,
    )
    protocol = _universal_roma_requirement_protocol(
        store, registry, create=False
    )
    projected = project_roma_requirement_tree(
        store.snapshot(), protocol, registry.value_graph_protocol, tree_root
    )
    projected.update({
        "ok": True,
        "application": registry.application_root,
        "brain_scope": registry.map.domains["brain"],
        "protocol": protocol.root_id,
        "registry": protocol.registry_root,
        "revision": store.revision,
    })
    return projected


def project_universal_roma_requirement_tree_index(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    *,
    authentication_context: object | None = None,
) -> dict[str, object]:
    """Project the ROMA requirement tree registry from the app Cell graph."""
