def _governed_work_interface(
    snapshot: Snapshot,
    registry: UniversalApplicationRegistry,
    work_root: str,
    name: str,
) -> Mapping[str, object]:
    assembly = _instance_projection(snapshot, registry, work_root)
    if assembly is None:
        raise InvalidCell("governed Work assembly is not projectable")
    matches = [
        interface for interface in assembly["interfaces"]
        if interface["name"] == name
    ]
    if len(matches) != 1 or not isinstance(matches[0].get("target"), str):
        raise InvalidCell("governed Work interface is missing or ambiguous")
    return matches[0]


def _governed_work_interface_target(
    snapshot: Snapshot,
    registry: UniversalApplicationRegistry,
    work_root: str,
    name: str,
) -> str:
    return str(_governed_work_interface(
        snapshot, registry, work_root, name
    )["target"])


def _bounded_baboom_plan_text(value: object, label: str, maximum: int) -> str:
    if type(value) is not str:
        raise InvalidCell("BABOOM Work plan %s must be text" % label)
    normalized = " ".join(value.split()).strip()
    if not normalized or len(normalized.encode("utf-8")) > maximum:
        raise InvalidCell("BABOOM Work plan %s is outside its bound" % label)
    return normalized


def _deterministic_baboom_work_plan(
    *,
    work_root: str,
    title: str,
    description: str,
    priority: int,
) -> dict[str, object]:
    """Compose a bounded, non-executing first draft from claimed Work only."""
    title = _bounded_baboom_plan_text(title, "title", 512)
    if type(priority) is not int:
        raise InvalidCell("BABOOM Work priority must be an integer")
    description = " ".join(description.split()).strip()
    if len(description.encode("utf-8")) > 8_192:
        raise InvalidCell("BABOOM Work description exceeds the planning bound")
    task_context = description or "No additional Work description was supplied."
    fingerprint = hashlib.sha256(
        json.dumps(
            {
                "work": work_root,
                "title": title,
                "description": description,
                "priority": priority,
            },
            sort_keys=True,
            separators=(",", ":"),
            ensure_ascii=True,
        ).encode("utf-8")
    ).hexdigest()
    work_input_digest = hashlib.sha256(
        json.dumps(
            {"title": title, "description": description},
            sort_keys=True,
            separators=(",", ":"),
            ensure_ascii=False,
        ).encode("utf-8")
    ).hexdigest()
    return {
        "kind": "baboom-deterministic-work-plan/v2",
        "state": "draft",
        "work": work_root,
        "source": "baboom-explicit-plan-request",
        "fingerprint": fingerprint,
        "work_input_digest": work_input_digest,
        "summary": title,
        "context": task_context,
        "priority_assessment": {
            "declared_priority": priority,
            "released_order": _BABOOM_WORKSHOP_COORDINATION_PRIORITY_POLICY,
            "model_authority": "none",
        },
        "steps": (
            {
                "order": 1,
                "title": _BABOOM_WORKSHOP_COUNCIL_STEPS[0],
                "effect": "none",
            },
            {
                "order": 2,
                "title": _BABOOM_WORKSHOP_COUNCIL_STEPS[1],
                "effect": "none",
            },
            {
                "order": 3,
                "title": _BABOOM_WORKSHOP_COUNCIL_STEPS[2],
                "effect": "none",
            },
            {
                "order": 4,
                "title": _BABOOM_WORKSHOP_COUNCIL_STEPS[3],
                "effect": "approval-required",
            },
            {
                "order": 5,
                "title": _BABOOM_WORKSHOP_COUNCIL_STEPS[4],
                "effect": "approval-required",
            },
        ),
        "execution": "none",
        "model_output": "not-used",
    }


_BABOOM_WORK_PLAN_ACTIVITY_STATES = frozenset({
    "not-requested", "awaiting-approval", "ready", "expired", "succeeded",
    "failed",
})


def _baboom_work_plan_live_activity(
    projection: Mapping[str, object],
    *,
    kind: str,
) -> str:
    """Reduce existing delegation/receipt Cells to one safe plan-view state."""
    total = projection.get("total")
    latest = projection.get("latest")
    if type(total) is not int or total < 0:
        raise InvalidCell("BABOOM Work plan %s activity is malformed" % kind)
    if total == 0:
        return "not-requested"
    if not isinstance(latest, Mapping):
        raise InvalidCell("BABOOM Work plan %s activity lacks its latest state" % kind)
    state = latest.get("state")
    if state == "awaiting_approval":
        state = "awaiting-approval"
    if type(state) is not str or state not in _BABOOM_WORK_PLAN_ACTIVITY_STATES:
        raise InvalidCell("BABOOM Work plan %s activity state is invalid" % kind)
    if state == "not-requested":
        raise InvalidCell("BABOOM Work plan activity cannot be unrequested")
    return state


def draft_universal_baboom_work_plan(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    *,
    agent_session_root: str,
    work_root: str,
    authentication_context: object | None = None,
) -> tuple[str, bool, int]:
    """Attach one explicit, deterministic Plan Value Graph to claimed Work.

    This is deliberately not a model proposal or a Work transition. It creates
    only the existing governed Work ``plan`` reference and returns an immutable
    draft that later model-backed cognition may review or supersede through its
    own Proposal protocol.
    """
    session, _, work = _baboom_execution_work_context(
        store,
        registry,
        agent_session_root=agent_session_root,
        work_root=work_root,
        authentication_context=authentication_context,
        purpose="BABOOM Work planning",
    )
    interfaces = work.get("interfaces")
    if not isinstance(interfaces, Mapping):
        raise InvalidCell("BABOOM Work planning interfaces are malformed")
    title = (interfaces.get("title") or {}).get("value")
    description = (interfaces.get("description") or {}).get("value")
    raw_priority = (interfaces.get("priority") or {}).get("value")
    if type(title) is not str or type(description) is not str:
        raise InvalidCell("BABOOM Work planning text is malformed")
    try:
        priority = int(raw_priority)
    except (TypeError, ValueError) as exc:
        raise InvalidCell("BABOOM Work planning priority is malformed") from exc
    plan = _deterministic_baboom_work_plan(
        work_root=work_root,
        title=title,
        description=description,
        priority=priority,
    )
    plan_root = "app:governed-work-plan:%s" % plan["fingerprint"]
    snapshot = store.snapshot()
    assembly = _instance_projection(snapshot, registry, work_root)
    if assembly is None:
        raise InvalidCell("BABOOM Work planning target is not projectable")
    plan_interface = next(
        (
            item for item in assembly["interfaces"]
            if item["name"] == "plan"
        ),
        None,
    )
    if (
        not isinstance(plan_interface, Mapping)
        or plan_interface.get("mode") != "connection"
        or type(plan_interface.get("target_incidence")) is not str
    ):
        raise InvalidCell("governed Work plan interface is unavailable")
    target_incidence = str(plan_interface["target_incidence"])
    current = snapshot.cells.get(target_incidence)
    if current is None:
        raise InvalidCell("governed Work plan binding is missing")
    if current.link1 == plan_root:
        return plan_root, True, snapshot.revision
    default_target = plan_interface.get("target")
    default_cell = (
        snapshot.cells.get(str(default_target))
        if isinstance(default_target, str)
        else None
    )
    if (
        default_cell is None
        or default_cell.link0 != NULL_CELL_ID
        or default_cell.link1 != NULL_CELL_ID
        or default_cell.atom != b"unwired"
        or current.link1 != default_cell.id
    ):
        raise InvalidCell(
            "governed Work already has a plan; create an explicit revision instead"
        )
    if plan_root not in snapshot.cells:
        build_value_graph(
            store,
            registry.value_graph_protocol,
            plan,
            root_id=plan_root,
        )
        snapshot = store.snapshot()
        current = snapshot.cells.get(target_incidence)
        if current is None or current.link1 != default_cell.id:
            raise InvalidCell("governed Work plan binding changed during creation")
    view_session, context = _view_session_for_context(
        registry, authentication_context
    )
    revision = _commit_universal_user_change(
        store,
        registry,
        view_session,
        context,
        snapshot,
        route="/api/universal/work-plan",
        command_name="catalog.configure",
        authorization_scope_root=work_root,
        authorization_interface_root=str(plan_interface["id"]),
        replace=(Cell(current.id, current.link0, plan_root, current.atom),),
    )
    _runtime_agent_session(store.snapshot(), registry, session.root_id)
    return plan_root, False, revision


def read_universal_baboom_work_plan(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    *,
    agent_session_root: str,
    work_root: str,
    authentication_context: object | None = None,
) -> tuple[str | None, Mapping[str, object] | None, int]:
    """Read the bounded plan attached to BABOOM's exact claimed Work only."""
    _session, _entry, work = _baboom_execution_work_context(
        store,
        registry,
        agent_session_root=agent_session_root,
        work_root=work_root,
        authentication_context=authentication_context,
        purpose="BABOOM Work plan read",
    )
    snapshot = store.snapshot()
    plan_root = _governed_work_interface_target(
        snapshot, registry, work_root, "plan"
    )
    target = snapshot.cells.get(plan_root)
    if (
        target is not None
        and target.link0 == NULL_CELL_ID
        and target.link1 == NULL_CELL_ID
        and target.atom == b"unwired"
    ):
        return None, None, snapshot.revision
    plan = read_value_graph(
        snapshot, registry.value_graph_protocol, plan_root
    )
    interfaces = work.get("interfaces")
    if not isinstance(interfaces, Mapping):
        raise InvalidCell("claimed Work plan interfaces are malformed")
    title = (interfaces.get("title") or {}).get("value")
    description = (interfaces.get("description") or {}).get("value")
    raw_priority = (interfaces.get("priority") or {}).get("value")
    if type(title) is not str or type(description) is not str:
        raise InvalidCell("claimed Work plan text is malformed")
    try:
        priority = int(raw_priority)
    except (TypeError, ValueError) as exc:
        raise InvalidCell("claimed Work plan priority is malformed") from exc
    expected = _deterministic_baboom_work_plan(
        work_root=work_root,
        title=title,
        description=description,
        priority=priority,
    )
    if (
        not isinstance(plan, Mapping)
        or json.dumps(plan, sort_keys=True, separators=(",", ":"), ensure_ascii=True)
        != json.dumps(expected, sort_keys=True, separators=(",", ":"), ensure_ascii=True)
    ):
        raise InvalidCell("claimed Work plan is not a valid BABOOM v2 draft")
    summary = _bounded_baboom_plan_text(plan.get("summary"), "summary", 512)
    steps = plan.get("steps")
    expected_steps = expected["steps"]
    if (
        not isinstance(steps, (tuple, list))
        or tuple(steps) != expected_steps
    ):
        raise InvalidCell("claimed Work plan steps are malformed")
    projected_steps: list[dict[str, object]] = []
    for expected_order, step in enumerate(steps, 1):
        projected_steps.append({
            "order": expected_order,
            "title": _bounded_baboom_plan_text(
                step.get("title"), "step title", 512
            ),
            "effect": step["effect"],
        })
    priority_assessment = plan.get("priority_assessment")
    if (
        not isinstance(priority_assessment, Mapping)
        or priority_assessment.get("declared_priority") != priority
        or tuple(priority_assessment.get("released_order", ()))
        != _BABOOM_WORKSHOP_COORDINATION_PRIORITY_POLICY
        or priority_assessment.get("model_authority") != "none"
    ):
        raise InvalidCell("claimed Work plan priority assessment is malformed")
    model_execution = _project_baboom_model_execution_by_work(
        snapshot, registry
    ).get(work_root, _empty_baboom_model_execution_projection())
    connector_execution = _project_baboom_connector_execution_by_work(
        snapshot, registry
    ).get(work_root, _empty_baboom_connector_execution_projection())
    return plan_root, {
        "state": "draft",
        "summary": summary,
        "priority_assessment": {
            "declared_priority": priority,
            "released_order": _BABOOM_WORKSHOP_COORDINATION_PRIORITY_POLICY,
            "model_authority": "none",
        },
        "steps": tuple(projected_steps),
        "execution": "none",
        "model_output": "not-used",
        "live_activity": {
            "model": _baboom_work_plan_live_activity(
                model_execution, kind="model"
            ),
            "connector": _baboom_work_plan_live_activity(
                connector_execution, kind="connector"
            ),
        },
    }, snapshot.revision


def _governed_work_handoff_policy(
    snapshot: Snapshot,
    registry: UniversalApplicationRegistry,
    work_root: str,
):
    """Read a released device-targeted policy, leaving other policies opaque."""
    policy_root = _governed_work_interface_target(
        snapshot, registry, work_root, "applicable-policy"
    )
    registered = {
        member.participant_id
        for member in read_relation(
            snapshot, registry.work_handoff_protocol.root_id, budget=100_000
        )
        if member.role_id == registry.work_handoff_protocol.role("handoff-member")
    }
    if policy_root not in registered:
        return None
    return read_work_handoff(
        snapshot, registry.work_handoff_protocol, policy_root
    )


def _governed_work_claim_transfer_policy(
    snapshot: Snapshot,
    registry: UniversalApplicationRegistry,
    work_root: str,
):
    """Read a released claim-transfer policy, leaving other policies opaque."""
    policy_root = _governed_work_interface_target(
        snapshot, registry, work_root, "applicable-policy"
    )
    registered = {
        member.participant_id
        for member in read_relation(
            snapshot, registry.work_claim_transfer_protocol.root_id, budget=100_000
        )
        if member.role_id == registry.work_claim_transfer_protocol.role(
            "transfer-member"
        )
    }
    if policy_root not in registered:
        return None
    transfer = read_work_claim_transfer(
        snapshot, registry.work_claim_transfer_protocol, policy_root
    )
    if transfer.work_root != work_root:
        raise InvalidCell("governed Work claim-transfer policy work drifted")
    return transfer


def _verify_governed_work_handoff_content(
    snapshot: Snapshot,
    registry: UniversalApplicationRegistry,
    work_root: str,
    handoff,
) -> None:
    description = _text(
        snapshot,
        _governed_work_interface_target(
            snapshot, registry, work_root, "description"
        ),
    )
    if hashlib.sha256(description.encode("utf-8")).hexdigest() != handoff.payload_digest:
        raise InvalidCell("governed Work content no longer matches its handoff digest")


def _governed_work_handoff_claim_is_admitted(
    snapshot: Snapshot,
    registry: UniversalApplicationRegistry,
    work_root: str,
    agent_session: AgentSessionProjection,
) -> bool:
    handoff = _governed_work_handoff_policy(snapshot, registry, work_root)
    if handoff is None:
        transfer = _governed_work_claim_transfer_policy(
            snapshot, registry, work_root
        )
        if transfer is None:
            return True
    presences = tuple(
        presence for presence in list_active_runtime_presences(
            snapshot,
            registry.runtime_presence_protocol,
            now=time.time(),
        )
        if presence.agent_session_root == agent_session.root_id
    )
    if len(presences) != 1:
        return False
    custody = read_device_custody(
        snapshot,
        registry.device_custody_protocol,
        presences[0].device_custody_root,
    )
    if custody.state_root != registry.device_custody_protocol.states["active"]:
        return False
    if handoff is not None:
        _verify_governed_work_handoff_content(
            snapshot, registry, work_root, handoff
        )
        return handoff_claim_is_permitted(
            snapshot,
            registry.work_handoff_protocol,
            handoff.root_id,
            device_custody_root=presences[0].device_custody_root,
            now=time.time(),
        )
    return claim_transfer_is_permitted(
        snapshot,
        registry.work_claim_transfer_protocol,
        transfer.root_id,
        device_custody_root=presences[0].device_custody_root,
        now=time.time(),
    )


def _runtime_agent_device_custody(
    snapshot: Snapshot,
    registry: UniversalApplicationRegistry,
    agent_session_root: str,
) -> str:
    """Resolve one active Device Custody for a device-proof runtime session."""
    session = _runtime_agent_session(snapshot, registry, agent_session_root)
    presences = tuple(
        presence for presence in list_active_runtime_presences(
            snapshot, registry.runtime_presence_protocol, now=time.time()
        )
        if presence.agent_session_root == session.root_id
    )
    if len(presences) != 1:
        raise AuthorizationDenied(
            "device handoff projection requires one live runtime presence"
        )
    custody = read_device_custody(
        snapshot,
        registry.device_custody_protocol,
        presences[0].device_custody_root,
    )
    if custody.state_root != registry.device_custody_protocol.states["active"]:
        raise AuthorizationDenied("runtime device custody is revoked")
    return custody.root_id


def project_universal_device_handoffs(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    *,
    agent_session_root: str,
    authentication_context: object | None = None,
) -> dict[str, object]:
    """Project only the exact graph handoffs visible to one custody-bound device.

    Work content, custody targets, delivery state, expiry, and claims remain
    primary-graph facts. This endpoint is a read lens over that one state; it
    neither mirrors command metadata nor uses an external relay queue.
    """
    snapshot = store.snapshot()
    _view_session, context = _view_session_for_context(
        registry, authentication_context
    )
    _require_application_authorization(
        snapshot,
        registry,
        "read",
        registry.governed_work_registry_root,
        authentication_context=context,
    )
    device_custody_root = _runtime_agent_device_custody(
        snapshot, registry, agent_session_root
    )
    work_index = project_universal_governed_work_index(
        store, registry, authentication_context=authentication_context
    )
    work_by_external_key: dict[str, Mapping[str, object]] = {}
    index_items = work_index.get("items")
    if not isinstance(index_items, (tuple, list)):
        raise InvalidCell("governed Work index is invalid")
    for item in index_items:
        if not isinstance(item, Mapping):
            raise InvalidCell("governed Work index item is invalid")
        interfaces = item.get("interfaces")
        external = (
            interfaces.get("external-key")
            if isinstance(interfaces, Mapping)
            else None
        )
        external_key = external.get("value") if isinstance(external, Mapping) else None
        if not isinstance(external_key, str):
            raise InvalidCell("governed Work external key is invalid")
        if external_key in work_by_external_key:
            raise InvalidCell("governed Work external key is ambiguous")
        work_by_external_key[external_key] = item

    handoff_members = read_relation(
        snapshot, registry.work_handoff_protocol.root_id, budget=100_000
    )
    state_labels = {
        root: label for label, root in registry.work_handoff_protocol.states.items()
    }
    now = time.time()
    items: list[dict[str, object]] = []
    for member in handoff_members:
        if member.role_id != registry.work_handoff_protocol.role("handoff-member"):
            continue
        handoff = read_work_handoff(
            snapshot, registry.work_handoff_protocol, member.participant_id
        )
        if device_custody_root not in {
            handoff.source_device_custody_root,
            handoff.target_device_custody_root,
        }:
            continue
        work = work_by_external_key.get("device-handoff:" + handoff.handoff_key)
        if work is None:
            raise InvalidCell("device handoff has no governed Work")
        work_root = work.get("root")
        if not isinstance(work_root, str) or not work_root:
            raise InvalidCell("device handoff Work root is invalid")
        _verify_governed_work_handoff_content(
            snapshot, registry, work_root, handoff
        )
        operational = work.get("operational")
        if not isinstance(operational, Mapping):
            raise InvalidCell("device handoff Work state is invalid")
        work_state = operational.get("current_state_label")
        if not isinstance(work_state, str):
            raise InvalidCell("device handoff Work state is invalid")
        title = _text(
            snapshot,
            _governed_work_interface_target(snapshot, registry, work_root, "title"),
        )
        description = _text(
            snapshot,
            _governed_work_interface_target(
                snapshot, registry, work_root, "description"
            ),
        )
        items.append({
            "handoff_root": handoff.root_id,
            "handoff_key": handoff.handoff_key,
            "work_root": work_root,
            "direction": (
                "outgoing"
                if handoff.source_device_custody_root == device_custody_root
                else "incoming"
            ),
            "source_device_custody": handoff.source_device_custody_root,
            "target_device_custody": handoff.target_device_custody_root,
            "payload_digest": handoff.payload_digest,
            "issued_at": handoff.issued_at,
            "expires_at": handoff.expires_at,
            "handoff_state": state_labels[handoff.state_root],
            "claimable": handoff_claim_is_permitted(
                snapshot,
                registry.work_handoff_protocol,
                handoff.root_id,
                device_custody_root=device_custody_root,
                now=now,
            ),
            "work_state": work_state,
            "claimant_session": work.get("claimant_session"),
            "title": title,
            "description": description,
        })
    items.sort(key=lambda item: (float(item["issued_at"]), str(item["handoff_key"])))
    return {
        "projection": "device-handoff-v1",
        "application": registry.application_root,
        "agent_session": agent_session_root,
        "device_custody": device_custody_root,
        "revision": snapshot.revision,
        "items": tuple(items),
    }


def create_universal_device_handoff_work(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    *,
    title: str,
    description: str,
    priority: int,
    scope: str,
    source_device_custody_root: str,
    target_device_custody_root: str,
    handoff_key: str,
    payload_digest: str,
    expires_at: float,
    x: float,
    y: float,
    authentication_context: object | None = None,
) -> tuple[str, str, str, int]:
    """Create one idempotent, custody-targeted Work in the primary graph.

    The caller supplies no raw remote identity beyond an already-proven Device
    Custody root.  The handoff composition becomes the Work's explicit
    ``applicable-policy`` endpoint, so the generic claim transition enforces
    it without a BABOOM-specific branch.
    """
    if type(description) is not str:
        raise InvalidCell("device handoff Work description must be text")
    computed_digest = hashlib.sha256(description.encode("utf-8")).hexdigest()
    if computed_digest != payload_digest:
        raise InvalidCell("device handoff payload digest does not match Work content")
    snapshot = store.snapshot()
    source = read_device_custody(
        snapshot, registry.device_custody_protocol, source_device_custody_root
    )
    target = read_device_custody(
        snapshot, registry.device_custody_protocol, target_device_custody_root
    )
    active_state = registry.device_custody_protocol.states["active"]
    if source.state_root != active_state or target.state_root != active_state:
        raise AuthorizationDenied("device handoff requires active Device Custody")
    now = time.time()
    handoff, _ = issue_work_handoff(
        store,
        registry.work_handoff_protocol,
        source_device_custody_root=source_device_custody_root,
        target_device_custody_root=target_device_custody_root,
        handoff_key=handoff_key,
        payload_digest=payload_digest,
        issued_at=now,
        expires_at=expires_at,
    )
    external_key = "device-handoff:%s" % handoff.handoff_key
    status = project_universal_governed_work(
        store, registry, authentication_context=authentication_context
    )
    existing = [
        item for item in status
        if item.get("interfaces", {}).get("external-key", {}).get("value")
        == external_key
    ]
    if len(existing) > 1:
        raise InvalidCell("device handoff Work identity is ambiguous")
    if existing:
        work_root = str(existing[0]["root"])
        existing_handoff = _governed_work_handoff_policy(
            store.snapshot(), registry, work_root
        )
        if existing_handoff is None or existing_handoff.root_id != handoff.root_id:
            raise InvalidCell("device handoff Work policy drifted")
        _verify_governed_work_handoff_content(
            store.snapshot(), registry, work_root, existing_handoff
        )
        return (
            work_root,
            "app:relation:governed-work:%s" % _part(work_root),
            handoff.root_id,
            store.revision,
        )
    work_root, membership_wire, revision = create_universal_governed_work(
        store,
        registry,
        title=title,
        description=description,
        priority=priority,
        external_key=external_key,
        references={
            "scope": scope,
            "applicable-policy": handoff.root_id,
        },
        x=x,
        y=y,
        compact_references=True,
        select_created=False,
        authentication_context=authentication_context,
    )
    attached = _governed_work_handoff_policy(
        store.snapshot(), registry, work_root
    )
    if attached is None or attached.root_id != handoff.root_id:
        raise InvalidCell("device handoff Work policy was not attached")
    _verify_governed_work_handoff_content(
        store.snapshot(), registry, work_root, attached
    )
    return work_root, membership_wire, handoff.root_id, revision


def create_universal_device_handoff_work_for_device_ref(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    *,
    agent_session_root: str,
    title: str,
    description: str,
    priority: int,
    scope: str,
    target_device_ref: str,
    handoff_key: str,
    payload_digest: str,
    expires_at: float,
    x: float,
    y: float,
    authentication_context: object | None = None,
) -> tuple[str, str, str, int]:
    """Create a handoff for one opaque founder-selected BABOOM device.

    Device selectors are a founder-local projection convenience only. Their
    resolution, current custody state, source-session proof, and resulting
    custody-root policy all remain in the Universal Cell application.
    """
    if (
        type(target_device_ref) is not str
        or not _FOUNDER_DEVICE_CUSTODY_REF.fullmatch(target_device_ref)
    ):
        raise InvalidCell("device handoff target device selector is invalid")
    snapshot = store.snapshot()
    source_session = _runtime_agent_session(snapshot, registry, agent_session_root)
    source_entry = _agent_body_catalog_entry_for_session(
        snapshot, registry, source_session
    )
    if source_entry.runtime != "baboom-execution":
        raise AuthorizationDenied(
            "BABOOM device handoff requires the receipt-bound action capability"
        )
    _view_session, context = _view_session_for_context(
        registry, authentication_context
    )
    identity = registry.authorization.broker.resolve(context)
    if source_session.subject_root != identity.subject_root:
        raise AuthorizationDenied("device handoff source subject drifted")
    source_custody = _runtime_agent_device_custody(
        snapshot, registry, agent_session_root
    )
    candidates = [
        custody_root for custody_root, row in _founder_device_custody_records(
            snapshot, registry, now=time.time()
        )
        if row["device_ref"] == target_device_ref
        and row["state"] == "active"
        and row["runtime_present"] is True
        and row["baboom_bound"] is True
        and custody_root != source_custody
    ]
    if len(candidates) != 1:
        raise AuthorizationDenied(
            "device handoff target BABOOM device is unavailable or ambiguous"
        )
    return create_universal_device_handoff_work(
        store,
        registry,
        title=title,
        description=description,
        priority=priority,
        scope=scope,
        source_device_custody_root=source_custody,
        target_device_custody_root=candidates[0],
        handoff_key=handoff_key,
        payload_digest=payload_digest,
        expires_at=expires_at,
        x=x,
        y=y,
        authentication_context=authentication_context,
    )


def record_universal_device_handoff_receipt(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    *,
    handoff_key: str,
    source_device_custody_root: str,
    kind: str,
    receipt_digest: str,
) -> tuple[str, str, int]:
    """Record a bounded transport receipt without promoting relay authority."""
    handoff_root = "work-handoff:sha256:%s" % handoff_key
    handoff = read_work_handoff(
        store.snapshot(), registry.work_handoff_protocol, handoff_root
    )
    if handoff.source_device_custody_root != source_device_custody_root:
        raise AuthorizationDenied("only the handoff source Device Custody may record delivery")
    _updated, receipt, revision = record_work_handoff_receipt(
        store,
        registry.work_handoff_protocol,
        handoff_root=handoff_root,
        kind=kind,
        receipt_digest=receipt_digest,
    )
    return handoff_root, receipt.root_id, revision


def _work_claim_transfer_identity_digest(
    snapshot: Snapshot,
    registry: UniversalApplicationRegistry,
    work_root: str,
) -> str:
    """Hash stable Work identity roots without copying Work content."""
    return hashlib.sha256(json.dumps(
        {
            "external_key": _governed_work_interface_target(
                snapshot, registry, work_root, "external-key"
            ),
            "plan": _governed_work_interface_target(
                snapshot, registry, work_root, "plan"
            ),
            "work": work_root,
        },
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=True,
    ).encode("utf-8")).hexdigest()


def _baboom_work_has_unsettled_execution(
    snapshot: Snapshot,
    registry: UniversalApplicationRegistry,
    work_root: str,
) -> bool:
    """Deny custody transfer while a delegated effect can still begin."""
    for projection in (
        _project_baboom_model_execution_by_work(snapshot, registry).get(work_root),
        _project_baboom_connector_execution_by_work(snapshot, registry).get(work_root),
    ):
        if projection is None:
            continue
        if not isinstance(projection, Mapping):
            raise InvalidCell("BABOOM execution projection is invalid")
        for state in ("awaiting_approval", "ready"):
            value = projection.get(state)
            if type(value) is not int or value < 0:
                raise InvalidCell("BABOOM execution state is invalid")
            if value:
                return True
    return False


def _governed_work_claim_transfer_binding(
    snapshot: Snapshot,
    registry: UniversalApplicationRegistry,
    work_root: str,
) -> tuple[Mapping[str, object], Cell]:
    interface = _governed_work_interface(
        snapshot, registry, work_root, "applicable-policy"
    )
    if (
        interface.get("mode") != "connection"
        or type(interface.get("id")) is not str
        or type(interface.get("target_incidence")) is not str
    ):
        raise InvalidCell("governed Work claim-transfer policy interface is unavailable")
    incidence = snapshot.cells.get(str(interface["target_incidence"]))
    if incidence is None:
        raise InvalidCell("governed Work claim-transfer policy binding is missing")
    return interface, incidence


def initiate_universal_baboom_work_claim_transfer(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    *,
    agent_session_root: str,
    work_root: str,
    target_device_ref: str,
    transfer_key: str,
    confirmation_digest: str,
    expires_at: float,
    authentication_context: object | None = None,
) -> dict[str, object]:
    """Release one claimed Work into an exact target-custody reservation."""
    if (
        type(transfer_key) is not str
        or not re.fullmatch(r"[0-9a-f]{64}", transfer_key)
        or type(confirmation_digest) is not str
        or not re.fullmatch(r"[0-9a-f]{64}", confirmation_digest)
    ):
        raise InvalidCell("work claim transfer key or confirmation is invalid")
    try:
        expiry = float(expires_at)
    except (TypeError, ValueError) as exc:
        raise InvalidCell("work claim transfer expiry is invalid") from exc
    now = time.time()
    if not math.isfinite(expiry) or expiry <= now or expiry - now > 86_400:
        raise InvalidCell("work claim transfer expiry is outside its bound")
    snapshot = store.snapshot()
    source_session = _runtime_agent_session(snapshot, registry, agent_session_root)
    source_entry = _agent_body_catalog_entry_for_session(
        snapshot, registry, source_session
    )
    if source_entry.runtime != "baboom-execution":
        raise AuthorizationDenied(
            "BABOOM Work claim transfer requires the receipt-bound action capability"
        )
    view_session, context = _view_session_for_context(
        registry, authentication_context
    )
    identity = registry.authorization.broker.resolve(context)
    if source_session.subject_root != identity.subject_root:
        raise AuthorizationDenied("Work claim transfer source subject drifted")
    source_custody = _runtime_agent_device_custody(
        snapshot, registry, agent_session_root
    )
    if (
        type(target_device_ref) is not str
        or not _FOUNDER_DEVICE_CUSTODY_REF.fullmatch(target_device_ref)
    ):
        raise InvalidCell("Work claim transfer target device selector is invalid")
    target_candidates = [
        custody_root for custody_root, row in _founder_device_custody_records(
            snapshot, registry, now=now
        )
        if row["device_ref"] == target_device_ref
        and row["state"] == "active"
        and row["runtime_present"] is True
    ]
    if len(target_candidates) != 1:
        raise AuthorizationDenied(
            "Work claim transfer target device is unavailable or ambiguous"
        )
    target_device_custody_root = target_candidates[0]
    work_digest = _work_claim_transfer_identity_digest(
        snapshot, registry, work_root
    )
    transfer_root = "work-claim-transfer:sha256:" + transfer_key
    existing_transfer = (
        read_work_claim_transfer(
            snapshot, registry.work_claim_transfer_protocol, transfer_root
        )
        if transfer_root in snapshot.cells
        else None
    )
    if existing_transfer is not None and (
        existing_transfer.work_root != work_root
        or existing_transfer.source_agent_session_root != agent_session_root
        or existing_transfer.source_device_custody_root != source_custody
        or existing_transfer.target_device_custody_root != target_device_custody_root
        or existing_transfer.work_digest != work_digest
        or existing_transfer.confirmation_digest != confirmation_digest
    ):
        raise AuthorizationDenied("Work claim transfer identity conflicts with the graph")
    status = project_universal_governed_work_status(
        store, registry, authentication_context=context
    )
    work = next((
        item for item in status["items"] if item.get("root") == work_root
    ), None)
    if work is None:
        raise InvalidCell("Work claim transfer target is unavailable")
    work_state = str(work["operational"]["current_state_label"]).casefold()
    if (
        existing_transfer is not None
        and existing_transfer.state_root
        == registry.work_claim_transfer_protocol.states["released"]
    ):
        # The governed-Work protocol records a transfer as released while its
        # generic lifecycle returns from claimed to open for the target to claim.
        if work_state != "open":
            raise InvalidCell("released Work claim transfer and Work state drifted")
        release_receipt_root = work_claim_transfer_receipt_root(
            existing_transfer.transfer_key, "release"
        )
        release_receipt = read_work_claim_transfer_receipt(
            snapshot,
            registry.work_claim_transfer_protocol,
            release_receipt_root,
        )
        if release_receipt.kind_root != (
            registry.work_claim_transfer_protocol.receipt_kinds["release"]
        ):
            raise InvalidCell("Work claim transfer release evidence drifted")
        return {
            "transfer_key": existing_transfer.transfer_key,
            "target_device_ref": target_device_ref,
            "state": "released",
            "expires_at": existing_transfer.expires_at,
            "policy_revision": snapshot.revision,
            "release_receipt_root": release_receipt_root,
            "revision": snapshot.revision,
            "reused": True,
        }
    if work_state != "claimed":
        raise InvalidCell("Work claim transfer target is not claimed")
    if work.get("claimant_session") != agent_session_root:
        raise AuthorizationDenied("only the current Work claimant may transfer custody")
    if _baboom_work_has_unsettled_execution(snapshot, registry, work_root):
        raise AuthorizationDenied(
            "Work claim transfer requires all model and connector delegations to settle"
        )
    interface, incidence = _governed_work_claim_transfer_binding(
        snapshot, registry, work_root
    )
    if existing_transfer is None:
        current_target = snapshot.cells.get(incidence.link1)
        if (
            current_target is None
            or current_target.link0 != NULL_CELL_ID
            or current_target.link1 != NULL_CELL_ID
            or current_target.atom != b"unwired"
        ):
            raise AuthorizationDenied(
                "Work claim transfer requires an unreserved applicable-policy interface"
            )
        transfer_root, transfer_create, transfer_replace = (
            prepare_work_claim_transfer_issue(
                snapshot,
                registry.work_claim_transfer_protocol,
                work_root=work_root,
                source_agent_session_root=agent_session_root,
                source_device_custody_root=source_custody,
                target_device_custody_root=target_device_custody_root,
                transfer_key=transfer_key,
                work_digest=work_digest,
                confirmation_digest=confirmation_digest,
                issued_at=now,
                expires_at=expiry,
            )
        )
        policy_revision = _commit_universal_user_change(
            store,
            registry,
            view_session,
            context,
            snapshot,
            route="/api/universal/work-claim-transfer",
            command_name="catalog.configure",
            authorization_scope_root=work_root,
            authorization_interface_root=str(interface["id"]),
            create=transfer_create,
            replace=(
                *transfer_replace,
                Cell(
                    incidence.id,
                    incidence.link0,
                    transfer_root,
                    incidence.atom,
                ),
            ),
        )
        snapshot = store.snapshot()
        transfer = read_work_claim_transfer(
            snapshot, registry.work_claim_transfer_protocol, transfer_root
        )
    else:
        transfer = existing_transfer
        if transfer.state_root != registry.work_claim_transfer_protocol.states["prepared"]:
            raise AuthorizationDenied("Work claim transfer is already terminal")
        if incidence.link1 != transfer.root_id:
            raise InvalidCell("prepared Work claim transfer policy drifted")
        policy_revision = snapshot.revision
    _release_history_root, revision = transition_universal_governed_work(
        store,
        registry,
        work_root,
        "release",
        agent_session_root=agent_session_root,
        additional_context_roots=(transfer.root_id,),
        authentication_context=context,
    )
    released = read_work_claim_transfer(
        store.snapshot(), registry.work_claim_transfer_protocol, transfer.root_id
    )
    if released.state_root != registry.work_claim_transfer_protocol.states["released"]:
        raise InvalidCell("Work claim transfer release receipt was not persisted")
    return {
        "transfer_key": released.transfer_key,
        "target_device_ref": target_device_ref,
        "state": "released",
        "expires_at": released.expires_at,
        "policy_revision": policy_revision,
        "release_receipt_root": work_claim_transfer_receipt_root(
            released.transfer_key, "release"
        ),
        "revision": revision,
        "reused": False,
    }


def project_universal_baboom_work_claim_transfers(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    *,
    agent_session_root: str,
    authentication_context: object | None = None,
) -> dict[str, object]:
    """Project custody-scoped continuation state without Work content or roots."""
    snapshot = store.snapshot()
    _view_session, context = _view_session_for_context(
        registry, authentication_context
    )
    _require_application_authorization(
        snapshot,
        registry,
        "read",
        registry.governed_work_registry_root,
        authentication_context=context,
    )
    device_custody_root = _runtime_agent_device_custody(
        snapshot, registry, agent_session_root
    )
    states = {
        root: label
        for label, root in registry.work_claim_transfer_protocol.states.items()
    }
    now = time.time()
    items: list[dict[str, object]] = []
    for member in read_relation(
        snapshot, registry.work_claim_transfer_protocol.root_id, budget=100_000
    ):
        if member.role_id != registry.work_claim_transfer_protocol.role(
            "transfer-member"
        ):
            continue
        transfer = read_work_claim_transfer(
            snapshot, registry.work_claim_transfer_protocol, member.participant_id
        )
        if device_custody_root not in {
            transfer.source_device_custody_root,
            transfer.target_device_custody_root,
        }:
            continue
        items.append({
            "transfer_key": transfer.transfer_key,
            "direction": (
                "outgoing"
                if transfer.source_device_custody_root == device_custody_root
                else "incoming"
            ),
            "issued_at": transfer.issued_at,
            "expires_at": transfer.expires_at,
            "state": states[transfer.state_root],
            "claimable": claim_transfer_is_permitted(
                snapshot,
                registry.work_claim_transfer_protocol,
                transfer.root_id,
                device_custody_root=device_custody_root,
                now=now,
            ),
        })
    items.sort(key=lambda item: (float(item["issued_at"]), str(item["transfer_key"])))
    return {
        "projection": "work-claim-transfer-v1",
        "application": registry.application_root,
        "agent_session": agent_session_root,
        "device_custody": device_custody_root,
        "revision": snapshot.revision,
        "items": tuple(items),
    }


def claim_universal_baboom_work_claim_transfer(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    *,
    agent_session_root: str,
    transfer_key: str,
    compliance_observation_root: str | None = None,
    authentication_context: object | None = None,
) -> dict[str, object]:
    """Claim one incoming transfer through ordinary governed-Work semantics."""
    if type(transfer_key) is not str or not re.fullmatch(r"[0-9a-f]{64}", transfer_key):
        raise InvalidCell("Work claim transfer key is invalid")
    snapshot = store.snapshot()
    transfer = read_work_claim_transfer(
        snapshot,
        registry.work_claim_transfer_protocol,
        "work-claim-transfer:sha256:" + transfer_key,
    )
    device_custody_root = _runtime_agent_device_custody(
        snapshot, registry, agent_session_root
    )
    if not claim_transfer_is_permitted(
        snapshot,
        registry.work_claim_transfer_protocol,
        transfer.root_id,
        device_custody_root=device_custody_root,
        now=time.time(),
    ):
        raise AuthorizationDenied("Work claim transfer is not claimable by this device")
    return claim_universal_governed_work(
        store,
        registry,
        agent_session_root=agent_session_root,
        work_root=transfer.work_root,
        compliance_observation_root=compliance_observation_root,
        authentication_context=authentication_context,
    )


def cancel_universal_baboom_work_claim_transfer(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    *,
    agent_session_root: str,
    transfer_key: str,
    cancellation_digest: str,
    authentication_context: object | None = None,
) -> dict[str, object]:
    """Cancel one source-owned continuation and restore ordinary Work claiming."""
    if (
        type(transfer_key) is not str
        or not re.fullmatch(r"[0-9a-f]{64}", transfer_key)
        or type(cancellation_digest) is not str
        or not re.fullmatch(r"[0-9a-f]{64}", cancellation_digest)
    ):
        raise InvalidCell("Work claim transfer cancellation input is invalid")
    snapshot = store.snapshot()
    source_session = _runtime_agent_session(snapshot, registry, agent_session_root)
    source_entry = _agent_body_catalog_entry_for_session(
        snapshot, registry, source_session
    )
    if source_entry.runtime != "baboom-execution":
        raise AuthorizationDenied(
            "BABOOM Work claim transfer cancellation requires the receipt-bound action capability"
        )
    view_session, context = _view_session_for_context(
        registry, authentication_context
    )
    identity = registry.authorization.broker.resolve(context)
    if source_session.subject_root != identity.subject_root:
        raise AuthorizationDenied("Work claim transfer cancellation source subject drifted")
    transfer = read_work_claim_transfer(
        snapshot,
        registry.work_claim_transfer_protocol,
        "work-claim-transfer:sha256:" + transfer_key,
    )
    source_custody = _runtime_agent_device_custody(
        snapshot, registry, agent_session_root
    )
    if (
        transfer.source_agent_session_root != agent_session_root
        or transfer.source_device_custody_root != source_custody
    ):
        raise AuthorizationDenied(
            "only the originating BABOOM device may cancel this Work continuation"
        )
    cancellation_receipt_root = work_claim_transfer_receipt_root(
        transfer.transfer_key, "cancellation"
    )
    if transfer.state_root == registry.work_claim_transfer_protocol.states["cancelled"]:
        receipt = read_work_claim_transfer_receipt(
            snapshot,
            registry.work_claim_transfer_protocol,
            cancellation_receipt_root,
        )
        if (
            receipt.kind_root
            != registry.work_claim_transfer_protocol.receipt_kinds["cancellation"]
            or receipt.digest != cancellation_digest
        ):
            raise InvalidCell("Work claim transfer cancellation evidence drifted")
        return {
            "transfer_key": transfer.transfer_key,
            "state": "cancelled",
            "cancellation_receipt_root": cancellation_receipt_root,
            "revision": snapshot.revision,
            "reused": True,
        }
    if transfer.state_root not in {
        registry.work_claim_transfer_protocol.states["prepared"],
        registry.work_claim_transfer_protocol.states["released"],
    }:
        raise AuthorizationDenied("Work claim transfer is already terminal")
    interface, incidence = _governed_work_claim_transfer_binding(
        snapshot, registry, transfer.work_root
    )
    if incidence.link1 != transfer.root_id:
        raise InvalidCell("Work claim transfer cancellation policy drifted")
    status = project_universal_governed_work_status(
        store, registry, authentication_context=context
    )
    work = next((
        item for item in status["items"] if item.get("root") == transfer.work_root
    ), None)
    if work is None:
        raise InvalidCell("Work claim transfer cancellation target is unavailable")
    work_state = str(work["operational"]["current_state_label"]).casefold()
    if transfer.state_root == registry.work_claim_transfer_protocol.states["prepared"]:
        if work_state != "claimed" or work.get("claimant_session") != agent_session_root:
            raise InvalidCell("prepared Work claim transfer ownership drifted")
    elif work_state != "open":
        raise InvalidCell("released Work claim transfer lifecycle drifted")
    cancellation_create, cancellation_replace = prepare_work_claim_transfer_receipt(
        snapshot,
        registry.work_claim_transfer_protocol,
        transfer_root=transfer.root_id,
        kind="cancellation",
        receipt_digest=cancellation_digest,
    )
    unwired_root = transfer.root_id + ":cancelled-unwired"
    unwired = snapshot.cells.get(unwired_root)
    if unwired is not None and (
        unwired.link0 != NULL_CELL_ID
        or unwired.link1 != NULL_CELL_ID
        or unwired.atom != b"unwired"
    ):
        raise InvalidCell("Work claim transfer cancellation unbound endpoint drifted")
    unwired_create: tuple[Cell, ...] = () if unwired is not None else (
        Cell(unwired_root, NULL_CELL_ID, NULL_CELL_ID, b"unwired"),
    )
    revision = _commit_universal_user_change(
        store,
        registry,
        view_session,
        context,
        snapshot,
        route="/api/universal/work-claim-transfer-cancel",
        command_name="catalog.configure",
        authorization_scope_root=transfer.work_root,
        authorization_interface_root=str(interface["id"]),
        create=(*cancellation_create, *unwired_create),
        replace=(
            *cancellation_replace,
            Cell(
                incidence.id,
                incidence.link0,
                unwired_root,
                incidence.atom,
            ),
        ),
    )
    cancelled = read_work_claim_transfer(
        store.snapshot(), registry.work_claim_transfer_protocol, transfer.root_id
    )
    if cancelled.state_root != registry.work_claim_transfer_protocol.states["cancelled"]:
        raise InvalidCell("Work claim transfer cancellation receipt was not persisted")
    return {
        "transfer_key": cancelled.transfer_key,
        "state": "cancelled",
        "cancellation_receipt_root": cancellation_receipt_root,
        "revision": revision,
        "reused": False,
    }


def _empty_baboom_model_execution_projection() -> dict[str, object]:
    return {
        "total": 0,
        "awaiting_approval": 0,
        "ready": 0,
        "expired": 0,
        "succeeded": 0,
        "failed": 0,
        "latest": None,
    }


def _empty_baboom_connector_execution_projection() -> dict[str, object]:
    return {
        "total": 0,
        "awaiting_approval": 0,
        "ready": 0,
        "expired": 0,
        "succeeded": 0,
        "failed": 0,
        "latest": None,
    }


def _project_baboom_connector_execution_by_work(
    snapshot: Snapshot,
    registry: UniversalApplicationRegistry,
) -> Mapping[str, dict[str, object]]:
    """Project connector-effect state without exposing inputs or outputs."""
    protocol = registry.baboom_connector_execution_protocol
    delegation_members = read_relation(
        snapshot, protocol.registry("delegation"), budget=100_000
    )
    delegations_by_work: dict[str, list[ConnectorDelegationProjection]] = {}
    for member in delegation_members:
        if member.role_id != protocol.role("registry-member"):
            continue
        delegation = read_connector_delegation(
            snapshot, protocol, registry.adapter_protocol, member.participant_id
        )
        delegations_by_work.setdefault(delegation.work_root, []).append(
            delegation
        )
    if not delegations_by_work:
        return MappingProxyType({})

    delegation_roots = {
        delegation.root_id
        for delegations in delegations_by_work.values()
        for delegation in delegations
    }
    receipts_by_delegation: dict[str, ConnectorExecutionReceiptProjection] = {}
    receipt_members = read_relation(
        snapshot, protocol.registry("receipt"), budget=100_000
    )
    for member in receipt_members:
        if member.role_id != protocol.role("registry-member"):
            continue
        receipt = read_connector_execution_receipt(
            snapshot, protocol, registry.adapter_protocol, member.participant_id
        )
        if receipt.delegation_root in delegation_roots:
            receipts_by_delegation[receipt.delegation_root] = receipt

    permission_states = {
        root: name
        for name, root in registry.adapter_protocol.states.items()
    }
    now = time.time()
    projected: dict[str, dict[str, object]] = {}
    for work_root, delegations in delegations_by_work.items():
        result = _empty_baboom_connector_execution_projection()
        latest: tuple[float, dict[str, object]] | None = None
        for delegation in delegations:
            receipt = receipts_by_delegation.get(delegation.root_id)
            if receipt is not None:
                state = receipt.outcome
                if state not in {"succeeded", "failed"}:
                    raise InvalidCell("connector receipt outcome is invalid")
                result[state] = int(result[state]) + 1
                candidate = {
                    "delegation": delegation.root_id,
                    "receipt": receipt.root_id,
                    "state": state,
                    "provider": receipt.provider_root,
                    "operation": receipt.operation,
                    "created_at": receipt.created_at,
                    "error_code": receipt.error_code,
                }
                rank = receipt.created_at
            else:
                permission = read_permission(
                    snapshot, registry.adapter_protocol, delegation.permission_root
                )
                permission_state = permission_states.get(
                    permission.lifecycle_root, "unknown"
                )
                if now >= delegation.expires_at:
                    state = "expired"
                elif permission_state == "requested":
                    state = "awaiting_approval"
                elif permission_state == "granted":
                    state = "ready"
                elif permission_state == "revoked":
                    state = "expired"
                else:
                    raise InvalidCell("connector delegation permission state is invalid")
                result[state] = int(result[state]) + 1
                candidate = {
                    "delegation": delegation.root_id,
                    "receipt": None,
                    "state": state,
                    "provider": delegation.provider_root,
                    "operation": read_connector_provider(
                        snapshot,
                        protocol,
                        registry.adapter_protocol,
                        delegation.provider_root,
                    ).operation,
                    "created_at": None,
                    "error_code": "",
                }
                rank = delegation.expires_at
            if latest is None or rank > latest[0]:
                latest = (rank, candidate)
        result["total"] = len(delegations)
        result["latest"] = latest[1] if latest is not None else None
        projected[work_root] = result
    return MappingProxyType(projected)


