def adjudicate_universal_governed_work(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    work_root: str,
    *,
    requesting_agent_session_root: str,
    workspace_root: str | Path,
    compact_status: bool = False,
    authentication_context: object | None = None,
) -> dict[str, object]:
    """Rerun one submitted work gate in the independent application court."""
    snapshot = store.snapshot()
    view_session, context = _view_session_for_context(
        registry, authentication_context
    )
    requesting_session = _runtime_agent_session(
        snapshot, registry, requesting_agent_session_root
    )
    identity = registry.authorization.broker.resolve(context)
    if requesting_session.subject_root != identity.subject_root:
        raise AuthorizationDenied(
            "runtime Agent Session belongs to another subject"
        )
    registered = {
        member.participant_id for member in read_relation(
            snapshot, registry.governed_work_registry_root, budget=100_000
        )
        if member.role_id == registry.roles["member"]
    }
    if work_root not in registered:
        raise InvalidCell("work court target is not registered")
    _require_application_authorization(
        snapshot,
        registry,
        "execute",
        work_root,
        authentication_context=context,
    )
    operational = registry.standard_library.state_machine_protocol
    machine = read_instance_state_machine(
        snapshot, registry.assembly_protocol, operational, work_root
    )
    if _text(snapshot, machine.current_state_root).casefold() != "review":
        raise InvalidCell("work court requires the review state")
    claimant = _governed_work_claimant_session(snapshot, registry, work_root)
    if claimant != requesting_agent_session_root:
        raise AuthorizationDenied(
            "only the submitting Agent Session may request this court"
        )

    items = project_universal_governed_work(
        store, registry, authentication_context=context
    )
    matches = tuple(item for item in items if item["root"] == work_root)
    if len(matches) != 1:
        raise InvalidCell("work court projection is missing or ambiguous")
    interfaces = matches[0]["interfaces"]
    structured = {}
    for name in ("requirements", "cde-container"):
        target = (interfaces.get(name) or {}).get("target")
        if type(target) is not str:
            raise InvalidCell("work court input is not wired")
        structured[name] = read_value_graph(
            snapshot, registry.value_graph_protocol, target
        )
    if type(structured["requirements"]) is not dict:
        raise InvalidCell("work requirements are not an object")
    if type(structured["cde-container"]) is not dict:
        raise InvalidCell("work CDE container is not an object")

    history = machine_history(snapshot, operational, machine.root_id)
    if not history:
        raise InvalidCell("work review has no submission history")
    submission = history[-1]
    if (
        _text(snapshot, submission.event_root).casefold() != "submit"
        or submission.actor_root != claimant
        or claimant not in submission.context_roots
        or len(submission.evidence_roots) != 1
    ):
        raise InvalidCell("work submission provenance is invalid")
    artifact = read_evidence(
        snapshot, operational, submission.evidence_roots[0]
    )
    if artifact.issuer_root != claimant:
        raise InvalidCell("artifact proof was not issued by the claimant")
    artifact_digest = hashlib.sha256(artifact.payload).hexdigest()
    resolved_workspace = Path(workspace_root).expanduser().resolve()
    workspace_digest = hashlib.sha256(
        str(resolved_workspace).casefold().encode("utf-8")
    ).hexdigest()
    subject_document = {
        "work_root": work_root,
        "agent_session": claimant,
        "submit_event": submission.root_id,
        "artifact_evidence_digest": artifact_digest,
        "workspace_digest": workspace_digest,
        "requirements": structured["requirements"],
        "cde": structured["cde-container"],
    }
    try:
        subject_content = json.dumps(
            subject_document,
            sort_keys=True,
            separators=(",", ":"),
            ensure_ascii=True,
        ).encode("utf-8")
    except (TypeError, ValueError) as exc:
        raise InvalidCell("work court input is not canonical") from exc
    parameters = {
        "workRoot": work_root,
        "agentSession": claimant,
        "submitEvent": submission.root_id,
        "artifactEvidenceDigest": artifact_digest,
        "workspaceDigest": workspace_digest,
    }
    attestation_root = registry.attestation_broker.run(
        store,
        registry.attestation_protocol,
        registry.work_completion_court_root,
        subject_name=work_root,
        subject_content=subject_content,
        external_parameters=parameters,
    )
    attestation = read_court_attestation(
        store.snapshot(), registry.attestation_protocol, attestation_root
    )
    passed = (
        attestation.result_root
        == registry.attestation_protocol.states["passed"]
    )
    outcome = "pass" if passed else "fail"
    subject_digest = hashlib.sha256(subject_content).hexdigest()
    registry.attestation_broker.verify(
        store.snapshot(),
        registry.attestation_protocol,
        attestation_root,
        expected_court_root=registry.work_completion_court_root,
        expected_subject_name=work_root,
        expected_subject_digest=subject_digest,
        expected_parameters=parameters,
        expected_result=outcome,
    )

    event = "accept" if passed else "return"
    candidates = []
    for transition_root in machine.transition_roots:
        transition = read_transition(
            store.snapshot(), operational, transition_root
        )
        if (
            transition.from_state_root == machine.current_state_root
            and _text(
                store.snapshot(), transition.event_root
            ).casefold() == event
        ):
            candidates.append(transition)
    if len(candidates) != 1:
        raise InvalidCell("work court transition is missing or ambiguous")
    transition = candidates[0]
    if len(transition.required_evidence_type_roots) != 1:
        raise InvalidCell("work court transition evidence contract drifted")
    evidence_payload = json.dumps({
        "attestation_root": attestation_root,
        "subject_digest": subject_digest,
        "result": outcome,
    }, sort_keys=True, separators=(",", ":")).encode("utf-8")
    decision_evidence_root, history_root, revision = (
        transition_machine_with_new_evidence(
            store,
            operational,
            machine.root_id,
            event_root=transition.event_root,
            expected_state_root=machine.current_state_root,
            actor_root=registry.work_completion_court_root,
            evidence_id="app:work-court-evidence:%s" % uuid.uuid4().hex,
            evidence_type_root=transition.required_evidence_type_roots[0],
            evidence_payload=evidence_payload,
            evidence_issuer_root=registry.work_completion_court_root,
            trusted_issuer_roots=(registry.work_completion_court_root,),
            context_roots=(
                view_session.root_id,
                claimant,
                attestation_root,
            ),
        )
    )
    status = (
        project_universal_governed_work_index(
            store, registry, authentication_context=context
        )
        if compact_status
        else project_universal_governed_work_status(
            store, registry, authentication_context=context
        )
    )
    return {
        "passed": passed,
        "event": event,
        "projection": "index" if compact_status else "status",
        "attestation_root": attestation_root,
        "decision_evidence_root": decision_evidence_root,
        "history_root": history_root,
        "revision": revision,
        "status": status,
    }


def project_universal_governed_work_status(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    *,
    authentication_context: object | None = None,
) -> dict[str, object]:
    """Derive queue status and ownership from the work graph itself."""
    items = project_universal_governed_work(
        store, registry, authentication_context=authentication_context
    )
    snapshot = store.snapshot()
    counts = {
        name: 0 for name in (
            "open", "claimed", "blocked", "review", "complete", "cancelled"
        )
    }
    model_counts = _empty_baboom_model_execution_projection()
    model_counts.pop("latest")
    connector_counts = _empty_baboom_connector_execution_projection()
    connector_counts.pop("latest")
    projected = []
    for item in items:
        state = str(item["operational"]["current_state_label"]).casefold()
        if state not in counts:
            raise InvalidCell("governed work has an unknown operational state")
        counts[state] += 1
        model_execution = item.get("model_execution")
        if not isinstance(model_execution, Mapping):
            raise InvalidCell("governed Work model execution is malformed")
        for name in model_counts:
            value = model_execution.get(name, 0)
            if type(value) is not int or value < 0:
                raise InvalidCell("governed Work model execution count is invalid")
            model_counts[name] += value
        connector_execution = item.get("connector_execution")
        if not isinstance(connector_execution, Mapping):
            raise InvalidCell("governed Work connector execution is malformed")
        for name in connector_counts:
            value = connector_execution.get(name, 0)
            if type(value) is not int or value < 0:
                raise InvalidCell("governed Work connector execution count is invalid")
            connector_counts[name] += value
        claimant = _governed_work_claimant_binding(
            snapshot, registry, str(item["root"])
        ) if state in {"claimed", "blocked", "review"} else None
        projected.append({
            **item,
            "claimant_session": claimant[0] if claimant else None,
            "claimant_agent_body": claimant[1] if claimant else None,
            "claim_binding": claimant[2] if claimant else None,
        })
    actionable = counts["open"] + counts["claimed"] + counts["review"]
    return {
        "revision": snapshot.revision,
        "registry": registry.governed_work_registry_root,
        "counts": counts,
        "model_execution": model_counts,
        "connector_execution": connector_counts,
        "total": len(projected),
        "actionable": actionable,
        "blocked": [
            item["root"] for item in projected
            if str(item["operational"]["current_state_label"]).casefold()
            == "blocked"
        ],
        "dry": (
            bool(projected)
            and actionable == 0
            and counts["blocked"] == 0
        ),
        "items": tuple(projected),
    }


def _baboom_work_counts_from_index(
    work_index: Mapping[str, object],
) -> dict[str, int]:
    if not isinstance(work_index, Mapping):
        raise InvalidCell("BABOOM context work index is invalid")
    raw_items = work_index.get("items")
    if not isinstance(raw_items, tuple):
        raise InvalidCell("BABOOM context work items are invalid")
    raw_total = work_index.get("total")
    if type(raw_total) is not int or raw_total < 0:
        raise InvalidCell("BABOOM context work total is invalid")
    if raw_total != len(raw_items):
        raise InvalidCell("BABOOM context work total is inconsistent")
    counts = {name: 0 for name in ("open", "claimed", "blocked", "review")}
    terminal_states = {"complete", "cancelled"}
    for item in raw_items:
        if not isinstance(item, Mapping):
            raise InvalidCell("BABOOM context work item is invalid")
        operational = item.get("operational")
        if not isinstance(operational, Mapping):
            raise InvalidCell("BABOOM context work item state is invalid")
        label = operational.get("current_state_label")
        if type(label) is not str:
            raise InvalidCell("BABOOM context work state is invalid")
        state = label.casefold()
        if state in counts:
            counts[state] += 1
        elif state not in terminal_states:
            raise InvalidCell("BABOOM context work state is unknown")
    return {"total": raw_total, **counts}


_RUNTIME_HANDOFF_READINESS_VERSION = "app:runtime-handoff-readiness:v1"


def project_universal_runtime_handoff_readiness(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    *,
    authentication_context: object | None = None,
    work_index: Mapping[str, object] | None = None,
) -> dict[str, object]:
    """Project bounded, same-revision evidence for a runtime handoff review.

    This lens is deliberately local to the signed machine runtime. It exposes
    aggregate graph activity and the current ownership state, never Work text,
    roots, session identities, device custody, or physical process details.
    Callers that can race graph mutations must hold the application mutation
    lock while obtaining the Work index and this projection.
    """
    if work_index is None:
        work_index = project_universal_governed_work_index(
            store, registry, authentication_context=authentication_context
        )
    snapshot = store.snapshot()
    if (
        not isinstance(work_index, Mapping)
        or type(work_index.get("revision")) is not int
        or work_index["revision"] != snapshot.revision
    ):
        raise InvalidCell("runtime handoff readiness changed during work projection")
    work = _baboom_work_counts_from_index(work_index)

    ownerships = tuple(
        ownership for ownership in verify_ownership_authority(
            snapshot, registry.ownership_protocol
        )
        if ownership.resource_root == registry.application_root
    )
    live_owner_states = {
        registry.ownership_protocol.states["active"]: "active",
        registry.ownership_protocol.states["draining"]: "draining",
    }
    live_owners = tuple(
        ownership for ownership in ownerships
        if ownership.state_root in live_owner_states
    )
    if len(live_owners) > 1:
        raise InvalidCell("application has multiple live runtime owners")
    latest_owner = max(ownerships, key=lambda item: item.generation, default=None)
    owner_state = (
        live_owner_states.get(latest_owner.state_root, "released")
        if latest_owner is not None else "unclaimed"
    )

    active_runtime_sessions: set[str] = set()
    for session_root in list_agent_session_roots(
        snapshot, registry.agent_body.protocol
    ):
        if not session_root.startswith("app:agent-session:runtime:"):
            continue
        session = read_agent_session(
            snapshot,
            registry.agent_body.protocol,
            registry.authorization.protocol,
            session_root,
        )
        if session.state_root == registry.agent_body.protocol.state("active"):
            active_runtime_sessions.add(session_root)

    active_presence_leases = tuple(list_active_runtime_presences(
        snapshot,
        registry.runtime_presence_protocol,
        now=time.time(),
    ))
    for presence in active_presence_leases:
        if presence.agent_session_root not in active_runtime_sessions:
            raise InvalidCell(
                "runtime handoff presence does not hold an active runtime session"
            )

    pending_or_active_work = sum(work[name] for name in (
        "open", "claimed", "blocked", "review",
    ))
    blockers: list[str] = []
    if owner_state == "active":
        blockers.append("one canonical runtime owner is active")
    elif owner_state == "draining":
        blockers.append("one canonical runtime owner is draining")
    if active_runtime_sessions:
        blockers.append("%s active runtime session(s)" % len(active_runtime_sessions))
    if active_presence_leases:
        blockers.append(
            "%s active runtime presence lease(s)" % len(active_presence_leases)
        )
    if pending_or_active_work:
        blockers.append(
            "%s pending or active governed Work item(s)" % pending_or_active_work
        )

    return {
        "cell_native": True,
        "projection": _RUNTIME_HANDOFF_READINESS_VERSION,
        "revision": snapshot.revision,
        "runtime_owner": {
            "state": owner_state,
            "generation": latest_owner.generation if latest_owner else 0,
        },
        "activity": {
            "active_runtime_owners": len(live_owners),
            "active_runtime_sessions": len(active_runtime_sessions),
            "active_runtime_presence_leases": len(active_presence_leases),
            "pending_or_active_work": pending_or_active_work,
            "work": work,
        },
        "founder_review": {
            "required": True,
            "graph_clear": not blockers,
            "blockers": blockers,
        },
    }


def _project_universal_baboom_persona_form(
    work: Mapping[str, int],
    attention: Mapping[str, int | bool],
    activity: Mapping[str, object],
    meeting_notes: Mapping[str, int],
) -> str:
    """Derive one visual form from the same graph revision as the context lens."""
    if work["blocked"] or attention["blocked_obligations"]:
        return "sentinel"
    if meeting_notes["active_sessions"]:
        return "librarian"
    foreground_apps = activity["foreground_apps"]
    if not isinstance(foreground_apps, Mapping):
        raise InvalidCell("BABOOM activity projection is malformed")
    apps = frozenset(foreground_apps)
    if apps & {"Revit", "AutoCAD", "3ds Max", "Rhino"}:
        return "bim-wizard"
    if apps & {"Codex", "VS Code", "Cursor"}:
        return "auditor"
    if apps & {"Browser", "Files"}:
        return "librarian"
    if apps & {"Excel", "PowerPoint", "Word"}:
        return "integrator"
    if work["claimed"]:
        return "runner"
    if attention["active_focus"]:
        return "focus"
    return "steward"


def project_universal_baboom_context(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    *,
    runtime_presence: Mapping[str, object] | None = None,
    authentication_context: object | None = None,
    work_index: Mapping[str, object] | None = None,
) -> dict[str, object]:
    """Return the narrow shared-application lens admitted to BABOOM voice.

    This is intentionally not a Work or Workshop projection. It reduces the
    already-authorised graph to state counts, known category counts, and a
    non-executing suggestion so an untrusted local model cannot receive titles,
    descriptions, values, receipts, identities, or arbitrary entry content.
    """
    if work_index is None:
        work_index = project_universal_governed_work_index(
            store, registry, authentication_context=authentication_context
        )
    work = _baboom_work_counts_from_index(work_index)

    snapshot = store.snapshot()
    entries = list_deliberation_entries(
        snapshot,
        registry.deliberation_protocol,
        registry.workshop_root,
    )
    category_by_root = {
        root: name for name, root in registry.workshop_category_roots.items()
    }
    category_counts = {
        name: 0 for name in registry.workshop_category_roots
    }
    for entry in entries:
        name = category_by_root.get(entry.category_root)
        if name is not None:
            category_counts[name] += 1

    attention = {"open_obligations": 0, "blocked_obligations": 0}
    for obligation in list_obligations(snapshot, registry.attention_protocol):
        if obligation.state_root == registry.attention_protocol.state("open"):
            attention["open_obligations"] += 1
        elif obligation.state_root == registry.attention_protocol.state("blocked"):
            attention["blocked_obligations"] += 1
    attention["active_focus"] = bool(active_focus(
        snapshot,
        registry.attention_protocol,
        session_root=registry.authorization.session.root_id,
    ))

    if work["blocked"]:
        suggestion = "Review blocked governed work."
    elif work["review"]:
        suggestion = "Review governed work awaiting decision."
    elif work["open"]:
        suggestion = "Offer the next approved governed work for claim."
    elif work["claimed"]:
        suggestion = "Observe claimed governed work."
    else:
        suggestion = "No governed work needs action."

    presence = {
        "active_runtime_sessions": 0,
        "baboom_connected": False,
        "baboom_action_capability_active": False,
    }
    active_baboom_devices: set[str] = set()
    active_baboom_bindings: set[tuple[str, str]] = set()
    for lease in list_active_runtime_presences(
        snapshot,
        registry.runtime_presence_protocol,
        now=time.time(),
    ):
        session = read_agent_session(
            snapshot,
            registry.agent_body.protocol,
            registry.authorization.protocol,
            lease.agent_session_root,
        )
        if session.state_root != registry.agent_body.protocol.state("active"):
            continue
        entry = _agent_body_catalog_entry_for_session(snapshot, registry, session)
        if entry.runtime != lease.runtime:
            raise InvalidCell("runtime presence catalog binding drifted")
        custody = read_device_custody(
            snapshot,
            registry.device_custody_protocol,
            lease.device_custody_root,
        )
        if custody.state_root != registry.device_custody_protocol.states["active"]:
            continue
        if lease.runtime == "baboom":
            active_baboom_devices.add(lease.device_custody_root)
            active_baboom_bindings.add(
                (lease.agent_session_root, lease.device_custody_root)
            )
        elif lease.runtime == "baboom-execution":
            presence["baboom_action_capability_active"] = True

    active_activities = tuple(
        activity for activity in list_active_baboom_activities(
            snapshot,
            registry.baboom_activity_protocol,
            now=time.time(),
        )
        if (
            activity.agent_session_root,
            activity.device_custody_root,
        ) in active_baboom_bindings
    )
    foreground_apps: dict[str, int] = {}
    for item in active_activities:
        foreground_apps[item.app] = foreground_apps.get(item.app, 0) + 1
    activity = {
        "active_baboom_devices": len({
            item.device_custody_root for item in active_activities
        }),
        "foreground_apps": dict(sorted(foreground_apps.items())),
    }
    active_meeting_notes = tuple(
        item for item in list_active_baboom_meeting_notes(
            snapshot,
            registry.baboom_meeting_notes_protocol,
            now=time.time(),
        )
        if (
            item.agent_session_root,
            item.device_custody_root,
        ) in active_baboom_bindings
    )
    meeting_notes = {"active_sessions": len(active_meeting_notes)}
    persona_form = _project_universal_baboom_persona_form(
        work, attention, activity, meeting_notes
    )

    device = {
        "enrollment_handoff_available": False,
        "current_runtime_proven": False,
        "active_baboom_devices": len(active_baboom_devices),
        "native_identity_provider_configured": False,
        "issued_cloud_sessions": 0,
        "remote_gateway_serving": False,
    }
    native_auth_members = read_relation(
        snapshot,
        registry.native_authentication_protocol.root_id,
        budget=100_000,
    )
    cloud_session_members = read_relation(
        snapshot,
        registry.cloud_session_protocol.root_id,
        budget=100_000,
    )
    native_identity_provider_configured = any(
        member.role_id
        == registry.native_authentication_protocol.role("client-member")
        for member in native_auth_members
    )
    issued_cloud_sessions = sum(
        member.role_id == registry.cloud_session_protocol.role("session-member")
        for member in cloud_session_members
    )
    if runtime_presence is not None:
        if not isinstance(runtime_presence, Mapping):
            raise InvalidCell("BABOOM runtime presence projection is invalid")
        active_runtime_sessions = runtime_presence.get("active_runtime_sessions")
        baboom_connected = runtime_presence.get("baboom_connected")
        baboom_action_capability_active = runtime_presence.get(
            "baboom_action_capability_active"
        )
        device_enrollment_handoff_available = runtime_presence.get(
            "device_enrollment_handoff_available", False
        )
        current_runtime_device_proven = runtime_presence.get(
            "current_runtime_device_proven", False
        )
        remote_gateway_serving = runtime_presence.get(
            "remote_gateway_serving", False
        )
        if (
            type(active_runtime_sessions) is not int
            or active_runtime_sessions < 0
            or type(baboom_connected) is not bool
            or type(baboom_action_capability_active) is not bool
            or type(device_enrollment_handoff_available) is not bool
            or type(current_runtime_device_proven) is not bool
            or type(remote_gateway_serving) is not bool
        ):
            raise InvalidCell("BABOOM runtime presence values are invalid")
        presence = {
            "active_runtime_sessions": active_runtime_sessions,
            "baboom_connected": baboom_connected,
            "baboom_action_capability_active": baboom_action_capability_active,
        }
        device = {
            "enrollment_handoff_available": device_enrollment_handoff_available,
            "current_runtime_proven": current_runtime_device_proven,
            "active_baboom_devices": len(active_baboom_devices),
            "native_identity_provider_configured": (
                native_identity_provider_configured
            ),
            "issued_cloud_sessions": issued_cloud_sessions,
            "remote_gateway_serving": remote_gateway_serving,
        }
    else:
        device.update({
            "native_identity_provider_configured": (
                native_identity_provider_configured
            ),
            "issued_cloud_sessions": issued_cloud_sessions,
        })

    return {
        "cell_native": True,
        "context_lens": _BABOOM_CONTEXT_LENS_VERSION,
        "revision": snapshot.revision,
        "work": work,
        "workshop": {
            "entry_count": len(entries),
            "category_counts": category_counts,
        },
        "attention": attention,
        "presence": presence,
        "activity": activity,
        "meeting_notes": meeting_notes,
        "device": device,
        "persona_form": persona_form,
        "suggestion": suggestion,
    }


def project_universal_baboom_companion_directive(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    *,
    runtime_presence: Mapping[str, object] | None = None,
    authentication_context: object | None = None,
    work_index: Mapping[str, object] | None = None,
) -> dict[str, object]:
    """Project one content-free desktop directive from the Universal graph.

    This is presentation output, not a second assistant state machine. Work,
    focus, runtime presence, activity, and persona stay in their existing Cell
    relations. The desktop may cache the opaque fingerprint to avoid repeating
    an unchanged message, but it cannot select a different assistant role,
    action, or proactive message on its own.
    """
    context = project_universal_baboom_context(
        store,
        registry,
        runtime_presence=runtime_presence,
        authentication_context=authentication_context,
        work_index=work_index,
    )
    work = context["work"]
    attention = context["attention"]
    activity = context["activity"]
    meeting_notes = context["meeting_notes"]
    if not all(isinstance(value, Mapping) for value in (
        work, attention, activity, meeting_notes,
    )):
        raise InvalidCell("BABOOM companion directive source lens is invalid")

    def count(source: Mapping[str, object], name: str) -> int:
        value = source.get(name)
        if type(value) is not int or value < 0:
            raise InvalidCell("BABOOM companion directive count is invalid")
        return value

    blocked_work = count(work, "blocked")
    review_work = count(work, "review")
    open_work = count(work, "open")
    claimed_work = count(work, "claimed")
    blocked_obligations = count(attention, "blocked_obligations")
    active_devices = count(activity, "active_baboom_devices")
    active_note_sessions = count(meeting_notes, "active_sessions")

    def counted(value: int, singular: str, plural: str) -> str:
        return "%s %s" % (value, singular if value == 1 else plural)

    if blocked_work:
        key, motion, message, action, action_label = (
            "blocked-governed-work",
            "warning",
            counted(
                blocked_work,
                "blocked Work item needs review.",
                "blocked Work items need review.",
            ),
            "review-governed-work",
            "Review Work",
        )
    elif review_work:
        key, motion, message, action, action_label = (
            "review-governed-work",
            "review",
            counted(
                review_work,
                "Work item awaits founder review.",
                "Work items await founder review.",
            ),
            "review-governed-work",
            "Review Work",
        )
    elif blocked_obligations:
        key, motion, message, action, action_label = (
            "blocked-attention",
            "focus",
            counted(
                blocked_obligations,
                "governance hold needs founder attention.",
                "governance holds need founder attention.",
            ),
            "review-founder-attention",
            "Review focus",
        )
    elif open_work:
        key, motion, message, action, action_label = (
            "claimable-governed-work",
            "working",
            counted(
                open_work,
                "Work item is ready to claim.",
                "Work items are ready to claim.",
            ),
            "claim-next-governed-work",
            "Claim Work",
        )
    elif claimed_work:
        key, motion, message, action, action_label = (
            "claimed-governed-work",
            "working",
            counted(
                claimed_work,
                "Work item is in progress.",
                "Work items are in progress.",
            ),
            "",
            "",
        )
    elif active_note_sessions:
        key, motion, message, action, action_label = (
            "meeting-notes-consent",
            "review",
            "Meeting notes are active for %s." % counted(
                active_note_sessions, "session", "sessions"
            ),
            "",
            "",
        )
    elif active_devices > 1:
        key, motion, message, action, action_label = (
            "multi-device-presence",
            "desk-scan",
            "BABOOM is present on %s." % counted(
                active_devices, "device", "devices"
            ),
            "",
            "",
        )
    else:
        key, motion, message, action, action_label = (
            "steady-observation",
            "idle",
            "No governed Work needs attention.",
            "",
            "",
        )

    fingerprint_payload = {
        "key": key,
        "persona_form": context["persona_form"],
        "motion": motion,
        "message": message,
        "action": action,
    }
    fingerprint = "baboom-directive:sha256:" + hashlib.sha256(
        json.dumps(
            fingerprint_payload,
            sort_keys=True,
            separators=(",", ":"),
            ensure_ascii=True,
        ).encode("ascii")
    ).hexdigest()
    return {
        "projection": _BABOOM_COMPANION_DIRECTIVE_VERSION,
        "revision": context["revision"],
        "fingerprint": fingerprint,
        "persona_form": context["persona_form"],
        "motion": motion,
        "message": message,
        "context": "ArchHub | Live activity",
        "compact_message": "" if key == "steady-observation" else message,
        "ttl_seconds": 12.0,
        "action": action,
        "action_label": action_label,
    }


def project_universal_founder_baboom_capability_report(
    store: CellStore,
    registry: UniversalApplicationRegistry,
) -> dict[str, object]:
    """Project released BABOOM adapters and governed routes from one graph revision."""
    snapshot = store.snapshot()

    def provider_entry(provider: object, *, operation: str = "") -> dict[str, object]:
        data_classes = sorted(
            _text(snapshot, root) for root in provider.datatype_roots
        )
        entry: dict[str, object] = {
            "root": provider.root_id,
            "action": _text(snapshot, provider.action_root),
            "location": _text(snapshot, provider.location_root),
            "data_classes": data_classes,
        }
        if operation:
            entry["operation"] = operation
        return entry

    models = sorted(
        (
            provider_entry(read_model_provider(
                snapshot,
                registry.baboom_model_execution_protocol,
                registry.adapter_protocol,
                root,
            ))
            for root in registry.baboom_model_provider_roots.values()
        ),
        key=lambda entry: str(entry["root"]),
    )
    connectors = sorted(
        (
            provider_entry(
                provider := read_connector_provider(
                    snapshot,
                    registry.baboom_connector_execution_protocol,
                    registry.adapter_protocol,
                    root,
                ),
                operation=provider.operation,
            )
            for root in registry.baboom_connector_provider_roots.values()
        ),
        key=lambda entry: str(entry["root"]),
    )
    routes = sorted(
        "%s %s" % (route.method, route.path_template)
        for route in list_cloud_routes(snapshot, registry.cloud_route_protocol)
        if (route.method, route.path_template) in _BABOOM_CAPABILITY_ROUTE_KEYS
    )
    if len(routes) != len(_BABOOM_CAPABILITY_ROUTE_KEYS):
        raise InvalidCell("BABOOM capability route graph is incomplete")
    return {
        "projection": _FOUNDER_BABOOM_CAPABILITY_REPORT_VERSION,
        "revision": snapshot.revision,
        "models": models,
        "connectors": connectors,
        "mcp_broker": project_universal_mcp_broker(store, registry),
        "routes": routes,
    }


def validate_universal_workshop_entry_content(content: object) -> str:
    """Reject content that cannot be persisted in the shared Workshop graph."""
    if type(content) is not str or not content.strip():
        raise InvalidCell("workshop entry content is invalid")
    if len(content.encode("utf-8")) > _WORKSHOP_ENTRY_MAX_BYTES:
        raise InvalidCell("workshop entry content exceeds the size limit")
    if any(ord(character) < 32 and character not in "\t\n\r" for character in content):
        raise InvalidCell("workshop entry content contains control characters")
    if (
        _FOUNDER_WORKSHOP_PROTECTED_TEXT.search(content)
        or _FOUNDER_WORKSHOP_PATH_TEXT.search(content)
    ):
        raise InvalidCell("workshop entry contains protected content")
    return content


def _founder_governed_work_title(value: object) -> tuple[str, bool]:
    """Bound one Work title for a founder-local report without leaking scope."""
    text = " ".join(str(value or "").split())
    if (
        not text
        or _FOUNDER_WORKSHOP_PROTECTED_TEXT.search(text)
        or _FOUNDER_WORKSHOP_PATH_TEXT.search(text)
        or _FOUNDER_ATTENTION_IDENTITY_TEXT.search(text)
    ):
        return _FOUNDER_GOVERNED_WORK_PROTECTED_LABEL, True
    if len(text) > _FOUNDER_GOVERNED_WORK_REPORT_TEXT_LIMIT:
        text = text[:_FOUNDER_GOVERNED_WORK_REPORT_TEXT_LIMIT - 3].rstrip() + "..."
    return text, False


def project_universal_founder_governed_work_report(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    *,
    authentication_context: object | None = None,
) -> dict[str, object]:
    """Project bounded Work detail without exporting the Work graph itself.

    This is a founder-local lens. It exposes neither roots, interfaces,
    assignments, receipt material, descriptions, nor graph references. BABOOM
    can therefore explain active Work without retaining a second task ledger.
    """
    status = project_universal_governed_work_status(
        store, registry, authentication_context=authentication_context
    )
    projected: list[dict[str, object]] = []
    active = 0
    protected = 0
    for item in status["items"]:
        if not isinstance(item, Mapping):
            raise InvalidCell("governed Work report item is invalid")
        operational = item.get("operational")
        interfaces = item.get("interfaces")
        if not isinstance(operational, Mapping) or not isinstance(interfaces, Mapping):
            raise InvalidCell("governed Work report interfaces are invalid")
        state = operational.get("current_state_label")
        if type(state) is not str or state.casefold() not in {
            "open", "claimed", "blocked", "review", "complete", "cancelled",
        }:
            raise InvalidCell("governed Work report state is invalid")
        state = state.casefold()
        if state in {"open", "claimed", "blocked", "review"}:
            active += 1
        title_interface = interfaces.get("title")
        raw_title = (
            title_interface.get("value")
            if isinstance(title_interface, Mapping)
            else None
        )
        title, title_is_protected = _founder_governed_work_title(raw_title)
        protected += int(title_is_protected)
        priority_interface = interfaces.get("priority")
        raw_priority = (
            priority_interface.get("value")
            if isinstance(priority_interface, Mapping)
            else None
        )
        try:
            priority = int(raw_priority)
        except (TypeError, ValueError):
            priority = None
        if priority is not None and not 0 <= priority <= 100:
            priority = None
        model_execution = item.get("model_execution")
        if not isinstance(model_execution, Mapping):
            raise InvalidCell("governed Work report model state is invalid")
        model_state = ""
        if int(model_execution.get("awaiting_approval") or 0) > 0:
            model_state = "awaiting approval"
        elif int(model_execution.get("ready") or 0) > 0:
            model_state = "ready"
        elif int(model_execution.get("failed") or 0) > 0:
            model_state = "failed"
        projected.append({
            "state": state,
            "title": title,
            "priority": priority,
            "model_state": model_state,
        })
    selected = projected[:_FOUNDER_GOVERNED_WORK_REPORT_LIMIT]
    return {
        "projection": "founder-local-governed-work-report",
        "revision": status["revision"],
        "count": len(projected),
        "active": active,
        "protected": protected,
        "truncated": len(projected) > len(selected),
        "items": selected,
    }


def project_universal_founder_model_council_report(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    *,
    authentication_context: object | None = None,
) -> dict[str, object]:
    """Project the bounded model-review council without exposing graph control.

    The report tells the founder which released reviewers have produced usable
    evidence, what Work is visible to the council, and what remains. It is not
    a provider readiness claim, a raw graph export, or authority to advance
    Work. Each included review has already passed the proposal/receipt/provider
    checks used by the sealed model coordination brief.
    """
    status = project_universal_governed_work_status(
        store, registry, authentication_context=authentication_context
    )
    snapshot = store.snapshot()
    revision = status.get("revision")
    if type(revision) is not int or snapshot.revision != revision:
        raise InvalidCell("model council report changed during projection")
    active_work: dict[str, dict[str, object]] = {}
    work_rows: list[tuple[str, dict[str, object]]] = []
    protected = 0
    for item in status["items"]:
        if not isinstance(item, Mapping):
            raise InvalidCell("model council Work item is invalid")
        operational = item.get("operational")
        interfaces = item.get("interfaces")
        root = item.get("root")
        if (
            not isinstance(operational, Mapping)
            or not isinstance(interfaces, Mapping)
            or type(root) is not str
            or not root
        ):
            raise InvalidCell("model council Work projection is invalid")
        state = operational.get("current_state_label")
        if type(state) is not str:
            raise InvalidCell("model council Work state is invalid")
        state = state.casefold()
        if state not in {"open", "claimed", "blocked", "review"}:
            continue
        title_interface = interfaces.get("title")
        title, is_protected = _founder_governed_work_title(
            title_interface.get("value")
            if isinstance(title_interface, Mapping) else None
        )
        protected += int(is_protected)
        priority_interface = interfaces.get("priority")
        try:
            priority = int(
                priority_interface.get("value")
                if isinstance(priority_interface, Mapping) else None
            )
        except (TypeError, ValueError):
            priority = None
        if priority is not None and not 0 <= priority <= 100:
            priority = None
        active_work[root] = {"title": title, "protected": is_protected}
        work_rows.append((root, {
            "state": state,
            "title": title,
            "priority": priority,
            "plan": _baboom_coordination_plan_state(snapshot, item),
            "model_state": _baboom_coordination_model_state(
                item.get("model_execution")
            ),
        }))
    selected = work_rows[:_FOUNDER_GOVERNED_WORK_REPORT_LIMIT]
    selected_rows = [row for _root, row in selected]
    selected_work = {
        root: active_work[root] for root, _row in selected
    }
    peer_reviews, review_count = _baboom_workshop_peer_review_rows(
        store,
        registry,
        snapshot=snapshot,
        active_work=selected_work,
        claimed_work_root="",
    )
    reviews = [{
        key: value for key, value in review.items()
        if key != "claimed_work"
    } for review in peer_reviews]
    admitted = sorted(registry.baboom_model_provider_roots)
    reviewed = sorted({
        str(review["provider"])
        for review in reviews
        if type(review.get("provider")) is str
    })
    pending = [provider for provider in admitted if provider not in reviewed]
    truncated = review_count > len(reviews)
    if truncated:
        state = "review-evidence-truncated"
    elif not reviewed:
        state = "research-not-started"
    elif pending:
        state = "peer-review-in-progress"
    else:
        state = "all-released-providers-reviewed"
    return {
        "projection": "founder-local-model-council-report",
        "revision": revision,
        "state": state,
        "admitted_providers": admitted,
        "reviewed_providers": reviewed,
        "pending_providers": pending,
        "next_provider": pending[0] if pending and not truncated else None,
        "review_count": review_count,
        "review_evidence_truncated": truncated,
        "work_count": len(work_rows),
        "work_protected": protected,
        "work_truncated": len(work_rows) > len(selected_rows),
        "work": selected_rows,
        "reviews": reviews,
        "review_policy": (
            "Provider reviews are bounded, untrusted evidence. Validate them "
            "before a separate founder-approved action."
        ),
    }


def project_universal_founder_baboom_steward_briefing(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    *,
    authentication_context: object | None = None,
) -> dict[str, object]:
    """Return BABOOM's complete founder-local proactive briefing from Cells.

    The caller must hold the application mutation lock while invoking this
    function. That keeps every nested projection on the same graph revision;
    the desktop Steward only transports and renders the resulting lens.
    """
    context = project_universal_baboom_context(
        store, registry, authentication_context=authentication_context
    )
    governed_work = project_universal_founder_governed_work_report(
        store, registry, authentication_context=authentication_context
    )
    workshop = project_universal_founder_workshop_report(store, registry)
    attention = project_universal_founder_attention_briefing(store, registry)
    revision = context["revision"]
    if any(
        projection.get("revision") != revision
        for projection in (governed_work, workshop, attention)
    ):
        raise InvalidCell("BABOOM Steward briefing changed during projection")
    return {
        "projection": _FOUNDER_STEWARD_BRIEFING_VERSION,
        "revision": revision,
        "context": context,
        "governed_work": governed_work,
        "workshop": workshop,
        "attention": attention,
    }


def project_universal_founder_workshop_report(
    store: CellStore,
    registry: UniversalApplicationRegistry,
) -> dict[str, object]:
    """Project a bounded, founder-local Workshop view from deliberation Cells.

    Unlike the content-free BABOOM context lens, this explicit report is for a
    founder-local surface. It intentionally excludes graph identity and routing
    material so the report cannot become a copied Workshop authority or a
    prompt-ready export of the deliberation graph.
    """
    snapshot = store.snapshot()
    entries = list_deliberation_entries(
        snapshot,
        registry.deliberation_protocol,
        registry.workshop_root,
    )
    categories = {
        root: name for name, root in registry.workshop_category_roots.items()
    }
    selected = entries[-_FOUNDER_WORKSHOP_REPORT_LIMIT:]
    projected: list[dict[str, object]] = []
    protected = 0
    for entry in selected:
        category = categories.get(entry.category_root)
        if category is None:
            raise InvalidCell("Workshop entry category is not released")
        text = " ".join(entry.content.split())
        is_protected = bool(
            not text or _FOUNDER_WORKSHOP_PROTECTED_TEXT.search(text)
        )
        if is_protected:
            text = "[protected Workshop entry]"
            protected += 1
        else:
            text = _FOUNDER_WORKSHOP_PATH_TEXT.sub("[path]", text)
            if len(text) > _FOUNDER_WORKSHOP_REPORT_TEXT_LIMIT:
                text = text[:_FOUNDER_WORKSHOP_REPORT_TEXT_LIMIT - 3].rstrip() + "..."
        projected.append({
            "sequence": entry.sequence,
            "kind": category,
            "text": text,
            "created_at": entry.created_at,
            "protected": is_protected,
        })
    return {
        "projection": "founder-local-workshop-report",
        "revision": snapshot.revision,
        "count": len(entries),
        "protected": protected,
        "truncated": len(entries) > len(selected),
        "entries": projected,
    }


def _founder_device_custody_ref(custody_root: str) -> str:
    """Derive a stable, non-graph selector for a founder-local device view."""
    if not custody_root.startswith("device-custody:sha256:"):
        raise InvalidCell("device custody root is invalid")
    digest = hashlib.sha256(
        ("archhub:founder-device-custody-ref:v1\\0" + custody_root).encode(
            "ascii"
        )
    ).hexdigest()
    return "device_" + digest[:24]


def _founder_device_custody_records(
    snapshot: Snapshot,
    registry: UniversalApplicationRegistry,
    *,
    now: float,
) -> tuple[tuple[str, dict[str, object]], ...]:
    """Read custody state as bounded founder-safe rows, never graph IDs."""
    active_runtime_by_custody: dict[str, set[str]] = {}
    for lease in list_active_runtime_presences(
        snapshot, registry.runtime_presence_protocol, now=now
    ):
        session = read_agent_session(
            snapshot,
            registry.agent_body.protocol,
            registry.authorization.protocol,
            lease.agent_session_root,
        )
        if session.state_root != registry.agent_body.protocol.state("active"):
            continue
        entry = _agent_body_catalog_entry_for_session(snapshot, registry, session)
        if entry.runtime != lease.runtime:
            raise InvalidCell("runtime presence catalog binding drifted")
        custody = read_device_custody(
            snapshot, registry.device_custody_protocol, lease.device_custody_root
        )
        if custody.state_root != registry.device_custody_protocol.states["active"]:
            continue
        active_runtime_by_custody.setdefault(custody.root_id, set()).add(
            lease.runtime
        )

    baboom_entry = _agent_body_catalog_entry_for_runtime(
        snapshot, registry, "baboom"
    )
    # Presence and receipt-bound action are profiles of the same BABOOM body.
    # A device admitted to either profile is BABOOM-bound; it is not a second
    # assistant or device identity.
    baboom_custody_roots = frozenset(
        custody_root
        for entry in list_agent_body_catalog_entries(
            snapshot, registry.agent_body_catalog.protocol
        )
        if entry.body_root == baboom_entry.body_root
        for custody_root in entry.device_custody_roots
    )
    records: list[tuple[str, dict[str, object]]] = []
    seen_refs: set[str] = set()
    for custody_root in list_device_custody_roots(
        snapshot, registry.device_custody_protocol
    ):
        custody = read_device_custody(
            snapshot, registry.device_custody_protocol, custody_root
        )
        if custody.state_root == registry.device_custody_protocol.states["active"]:
            state = "active"
        elif custody.state_root == registry.device_custody_protocol.states["revoked"]:
            state = "revoked"
        else:
            raise InvalidCell("device custody state is not released")
        device_ref = _founder_device_custody_ref(custody.root_id)
        if device_ref in seen_refs:
            raise InvalidCell("founder device custody selector collision")
        seen_refs.add(device_ref)
        active_runtimes = active_runtime_by_custody.get(custody.root_id, set())
        records.append((custody.root_id, {
            "device_ref": device_ref,
            "label": "Device " + device_ref[-8:].upper(),
            "state": state,
            "hardware_backed": _text(
                snapshot, custody.hardware_backed_root
            ) == "true",
            "baboom_bound": custody.root_id in baboom_custody_roots,
            "runtime_present": bool(active_runtimes),
            "baboom_present": "baboom" in active_runtimes,
        }))
    return tuple(records)


def project_universal_founder_device_custody_report(
    store: CellStore,
    registry: UniversalApplicationRegistry,
) -> dict[str, object]:
    """Project custody posture for a founder-local device management surface.

    The projection does not expose device public keys, thumbprints, custody
    roots, Agent Session roots, timestamps, or revocation text. `device_ref`
    is an opaque selector accepted only by the paired revocation operation.
    """
    snapshot = store.snapshot()
    records = _founder_device_custody_records(
        snapshot, registry, now=time.time()
    )
    rows = [row for _custody_root, row in records]
    rows.sort(key=lambda row: (
        row["state"] != "active",
        not row["baboom_present"],
        not row["runtime_present"],
        row["device_ref"],
    ))
    selected = rows[:_FOUNDER_DEVICE_CUSTODY_REPORT_LIMIT]
    return {
        "projection": "founder-local-device-custody-report",
        "revision": snapshot.revision,
        "registered": len(rows),
        "active": sum(row["state"] == "active" for row in rows),
        "revoked": sum(row["state"] == "revoked" for row in rows),
        "hardware_backed": sum(
            row["hardware_backed"] is True for row in rows
        ),
        "reported": len(selected),
        "truncated": len(rows) > len(selected),
        "devices": selected,
    }


def revoke_universal_founder_device_custody(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    *,
    device_ref: object,
    reason_code: object,
    authentication_context: object | None = None,
) -> tuple[str, int]:
    """Revoke one founder-selected device custody through graph authority.

    Free-form text is intentionally not persisted here. The revoked custody
    Cell remains the durable authority fact, while the canonical reason code
    avoids using a sensitive diagnostic note as a cross-device control record.
    """
    if (
        type(device_ref) is not str
        or not _FOUNDER_DEVICE_CUSTODY_REF.fullmatch(device_ref)
        or type(reason_code) is not str
        or reason_code not in _FOUNDER_DEVICE_CUSTODY_REVOCATION_CODES
    ):
        raise InvalidCell("founder device custody revocation request is invalid")
    authority = registry.authorization
    context = _active_authentication_context(authority, authentication_context)
    snapshot = store.snapshot()
    identity = authority.broker.resolve(context)
    if identity.subject_root != authority.subject_root:
        raise AuthorizationDenied("only the founder may revoke device custody")
    _require_application_authorization(
        snapshot,
        registry,
        "manage-policy",
        registry.application_root,
        authentication_context=context,
    )
    candidates = [
        custody_root
        for custody_root, row in _founder_device_custody_records(
            snapshot, registry, now=time.time()
        )
        if row["device_ref"] == device_ref
    ]
    if len(candidates) != 1:
        raise AuthorizationDenied("founder device custody selector is unavailable")
    revision = revoke_device_custody(
        store,
        registry.device_custody_protocol,
        candidates[0],
        reason=_FOUNDER_DEVICE_CUSTODY_REVOCATION_PREFIX + reason_code,
    )
    return device_ref, revision


def _founder_attention_label(value: str) -> tuple[str, bool]:
    """Return bounded founder-local explanation text without a graph identity."""
    label = " ".join(value.split())
    if (
        not label
        or _FOUNDER_WORKSHOP_PROTECTED_TEXT.search(label)
        or _FOUNDER_WORKSHOP_PATH_TEXT.search(label)
        or _FOUNDER_ATTENTION_IDENTITY_TEXT.search(label)
    ):
        return _FOUNDER_ATTENTION_PROTECTED_LABEL, True
    if len(label) > _FOUNDER_ATTENTION_BRIEFING_TEXT_LIMIT:
        label = label[:_FOUNDER_ATTENTION_BRIEFING_TEXT_LIMIT - 3].rstrip() + "..."
    return label, False


def project_universal_founder_attention_briefing(
    store: CellStore,
    registry: UniversalApplicationRegistry,
) -> dict[str, object]:
    """Project why the founder's current graph focus matters.

    This is a founder-local read lens over existing Focus and Core Value
    Obligation Cells. It is intentionally not a canvas export: no Cell root,
    actor, scope, consent, dependency, evidence, or general graph text leaves
    this projection. BABOOM therefore explains current priorities without
    acquiring a copied attention authority or prompt-ready graph context.
    """
    snapshot = store.snapshot()
    focus = active_focus(
        snapshot,
        registry.attention_protocol,
        session_root=registry.authorization.session.root_id,
    )
    focus_reasons = {
        _FOCUS_REASON_INITIAL: "Initial application focus",
        _FOCUS_REASON_GESTURE: "Direct user manipulation",
        _FOCUS_REASON_COMPOSITION: "Composition changed",
        _FOCUS_REASON_SCOPE: "Visible scope changed",
    }
    if focus is None:
        focus_projection: dict[str, object] = {
            "active": False,
            "label": "No active ArchHub focus",
            "reasons": [],
        }
    else:
        reasons = []
        for reason_root in focus.reason_roots:
            reason = focus_reasons.get(reason_root)
            if reason is not None:
                reasons.append(reason)
        focus_projection = {
            "active": True,
            "label": "Current ArchHub focus",
            "reasons": list(dict.fromkeys(reasons)) or ["Graph focus updated"],
        }

    priority_labels = dict(_ATTENTION_PRIORITY_SPECS)
    priority_order = {
        root: index for index, (root, _label) in enumerate(
            _ATTENTION_PRIORITY_SPECS
        )
    }
    open_state = registry.attention_protocol.state("open")
    blocked_state = registry.attention_protocol.state("blocked")
    state_labels = {
        open_state: "Open",
        blocked_state: "Blocked",
    }
    obligations = {
        item.root_id: item
        for item in list_obligations(snapshot, registry.attention_protocol)
    }
    if not set(registry.core_value_obligation_roots).issubset(obligations):
        raise InvalidCell("application Core Value obligations are incomplete")
    open_count = sum(
        item.state_root == open_state for item in obligations.values()
    )
    blocked_count = sum(
        item.state_root == blocked_state for item in obligations.values()
    )

    candidates: list[tuple[int, dict[str, object]]] = []
    for root in registry.core_value_obligation_roots:
        obligation = obligations[root]
        if obligation.state_root not in state_labels:
            continue
        priority = priority_labels.get(obligation.priority_root)
        if priority is None or obligation.priority_root not in priority_order:
            raise InvalidCell("Core Value obligation priority is not released")
        gap_members = read_relation(snapshot, obligation.subject_root, budget=64)
        reason_root = _one_for_role(
            gap_members, registry.core_values.roles["why"]
        )
        if reason_root is None:
            raise InvalidCell("Core Value obligation subject has no reason")
        label, protected = _founder_attention_label(_text(snapshot, reason_root))
        candidates.append((priority_order[obligation.priority_root], {
            "priority": priority,
            "state": state_labels[obligation.state_root],
            "label": label,
            "protected": protected,
        }))
    candidates.sort(key=lambda item: item[0])
    selected = candidates[:_FOUNDER_ATTENTION_BRIEFING_LIMIT]
    projected = [item for _priority, item in selected]
    return {
        "projection": "founder-local-attention-briefing",
        "revision": snapshot.revision,
        "focus": focus_projection,
        "open_obligations": open_count,
        "blocked_obligations": blocked_count,
        "protected": sum(item["protected"] is True for item in projected),
        "truncated": len(candidates) > len(selected),
        "obligations": projected,
    }


def read_universal_baboom_current_claimed_work(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    *,
    agent_session_root: str,
    authentication_context: object | None = None,
) -> tuple[Mapping[str, object] | None, int]:
    """Read the exact claimed Work for BABOOM's execution session.

    The assignment remains a relationship in the governed Work graph. This
    bounded projection exists so a restarted BABOOM body can re-derive its
    current claim instead of treating process memory as task authority.
    """
    snapshot = store.snapshot()
    session = _runtime_agent_session(snapshot, registry, agent_session_root)
    entry = _agent_body_catalog_entry_for_session(snapshot, registry, session)
    if entry.runtime != "baboom-execution":
        raise AuthorizationDenied(
            "current BABOOM Work requires the receipt-bound action capability"
        )
    view_session, context = _view_session_for_context(
        registry, authentication_context
    )
    identity = registry.authorization.broker.resolve(context)
    if (
        session.subject_root != identity.subject_root
        or view_session.subject_root != session.subject_root
    ):
        raise AuthorizationDenied("runtime Agent Session view scope drifted")
    status = project_universal_governed_work_status(
        store, registry, authentication_context=context
    )
    owned = [
        item for item in status["items"]
        if item.get("claimant_session") == session.root_id
        and str(item["operational"]["current_state_label"]).casefold()
        == "claimed"
    ]
    if len(owned) > 1:
        raise InvalidCell(
            "Agent Session owns multiple active governed-work assignments"
        )
    if not owned:
        return None, int(status["revision"])
    work = owned[0]
    interfaces = work.get("interfaces")
    title = (interfaces.get("title") or {}).get("value") if isinstance(
        interfaces, Mapping
    ) else None
    root = work.get("root")
    if type(root) is not str or type(title) is not str or not title.strip():
        raise InvalidCell("current BABOOM Work projection is malformed")
    return {
        "root": root,
        "title": _bounded_baboom_plan_text(title, "title", 512),
    }, int(status["revision"])


def claim_next_universal_governed_work(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    *,
    agent_session_root: str,
    compliance_observation_root: str | None = None,
    authentication_context: object | None = None,
) -> dict[str, object]:
    """Atomically choose and claim the graph's highest-priority open work."""
    require_universal_runtime_compliance(
        store,
        registry,
        agent_session_root=agent_session_root,
        compliance_observation_root=compliance_observation_root,
        authentication_context=authentication_context,
    )
    status = project_universal_governed_work_status(
        store, registry, authentication_context=authentication_context
    )
    owned = [
        item for item in status["items"]
        if item.get("claimant_session") == agent_session_root
        and str(item["operational"]["current_state_label"]).casefold()
        == "claimed"
    ]
    if len(owned) > 1:
        raise InvalidCell(
            "Agent Session owns multiple active governed-work assignments"
        )
    if owned:
        return {
            "claimed": True,
            "reused": True,
            "work": owned[0],
            "history_root": "",
            "revision": status["revision"],
            "status": status,
        }
    candidates = []
    claim_session = _runtime_agent_session(
        store.snapshot(), registry, agent_session_root
    )
    for item in status["items"]:
        state = str(item["operational"]["current_state_label"]).casefold()
        if state != "open":
            continue
        if not _governed_work_handoff_claim_is_admitted(
            store.snapshot(), registry, str(item["root"]), claim_session
        ):
            continue
        try:
            priority = int(str(item["interfaces"]["priority"]["value"]))
        except (KeyError, TypeError, ValueError) as exc:
            raise InvalidCell(
                "governed work priority is not an integer"
            ) from exc
        candidates.append((
            -priority,
            int(item["queue_index"]),
            str(item["root"]),
        ))
    if not candidates:
        return {"claimed": False, "work": None, "status": status}
    _, _, work_root = min(candidates)
    history_root, revision = transition_universal_governed_work(
        store,
        registry,
        work_root,
        "claim",
        agent_session_root=agent_session_root,
        authentication_context=authentication_context,
    )
    changed = project_universal_governed_work_status(
        store, registry, authentication_context=authentication_context
    )
    work = next(
        item for item in changed["items"] if item["root"] == work_root
    )
    return {
        "claimed": True,
        "reused": False,
        "work": work,
        "history_root": history_root,
        "revision": revision,
        "status": changed,
    }


def claim_universal_governed_work(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    *,
    agent_session_root: str,
    work_root: str,
    compliance_observation_root: str | None = None,
    authentication_context: object | None = None,
) -> dict[str, object]:
    """Claim one exact open Work without selecting another queue item."""
    if type(work_root) is not str or not work_root:
        raise InvalidCell("governed Work claim target is invalid")
    require_universal_runtime_compliance(
        store,
        registry,
        agent_session_root=agent_session_root,
        compliance_observation_root=compliance_observation_root,
        authentication_context=authentication_context,
    )
    status = project_universal_governed_work_status(
        store, registry, authentication_context=authentication_context
    )
    owned = [
        item for item in status["items"]
        if item.get("claimant_session") == agent_session_root
        and str(item["operational"]["current_state_label"]).casefold()
        == "claimed"
    ]
    if len(owned) > 1:
        raise InvalidCell(
            "Agent Session owns multiple active governed-work assignments"
        )
    if owned:
        if owned[0]["root"] != work_root:
            raise AuthorizationDenied(
                "Agent Session already owns another governed-work assignment"
            )
        return {
            "claimed": True,
            "reused": True,
            "work": owned[0],
            "history_root": "",
            "revision": status["revision"],
            "status": status,
        }
    target = next(
        (item for item in status["items"] if item["root"] == work_root),
        None,
    )
    if target is None:
        raise InvalidCell("governed Work claim target is not registered")
    if (
        str(target["operational"]["current_state_label"]).casefold()
        != "open"
    ):
        raise InvalidCell("governed Work claim target is not open")
    history_root, revision = transition_universal_governed_work(
        store,
        registry,
        work_root,
        "claim",
        agent_session_root=agent_session_root,
        authentication_context=authentication_context,
    )
    changed = project_universal_governed_work_status(
        store, registry, authentication_context=authentication_context
    )
    work = next(
        item for item in changed["items"] if item["root"] == work_root
    )
    return {
        "claimed": True,
        "reused": False,
        "work": work,
        "history_root": history_root,
        "revision": revision,
        "status": changed,
    }


def project_universal_value_graph(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    root_id: str,
    *,
    authentication_context: object | None = None,
) -> object:
    """Project one visible value through its registered open graph."""
    if type(root_id) is not str or not root_id:
        raise InvalidCell("value-graph projection root is invalid")
    snapshot = store.snapshot()
    view_session, context = _view_session_for_context(
        registry, authentication_context
    )
    visible_roots, _, _ = _session_canvas_roots(
        snapshot, registry, view_session
    )
    authority_root = root_id if root_id in visible_roots else None
    if authority_root is None:
        for candidate_root in visible_roots:
            assembly = _instance_projection(snapshot, registry, candidate_root)
            if assembly is None:
                continue
            if any(
                interface["target"] == root_id
                for interface in assembly["interfaces"]
            ):
                authority_root = candidate_root
                break
    if authority_root is None:
        raise InvalidCell("value graph is outside the active canvas")
    _require_application_authorization(
        snapshot,
        registry,
        "read",
        authority_root,
        authentication_context=context,
    )
    _require_resource_audience_authority(
        snapshot, registry, view_session.subject_root, (authority_root,)
    )
    return read_value_graph(
        snapshot, registry.value_graph_protocol, root_id
    )


@with_relation_projection_scope
def project_universal_machine_canvas(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    *,
    authentication_context: object | None = None,
    node_limit: int = 96,
    wire_limit: int = 192,
    catalog_limit: int = 64,
    property_limit: int = 64,
) -> dict[str, object]:
    """Return a bounded machine canvas summary without the browser inspector."""
    def compact_text(value: object, limit: int = 96) -> str:
        text = str(value)
        if len(text) <= limit:
            return text
        return text[:max(0, limit - 1)] + "..."

    snapshot = store.snapshot()
    authority = registry.authorization
    authority_snapshot = verify_relationship_authority_snapshot(
        snapshot,
        authority.identity_protocol,
        authority.relationship_broker,
        now=time.time(),
    )
    view_session, context = _view_session_for_context(
        registry, authentication_context
    )
    (
        visible_roots,
        relation_roots,
        property_scopes,
        scope_trail,
    ) = _session_machine_canvas_roots(
        snapshot,
        registry,
        view_session,
        authority_snapshot=authority_snapshot,
    )
    require_authorizations(
        snapshot,
        authority.protocol,
        authority.policy_root,
        authority.broker,
        context,
        (
            AuthorizationRequest(
                action_root=authority.protocol.actions["read"],
                object_root=authority.shell_scope_root,
                resource_lineage_roots=(authority.scope_root,),
                purpose_root=authority.purpose_root,
                classification_root=authority.classification_root,
                audience_root=authority.audience_root,
                now=authority_snapshot.evaluated_at,
            ),
            AuthorizationRequest(
                action_root=authority.protocol.actions["inspect"],
                object_root=view_session.root_id,
                resource_lineage_roots=(
                    authority.personal_view_scope_root,
                    authority.scope_root,
                ),
                purpose_root=authority.purpose_root,
                classification_root=authority.classification_root,
                audience_root=authority.audience_root,
                now=authority_snapshot.evaluated_at,
            ),
        ),
        resolver_state=authority_snapshot,
    )
    selection_members = read_relation(
        snapshot, view_session.selection_state_root, budget=100_000
    )
    selected_roots = frozenset(
        member.participant_id
        for member in selection_members
        if member.role_id == registry.roles["selected"]
    )
    visible_limited = tuple(visible_roots[:max(0, node_limit)])
    node_index: dict[str, dict[str, object]] = {}
    relation_member_cache: dict[str, tuple] = {}
    interface_owner: dict[str, str] = {}
    interface_role = registry.assembly_protocol.role("interface")
    nodes: list[dict[str, object]] = []
    for index, root_id in enumerate(visible_limited):
        cell = snapshot.cells[root_id]
        relation_members = _relation_members_or_none(snapshot, root_id) or ()
        relation_member_cache[root_id] = tuple(relation_members)
        for member in relation_members:
            if member.role_id == interface_role:
                interface_owner[member.participant_id] = root_id
        node = {
            "id": root_id,
            "label": compact_text(_humanize_root_id(root_id)),
            "x": 60.0 + (index % 5) * 244.0,
            "y": 92.0 + (index // 5) * 174.0,
            "selected": root_id in selected_roots,
            "openable": bool(relation_members),
            "physical": {
                "linked": bool(cell.link0 or cell.link1),
                "atom_bytes": len(cell.atom),
            },
            "ports": [],
            "member_count": len(relation_members),
            "connection_count": 0,
        }
        nodes.append(node)
        node_index[root_id] = node

    wires: list[dict[str, object]] = []
    visible_set = set(node_index)
    port_index: dict[tuple[str, str], dict[str, object]] = {}

    def owner_for(participant_id: str) -> str | None:
        if participant_id in visible_set:
            return participant_id
        return interface_owner.get(participant_id)

    def interface_for(member, owner: str) -> str:
        if member.participant_id == owner:
            return member.incidence_id
        return member.participant_id

    def ensure_port(owner: str, incidence_id: str, side: str) -> None:
        if owner not in node_index:
            return
        key = (owner, incidence_id)
        if key in port_index:
            return
        port = {
            "id": incidence_id,
            "name": side,
            "mode": "connection",
            "editable": False,
            "side": side,
            "connectable": True,
        }
        port_index[key] = port
        node_index[owner]["ports"].append(port)

    for relation_root in relation_roots:
        if len(wires) >= wire_limit:
            break
        members = read_relation(snapshot, relation_root, budget=256)
        source_members = tuple(
            member for member in members
            if member.role_id == registry.roles["source"]
        )
        target_members = tuple(
            member for member in members
            if member.role_id == registry.roles["target"]
        )
        if len(source_members) != 1 or len(target_members) != 1:
            continue
        source_member = source_members[0]
        target_member = target_members[0]
        source = owner_for(source_member.participant_id)
        target = owner_for(target_member.participant_id)
        if source not in visible_set or target not in visible_set:
            continue
        source_interface = interface_for(source_member, source)
        target_interface = interface_for(target_member, target)
        ensure_port(source, source_interface, "source")
        ensure_port(target, target_interface, "target")
        authorities = [
            member.participant_id
            for member in members if member.role_id == registry.roles["authority"]
        ][:4]
        wires.append({
            "id": relation_root,
            "source": source,
            "target": target,
            "source_interface": source_interface,
            "target_interface": target_interface,
            "source_incidence": source_member.incidence_id,
            "target_incidence": target_member.incidence_id,
            "authority_roots": authorities,
            "directed": True,
            "nary": False,
        })

    for wire in wires:
        for node_id in (wire["source"], wire["target"]):
            node = node_index[str(node_id)]
            node["connection_count"] = int(node["connection_count"]) + 1

    viewport = {
        name: float(_text(snapshot, reference.value_root))
        for name, reference in view_session.viewport_properties.items()
    }
    catalog_sections = _machine_node_library_sections(
        snapshot,
        registry.roles,
        library_root=registry.library_root,
        limit=max(0, catalog_limit),
    )
    return {
        "canvas_root": registry.canvas_root,
        "application_root": registry.application_root,
        "revision": snapshot.revision,
        "scope": {
            "trail": list(scope_trail),
            "visible_count": len(visible_roots),
            "relation_count": len(relation_roots),
            "property_scope_count": len(property_scopes),
            "truncated": (
                len(visible_roots) > node_limit
                or len(relation_roots) > wire_limit
            ),
        },
        "nodes": nodes,
        "wires": wires,
        "catalog": [
            {
                "id": section["id"],
                "label": compact_text(section["label"], 64),
                "title": compact_text(section["label"], 64),
            }
            for section in catalog_sections
        ],
        "properties": [],
        "selection": list(selected_roots)[:max(0, property_limit)],
        "inspector": {
            "selected": next(iter(selected_roots), None),
            "lens": "machine-summary",
        },
        "viewport": viewport,
        "machine_projection": {
            "kind": "bounded-canvas-summary",
            "node_limit": node_limit,
            "wire_limit": wire_limit,
            "catalog_limit": catalog_limit,
            "property_limit": property_limit,
            "node_count": len(visible_roots),
            "wire_count": len(relation_roots),
        },
    }


def instantiate_universal_relation_definition(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    definition_root: str,
    bindings: tuple[tuple[str, str], ...],
    *,
    x: float,
    y: float,
    additional_create: Iterable[Cell] = (),
    additional_replace: Iterable[Cell] = (),
    mutation_route: str = "/api/universal/instantiate",
    authentication_context: object | None = None,
) -> tuple[str, int]:
    """Atomically publish one contract-valid, relation-backed WIP assembly."""
    if not math.isfinite(x) or not math.isfinite(y):
        raise InvalidCell("assembly position must be finite")
    if not bindings:
        raise InvalidCell("relation-backed assembly requires explicit bindings")
    snapshot = store.dense_snapshot()
    view_session, context = _view_session_for_context(
        registry, authentication_context
    )
    visible_roots, relation_roots, _ = _session_canvas_roots(
        snapshot, registry, view_session
    )
    instance_count = sum(
        _instance_projection(snapshot, registry, root_id) is not None
        for root_id in visible_roots
    )
    _authorize(
        snapshot,
        registry,
        "catalog.instantiate",
        object_root=definition_root,
        authentication_context=context,
        definition_root=definition_root,
        resource_usage={
            "max-instances": (instance_count, 1),
            "max-relations": (len(relation_roots), 1),
        },
    )
    definition = read_definition(
        snapshot, registry.assembly_protocol, definition_root
    )
    authority = resolve_relation_contract_authority(
        snapshot,
        capability_roots=definition.capability_roots,
        rule_roots=definition.rule_roots,
        budget=100_000,
    )
    constraints = {
        item.participant_role: item
        for item in authority.contract.constraints
    }
    visible = set(visible_roots)
    for role_root, participant_root in bindings:
        constraint = constraints.get(role_root)
        if constraint is None:
            raise InvalidCell("relation binding uses an undeclared role")
        if constraint.fixed_participant_root is not None:
            if participant_root != constraint.fixed_participant_root:
                raise InvalidCell("relation binding violates its fixed participant")
        elif participant_root not in visible:
            raise InvalidCell(
                "relation binding participant is outside the authorized canvas"
            )

    token = uuid.uuid4().hex
    candidate = compose_validated_relation(
        snapshot,
        authority.protocol,
        authority.contract.root_id,
        bindings,
        relation_id="app:wip-relation:%s" % token,
        budget=100_000,
    )
    composed = compose_relation_backed_catalog_instance(
        snapshot,
        registry.assembly_protocol,
        registry.standard_library.catalog_root,
        definition_root,
        candidate,
        token=token,
        budget=100_000,
    )
    instance = composed.instance
    property_specs = (
        ("title", _text(snapshot, definition.name_root), False),
        ("position_x", x, False),
        ("position_y", y, False),
        ("color", _DEFAULT_NODE_PRESENTATION_COLOR, False),
        ("definition", definition_root, True),
        ("version", _text(snapshot, definition.version_root), True),
    )
    property_refs: list[PropertyRef] = []
    property_cells: list[Cell] = []
    for key, value, read_only in property_specs:
        reference, cells = _compose_property(
            registry,
            instance.root_id,
            key,
            value,
            read_only=read_only,
        )
        property_refs.append(reference)
        property_cells.extend(cells)

    revision = _commit_atomic_visible_wip_resource(
        store,
        registry,
        snapshot,
        view_session,
        context,
        route=mutation_route,
        command_name="catalog.instantiate",
        authorization_scope_root=definition_root,
        resource_root=instance.root_id,
        resource_cells=tuple(composed.cells),
        property_refs=tuple(property_refs),
        property_cells=tuple(property_cells),
        additional_create=tuple(additional_create),
        additional_replace=tuple(additional_replace),
    )
    return instance.root_id, revision


def instantiate_universal_relation_composer(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    definition_root: str,
    *,
    mutation_route: str = "/api/universal/interaction",
    authentication_context: object | None = None,
) -> tuple[str, int]:
    """Create only from the authoritative session draft and clear it atomically."""
    snapshot = store.snapshot()
    view_session, context = _view_session_for_context(
        registry, authentication_context
    )
    composer = _project_current_relation_composer(
        store, registry, view_session, definition_root
    )
    snapshot = store.snapshot()
    draft = read_relation_composer_draft(
        snapshot, registry.relation_composer_protocol, view_session.root_id
    )
    if (
        draft is None
        or draft.definition_root != definition_root
        or composer["draft"] != draft.root_id
    ):
        raise InvalidCell("relation creation requires a committed graph draft")
    if not composer["complete"]:
        raise InvalidCell("relation-composer draft is incomplete")
    if composer["x"] is None or composer["y"] is None:
        raise InvalidCell("relation-composer placement is not committed")
    bindings = tuple(
        (str(binding["role"]), str(binding["participant"]))
        for binding in composer["bindings"]
    )
    reset = prepare_relation_composer_draft(
        snapshot,
        registry.relation_composer_protocol,
        view_session.root_id,
        None,
        (),
    )
    return instantiate_universal_relation_definition(
        store,
        registry,
        definition_root,
        bindings,
        x=float(composer["x"]),
        y=float(composer["y"]),
        additional_create=reset.create,
        additional_replace=reset.replace,
        mutation_route=mutation_route,
        authentication_context=context,
    )


def edit_universal_lifecycle_content(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    resource_root: str,
    interface_root: str,
    value: str,
    *,
    base_revision_root: str,
    authentication_context: object | None = None,
) -> tuple[str, int]:
    """Append immutable WIP through the assembly's declared content port."""
    snapshot = store.snapshot()
    view_session, context = _view_session_for_context(
        registry, authentication_context
    )
    visible_roots, _, _ = _session_canvas_roots(
        snapshot, registry, view_session
    )
    if resource_root not in visible_roots:
        raise InvalidCell("lifecycle resource is outside the active canvas")
    lifecycle = registry.standard_library.lifecycle_protocol
    instance = read_lifecycle_instance(
        snapshot,
        registry.assembly_protocol,
        lifecycle,
        resource_root,
    )
    if interface_root != instance.content_interface_root:
        raise InvalidCell("interface is not the lifecycle content port")
    encoded = value.encode("utf-8")
    _authorize(
        snapshot,
        registry,
        "catalog.configure",
        object_root=resource_root,
        interface_root=interface_root,
        authentication_context=context,
        resource_usage={"max-atom-bytes": (0, len(encoded))},
    )
    actor_root = registry.authorization.broker.resolve(context).subject_root
    revision_root = append_wip_revision(
        store,
        registry.assembly_protocol,
        lifecycle,
        resource_root,
        content=encoded,
        actor_root=actor_root,
        base_revision_root=base_revision_root,
        reason="edit through lifecycle content interface",
    )
    return revision_root, store.revision


def merge_universal_lifecycle_content(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    resource_root: str,
    interface_root: str,
    value: str,
    *,
    parent_revision_roots: Iterable[str],
    authentication_context: object | None = None,
) -> tuple[str, str, int]:
    """Court and merge selected WIP heads through the declared content port."""
    snapshot = store.snapshot()
    view_session, context = _view_session_for_context(
        registry, authentication_context
    )
    visible_roots, _, _ = _session_canvas_roots(
        snapshot, registry, view_session
    )
    if resource_root not in visible_roots:
        raise InvalidCell("lifecycle resource is outside the active canvas")
    lifecycle = registry.standard_library.lifecycle_protocol
    instance = read_lifecycle_instance(
        snapshot,
        registry.assembly_protocol,
        lifecycle,
        resource_root,
    )
    if interface_root != instance.content_interface_root:
        raise InvalidCell("interface is not the lifecycle content port")
    parents = tuple(dict.fromkeys(parent_revision_roots))
    if len(parents) < 2:
        raise InvalidCell("lifecycle merge requires at least two WIP heads")
    current_heads = state_heads(
        snapshot,
        lifecycle,
        instance.state_pointers[lifecycle.states["wip"]],
    )
    if any(parent not in current_heads for parent in parents):
        raise InvalidCell("lifecycle merge parent is not a current WIP head")
    encoded = value.encode("utf-8")
    _authorize(
        snapshot,
        registry,
        "catalog.configure",
        object_root=resource_root,
        interface_root=interface_root,
        authentication_context=context,
        resource_usage={"max-atom-bytes": (0, len(encoded))},
    )
    parents_digest = hashlib.sha256(
        "\0".join(parents).encode("utf-8")
    ).hexdigest()
    parameters = {
        "asset": resource_root,
        "targetState": lifecycle.states["wip"],
        "parentsDigest": parents_digest,
    }
    evidence_root = registry.attestation_broker.run(
        store,
        registry.attestation_protocol,
        registry.resource_lifecycle_court_root,
        subject_name=resource_root,
        subject_content=encoded,
        external_parameters=parameters,
    )
    current = store.snapshot()
    receipt = registry.attestation_broker.consume(
        current,
        registry.attestation_protocol,
        evidence_root,
        purpose="merge:%s:%s" % (resource_root, parents_digest),
        expected_court_root=registry.resource_lifecycle_court_root,
        expected_subject_name=resource_root,
        expected_subject_digest=hashlib.sha256(encoded).hexdigest(),
        expected_parameters=parameters,
    )
    actor_root = registry.authorization.broker.resolve(context).subject_root
    revision_root = merge_wip_revisions(
        store,
        registry.assembly_protocol,
        lifecycle,
        resource_root,
        parent_revision_roots=parents,
        content=encoded,
        actor_root=actor_root,
        evidence_roots=(evidence_root,),
        evidence_receipts=(receipt,),
        attestation_broker=registry.attestation_broker,
    )
    return revision_root, evidence_root, store.revision


def promote_universal_resource_lifecycle(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    resource_root: str,
    target_state: str,
    *,
    source_revision_root: str | None = None,
    authentication_context: object | None = None,
) -> tuple[str, str, int]:
    """Court, promote, and re-sign audience state in one graph commit.

    The court attestation is created first. The lifecycle head and the signed
    resource audience evidence then change together or neither changes.
    """
    lifecycle = registry.standard_library.lifecycle_protocol
    action_by_state = {
        "shared": "share",
        "published": "publish",
        "archived": "promote",
    }
    try:
        target_state_root = lifecycle.states[target_state]
        action_name = action_by_state[target_state]
    except KeyError as exc:
        raise InvalidCell("resource lifecycle target is not admitted") from exc

    snapshot = store.snapshot()
    view_session, context = _view_session_for_context(
        registry, authentication_context
    )
    _require_application_authorization(
        snapshot,
        registry,
        action_name,
        resource_root,
        authentication_context=context,
    )
    try:
        instance_members = read_relation(
            snapshot, resource_root, budget=100_000
        )
    except InvalidCell as exc:
        raise InvalidCell(
            "resource lifecycle requires a catalogue assembly"
        ) from exc
    capabilities = {
        member.participant_id
        for member in instance_members
        if member.role_id == registry.assembly_protocol.role("capability")
    }
    if lifecycle.root_id not in capabilities:
        raise InvalidCell(
            "resource lifecycle requires the released lifecycle capability"
        )
    instance = read_lifecycle_instance(
        snapshot, registry.assembly_protocol, lifecycle, resource_root
    )
    matching_transitions = []
    for transition_root in instance.transition_roots:
        members = read_relation(snapshot, transition_root, budget=16)
        if (
            _one_for_role(members, lifecycle.role("to-state"))
            == target_state_root
        ):
            matching_transitions.append(members)
    if len(matching_transitions) != 1:
        raise InvalidCell("resource lifecycle transition is not uniquely admitted")
    source_state_root = _one_for_role(
        matching_transitions[0], lifecycle.role("from-state")
    )
    if source_state_root is None:
        raise InvalidCell("resource lifecycle transition has no source")
    source_heads = state_heads(
        snapshot,
        lifecycle,
        instance.state_pointers[source_state_root],
    )
    if source_revision_root is None:
        if len(source_heads) != 1:
            raise InvalidCell(
                "resource lifecycle source requires one selected head"
            )
        source_revision_root = source_heads[0]
    elif source_revision_root not in source_heads:
        raise InvalidCell("resource lifecycle source is not a current head")
    source = read_revision(snapshot, lifecycle, source_revision_root)
    source_digest = _text(snapshot, source.content_digest_root)
    parameters = {
        "asset": resource_root,
        "targetState": target_state_root,
    }
    evidence_root = registry.attestation_broker.run(
        store,
        registry.attestation_protocol,
        registry.resource_lifecycle_court_root,
        subject_name=source.root_id,
        subject_content=graph_content_bytes(snapshot, source.content_root),
        external_parameters=parameters,
    )

    current = store.snapshot()
    _require_application_authorization(
        current,
        registry,
        action_name,
        resource_root,
        authentication_context=context,
    )
    receipt = registry.attestation_broker.consume(
        current,
        registry.attestation_protocol,
        evidence_root,
        purpose="promote:%s:%s" % (resource_root, target_state_root),
        expected_court_root=registry.resource_lifecycle_court_root,
        expected_subject_name=source.root_id,
        expected_subject_digest=source_digest,
        expected_parameters=parameters,
    )
    verified_authority = verify_relationship_authority_snapshot(
        current,
        registry.authorization.identity_protocol,
        registry.authorization.relationship_broker,
    )
    bindings = _require_resource_audience_authority(
        current,
        registry,
        view_session.subject_root,
        (resource_root,),
        authority_snapshot=verified_authority,
    )
    (
        relationship_root,
        bound_state_root,
        owner_root,
        bound_release_root,
    ) = bindings[resource_root]
    if bound_state_root != source_state_root:
        raise InvalidCell(
            "signed resource lifecycle differs from the source revision state"
        )
    if bound_release_root is not None:
        if bound_state_root == lifecycle.states["wip"]:
            pending = [source.root_id]
            visited = set()
            anchored = False
            while pending:
                revision_root = pending.pop()
                if revision_root in visited:
                    continue
                visited.add(revision_root)
                if len(visited) > 100_000:
                    raise InvalidCell(
                        "resource WIP ancestry exceeds its traversal budget"
                    )
                if revision_root == bound_release_root:
                    anchored = True
                    break
                pending.extend(
                    read_revision(
                        current, lifecycle, revision_root
                    ).predecessor_roots
                )
            if not anchored:
                raise InvalidCell(
                    "selected WIP is outside the signed resource lineage"
                )
        elif bound_release_root != source.root_id:
            raise InvalidCell(
                "signed resource release differs from the selected source revision"
            )
    administrator_root = registry.authorization.broker.resolve(
        context
    ).subject_root
    next_evidence = (target_state_root, owner_root, source.root_id)
    manage_request = AuthorizationRequest(
        action_root=registry.authorization.protocol.actions["manage-policy"],
        object_root=registry.authorization.tenant_root,
        resource_lineage_roots=tuple(dict.fromkeys((
            registry.authorization.scope_root,
            relationship_root,
            resource_root,
            registry.authorization.audience_root,
            *next_evidence,
        ))),
        purpose_root=registry.authorization.purpose_root,
        classification_root=registry.authorization.classification_root,
        audience_root=registry.authorization.audience_root,
    )
    administration_handle = (
        registry.authorization.relationship_broker
        .mint_from_authorized_relationship_evidence_revision(
            current,
            registry.authorization.identity_protocol,
            registry.authorization.protocol,
            registry.authorization.policy_root,
            registry.authorization.broker,
            context,
            manage_request,
            administrator_root=administrator_root,
            relationship_root=relationship_root,
            evidence_roots=next_evidence,
            reason="resource lifecycle promotion",
        )
    )
    lifecycle_patch = prepare_promotion_revision(
        current,
        registry.assembly_protocol,
        lifecycle,
        resource_root,
        target_state_root=target_state_root,
        source_revision_root=source.root_id,
        actor_root=administrator_root,
        evidence_roots=(evidence_root,),
        evidence_receipts=(receipt,),
        attestation_broker=registry.attestation_broker,
    )
    authority_patch = prepare_authority_relationship_evidence_revision(
        current,
        registry.authorization.identity_protocol,
        registry.authorization.relationship_broker,
        administration_handle,
        relationship_root,
        administrator_root=administrator_root,
        evidence_roots=next_evidence,
        reason="resource lifecycle promotion",
    )
    if lifecycle_patch.expected_revision != authority_patch.expected_revision:
        raise InvalidCell("atomic resource lifecycle patches disagree on revision")
    create_ids = {cell.id for cell in lifecycle_patch.create}
    if create_ids.intersection(cell.id for cell in authority_patch.create):
        raise InvalidCell("atomic resource lifecycle patches create one cell twice")
    replace_ids = {cell.id for cell in lifecycle_patch.replace}
    if replace_ids.intersection(cell.id for cell in authority_patch.replace):
        raise InvalidCell("atomic resource lifecycle patches replace one cell twice")
    committed_revision = store.commit(
        lifecycle_patch.expected_revision,
        create=(*lifecycle_patch.create, *authority_patch.create),
        replace=(*lifecycle_patch.replace, *authority_patch.replace),
    )
    record_authority_relationship_evidence_revision(
        registry.authorization.relationship_broker,
        authority_patch,
        committed_revision,
    )
    return lifecycle_patch.revision_root, evidence_root, committed_revision


def connect_universal_roots(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    source_root: str,
    target_root: str,
    *,
    source_interface: str | None = None,
    target_interface: str | None = None,
    mutation_route: str = "/api/universal/interaction",
    authentication_context: object | None = None,
    leased_projection: Mapping[str, object] | None = None,
) -> tuple[str, int]:
    """Create one inspectable relation between two declared interfaces."""
    if type(mutation_route) is not str or not mutation_route.startswith("/"):
        raise InvalidCell("connection mutation route must be an absolute path")
    snapshot = store.dense_snapshot()
    view_session, context = _view_session_for_context(
        registry, authentication_context
    )
    projected_nodes: dict[str, Mapping[str, object]] | None = None
    projected_wires: tuple[Mapping[str, object], ...] | None = None
    if leased_projection is None:
        visible_roots, relation_roots, _, scope_trail = _session_canvas_roots(
            snapshot, registry, view_session, include_trail=True
        )
        active_scope_root = scope_trail[-1]
    else:
        raw_nodes = leased_projection.get("nodes")
        raw_wires = leased_projection.get("wires")
        raw_scope = leased_projection.get("scope")
        if (
            leased_projection.get("revision") != snapshot.revision
            or leased_projection.get("application_root")
            != registry.application_root
            or leased_projection.get("canvas_root") != registry.canvas_root
            or not isinstance(raw_nodes, list)
            or not isinstance(raw_wires, list)
            or not isinstance(raw_scope, Mapping)
            or any(not isinstance(item, Mapping) for item in raw_nodes)
            or any(not isinstance(item, Mapping) for item in raw_wires)
        ):
            raise InvalidCell("leased topology projection is invalid")
        projected_nodes = {
            str(item["id"]): item
            for item in raw_nodes
            if type(item.get("id")) is str and item.get("id")
        }
        projected_wires = tuple(raw_wires)
        if len(projected_nodes) != len(raw_nodes):
            raise InvalidCell("leased topology nodes are not unique")
        visible_roots = tuple(projected_nodes)
        relation_roots = tuple(dict.fromkeys(
            str(item["id"])
            for item in projected_wires
            if type(item.get("id")) is str and item.get("id")
        ))
        active_scope_root = raw_scope.get("current")
        scope_trail = _read_view_scope_trail_structure(
            snapshot, registry, view_session
        )
        if (
            type(active_scope_root) is not str
            or not scope_trail
            or scope_trail[-1] != active_scope_root
        ):
            raise InvalidCell("leased topology scope is not current")
    _authorize(
        snapshot,
        registry,
        "catalog.connect",
        object_root=target_root,
        authentication_context=context,
        resource_usage={"max-relations": (len(relation_roots), 1)},
    )
    visible = set(visible_roots)
    if source_root not in visible or target_root not in visible:
        raise InvalidCell("connection endpoint is outside the active canvas")
    if source_root == target_root:
        raise InvalidCell("self-connections are not admitted")
    if projected_nodes is None:
        registered = _registered_canvas_interfaces(snapshot, registry)
        source_interfaces = tuple(
            interface for interface in registered
            if interface["owner"] == source_root
            and interface["side"] == "source"
        )
    else:
        source_node = projected_nodes[source_root]
        source_interfaces = tuple(
            interface for interface in source_node.get("ports", ())
            if isinstance(interface, Mapping)
            and interface.get("side") == "source"
            and interface.get("mode") == "connection"
        )
    if source_interface is None:
        if len(source_interfaces) != 1:
            raise InvalidCell(
                "source node requires one selected source interface"
            )
        projected_source_interface = source_interfaces[0]
        source_interface = str(projected_source_interface["id"])
    else:
        projected_source_interface = next((
            interface for interface in source_interfaces
            if interface["id"] == source_interface
        ), None)
    if projected_source_interface is None:
        raise InvalidCell("source interface is outside the source node")
    if _is_derived_composition_interface(
        snapshot, registry, source_interface
    ):
        raise InvalidCell(
            "derived composition boundaries cannot accept new connections"
        )
    if target_interface is not None and _is_derived_composition_interface(
        snapshot, registry, target_interface
    ):
        raise InvalidCell(
            "derived composition boundaries cannot accept new connections"
        )
    target_endpoint = None
    target_binding_incidence = None
    target_contract = None
    registered_targets = (
        tuple(
            interface for interface in registered
            if interface["owner"] == target_root
            and interface["side"] == "target"
        )
        if projected_nodes is None else tuple(
            interface for interface in projected_nodes[target_root].get(
                "ports", ()
            )
            if isinstance(interface, Mapping)
            and interface.get("side") == "target"
            and interface.get("mode") == "connection"
        )
    )
    registered_target = (
        next((
            interface for interface in registered_targets
            if interface["id"] == target_interface
        ), None)
        if target_interface is not None else (
            registered_targets[0] if len(registered_targets) == 1 else None
        )
    )
    if target_interface is None and len(registered_targets) > 1:
        raise InvalidCell("target node requires one selected target interface")
    if registered_target is not None:
        target_endpoint = str(registered_target["id"])
        target_contract = str(registered_target["contract_root"])
        projected_incidence = registered_target.get("target_incidence")
        if type(projected_incidence) is str:
            target_binding_incidence = projected_incidence
    else:
        if projected_nodes is not None:
            raise InvalidCell("target node has no compatible target interface")
        target_assembly = _instance_projection(snapshot, registry, target_root)
        interfaces = [
            item for item in (target_assembly or {}).get("interfaces", [])
            if item["mode"] == "connection"
        ]
        interface = None
        if target_interface is None and len(interfaces) == 1:
            interface = interfaces[0]
        elif target_interface is not None:
            interface = next(
                (item for item in interfaces if item["id"] == target_interface),
                None,
            )
        elif interfaces:
            raise InvalidCell("target assembly interface must be selected")
        if interface is None:
            raise InvalidCell("target node has no compatible target interface")
        target_endpoint = interface["id"]
        target_binding_incidence = interface["target_incidence"]
        target_contract = interface["contract_root"]
    if _is_derived_composition_interface(
        snapshot, registry, target_endpoint
    ):
        raise InvalidCell(
            "derived composition boundaries cannot accept new connections"
        )
    if not _interface_contracts_compatible(
        registry.assembly_protocol,
        str(projected_source_interface["contract_root"]),
        target_contract,
    ):
        raise InvalidCell("connection interface contracts are incompatible")
    if projected_wires is None:
        for existing_root in relation_roots:
            existing = read_relation(snapshot, existing_root, budget=256)
            existing_source = next((
                member for member in existing
                if member.role_id == registry.roles["source"]
            ), None)
            existing_target = next((
                member for member in existing
                if member.role_id == registry.roles["target"]
            ), None)
            if (
                existing_source is not None
                and existing_target is not None
                and existing_source.participant_id == source_interface
                and existing_target.participant_id == target_endpoint
            ):
                raise InvalidCell("duplicate connection is not admitted")
            if (
                target_binding_incidence is not None
                and existing_target is not None
                and existing_target.participant_id == target_endpoint
            ):
                raise InvalidCell("target interface already has a connection")
    else:
        for existing in projected_wires:
            if existing.get("nary") is not False:
                continue
            if (
                existing.get("source_interface") == source_interface
                and existing.get("target_interface") == target_endpoint
            ):
                raise InvalidCell("duplicate connection is not admitted")
            if (
                target_binding_incidence is not None
                and existing.get("target_interface") == target_endpoint
            ):
                raise InvalidCell("target interface already has a connection")

    relation_root = "app:canvas-relation:%s" % uuid.uuid4().hex
    members = [
        (registry.roles["source"], source_interface),
        (registry.roles["target"], target_endpoint),
        (registry.roles["scope"], active_scope_root),
    ]
    relation = compose_relation_cells(members, relation_id=relation_root)
    public_interface_patches = []
    for interface_root, incidence_root in zip(
        (source_interface, target_endpoint),
        relation.build.incidence_ids[:2],
        strict=True,
    ):
        if not _is_domain_public_interface(
            snapshot, registry.assembly_protocol, interface_root
        ):
            continue
        public_interface_patches.append(prepare_append_relation_members(
            snapshot,
            interface_root,
            (
                (registry.roles["seed"], relation_root),
                (registry.roles["authority"], incidence_root),
            ),
            budget=100_000,
        ))
    property_specs = (
        ("color", "#5fb3b3"),
        ("width", "1.35"),
        ("dash", ""),
        ("relation_count", 1),
    )
    property_refs: list[PropertyRef] = []
    property_cells: list[Cell] = []
    for key, value in property_specs:
        reference, cells = _compose_property(
            registry, relation_root, key, value
        )
        property_refs.append(reference)
        property_cells.extend(cells)
    canvas_patch = prepare_append_relation_members(
        snapshot,
        registry.canvas_root,
        (
            (registry.roles["relation"], relation_root),
            *((registry.roles["property"], ref.relation_root)
              for ref in property_refs),
        ),
        budget=100_000,
    )
    scope_patch = (
        prepare_append_relation_members(
            snapshot,
            active_scope_root,
            ((registry.roles["relation"], relation_root),),
            budget=100_000,
        )
        if active_scope_root != registry.canvas_root else None
    )
    eligible_views = tuple(
        view for view in registry.view_sessions.values()
        if (
            view.root_id == view_session.root_id
            and {source_root, target_root}.issubset(set(visible_roots))
        ) or (
            view.root_id != view_session.root_id
            and {source_root, target_root}.issubset(set(
                _session_canvas_roots(snapshot, registry, view)[0]
            ))
        )
    )
    lens_patches = tuple(
        prepare_append_relation_members(
            snapshot,
            view.properties_lens_root,
            ((registry.roles["scope"], ref.relation_root)
             for ref in property_refs),
            budget=100_000,
        )
        for view in eligible_views
    )
    selection_transition = _prepare_selection_transition(
        snapshot,
        registry,
        view_session,
        (),
        relation_root,
        pending_roots=(relation_root,),
        scope_root=active_scope_root,
    )
    replacements = {
        cell.id: cell for cell in selection_transition.replace
    }
    for cell in (
        *canvas_patch.replace,
        *(scope_patch.replace if scope_patch else ()),
        *(cell for patch in public_interface_patches
          for cell in patch.replace),
        *(cell for patch in lens_patches for cell in patch.replace),
    ):
        replacements[cell.id] = cell
    if target_binding_incidence is not None:
        incidence = snapshot.cells[target_binding_incidence]
        replacements[incidence.id] = Cell(
            incidence.id, incidence.link0, source_root, incidence.atom
        )
    revision = _commit_universal_user_change(
        store,
        registry,
        view_session,
        context,
        snapshot,
        route=mutation_route,
        command_name="catalog.connect",
        authorization_scope_root=target_root,
        create=(
            *relation.cells,
            *property_cells,
            *(cell for patch in public_interface_patches
              for cell in patch.create),
            *selection_transition.create,
            *canvas_patch.create,
            *(scope_patch.create if scope_patch else ()),
            *(cell for patch in lens_patches for cell in patch.create),
        ),
        replace=tuple(replacements.values()),
    )
    return relation_root, revision


def _assembly_connection_binding_incidence(
    snapshot: Snapshot,
    registry: UniversalApplicationRegistry,
    owner_root: str,
    interface_root: str,
) -> str | None:
    """Return the owned binding behind one assembly input, if it has one."""
    assembly = _instance_projection(snapshot, registry, owner_root)
    if assembly is None:
        return None
    interface = next((
        item for item in assembly.get("interfaces", ())
        if item["id"] == interface_root
    ), None)
    if interface is None or interface["mode"] != "connection":
        return None
    incidence = interface.get("target_incidence")
    return str(incidence) if incidence is not None else None


def _connection_binding_before_creation(
    store: CellStore,
    relation_root: str,
    incidence_id: str,
) -> Cell:
    """Read the exact input binding retained before a wire was created."""
    created_revision = store.cell_created_revision(relation_root)
    if created_revision <= 0:
        raise InvalidCell("connection has no reversible creation revision")
    previous = store.at(created_revision - 1)
    try:
        return previous.cells[incidence_id]
    except KeyError as exc:
        raise InvalidCell(
            "connection input did not exist before the wire"
        ) from exc


def disconnect_universal_connection(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    relation_root: str,
    *,
    mutation_route: str = "/api/universal/interaction",
    authentication_context: object | None = None,
) -> int:
    """Detach one visible binary wire without deleting Cell history."""
    if type(mutation_route) is not str or not mutation_route.startswith("/"):
        raise InvalidCell("connection mutation route must be an absolute path")
    snapshot = store.dense_snapshot()
    view_session, context = _view_session_for_context(
        registry, authentication_context
    )
    visible_roots, relation_roots, _, scope_trail = _session_canvas_roots(
        snapshot, registry, view_session, include_trail=True
    )
    if relation_root not in relation_roots:
        raise InvalidCell("connection is outside the active canvas lens")
    members = read_relation(snapshot, relation_root, budget=256)
    source_members = tuple(
        member for member in members
        if member.role_id == registry.roles["source"]
    )
    target_members = tuple(
        member for member in members
        if member.role_id == registry.roles["target"]
    )
    if len(source_members) != 1 or len(target_members) != 1:
        raise InvalidCell("only binary canvas connections may be detached")
    declared_scopes = tuple(
        member.participant_id for member in members
        if member.role_id == registry.roles["scope"]
    )
    if len(declared_scopes) > 1:
        raise InvalidCell("canvas connection declares multiple scopes")
    active_scope_root = scope_trail[-1]
    if declared_scopes and declared_scopes != (active_scope_root,):
        raise InvalidCell("canvas connection scope differs from the active lens")
    source_member, target_member = source_members[0], target_members[0]
    source_owner, source_interface = _canvas_endpoint(
        snapshot, registry, source_member, visible_roots
    )
    target_owner, target_interface = _canvas_endpoint(
        snapshot, registry, target_member, visible_roots
    )
    if (
        source_owner not in visible_roots
        or target_owner not in visible_roots
        or source_interface is None
        or target_interface is None
    ):
        raise InvalidCell("connection endpoints are outside the visible interface graph")
    _authorize(
        snapshot,
        registry,
        "catalog.connect",
        object_root=target_owner,
        authentication_context=context,
        resource_usage={"max-relations": (len(relation_roots), 0)},
    )

    canvas_members = read_relation(
        snapshot, registry.canvas_root, budget=100_000
    )
    property_roots = tuple(
        member.participant_id for member in canvas_members
        if member.role_id == registry.roles["property"]
        and _one_for_role(
            read_relation(snapshot, member.participant_id, budget=16),
            registry.roles["owner"],
        ) == relation_root
    )
    canvas_detach_ids = tuple(
        member.incidence_id for member in canvas_members
        if (
            member.role_id == registry.roles["relation"]
            and member.participant_id == relation_root
        ) or (
            member.role_id == registry.roles["property"]
            and member.participant_id in property_roots
        )
    )
    if sum(
        member.role_id == registry.roles["relation"]
        and member.participant_id == relation_root
        for member in canvas_members
    ) != 1:
        raise InvalidCell("canvas connection membership is inconsistent")

    patches = [prepare_remove_relation_members(
        snapshot,
        registry.canvas_root,
        canvas_detach_ids,
        budget=100_000,
    )]
    if declared_scopes and active_scope_root != registry.canvas_root:
        scope_members = read_relation(
            snapshot, active_scope_root, budget=100_000
        )
        scope_detach_ids = tuple(
            member.incidence_id for member in scope_members
            if member.role_id == registry.roles["relation"]
            and member.participant_id == relation_root
        )
        if len(scope_detach_ids) != 1:
            raise InvalidCell("scoped canvas connection membership is inconsistent")
        patches.append(prepare_remove_relation_members(
            snapshot,
            active_scope_root,
            scope_detach_ids,
            budget=100_000,
        ))
    for candidate_view in registry.view_sessions.values():
        lens_members = read_relation(
            snapshot, candidate_view.properties_lens_root, budget=100_000
        )
        detach_ids = tuple(
            member.incidence_id for member in lens_members
            if member.role_id == registry.roles["scope"]
            and member.participant_id in property_roots
        )
        if detach_ids:
            patches.append(prepare_remove_relation_members(
                snapshot,
                candidate_view.properties_lens_root,
                detach_ids,
                budget=100_000,
            ))

    for endpoint in (source_member, target_member):
        interface_root = endpoint.participant_id
        if not _is_domain_public_interface(
            snapshot, registry.assembly_protocol, interface_root
        ):
            continue
        interface_members = read_relation(
            snapshot, interface_root, budget=100_000
        )
        detach_ids = tuple(
            member.incidence_id for member in interface_members
            if (
                member.role_id == registry.roles["seed"]
                and member.participant_id == relation_root
            ) or (
                member.role_id == registry.roles["authority"]
                and member.participant_id == endpoint.incidence_id
            )
        )
        if len(detach_ids) != 2:
            raise InvalidCell("public interface membership is inconsistent")
        patches.append(prepare_remove_relation_members(
            snapshot, interface_root, detach_ids, budget=100_000
        ))

    replacements: dict[str, Cell] = {}
    for patch in patches:
        for cell in patch.replace:
            if cell.id in replacements and replacements[cell.id] != cell:
                raise InvalidCell("connection detach patches conflict")
            replacements[cell.id] = cell

    binding_incidence = _assembly_connection_binding_incidence(
        snapshot, registry, target_owner, target_member.participant_id
    )
    if binding_incidence is not None:
        current_binding = snapshot.cells[binding_incidence]
        if current_binding.link1 != source_owner:
            raise InvalidCell("connection input binding differs from its visible source")
        previous_binding = _connection_binding_before_creation(
            store, relation_root, binding_incidence
        )
        replacements[binding_incidence] = Cell(
            current_binding.id,
            current_binding.link0,
            previous_binding.link1,
            current_binding.atom,
        )

    selection_transition = _prepare_selection_transition(
        snapshot,
        registry,
        view_session,
        (),
        source_owner,
        pending_roots=(relation_root,),
    )
    for cell in selection_transition.replace:
        if cell.id in replacements and replacements[cell.id] != cell:
            raise InvalidCell("connection detach conflicts with selection state")
        replacements[cell.id] = cell
    revision = _commit_universal_user_change(
        store,
        registry,
        view_session,
        context,
        snapshot,
        route=mutation_route,
        command_name="catalog.connect",
        authorization_scope_root=target_owner,
        create=selection_transition.create,
        replace=tuple(replacements.values()),
    )
    if not set(snapshot.cells).issubset(store.snapshot().cells):
        raise InvalidCell("connection detach deleted Cell history")
    return revision


def edit_universal_interface_value(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    instance_root: str,
    interface_root: str,
    value: str,
    *,
    mutation_route: str = "/api/universal/assembly-field",
    authentication_context: object | None = None,
) -> int:
    """Edit one instance-owned scalar through its declared interface."""
    snapshot = store.snapshot()
    view_session, context = _view_session_for_context(
        registry, authentication_context
    )
    visible_roots, _, _ = _session_canvas_roots(
        snapshot, registry, view_session
    )
    if instance_root not in visible_roots:
        raise InvalidCell("interface owner is outside the active canvas")
    assembly = _instance_projection(snapshot, registry, instance_root)
    if assembly is None:
        raise InvalidCell("interface owner is not an assembly instance")
    interface = next(
        (item for item in assembly["interfaces"]
         if item["id"] == interface_root),
        None,
    )
    if (
        interface is None
        or interface["mode"] != "connection"
        or not interface["editable"]
    ):
        raise InvalidCell("interface does not expose an owned scalar value")
    encoded = value.encode("utf-8")
    _authorize(
        snapshot,
        registry,
        "catalog.configure",
        object_root=interface["target"],
        interface_root=interface_root,
        authentication_context=context,
        resource_usage={"max-atom-bytes": (0, len(encoded))},
    )
    current = snapshot.cells[interface["target"]]
    # A declared default can already equal an omitted client value. There is
    # no graph mutation to compensate or receipt to record in that case.
    if current.atom == encoded:
        return snapshot.revision
    return _commit_universal_user_change(
        store,
        registry,
        view_session,
        context,
        snapshot,
        route=mutation_route,
        command_name="catalog.configure",
        authorization_scope_root=interface["target"],
        authorization_interface_root=interface_root,
        replace=(Cell(current.id, current.link0, current.link1, encoded),),
    )


def _candidate_snapshot_for_atomic_commit(
    snapshot: Snapshot,
    *,
    create: tuple[Cell, ...] = (),
    replace: tuple[Cell, ...] = (),
) -> Snapshot:
    """Apply a bounded patch to an isolated pre-commit validation snapshot."""
    return overlay_read_snapshot(snapshot, create=create, replace=replace)


def _prepare_relation_member_removal(
    snapshot: Snapshot,
    relation_root: str,
    incidence_id: str,
    *,
    budget: int,
) -> tuple[Cell, ...]:
    """Prepare one history-preserving detach without committing it."""
    members = read_relation(snapshot, relation_root, budget=budget)
    incidence_ids = tuple(member.incidence_id for member in members)
    if incidence_id not in incidence_ids:
        raise InvalidCell("relation removal target is not a member")
    chain_ids: list[str] = []
    cursor = relation_root
    seen: set[str] = set()
    while cursor != NULL_CELL_ID:
        if len(chain_ids) >= budget:
            raise InvalidCell("relation removal exceeded its traversal budget")
        if cursor in seen:
            raise InvalidCell("relation removal found a cyclic chain")
        seen.add(cursor)
        chain_ids.append(cursor)
        cursor = snapshot.cells[cursor].link1
    if len(chain_ids) != len(members):
        raise InvalidCell("relation chain and incidence counts disagree")
    index = incidence_ids.index(incidence_id)
    root = snapshot.cells[relation_root]
    if len(members) == 1:
        return (Cell(root.id, NULL_CELL_ID, NULL_CELL_ID, root.atom),)
    if index == 0:
        successor = snapshot.cells[chain_ids[1]]
        return (Cell(
            root.id, successor.link0, successor.link1, root.atom
        ),)
    predecessor = snapshot.cells[chain_ids[index - 1]]
    target = snapshot.cells[chain_ids[index]]
    return (Cell(
        predecessor.id,
        predecessor.link0,
        target.link1,
        predecessor.atom,
    ),)


def _edit_relation_role_interface(
    store: CellStore,
    snapshot: Snapshot,
    registry: UniversalApplicationRegistry,
    view_session: ApplicationViewSession,
    context: object,
    assembly: Mapping[str, object],
    interface: Mapping[str, object],
    action: str,
    *,
    value: str,
    incidence_id: str | None,
    visible_roots: tuple[str, ...],
    mutation_route: str,
) -> int:
    """Edit one role through its real interface under the full contract."""
    definition = read_definition(
        snapshot,
        registry.assembly_protocol,
        str(assembly["definition"]),
    )
    authority = resolve_relation_contract_authority(
        snapshot,
        capability_roots=definition.capability_roots,
        rule_roots=definition.rule_roots,
        budget=100_000,
    )
    if interface.get("contract_root") != authority.contract.root_id:
        raise InvalidCell("relation interface contract authority is ambiguous")
    member_role = str(interface["member_role"])
    constraints = {
        item.participant_role: item
        for item in authority.contract.constraints
    }
    constraint = constraints.get(member_role)
    if constraint is None or interface.get("constraint") != constraint.root_id:
        raise InvalidCell("relation interface role is outside its contract")
    relation_root = str(interface["target"])
    members = read_relation(snapshot, relation_root, budget=100_000)
    by_incidence = {member.incidence_id: member for member in members}
    role_members = tuple(
        member for member in members if member.role_id == member_role
    )
    if action == "reorder":
        raise InvalidCell(
            "this relation contract does not declare ordered role semantics"
        )
    usage = {"max-collection-items": (len(role_members), 0)}
    if action == "append":
        usage["max-collection-items"] = (len(role_members), 1)
    _authorize(
        snapshot,
        registry,
        "catalog.configure",
        object_root=relation_root,
        interface_root=str(interface["id"]),
        authentication_context=context,
        resource_usage=usage,
    )

    create: tuple[Cell, ...] = ()
    replace: tuple[Cell, ...] = ()
    if action in {"append", "edit"}:
        if (
            not value
            or len(value) > 4096
            or value not in visible_roots
            or value not in snapshot.cells
        ):
            raise InvalidCell(
                "relation participant must be an exact visible canvas root"
            )
    if action == "append":
        patch = prepare_append_relation_members(
            snapshot,
            relation_root,
            ((member_role, value),),
            budget=100_000,
        )
        create = patch.create
        replace = patch.replace
    elif action == "edit":
        member = by_incidence.get(incidence_id or "")
        if member is None or member.role_id != member_role:
            raise InvalidCell("relation edit target is outside this role interface")
        current = snapshot.cells[member.incidence_id]
        replace = (Cell(
            current.id, current.link0, value, current.atom
        ),)
    elif action == "remove":
        member = by_incidence.get(incidence_id or "")
        if member is None or member.role_id != member_role:
            raise InvalidCell(
                "relation removal target is outside this role interface"
            )
        replace = _prepare_relation_member_removal(
            snapshot,
            relation_root,
            member.incidence_id,
            budget=100_000,
        )
    else:
        raise InvalidCell("unsupported relation-role interface action")

    candidate = _candidate_snapshot_for_atomic_commit(
        snapshot, create=create, replace=replace
    )
    validate_relation(
        candidate,
        authority.protocol,
        authority.contract.root_id,
        relation_root,
        budget=100_000,
    )
    return _commit_universal_user_change(
        store,
        registry,
        view_session,
        context,
        snapshot,
        route=mutation_route,
        command_name="catalog.configure",
        authorization_scope_root=relation_root,
        authorization_interface_root=str(interface["id"]),
        create=create,
        replace=replace,
    )


def edit_universal_interface_collection(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    instance_root: str,
    interface_root: str,
    action: str,
    *,
    value: str = "",
    incidence_id: str | None = None,
    incidence_order: tuple[str, ...] | list[str] = (),
    mutation_route: str = "/api/universal/interaction",
    reject_direct_collection_value_edit: bool = False,
    reject_direct_collection_structure_edit: bool = False,
    authentication_context: object | None = None,
) -> int:
    """Edit any graph interface declaring an ordered member-role contract."""
    snapshot = store.snapshot()
    view_session, context = _view_session_for_context(
        registry, authentication_context
    )
    visible_roots, _, _ = _session_canvas_roots(
        snapshot, registry, view_session
    )
    if instance_root not in visible_roots:
        raise InvalidCell("collection owner is outside the active canvas")
    assembly = _instance_projection(snapshot, registry, instance_root)
    if assembly is None:
        raise InvalidCell("collection owner is not an assembly instance")
    interface = next(
        (item for item in assembly["interfaces"]
         if item["id"] == interface_root),
        None,
    )
    if interface is None or interface["mode"] not in {
        "collection", "relation-role"
    }:
        raise InvalidCell("interface does not expose an ordered collection")
    if interface["mode"] == "relation-role":
        return _edit_relation_role_interface(
            store,
            snapshot,
            registry,
            view_session,
            context,
            assembly,
            interface,
            action,
            value=value,
            incidence_id=incidence_id,
            visible_roots=visible_roots,
            mutation_route=mutation_route,
        )
    if action == "edit" and reject_direct_collection_value_edit:
        raise InvalidCell(
            "collection item edits require a graph Interaction lease"
        )
    if (
        action in {"append", "remove", "reorder"}
        and reject_direct_collection_structure_edit
    ):
        raise InvalidCell(
            "collection structure edits require a graph Interaction lease"
        )
    target_root = interface["target"]
    member_role = interface["member_role"]
    members = read_relation(snapshot, target_root, budget=100_000)
    by_incidence = {member.incidence_id: member for member in members}
    encoded = value.encode("utf-8")
    usage = {"max-atom-bytes": (0, len(encoded))}
    if action == "append":
        usage["max-collection-items"] = (len(members), 1)
    _authorize(
        snapshot,
        registry,
        "catalog.configure",
        object_root=target_root,
        interface_root=interface_root,
        authentication_context=context,
        resource_usage=usage,
    )

    if action == "append":
        value_root = "app:collection-value:%s" % uuid.uuid4().hex
        patch = prepare_append_relation_members(
            snapshot,
            target_root,
            ((member_role, value_root),),
            budget=100_000,
        )
        return _commit_universal_user_change(
            store,
            registry,
            view_session,
            context,
            snapshot,
            route=mutation_route,
            command_name="catalog.configure",
            authorization_scope_root=target_root,
            authorization_interface_root=interface_root,
            create=(
                Cell(value_root, NULL_CELL_ID, NULL_CELL_ID, encoded),
                *patch.create,
            ),
            replace=patch.replace,
        )
    if action == "edit":
        if incidence_id not in by_incidence:
            raise InvalidCell("collection edit target is not a member")
        value_root = by_incidence[incidence_id].participant_id
        current = snapshot.cells[value_root]
        return _commit_universal_user_change(
            store,
            registry,
            view_session,
            context,
            snapshot,
            route=mutation_route,
            command_name="catalog.configure",
            authorization_scope_root=target_root,
            authorization_interface_root=interface_root,
            replace=(Cell(
                current.id, current.link0, current.link1, encoded
            ),),
        )
    if action == "remove":
        if incidence_id is None:
            raise InvalidCell("collection removal requires an incidence")
        return _commit_universal_user_change(
            store,
            registry,
            view_session,
            context,
            snapshot,
            route=mutation_route,
            command_name="catalog.configure",
            authorization_scope_root=target_root,
            authorization_interface_root=interface_root,
            replace=_prepare_relation_member_removal(
                snapshot, target_root, incidence_id, budget=100_000
            ),
        )
    if action == "reorder":
        replacements = prepare_reorder_relation_members(
            snapshot, target_root, incidence_order, budget=100_000
        )
        if not replacements:
            return snapshot.revision
        return _commit_universal_user_change(
            store,
            registry,
            view_session,
            context,
            snapshot,
            route=mutation_route,
            command_name="catalog.configure",
            authorization_scope_root=target_root,
            authorization_interface_root=interface_root,
            replace=replacements,
        )
    raise InvalidCell("unsupported collection action")


def transition_universal_operational_state(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    instance_root: str,
    event_root: str,
    expected_state_root: str,
    *,
    evidence_roots: tuple[str, ...] | list[str] = (),
    authentication_context: object | None = None,
) -> int:
    """Execute one graph-declared operational transition under both gates."""
    snapshot = store.snapshot()
    view_session, context = _view_session_for_context(
        registry, authentication_context
    )
    visible_roots, _, _ = _session_canvas_roots(
        snapshot, registry, view_session
    )
    if instance_root not in visible_roots:
        raise InvalidCell("operational node is outside the active canvas")
    operational = registry.standard_library.state_machine_protocol
    machine = read_instance_state_machine(
        snapshot, registry.assembly_protocol, operational, instance_root
    )
    _require_application_authorization(
        snapshot,
        registry,
        "execute",
        instance_root,
        authentication_context=context,
        interface_root=machine.root_id,
    )
    authority = registry.authorization
    identity = authority.broker.resolve(
        context
    )
    permission_definition = (
        registry.standard_library.governed_domains.definitions[
            "permission-request"
        ].definition_root
    )
    instance_members = read_relation(snapshot, instance_root, budget=100_000)
    definition_root = _one_for_role(
        instance_members, registry.assembly_protocol.role("provenance")
    )
    if (
        definition_root == permission_definition
        and event_root in snapshot.cells
        and _text(snapshot, event_root) in {"approve", "reject", "cancel"}
    ):
        if tuple(evidence_roots):
            raise InvalidCell(
                "user decision evidence is issued only by the authenticated action"
            )
        _, _, revision = decide_permission_request(
            store,
            registry.assembly_protocol,
            operational,
            instance_root,
            expected_definition_root=permission_definition,
            event_root=event_root,
            expected_state_root=expected_state_root,
            actor_root=identity.subject_root,
            context_roots=(view_session.root_id,),
        )
        return revision
    adapters = verify_adapter_catalog(
        snapshot, registry.adapter_protocol, registry.adapter_catalog_root
    )
    _, revision = transition_machine(
        store,
        operational,
        machine.root_id,
        event_root=event_root,
        expected_state_root=expected_state_root,
        actor_root=identity.subject_root,
        evidence_roots=tuple(evidence_roots),
        trusted_issuer_roots=adapters.adapter_roots,
        context_roots=(view_session.root_id,),
    )
    return revision


def execute_universal_adapter_request(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    instance_root: str,
    *,
    consent_broker,
    key_factory=None,
    authentication_context: object | None = None,
):
    """Run the graph-allowlisted executor for one approved visible request."""
    snapshot = store.snapshot()
    view_session, context = _view_session_for_context(
        registry, authentication_context
    )
    visible_roots, _, _ = _session_canvas_roots(
        snapshot, registry, view_session
    )
    if instance_root not in visible_roots:
        raise InvalidCell("adapter request is outside the active canvas")
    _require_application_authorization(
        snapshot,
        registry,
        "execute",
        instance_root,
        authentication_context=context,
    )
    identity = registry.authorization.broker.resolve(context)
    return execute_device_enrollment(
        store,
        registry,
        instance_root,
        actor_root=identity.subject_root,
        consent_broker=consent_broker,
        key_factory=key_factory,
    )


def select_universal_root(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    root_id: str,
    *,
    authentication_context: object | None = None,
) -> int:
    return set_universal_selection(
        store,
        registry,
        None,
        focus_root=root_id,
        authentication_context=authentication_context,
        _user_selectable_only=True,
    )


def _composition_exposure_cells(
    registry: UniversalApplicationRegistry,
    parent_root: str,
    visible_roots: tuple[str, ...],
    *,
    entry_root: str,
):
    return compose_relation_cells((
        (registry.roles["scope"], parent_root),
        *((registry.roles["visible"], root) for root in visible_roots),
    ), relation_id=entry_root)


def _prepare_active_top_scope_exposure_extension(
    snapshot: Snapshot,
    registry: UniversalApplicationRegistry,
    view_session: ApplicationViewSession,
    pending_root: str,
    parent_root: str,
) -> tuple[tuple[Cell, ...], tuple[Cell, ...]]:
    """Advance the active personal scope exposure without rewriting history."""
    active = _view_scope_exposures(
        snapshot,
        registry,
        view_session,
    ).get(parent_root)
    if active is None:
        return (), ()
    _previous_root, visible_roots = active
    if pending_root in visible_roots:
        raise InvalidCell("pending root already exists in the active exposure")
    entry_root = "app:scope-exposure:%s" % uuid.uuid4().hex
    exposure = _composition_exposure_cells(
        registry,
        parent_root,
        (*visible_roots, pending_root),
        entry_root=entry_root,
    )
    _previous, registry_create, registry_replace = (
        _prepare_exposure_activation(
            snapshot,
            registry,
            view_session,
            parent_root,
            entry_root,
        )
    )
    return (
        (*exposure.cells, *registry_create),
        tuple(registry_replace),
    )


def _composition_history_cells(
    registry: UniversalApplicationRegistry,
    *,
    history_entry_root: str,
    operation: str,
    actor_root: str,
    parent_root: str,
    composition_root: str,
    before_exposure_root: str | None,
    after_exposure_root: str,
):
    operation_root = history_entry_root + ":operation"
    timestamp_root = history_entry_root + ":timestamp"
    relation = compose_relation_cells((
        (registry.roles["why"], operation_root),
        (registry.roles["authority"], actor_root),
        (registry.roles["scope"], parent_root),
        (registry.roles["member"], composition_root),
        *((
            (registry.roles["source"], before_exposure_root),
        ) if before_exposure_root is not None else ()),
        (registry.roles["target"], after_exposure_root),
        (registry.roles["value"], timestamp_root),
    ), relation_id=history_entry_root)
    return (
        Cell(
            operation_root,
            NULL_CELL_ID,
            NULL_CELL_ID,
            operation.encode("ascii"),
        ),
        Cell(
            timestamp_root,
            NULL_CELL_ID,
            NULL_CELL_ID,
            datetime.now(timezone.utc).isoformat().encode("ascii"),
        ),
        *relation.cells,
    )


def _prepare_exposure_activation(
    snapshot: Snapshot,
    registry: UniversalApplicationRegistry,
    view_session: ApplicationViewSession,
    parent_root: str,
    entry_root: str,
):
    exposures = _view_scope_exposures(snapshot, registry, view_session)
    previous = exposures.get(parent_root)
    registry_members = read_relation(
        snapshot, view_session.scope_exposure_root, budget=100_000
    )
    if previous is None:
        patch = prepare_append_relation_members(
            snapshot,
            view_session.scope_exposure_root,
            ((registry.roles["relation"], entry_root),),
            budget=100_000,
        )
        return None, patch.create, patch.replace
    previous_root, _visible = previous
    incidence = next(
        member for member in registry_members
        if member.role_id == registry.roles["relation"]
        and member.participant_id == previous_root
    )
    current = snapshot.cells[incidence.incidence_id]
    return previous_root, (), (Cell(
        current.id,
        current.link0,
        entry_root,
        current.atom,
    ),)


def _composition_boundary_cells(
    snapshot: Snapshot,
    registry: UniversalApplicationRegistry,
    composition_root: str,
    relation_roots: tuple[str, ...],
    visible_roots: tuple[str, ...],
    selected_roots: frozenset[str],
) -> tuple[tuple[str, ...], tuple[str, ...], tuple[Cell, ...]]:
    """Return internal relation ids and exact derived boundary interfaces."""
    internal = []
    boundaries = []
    cells: list[Cell] = []
    for relation_root in relation_roots:
        members = read_relation(snapshot, relation_root, budget=256)
        source_member = next((
            member for member in members
            if member.role_id == registry.roles["source"]
        ), None)
        target_member = next((
            member for member in members
            if member.role_id == registry.roles["target"]
        ), None)
        if source_member is None or target_member is None:
            continue
        source_owner, source_interface = _canvas_endpoint(
            snapshot, registry, source_member, visible_roots
        )
        target_owner, target_interface = _canvas_endpoint(
            snapshot, registry, target_member, visible_roots
        )
        source_inside = source_owner in selected_roots
        target_inside = target_owner in selected_roots
        if source_inside and target_inside:
            internal.append(relation_root)
            continue
        if source_inside == target_inside:
            continue
        endpoint = source_member if source_inside else target_member
        endpoint_interface = (
            source_interface if source_inside else target_interface
        )
        side = "source" if source_inside else "target"
        if endpoint_interface is None:
            raise InvalidCell(
                "composition crossing lacks an exact declared interface"
            )
        token = len(boundaries)
        boundary_root = "%s:boundary:%s" % (composition_root, token)
        name_root = boundary_root + ":name"
        contract_root = boundary_root + ":contract"
        presentation_root = boundary_root + ":presentation"
        cells.extend((
            Cell(
                name_root,
                NULL_CELL_ID,
                NULL_CELL_ID,
                ("Provides" if side == "source" else "Requires").encode(
                    "ascii"
                ),
            ),
            Cell(
                contract_root,
                NULL_CELL_ID,
                NULL_CELL_ID,
                b"Derived composition boundary; incidence identity preserved",
            ),
            Cell(
                presentation_root,
                NULL_CELL_ID,
                NULL_CELL_ID,
                side.encode("ascii"),
            ),
        ))
        boundary = compose_relation_cells((
            (
                registry.assembly_protocol.role("interface-target"),
                composition_root,
            ),
            (registry.assembly_protocol.role("name"), name_root),
            (
                registry.assembly_protocol.role("interface-contract"),
                contract_root,
            ),
            (
                registry.assembly_protocol.role("interface-presentation"),
                presentation_root,
            ),
            (registry.roles["seed"], endpoint_interface["id"]),
            (registry.roles["authority"], endpoint.incidence_id),
            (registry.roles["relation"], relation_root),
            (registry.roles["read-only"], registry.roles["read-only"]),
        ), relation_id=boundary_root)
        cells.extend(boundary.cells)
        boundaries.append(boundary_root)
    return tuple(internal), tuple(boundaries), tuple(cells)


def group_universal_selection(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    *,
    title: str = "Composition",
    projected_canvas: Mapping[str, object] | None = None,
    authentication_context: object | None = None,
) -> tuple[str, int]:
    """Fold the current selection into one personal WIP composition."""
    title = title.strip()
    if not title or len(title.encode("utf-8")) > 256:
        raise InvalidCell("composition title is empty or too large")
    snapshot = store.dense_snapshot()
    view_session, context = _view_session_for_context(
        registry, authentication_context
    )
    projection = _interaction_canvas_at_revision(
        store, registry, context, snapshot.revision, projected_canvas
    )
    projected_nodes = tuple(projection.get("nodes", ()))
    if any(not isinstance(node, Mapping) for node in projected_nodes):
        raise InvalidCell("composition projection nodes are invalid")
    visible_roots = tuple(str(node["id"]) for node in projected_nodes)
    relation_roots = tuple(dict.fromkeys(
        str(wire["id"])
        for wire in projection.get("wires", ())
        if isinstance(wire, Mapping) and type(wire.get("id")) is str
    ))
    selected = tuple(
        root for root in visible_roots
        if root in set(projection.get("selection", ()))
    )
    if len(selected) < 2:
        raise InvalidCell("group requires at least two selected roots")
    _authorize(
        snapshot,
        registry,
        "catalog.configure",
        object_root=view_session.root_id,
        authentication_context=context,
        resource_usage={"max-instances": (len(visible_roots), 1)},
    )
    projected_scope = projection.get("scope")
    if not isinstance(projected_scope, Mapping):
        raise InvalidCell("composition projection scope is missing")
    parent_root = projected_scope.get("current")
    structural_trail = _read_view_scope_trail_structure(
        snapshot, registry, view_session
    )
    if type(parent_root) is not str or structural_trail[-1] != parent_root:
        raise InvalidCell("composition projection scope drifted")
    token = uuid.uuid4().hex
    composition_root = "app:composition:%s" % token
    entry_root = "app:scope-exposure:%s" % token
    selected_set = frozenset(selected)
    internal_relations, boundary_roots, boundary_cells = (
        _composition_boundary_cells(
            snapshot,
            registry,
            composition_root,
            relation_roots,
            visible_roots,
            selected_set,
        )
    )
    nodes_by_root = {str(node["id"]): node for node in projected_nodes}
    positions = []
    colors = []
    for index, root_id in enumerate(selected):
        node = nodes_by_root[root_id]
        positions.append((
            float(node.get("x", 60.0 + index * 40)),
            float(node.get("y", 92.0 + index * 30)),
        ))
        color = node.get("color")
        if type(color) is str and color:
            colors.append(color)
    property_specs = (
        ("title", title, False),
        (
            "position_x",
            sum(point[0] for point in positions) / len(positions),
            False,
        ),
        (
            "position_y",
            sum(point[1] for point in positions) / len(positions),
            False,
        ),
        (
            "color",
            colors[0] if colors else _DEFAULT_NODE_PRESENTATION_COLOR,
            False,
        ),
        ("lifecycle", "WIP", True),
        ("description", "Personal WIP composition", False),
    )
    property_refs = []
    property_cells = []
    for key, value, read_only in property_specs:
        reference, cells = _compose_property(
            registry,
            composition_root,
            key,
            value,
            read_only=read_only,
        )
        property_refs.append(reference)
        property_cells.extend(cells)
    actor_root = registry.authorization.broker.resolve(context).subject_root
    composition = compose_relation_cells((
        (registry.roles["seed"], _COMPOSITION_MARKER_ROOT),
        (registry.roles["scope"], parent_root),
        (registry.roles["authority"], actor_root),
        *((registry.roles["member"], root) for root in selected),
        *((registry.roles["relation"], root) for root in internal_relations),
        *((
            registry.assembly_protocol.role("interface"), root
        ) for root in boundary_roots),
        *((
            registry.roles["property"], reference.relation_root
        ) for reference in property_refs),
    ), relation_id=composition_root)
    after_roots = []
    inserted = False
    for root_id in visible_roots:
        if root_id in selected_set:
            if not inserted:
                after_roots.append(composition_root)
                inserted = True
        else:
            after_roots.append(root_id)
    exposure = _composition_exposure_cells(
        registry, parent_root, tuple(after_roots), entry_root=entry_root
    )
    canvas_patch = prepare_append_relation_members(
        snapshot,
        registry.canvas_root,
        (
            (registry.roles["member"], composition_root),
            *((registry.roles["property"], ref.relation_root)
              for ref in property_refs),
        ),
        budget=100_000,
    )
    lens_patch = prepare_append_relation_members(
        snapshot,
        view_session.properties_lens_root,
        ((registry.roles["scope"], ref.relation_root)
         for ref in property_refs),
        budget=100_000,
    )
    selection_patch = prepare_append_relation_members(
        snapshot,
        view_session.selection_state_root,
        ((registry.roles["selected"], composition_root),),
        budget=100_000,
    )
    previous_entry, exposure_create, exposure_replace = (
        _prepare_exposure_activation(
            snapshot,
            registry,
            view_session,
            parent_root,
            entry_root,
        )
    )
    history_root = "app:composition-history:%s" % token
    history_cells = _composition_history_cells(
        registry,
        history_entry_root=history_root,
        operation="group",
        actor_root=actor_root,
        parent_root=parent_root,
        composition_root=composition_root,
        before_exposure_root=previous_entry,
        after_exposure_root=entry_root,
    )
    history_patch = prepare_append_relation_members(
        snapshot,
        view_session.composition_history_root,
        ((registry.roles["relation"], history_root),),
        budget=100_000,
    )
    base_create = (
        *boundary_cells,
        *property_cells,
        *composition.cells,
        *exposure.cells,
        *canvas_patch.create,
        *lens_patch.create,
        *selection_patch.create,
        *exposure_create,
        *history_cells,
        *history_patch.create,
    )
    base_ids = tuple(cell.id for cell in base_create)
    if (
        len(base_ids) != len(set(base_ids))
        or any(root_id in snapshot.cells for root_id in base_ids)
    ):
        raise InvalidCell("atomic composition has invalid pending identities")

    authority = registry.authorization
    identity = authority.identity_protocol
    relationship_broker = authority.relationship_broker
    read_root = authority.protocol.actions["read"]
    audience_grant = prepare_authority_relationship_grant(
        snapshot,
        identity,
        relationship_broker,
        relationship_broker.mint_from_trusted_administrator(actor_root),
        relationship_id=_resource_audience_binding_root(composition_root),
        source_root=composition_root,
        target_root=authority.audience_root,
        kind="audience-binding",
        tenant_root=authority.tenant_root,
        administrator_root=actor_root,
        scope_root=authority.classification_root,
        action_roots=(read_root,),
        reason="resource is classified and released to this audience",
        evidence_roots=(
            registry.standard_library.lifecycle_protocol.states["wip"],
            view_session.subject_root,
            composition_root,
        ),
        pending_roots=base_ids,
    )
    projection_grant = prepare_authority_relationship_grant(
        snapshot,
        identity,
        relationship_broker,
        relationship_broker.mint_from_trusted_administrator(actor_root),
        relationship_id=_projection_grant_root(
            view_session.subject_root,
            composition_root,
            entry_root,
        ),
        source_root=authority.resource_reader_principal_root,
        target_root=view_session.subject_root,
        kind="delegation",
        tenant_root=authority.tenant_root,
        administrator_root=actor_root,
        scope_root=composition_root,
        action_roots=(read_root,),
        reason="subject receives this resource through the authorized view",
        evidence_roots=(entry_root,),
        pending_roots=base_ids,
    )
    identity_patch = prepare_append_relation_members(
        snapshot,
        identity.root_id,
        (
            (identity.role("relationship-member"), audience_grant.root_id),
            (identity.role("relationship-member"), projection_grant.root_id),
        ),
        budget=100_000,
    )
    session_patch = prepare_append_relation_members(
        snapshot,
        view_session.root_id,
        ((registry.roles["relation"], projection_grant.root_id),),
        budget=100_000,
    )
    pending_roots = (
        *base_ids,
        *(cell.id for cell in audience_grant.cells),
        *(cell.id for cell in projection_grant.cells),
        *(cell.id for cell in identity_patch.create),
        *(cell.id for cell in session_patch.create),
    )
    selection_transition = _prepare_selection_transition(
        snapshot,
        registry,
        view_session,
        (composition_root,),
        composition_root,
        reason_root=_FOCUS_REASON_COMPOSITION,
        pending_roots=pending_roots,
        scope_root=parent_root,
    )
    replacements = {}
    for cell in (
        *canvas_patch.replace,
        *lens_patch.replace,
        *selection_patch.replace,
        *exposure_replace,
        *history_patch.replace,
        *identity_patch.replace,
        *session_patch.replace,
        *selection_transition.replace,
    ):
        if cell.id in replacements and replacements[cell.id] != cell:
            raise InvalidCell("atomic composition has conflicting patches")
        replacements[cell.id] = cell
    revision = _commit_universal_user_change(
        store,
        registry,
        view_session,
        context,
        snapshot,
        route="/api/universal/interaction",
        command_name="catalog.configure",
        authorization_scope_root=view_session.root_id,
        create=(
            *base_create,
            *audience_grant.cells,
            *projection_grant.cells,
            *identity_patch.create,
            *session_patch.create,
            *selection_transition.create,
        ),
        replace=tuple(replacements.values()),
    )
    for grant in (audience_grant, projection_grant):
        relationship_broker.record_generation(grant.root_id, grant.generation)
    return composition_root, revision


def ungroup_universal_composition(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    composition_root: str,
    *,
    projected_canvas: Mapping[str, object] | None = None,
    authentication_context: object | None = None,
) -> int:
    """Remove one personal WIP boundary while preserving its graph history."""
    snapshot = store.dense_snapshot()
    view_session, context = _view_session_for_context(
        registry, authentication_context
    )
    projection = _interaction_canvas_at_revision(
        store, registry, context, snapshot.revision, projected_canvas
    )
    visible_roots = tuple(
        str(node["id"])
        for node in projection.get("nodes", ())
        if isinstance(node, Mapping) and type(node.get("id")) is str
    )
    if composition_root not in visible_roots or not _is_universal_composition(
        snapshot, registry, composition_root
    ):
        raise InvalidCell("ungroup target is not a visible WIP composition")
    _authorize(
        snapshot,
        registry,
        "catalog.configure",
        object_root=composition_root,
        authentication_context=context,
    )
    composition_members = read_relation(
        snapshot, composition_root, budget=100_000
    )
    children = tuple(
        member.participant_id for member in composition_members
        if member.role_id == registry.roles["member"]
    )
    if not children:
        raise InvalidCell("composition has no direct members to expose")
    projected_scope = projection.get("scope")
    if not isinstance(projected_scope, Mapping):
        raise InvalidCell("ungroup projection scope is missing")
    parent_root = projected_scope.get("current")
    structural_trail = _read_view_scope_trail_structure(
        snapshot, registry, view_session
    )
    if type(parent_root) is not str or structural_trail[-1] != parent_root:
        raise InvalidCell("ungroup projection scope drifted")
    token = uuid.uuid4().hex
    entry_root = "app:scope-exposure:%s" % token
    after_roots = []
    for root_id in visible_roots:
        if root_id == composition_root:
            after_roots.extend(children)
        else:
            after_roots.append(root_id)
    if len(after_roots) != len(set(after_roots)):
        raise InvalidCell("ungroup would duplicate a visible root")
    exposure = _composition_exposure_cells(
        registry, parent_root, tuple(after_roots), entry_root=entry_root
    )
    missing_selection = tuple(
        child for child in children
        if child not in view_session.selection_incidences
        and not any(
            member.participant_id == child
            for member in read_relation(
                snapshot,
                view_session.selection_state_root,
                budget=100_000,
            )
        )
    )
    selection_patch = prepare_append_relation_members(
        snapshot,
        view_session.selection_state_root,
        ((registry.roles["selected"], root) for root in missing_selection),
        budget=100_000,
    )
    actor_root = registry.authorization.broker.resolve(context).subject_root
    nested_compositions = tuple(
        root for root in children
        if _is_universal_composition(snapshot, registry, root)
    )
    previous_entry, exposure_create, exposure_replace = (
        _prepare_exposure_activation(
            snapshot,
            registry,
            view_session,
            parent_root,
            entry_root,
        )
    )
    history_root = "app:composition-history:%s" % token
    history_cells = _composition_history_cells(
        registry,
        history_entry_root=history_root,
        operation="ungroup",
        actor_root=actor_root,
        parent_root=parent_root,
        composition_root=composition_root,
        before_exposure_root=previous_entry,
        after_exposure_root=entry_root,
    )
    history_patch = prepare_append_relation_members(
        snapshot,
        view_session.composition_history_root,
        ((registry.roles["relation"], history_root),),
        budget=100_000,
    )
    base_create = (
        *exposure.cells,
        *selection_patch.create,
        *exposure_create,
        *history_cells,
        *history_patch.create,
    )
    base_ids = tuple(cell.id for cell in base_create)
    if (
        len(base_ids) != len(set(base_ids))
        or any(root_id in snapshot.cells for root_id in base_ids)
    ):
        raise InvalidCell("atomic ungroup has invalid pending identities")

    authority = registry.authorization
    identity = authority.identity_protocol
    relationship_broker = authority.relationship_broker
    read_root = authority.protocol.actions["read"]
    projection_grants = tuple(
        prepare_authority_relationship_grant(
            snapshot,
            identity,
            relationship_broker,
            relationship_broker.mint_from_trusted_administrator(actor_root),
            relationship_id=_projection_grant_root(
                view_session.subject_root,
                target_root,
                entry_root,
            ),
            source_root=authority.resource_reader_principal_root,
            target_root=view_session.subject_root,
            kind="delegation",
            tenant_root=authority.tenant_root,
            administrator_root=actor_root,
            scope_root=target_root,
            action_roots=(read_root,),
            reason="subject receives this resource through the authorized view",
            evidence_roots=(entry_root,),
            pending_roots=base_ids,
        )
        for target_root in nested_compositions
    )
    identity_patch = prepare_append_relation_members(
        snapshot,
        identity.root_id,
        (
            (identity.role("relationship-member"), grant.root_id)
            for grant in projection_grants
        ),
        budget=100_000,
    )
    session_patch = prepare_append_relation_members(
        snapshot,
        view_session.root_id,
        ((registry.roles["relation"], grant.root_id) for grant in projection_grants),
        budget=100_000,
    )
    # The old grant is bound to the old exposure evidence and becomes dormant.
    # Keeping it signed allows authorized undo without rewinding revocation state.
    pending_roots = (
        *base_ids,
        *(cell.id for grant in projection_grants for cell in grant.cells),
        *(cell.id for cell in identity_patch.create),
        *(cell.id for cell in session_patch.create),
    )
    selection_transition = _prepare_selection_transition(
        snapshot,
        registry,
        view_session,
        children,
        children[0],
        reason_root=_FOCUS_REASON_COMPOSITION,
        pending_roots=pending_roots,
        scope_root=parent_root,
    )
    replacements = {}
    for cell in (
        *selection_patch.replace,
        *exposure_replace,
        *history_patch.replace,
        *identity_patch.replace,
        *session_patch.replace,
        *selection_transition.replace,
    ):
        if cell.id in replacements and replacements[cell.id] != cell:
            raise InvalidCell("atomic ungroup has conflicting patches")
        replacements[cell.id] = cell
    revision = _commit_universal_user_change(
        store,
        registry,
        view_session,
        context,
        snapshot,
        route="/api/universal/interaction",
        command_name="catalog.configure",
        authorization_scope_root=composition_root,
        create=(
            *base_create,
            *(cell for grant in projection_grants for cell in grant.cells),
            *identity_patch.create,
            *session_patch.create,
            *selection_transition.create,
        ),
        replace=tuple(replacements.values()),
    )
    for grant in projection_grants:
        relationship_broker.record_generation(grant.root_id, grant.generation)
    return revision


def _set_universal_scope_execution(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    target_root: str | None = None,
    *,
    expected_revision: int | None = None,
    projected_canvas: Mapping[str, object] | None = None,
    authentication_context: object | None = None,
) -> UniversalScopeExecution:
    """Enter one direct graph level or return to an existing trail ancestor."""
    snapshot = store.dense_snapshot()
    if expected_revision is not None and snapshot.revision != expected_revision:
        raise Conflict(
            "expected revision %s, current revision is %s"
            % (expected_revision, snapshot.revision)
        )
    view_session, context = _view_session_for_context(
        registry, authentication_context
    )
    _authorize(
        snapshot,
        registry,
        "canvas.select",
        object_root=view_session.root_id,
        authentication_context=context,
        resource_lineage_roots=(
            registry.authorization.personal_view_scope_root,
        ),
    )
    projection = _interaction_canvas_at_revision(
        store, registry, context, snapshot.revision, projected_canvas
    )
    projected_scope = projection.get("scope")
    if not isinstance(projected_scope, Mapping):
        raise InvalidCell("scope interaction projection is invalid")
    projected_trail = projected_scope.get("trail")
    if not isinstance(projected_trail, list) or any(
        not isinstance(item, Mapping) or type(item.get("root")) is not str
        for item in projected_trail
    ):
        raise InvalidCell("scope interaction trail projection is invalid")
    trail = _read_view_scope_trail_structure(
        snapshot, registry, view_session
    )
    if tuple(item["root"] for item in projected_trail) != trail:
        raise InvalidCell("scope interaction trail projection drifted")
    current_root = trail[-1]
    if projected_scope.get("current") != current_root:
        raise InvalidCell("scope projection current root drifted")
    if target_root == current_root:
        return UniversalScopeExecution(snapshot.revision, None)

    if target_root is None:
        target_index = max(0, len(trail) - 2)
    elif target_root in trail:
        target_index = trail.index(target_root)
    else:
        if len(trail) >= _SCOPE_TRAIL_MAX_DEPTH:
            raise InvalidCell("view scope trail reached its maximum depth")
        visible_roots = tuple(
            str(node["id"])
            for node in projection.get("nodes", ())
            if isinstance(node, Mapping) and type(node.get("id")) is str
        )
        if target_root not in visible_roots:
            raise InvalidCell("scope target is outside the active graph level")
        if not _relation_members_or_none(snapshot, target_root):
            raise InvalidCell("scope target is a terminal cell")
        next_roots, next_relations, next_properties = _nested_canvas_scope(
            snapshot, registry, target_root
        )
        trail_patch = prepare_append_relation_members(
            snapshot,
            view_session.scope_trail_root,
            ((registry.roles["scope"], target_root),),
            budget=_SCOPE_TRAIL_MAX_DEPTH + 1,
        )
        selection_members = read_relation(
            snapshot, view_session.selection_state_root, budget=100_000
        )
        known_selection_roots = {
            member.participant_id for member in selection_members
        }
        missing_roots = tuple(
            root_id for root_id in next_roots
            if root_id not in known_selection_roots
        )
        selection_patch = prepare_append_relation_members(
            snapshot,
            view_session.selection_state_root,
            (
                (registry.roles["available"], root_id)
                for root_id in missing_roots
            ),
            budget=100_000,
        )
        selection_transition = _prepare_selection_transition(
            snapshot,
            registry,
            view_session,
            (),
            next_roots[0],
            reason_root=_FOCUS_REASON_SCOPE,
            scope_root=target_root,
        )
        revision = store.commit(
            snapshot.revision,
            create=(
                *selection_transition.create,
                *trail_patch.create,
                *selection_patch.create,
            ),
            replace=(
                *trail_patch.replace,
                *selection_patch.replace,
                *selection_transition.replace,
            ),
        )
        return UniversalScopeExecution(
            revision,
            UniversalScopeMaterialization(
                revision,
                view_session.root_id,
                view_session.subject_root,
                (*trail, target_root),
                next_roots,
                next_relations,
                next_properties,
            ),
        )

    if target_index == len(trail) - 1:
        return UniversalScopeExecution(snapshot.revision, None)
    trail_members = read_relation(
        snapshot,
        view_session.scope_trail_root,
        budget=_SCOPE_TRAIL_MAX_DEPTH + 1,
    )
    removal = prepare_remove_relation_members(
        snapshot,
        view_session.scope_trail_root,
        (
            member.incidence_id
            for member in trail_members[target_index + 1:]
        ),
        budget=_SCOPE_TRAIL_MAX_DEPTH + 1,
    )
    candidate = _candidate_snapshot_for_atomic_commit(
        snapshot, replace=removal.replace
    )
    visible_roots, relation_roots, property_roots = _session_canvas_roots(
        candidate, registry, view_session
    )
    destination_root = trail[target_index]
    focus_root = visible_roots[0] if visible_roots else destination_root
    selection_transition = _prepare_selection_transition(
        candidate,
        registry,
        view_session,
        (),
        focus_root,
        reason_root=_FOCUS_REASON_SCOPE,
        scope_root=destination_root,
    )
    replacements = {cell.id: cell for cell in removal.replace}
    for cell in selection_transition.replace:
        previous = replacements.get(cell.id)
        if previous is not None and previous != cell:
            raise InvalidCell("scope transition patches conflict")
        replacements[cell.id] = cell
    revision = store.commit(
        snapshot.revision,
        create=selection_transition.create,
        replace=tuple(replacements.values()),
    )
    return UniversalScopeExecution(
        revision,
        UniversalScopeMaterialization(
            revision,
            view_session.root_id,
            view_session.subject_root,
            trail[:target_index + 1],
            visible_roots,
            relation_roots,
            property_roots,
        ),
    )


def set_universal_scope(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    target_root: str | None = None,
    *,
    expected_revision: int | None = None,
    projected_canvas: Mapping[str, object] | None = None,
    authentication_context: object | None = None,
) -> int:
    """Enter one graph level and return only its committed Store revision."""
    return _set_universal_scope_execution(
        store,
        registry,
        target_root,
        expected_revision=expected_revision,
        projected_canvas=projected_canvas,
        authentication_context=authentication_context,
    ).revision


def set_universal_selection(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    roots: tuple[str, ...] | list[str] | None,
    *,
    focus_root: str | None = None,
    consent_evidence_root: str | None = None,
    authentication_context: object | None = None,
    _user_selectable_only: bool = False,
) -> int:
    """Atomically rewire visible selection roles and the Properties focus."""
    snapshot = store.dense_snapshot()
    view_session, context = _view_session_for_context(
        registry, authentication_context
    )
    _authorize(
        snapshot,
        registry,
        "canvas.select",
        object_root=view_session.root_id,
        authentication_context=context,
        resource_lineage_roots=(
            registry.authorization.personal_view_scope_root,
        ),
    )
    visible_roots, relation_roots, _ = _session_canvas_roots(
        snapshot, registry, view_session
    )
    exposed_relation_roots = _relation_backed_canvas_roots(
        snapshot, registry, visible_roots
    )
    visible_interface_roots = _visible_canvas_interface_roots(
        snapshot, registry, visible_roots
    )
    if roots is None:
        if focus_root is None:
            raise InvalidCell("selection target is missing")
        ordered = (focus_root,) if focus_root in visible_roots else ()
    else:
        ordered = tuple(dict.fromkeys(roots))
    visible = set(visible_roots)
    if any(root_id not in visible for root_id in ordered):
        raise InvalidCell("multi-selection contains a root outside the active canvas")
    definitions = {
        item["id"] for item in _project_standard_catalog(
            store, snapshot, registry
        )
    }
    if focus_root is None:
        if ordered:
            focus_root = ordered[-1]
        else:
            focus_pointer_root = _one_for_role(
                read_relation(snapshot, view_session.properties_lens_root),
                registry.roles["focus"],
            )
            focus_root = read_focus(
                snapshot, registry.attention_protocol, focus_pointer_root
            ).primary_root
    focus_pointer_root = _one_for_role(
        read_relation(snapshot, view_session.properties_lens_root),
        registry.roles["focus"],
    )
    current_focus_root = read_focus(
        snapshot, registry.attention_protocol, focus_pointer_root
    ).primary_root
    identity = registry.authorization.broker.resolve(context)
    direct_founder_navigation = (
        identity.subject_root == registry.authorization.subject_root
        and _is_direct_relation_participant(
            snapshot, current_focus_root, focus_root
        )
    )
    browser_session_focus_roots = _inspectable_browser_session_roots(
        snapshot, registry, identity.subject_root
    )
    if _user_selectable_only:
        user_allowed = (
            visible
            | set(relation_roots)
            | set(exposed_relation_roots)
            | set(visible_interface_roots)
            | definitions
            | set(registry.container_roots)
            | set(browser_session_focus_roots)
            | {
                registry.primitive_root,
                view_session.settings_root,
                view_session.root_id,
            }
        )
        if focus_root not in user_allowed:
            raise InvalidCell(
                "selection target is outside the active canvas lens"
            )
    view_focus_roots = _inspectable_view_focus_roots(
        snapshot, registry, view_session
    )
    if (focus_root not in visible and focus_root not in relation_roots
            and focus_root not in exposed_relation_roots
            and focus_root not in visible_interface_roots
            and focus_root not in definitions
            and focus_root not in registry.container_roots
            and focus_root not in browser_session_focus_roots
            and focus_root not in view_focus_roots
            and not (
                identity.subject_root == registry.authorization.subject_root
                and focus_root in registry.core_value_obligation_roots
            )
            and not direct_founder_navigation
            and focus_root not in (
                registry.primitive_root,
                view_session.settings_root,
                view_session.root_id,
            )):
        raise InvalidCell("Properties focus is outside the active canvas")

    transition = _prepare_selection_transition(
        snapshot,
        registry,
        view_session,
        ordered,
        focus_root,
        consent_evidence_root=consent_evidence_root,
    )
    if not transition.create and not transition.replace:
        return snapshot.revision
    return store.commit(
        snapshot.revision,
        create=transition.create,
        replace=transition.replace,
    )


def set_universal_inspector_lens(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    lens_root: str,
    *,
    expected_revision: int | None = None,
    projected_canvas: Mapping[str, object] | None = None,
    authentication_context: object | None = None,
) -> int:
    """Rewire one personal progressive-disclosure lens under view authority."""
    snapshot = store.dense_snapshot()
    if expected_revision is not None and snapshot.revision != expected_revision:
        raise InvalidCell("inspector lens interaction revision is stale")
    view_session, context = _view_session_for_context(
        registry, authentication_context
    )
    _authorize(
        snapshot,
        registry,
        "canvas.select",
        object_root=view_session.root_id,
        authentication_context=context,
        resource_lineage_roots=(
            registry.authorization.personal_view_scope_root,
        ),
    )
    identity = registry.authorization.broker.resolve(context)
    authority_snapshot = verify_relationship_authority_snapshot(
        snapshot,
        registry.authorization.identity_protocol,
        registry.authorization.relationship_broker,
    )
    live_memberships = active_membership_roots(
        snapshot,
        registry.authorization.identity_protocol,
        registry.authorization.relationship_broker,
        identity.subject_root,
        identity.tenant_root,
        authority_snapshot=authority_snapshot,
    )
    live_principals = tuple(dict.fromkeys((
        *identity.principal_roots,
        *live_memberships,
    )))
    admitted = {
        lens["id"] for lens in _project_inspector_lenses(
            snapshot,
            registry,
            view_session,
            live_principals,
        )["lenses"]
    }
    if lens_root not in admitted:
        raise InvalidCell("inspector lens is outside identity authority")
    lens_incidence = snapshot.cells[view_session.inspector_lens_incidence]
    if (
        lens_incidence.link0 != registry.roles["focus"]
        or lens_incidence.link1 not in registry.inspector_lens_roots.values()
    ):
        raise InvalidCell("view inspector lens incidence drifted")

    projection = _interaction_canvas_at_revision(
        store,
        registry,
        context,
        snapshot.revision,
        projected_canvas,
    )
    selected_root = str(projection["selected"])
    selected_assembly = projection.get("selected_assembly")
    available = _properties_available_components(
        registry,
        properties=list(projection["properties"]),
        connections=list(projection["connections"]),
        has_attached_relations=any(
            wire["source"] == selected_root
            or wire["target"] == selected_root
            for wire in projection["wires"]
        ),
        selected_relation=projection.get("selected_relation"),
        selected_assembly=(
            selected_assembly if isinstance(selected_assembly, dict) else None
        ),
            selected_interfaces=(
                list(projection.get("selected_interfaces") or ())
            ),
            can_add_property=bool(
                projection.get("authoring", {}).get("add_property")
            ),
            can_add_interface=bool(
                projection.get("authoring", {}).get("add_interface")
            ),
            selected_settings=selected_root == view_session.settings_root,
        has_history=bool(
            selected_root == view_session.settings_root
            or projection.get("action_history", {}).get("transactions")
            or isinstance(selected_assembly, dict)
            and selected_assembly.get("lifecycle")
        ),
        has_access=(
            identity.subject_root == registry.authorization.subject_root
        ),
        has_evidence=bool(
            identity.subject_root == registry.authorization.subject_root
            and (
                projection.get("selected_definition")
                or isinstance(selected_assembly, dict)
                and selected_assembly.get("lifecycle")
                and any(
                    head.get("evidence_details")
                    for state in selected_assembly["lifecycle"]["states"]
                    for head in state["heads"]
                )
            )
        ),
    )
    target = project_presentation(
        snapshot,
        registry.properties_presentation_protocol,
        registry.properties_presentation_root,
        active_lens_root=lens_root,
        focus_binding_root=view_session.properties_panel_binding_root,
        available_component_roots=available,
        principal_roots=live_principals,
    ).active_panel_root
    if target is None:
        raise InvalidCell("inspector lens has no applicable Properties panel")

    panel_incidence = snapshot.cells[view_session.properties_panel_incidence]
    if (
        panel_incidence.link0
        != registry.properties_presentation_protocol.role("focus")
        or panel_incidence.link1
        not in registry.properties_panel_roots.values()
    ):
        raise InvalidCell("view Properties panel incidence drifted")

    replacements = []
    if lens_incidence.link1 != lens_root:
        replacements.append(Cell(
            lens_incidence.id,
            lens_incidence.link0,
            lens_root,
            lens_incidence.atom,
        ))
    if panel_incidence.link1 != target:
        replacements.append(Cell(
            panel_incidence.id,
            panel_incidence.link0,
            target,
            panel_incidence.atom,
        ))
    if not replacements:
        return snapshot.revision
    return store.commit(snapshot.revision, replace=tuple(replacements))


def set_universal_properties_panel(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    panel_root: str,
    *,
    authentication_context: object | None = None,
) -> int:
    """Rewire the graph-held active Properties panel for this view."""
    snapshot = store.dense_snapshot()
    view_session, context = _view_session_for_context(
        registry, authentication_context
    )
    _authorize(
        snapshot,
        registry,
        "canvas.select",
        object_root=view_session.root_id,
        authentication_context=context,
        resource_lineage_roots=(
            registry.authorization.personal_view_scope_root,
        ),
    )
    projection = project_universal_canvas(
        store, registry, authentication_context=context
    )
    admitted = {
        panel["id"]
        for panel in projection["inspector"]["presentation"]["panels"]
    }
    if panel_root not in admitted:
        raise InvalidCell("Properties panel is not applicable or authorised")
    snapshot = store.dense_snapshot()
    incidence = snapshot.cells[view_session.properties_panel_incidence]
    if (
        incidence.link0
        != registry.properties_presentation_protocol.role("focus")
        or incidence.link1 not in registry.properties_panel_roots.values()
    ):
        raise InvalidCell("view Properties panel incidence drifted")
    if incidence.link1 == panel_root:
        return snapshot.revision
    return store.commit(snapshot.revision, replace=(Cell(
        incidence.id,
        incidence.link0,
        panel_root,
        incidence.atom,
    ),))


def ensure_universal_properties_panel_interactions(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    subject_root: str,
) -> tuple[str, Mapping[str, str]]:
    """Compose real Properties-tab controls through the generic rule protocol."""
    try:
        view_session = registry.view_sessions[subject_root]
    except KeyError as exc:
        raise AuthorizationDenied(
            "interaction subject has no provisioned application view"
        ) from exc
    event_root = "app:interaction-event:activate"
    pattern_role = "app:interaction-rule:incidence-pattern:role"
    pattern_current = "app:interaction-rule:incidence-pattern:current"
    pattern_root = "app:interaction-rule:incidence-pattern"
    foundation = (
        Cell(event_root, NULL_CELL_ID, NULL_CELL_ID, b"activate"),
        Cell(pattern_role, NULL_CELL_ID, NULL_CELL_ID, b""),
        Cell(pattern_current, NULL_CELL_ID, NULL_CELL_ID, b""),
        Cell(pattern_root, pattern_role, pattern_current, b""),
    )
    snapshot = store.snapshot()
    present_foundation = {
        cell.id for cell in foundation if cell.id in snapshot.cells
    }
    if present_foundation and len(present_foundation) != len(foundation):
        raise InvalidCell("Properties interaction foundation is partial")
    if not present_foundation:
        store.commit(snapshot.revision, create=foundation)

    rule_roots: dict[str, str] = {}
    action_roots: dict[str, str] = {}
    interaction_roots: dict[str, str] = {}
    subject_token = _part(subject_root)
    for panel_name, panel_root in sorted(registry.properties_panel_roots.items()):
        panel_token = _part(panel_name)
        replacement_role = (
            "app:interaction-rule:properties-panel:%s:role" % panel_token
        )
        replacement_panel = (
            "app:interaction-rule:properties-panel:%s:panel" % panel_token
        )
        replacement_root = (
            "app:interaction-rule:properties-panel:%s:replacement" % panel_token
        )
        rule_root = "app:interaction-rule:properties-panel:%s" % panel_token
        replacement = (
            Cell(replacement_role, NULL_CELL_ID, NULL_CELL_ID, b""),
            Cell(replacement_panel, NULL_CELL_ID, NULL_CELL_ID, b""),
            Cell(replacement_root, replacement_role, replacement_panel, b""),
        )
        snapshot = store.snapshot()
        present_replacement = {
            cell.id for cell in replacement if cell.id in snapshot.cells
        }
        if present_replacement and len(present_replacement) != len(replacement):
            raise InvalidCell("Properties interaction replacement is partial")
        if not present_replacement:
            store.commit(snapshot.revision, create=replacement)
            snapshot = store.snapshot()
        if rule_root not in snapshot.cells:
            build_rule(
                store,
                registry.rule_protocol,
                rule_id=rule_root,
                pattern_root=pattern_root,
                replacement_root=replacement_root,
                pattern_variables=(pattern_role, pattern_current),
                replacement_bindings={replacement_role: pattern_role},
                replacement_constants={replacement_panel: panel_root},
            )
        else:
            rule = read_rule(
                snapshot, registry.rule_protocol, rule_root, budget=512
            )
            if (
                rule.pattern_root != pattern_root
                or rule.replacement_root != replacement_root
                or set(rule.pattern_variables) != {pattern_role, pattern_current}
                or dict(rule.replacement_bindings)
                != {replacement_role: pattern_role}
                or dict(rule.replacement_constants)
                != {replacement_panel: panel_root}
            ):
                raise InvalidCell("Properties interaction rule drifted")
        rule_roots[panel_root] = rule_root

        legacy_transaction_root = (
            "app:interaction-transaction:properties-panel:%s" % panel_token
        )
        transaction_root = (
            "app:interaction-transaction:properties-panel:%s:%s"
            % (subject_token, panel_token)
        )
        snapshot = store.snapshot()
        if transaction_root not in snapshot.cells:
            build_transaction(
                store,
                registry.transaction_protocol,
                transaction_id=transaction_root,
                steps=((rule_root, view_session.properties_panel_incidence),),
            )
        else:
            transaction = read_transaction(
                snapshot,
                registry.transaction_protocol,
                transaction_root,
                budget=512,
            )
            if (
                len(transaction.steps) != 1
                or transaction.steps[0].rule_root != rule_root
                or transaction.steps[0].target_root
                != view_session.properties_panel_incidence
                or transaction.evidence_roots
                or transaction.outcome_roots
            ):
                raise InvalidCell("Properties interaction transaction drifted")
        action_roots[panel_root] = transaction_root

        interaction_root = (
            "app:interaction:properties-panel:%s:%s"
            % (subject_token, panel_token)
        )
        snapshot = store.snapshot()
        if interaction_root not in snapshot.cells:
            build_interaction(
                store,
                registry.interaction_protocol,
                interaction_id=interaction_root,
                control_root=panel_root,
                event_root=event_root,
                target_root=view_session.properties_panel_incidence,
                input_roots=(panel_root,),
                action_root=transaction_root,
                subject_root=view_session.subject_root,
                policy_root=registry.authorization.policy_root,
                authorization_action_root=(
                    registry.authorization.protocol.actions["inspect"]
                ),
                authorization_object_root=view_session.root_id,
                authorization_scope_roots=(
                    registry.authorization.personal_view_scope_root,
                    registry.authorization.scope_root,
                ),
                authorization_purpose_root=registry.authorization.purpose_root,
                authorization_classification_root=(
                    registry.authorization.classification_root
                ),
                authorization_audience_root=registry.authorization.audience_root,
                release_policy_root=registry.authorization.policy_root,
                release_authorization_action_root=(
                    registry.authorization.protocol.actions["publish"]
                ),
                release_authorization_object_root=(
                    registry.authorization.scope_root
                ),
                release_authorization_purpose_root=(
                    registry.authorization.purpose_root
                ),
                release_authorization_classification_root=(
                    registry.authorization.classification_root
                ),
                release_authorization_audience_root=(
                    registry.authorization.audience_root
                ),
                version="0.3.0",
            )
        else:
            interaction = read_interaction(
                snapshot,
                registry.interaction_protocol,
                interaction_root,
                budget=512,
            )
            expected = (
                panel_root,
                event_root,
                view_session.properties_panel_incidence,
                (panel_root,),
                transaction_root,
                view_session.subject_root,
            )
            actual = (
                interaction.control_root,
                interaction.event_root,
                interaction.target_root,
                interaction.input_roots,
                interaction.action_root,
                interaction.subject_root,
            )
            if actual != expected:
                legacy_action_versions = {
                    rule_root: b"0.1.0",
                    legacy_transaction_root: b"0.2.0",
                }
                known_legacy = (
                    actual[:4] == expected[:4]
                    and actual[4] in legacy_action_versions
                    and actual[5] == expected[5]
                )
                if not known_legacy:
                    raise InvalidCell("Properties interaction definition drifted")
                if interaction.lifecycle_root != (
                    registry.interaction_protocol.state("draft")
                ):
                    raise InvalidCell(
                        "released Properties interaction requires explicit replacement"
                    )
                members = read_relation(snapshot, interaction_root, budget=512)
                action_members = tuple(
                    member for member in members
                    if member.role_id
                    == registry.interaction_protocol.role("action")
                )
                if len(action_members) != 1:
                    raise InvalidCell("Properties interaction action incidence drifted")
                action_incidence = snapshot.cells[action_members[0].incidence_id]
                version_cell = snapshot.cells[interaction.version_root]
                digest_cell = snapshot.cells[interaction.digest_root]
                if (
                    version_cell.link0 != NULL_CELL_ID
                    or version_cell.link1 != NULL_CELL_ID
                    or version_cell.atom
                    != legacy_action_versions[interaction.action_root]
                    or digest_cell.link0 != NULL_CELL_ID
                    or digest_cell.link1 != NULL_CELL_ID
                    or digest_cell.atom
                ):
                    raise InvalidCell(
                        "legacy Properties interaction release fields drifted"
                    )
                store.commit(
                    snapshot.revision,
                    replace=(
                        Cell(
                            action_incidence.id,
                            action_incidence.link0,
                            transaction_root,
                            action_incidence.atom,
                        ),
                        Cell(
                            version_cell.id,
                            version_cell.link0,
                            version_cell.link1,
                            b"0.3.0",
                        ),
                    ),
                )
                interaction = read_interaction(
                    store.snapshot(),
                    registry.interaction_protocol,
                    interaction_root,
                    budget=512,
                )
                if interaction.action_root != transaction_root:
                    raise InvalidCell("Properties interaction migration failed")
        interaction_roots[panel_root] = interaction_root

    snapshot = store.snapshot()
    application_members = {
        member.participant_id for member in read_relation(
            snapshot, registry.application_root, budget=100_000
        )
        if member.role_id == registry.roles["member"]
    }
    required_members = {
        event_root,
        *rule_roots.values(),
        *action_roots.values(),
        *interaction_roots.values(),
    }
    missing = tuple(sorted(required_members - application_members))
    if missing:
        patch = prepare_append_relation_members(
            snapshot,
            registry.application_root,
            (
                (registry.roles["member"], root)
                for root in missing
            ),
            budget=100_000,
        )
        store.commit(
            snapshot.revision,
            create=patch.create,
            replace=patch.replace,
        )
    return event_root, MappingProxyType(interaction_roots)


def ensure_universal_relation_form_interactions(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    subject_root: str,
) -> tuple[str, Mapping[str, str]]:
    """Bind every released visual relation form to one generic interaction."""
    try:
        view_session = registry.view_sessions[subject_root]
    except KeyError as exc:
        raise AuthorizationDenied(
            "interaction subject has no provisioned application view"
        ) from exc
    event_root = "app:interaction-event:submit"
    snapshot = store.snapshot()
    if event_root not in snapshot.cells:
        store.commit(snapshot.revision, create=(Cell(
            event_root, NULL_CELL_ID, NULL_CELL_ID, b"submit"
        ),))

    interactions: dict[str, str] = {}
    subject_token = _part(subject_root)
    for form_name, form_root in sorted(registry.relation_form_roots.items()):
        form = read_relation_form_binding(
            store.snapshot(), registry.relation_form_protocol, form_root
        )
        submitted_inputs = tuple(
            spec.root_id for spec in form.input_specs
            if spec.source == "submitted"
        )
        interaction_root = "app:interaction:relation-form:%s:%s" % (
            subject_token,
            _part(form_name),
        )
        expected = (
            form.control_root,
            event_root,
            view_session.properties_lens_root,
            (form.root_id, *submitted_inputs),
            form.operation_root,
            view_session.subject_root,
        )
        snapshot = store.snapshot()
        if interaction_root not in snapshot.cells:
            build_interaction(
                store,
                registry.interaction_protocol,
                interaction_id=interaction_root,
                control_root=form.control_root,
                event_root=event_root,
                target_root=view_session.properties_lens_root,
                input_roots=(form.root_id, *submitted_inputs),
                action_root=form.operation_root,
                subject_root=view_session.subject_root,
                policy_root=registry.authorization.policy_root,
                authorization_action_root=(
                    registry.authorization.protocol.actions["edit"]
                ),
                authorization_object_root=view_session.root_id,
                authorization_scope_roots=(
                    registry.authorization.personal_view_scope_root,
                    registry.authorization.scope_root,
                ),
                authorization_purpose_root=registry.authorization.purpose_root,
                authorization_classification_root=(
                    registry.authorization.classification_root
                ),
                authorization_audience_root=registry.authorization.audience_root,
                version="0.1.0",
            )
        else:
            interaction = read_interaction(
                snapshot,
                registry.interaction_protocol,
                interaction_root,
                budget=512,
            )
            actual = (
                interaction.control_root,
                interaction.event_root,
                interaction.target_root,
                interaction.input_roots,
                interaction.action_root,
                interaction.subject_root,
            )
            if actual != expected:
                raise InvalidCell("relation-form interaction definition drifted")
        interactions[form.control_root] = interaction_root

    snapshot = store.snapshot()
    application_members = {
        member.participant_id for member in read_relation(
            snapshot, registry.application_root, budget=100_000
        )
        if member.role_id == registry.roles["member"]
    }
    required = {event_root, *interactions.values()}
    missing = tuple(sorted(required - application_members))
    if missing:
        patch = prepare_append_relation_members(
            snapshot,
            registry.application_root,
            tuple((registry.roles["member"], root) for root in missing),
            budget=100_000,
        )
        store.commit(
            snapshot.revision,
            create=patch.create,
            replace=patch.replace,
        )
    return event_root, MappingProxyType(interactions)


def _project_scope_interaction_targets(
    projection: Mapping[str, object],
) -> Mapping[str, str]:
    """Resolve the exact visible control-to-scope wiring from one projection."""
    scope = projection.get("scope")
    nodes = projection.get("nodes")
    configuration = projection.get("configuration")
    if (
        not isinstance(scope, Mapping)
        or type(nodes) is not list
        or not isinstance(configuration, Mapping)
    ):
        raise InvalidCell("scope interaction projection is incomplete")
    current_root = scope.get("current")
    trail = scope.get("trail")
    if type(current_root) is not str or type(trail) is not list:
        raise InvalidCell("scope interaction trail is invalid")

    targets: dict[str, str] = {}

    def attach(control_root: object, target_root: object) -> None:
        if (
            type(control_root) is not str
            or not control_root
            or type(target_root) is not str
            or not target_root
        ):
            raise InvalidCell("scope interaction identity is invalid")
        previous = targets.get(control_root)
        if previous is not None and previous != target_root:
            raise InvalidCell("scope control resolves multiple destinations")
        targets[control_root] = target_root

    for node in nodes:
        if not isinstance(node, Mapping):
            raise InvalidCell("scope interaction canvas node is invalid")
        if node.get("openable") is True:
            attach(node.get("id"), node.get("id"))
    for item in trail:
        if not isinstance(item, Mapping):
            raise InvalidCell("scope interaction breadcrumb is invalid")
        if item.get("root") != current_root:
            attach(item.get("root"), item.get("root"))

    design_system = configuration.get("design_system")
    control_catalog = (
        design_system.get("control_catalog")
        if isinstance(design_system, Mapping) else None
    )
    controls = (
        control_catalog.get("controls")
        if isinstance(control_catalog, Mapping) else None
    )
    if type(controls) is not list:
        raise InvalidCell("scope interaction control catalogue is invalid")
    parent_root = scope.get("parent")
    for control in controls:
        if not isinstance(control, Mapping):
            raise InvalidCell("scope interaction control is invalid")
        activation = control.get("activation")
        if (
            control.get("applicable") is True
            and isinstance(activation, Mapping)
            and activation.get("capability") == CAPABILITY_SCOPE
        ):
            attach(control.get("owner"), parent_root)
    return MappingProxyType(targets)


def ensure_universal_scope_interactions(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    subject_root: str,
    projection: Mapping[str, object],
) -> tuple[str, Mapping[str, str], Mapping[str, str]]:
    """Bind every visible graph-scope control to one exact Interaction node."""
    try:
        view_session = registry.view_sessions[subject_root]
    except KeyError as exc:
        raise AuthorizationDenied(
            "interaction subject has no provisioned application view"
        ) from exc
    event_root = "app:interaction-event:activate"
    snapshot = store.snapshot()
    if event_root not in snapshot.cells:
        store.commit(snapshot.revision, create=(Cell(
            event_root, NULL_CELL_ID, NULL_CELL_ID, b"activate"
        ),))
    elif snapshot.cells[event_root] != Cell(
        event_root, NULL_CELL_ID, NULL_CELL_ID, b"activate"
    ):
        raise InvalidCell("scope interaction event identity drifted")

    operation_root = CAPABILITY_SCOPE
    targets = _project_scope_interaction_targets(projection)
    current_root = str(projection["scope"]["current"])
    subject_token = _part(subject_root)
    interactions: dict[str, str] = {}
    interaction_batch = CellBatch(store)
    pending_interactions = False
    for control_root, target_root in sorted(targets.items()):
        token = hashlib.sha256(
            (subject_root + "\0" + control_root + "\0" + current_root
             + "\0" + target_root).encode("utf-8")
        ).hexdigest()[:24]
        interaction_root = "app:interaction:scope:%s:%s" % (
            subject_token, token
        )
        expected = (
            control_root,
            event_root,
            view_session.scope_trail_root,
            (current_root, target_root),
            operation_root,
            view_session.subject_root,
        )
        snapshot = store.snapshot()
        if interaction_root not in snapshot.cells:
            build_interaction(
                store,
                registry.interaction_protocol,
                interaction_id=interaction_root,
                control_root=control_root,
                event_root=event_root,
                target_root=view_session.scope_trail_root,
                input_roots=(current_root, target_root),
                action_root=operation_root,
                subject_root=view_session.subject_root,
                policy_root=registry.authorization.policy_root,
                authorization_action_root=(
                    registry.authorization.protocol.actions["edit"]
                ),
                authorization_object_root=view_session.root_id,
                authorization_scope_roots=(
                    registry.authorization.personal_view_scope_root,
                    registry.authorization.scope_root,
                ),
                authorization_purpose_root=registry.authorization.purpose_root,
                authorization_classification_root=(
                    registry.authorization.classification_root
                ),
                authorization_audience_root=registry.authorization.audience_root,
                version="0.1.0",
                batch=interaction_batch,
            )
            pending_interactions = True
        else:
            interaction = read_interaction(
                snapshot,
                registry.interaction_protocol,
                interaction_root,
                budget=512,
            )
            actual = (
                interaction.control_root,
                interaction.event_root,
                interaction.target_root,
                interaction.input_roots,
                interaction.action_root,
                interaction.subject_root,
            )
            if actual != expected:
                raise InvalidCell("scope interaction definition drifted")
        interactions[control_root] = interaction_root

    if pending_interactions:
        interaction_batch.commit()
    snapshot = store.snapshot()
    application_members = {
        member.participant_id for member in read_relation(
            snapshot, registry.application_root, budget=100_000
        )
        if member.role_id == registry.roles["member"]
    }
    required = {event_root, operation_root, *interactions.values()}
    missing = tuple(sorted(required - application_members))
    if missing:
        patch = prepare_append_relation_members(
            snapshot,
            registry.application_root,
            tuple((registry.roles["member"], root) for root in missing),
            budget=100_000,
        )
        store.commit(
            snapshot.revision,
            create=patch.create,
            replace=patch.replace,
        )
    return (
        event_root,
        MappingProxyType(interactions),
        targets,
    )


def ensure_universal_inspector_lens_interactions(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    subject_root: str,
    projection: Mapping[str, object],
) -> tuple[str, Mapping[str, str]]:
    """Bind every visible progressive-disclosure lens to one Interaction."""
    try:
        view_session = registry.view_sessions[subject_root]
    except KeyError as exc:
        raise AuthorizationDenied(
            "interaction subject has no provisioned application view"
        ) from exc
    inspector = projection.get("inspector")
    if not isinstance(inspector, Mapping):
        raise InvalidCell("inspector interaction projection is incomplete")
    current_root = inspector.get("active")
    lenses = inspector.get("lenses")
    if type(current_root) is not str or type(lenses) is not list:
        raise InvalidCell("inspector interaction lens projection is invalid")

    event_root = "app:interaction-event:activate"
    snapshot = store.snapshot()
    expected_event = Cell(
        event_root, NULL_CELL_ID, NULL_CELL_ID, b"activate"
    )
    if event_root not in snapshot.cells:
        store.commit(snapshot.revision, create=(expected_event,))
    elif snapshot.cells[event_root] != expected_event:
        raise InvalidCell("inspector interaction event identity drifted")

    interactions: dict[str, str] = {}
    interaction_batch = CellBatch(store)
    pending_interactions = False
    subject_token = _part(subject_root)
    for lens in lenses:
        if not isinstance(lens, Mapping) or type(lens.get("id")) is not str:
            raise InvalidCell("inspector interaction lens is invalid")
        lens_root = str(lens["id"])
        if lens_root == current_root:
            continue
        token = hashlib.sha256(
            (subject_root + "\0" + current_root + "\0" + lens_root).encode(
                "utf-8"
            )
        ).hexdigest()[:24]
        interaction_root = "app:interaction:view-section:%s:%s" % (
            subject_token, token
        )
        expected = (
            lens_root,
            event_root,
            view_session.inspector_lens_binding_root,
            (current_root, lens_root),
            CAPABILITY_VIEW_SECTION,
            view_session.subject_root,
        )
        snapshot = store.snapshot()
        if interaction_root not in snapshot.cells:
            build_interaction(
                store,
                registry.interaction_protocol,
                interaction_id=interaction_root,
                control_root=lens_root,
                event_root=event_root,
                target_root=view_session.inspector_lens_binding_root,
                input_roots=(current_root, lens_root),
                action_root=CAPABILITY_VIEW_SECTION,
                subject_root=view_session.subject_root,
                policy_root=registry.authorization.policy_root,
                authorization_action_root=(
                    registry.authorization.protocol.actions["edit"]
                ),
                authorization_object_root=view_session.root_id,
                authorization_scope_roots=(
                    registry.authorization.personal_view_scope_root,
                    registry.authorization.scope_root,
                ),
                authorization_purpose_root=registry.authorization.purpose_root,
                authorization_classification_root=(
                    registry.authorization.classification_root
                ),
                authorization_audience_root=registry.authorization.audience_root,
                version="0.1.0",
                batch=interaction_batch,
            )
            pending_interactions = True
        else:
            interaction = read_interaction(
                snapshot,
                registry.interaction_protocol,
                interaction_root,
                budget=512,
            )
            actual = (
                interaction.control_root,
                interaction.event_root,
                interaction.target_root,
                interaction.input_roots,
                interaction.action_root,
                interaction.subject_root,
            )
            if actual != expected:
                raise InvalidCell("inspector interaction definition drifted")
        interactions[lens_root] = interaction_root

    if pending_interactions:
        interaction_batch.commit()
    snapshot = store.snapshot()
    application_members = {
        member.participant_id for member in read_relation(
            snapshot, registry.application_root, budget=100_000
        )
        if member.role_id == registry.roles["member"]
    }
    required = {event_root, CAPABILITY_VIEW_SECTION, *interactions.values()}
    missing = tuple(sorted(required - application_members))
    if missing:
        patch = prepare_append_relation_members(
            snapshot,
            registry.application_root,
            tuple((registry.roles["member"], root) for root in missing),
            budget=100_000,
        )
        store.commit(
            snapshot.revision,
            create=patch.create,
            replace=patch.replace,
        )
    return event_root, MappingProxyType(interactions)


def _ensure_universal_toolbar_capability_interactions(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    subject_root: str,
    projection: Mapping[str, object],
    *,
    capability_root: str,
    family: str,
    target_root: str,
) -> tuple[str, Mapping[str, str]]:
    """Bind one generic toolbar capability to exact graph Interactions."""
    try:
        view_session = registry.view_sessions[subject_root]
    except KeyError as exc:
        raise AuthorizationDenied(
            "interaction subject has no provisioned application view"
        ) from exc
    catalog = projection.get("configuration")
    if not isinstance(catalog, Mapping):
        raise InvalidCell("%s interaction projection is incomplete" % family)
    design_system = catalog.get("design_system")
    if not isinstance(design_system, Mapping):
        raise InvalidCell("%s interaction design system is missing" % family)
    control_catalog = design_system.get("control_catalog")
    if not isinstance(control_catalog, Mapping):
        raise InvalidCell("%s interaction control catalog is missing" % family)
    controls = control_catalog.get("controls")
    if not isinstance(controls, list):
        raise InvalidCell("%s interaction controls are invalid" % family)

    event_root = "app:interaction-event:activate"
    snapshot = store.snapshot()
    expected_event = Cell(
        event_root, NULL_CELL_ID, NULL_CELL_ID, b"activate"
    )
    if event_root not in snapshot.cells:
        store.commit(snapshot.revision, create=(expected_event,))
    elif snapshot.cells[event_root] != expected_event:
        raise InvalidCell("%s interaction event identity drifted" % family)

    admitted_controls: list[tuple[str, str]] = []
    for control in controls:
        if not isinstance(control, Mapping):
            raise InvalidCell("%s interaction control is invalid" % family)
        activation = control.get("activation")
        if (
            control.get("zone") == "canvas-toolbar"
            and control.get("applicable") is True
            and isinstance(activation, Mapping)
            and activation.get("capability") == capability_root
        ):
            owner = control.get("owner")
            binding = activation.get("binding")
            if type(owner) is not str or type(binding) is not str:
                raise InvalidCell("%s interaction binding is invalid" % family)
            admitted_controls.append((owner, binding))

    interactions: dict[str, str] = {}
    interaction_batch = CellBatch(store)
    pending_interactions = False
    subject_token = _part(subject_root)
    for control_root, binding_root in sorted(admitted_controls):
        token = hashlib.sha256(
            (subject_root + "\0" + control_root + "\0" + binding_root).encode(
                "utf-8"
            )
        ).hexdigest()[:24]
        interaction_root = "app:interaction:%s:%s:%s" % (
            family,
            subject_token, token
        )
        expected = (
            control_root,
            event_root,
            target_root,
            (binding_root,),
            capability_root,
            view_session.subject_root,
        )
        snapshot = store.snapshot()
        if interaction_root not in snapshot.cells:
            build_interaction(
                store,
                registry.interaction_protocol,
                interaction_id=interaction_root,
                control_root=control_root,
                event_root=event_root,
                target_root=target_root,
                input_roots=(binding_root,),
                action_root=capability_root,
                subject_root=view_session.subject_root,
                policy_root=registry.authorization.policy_root,
                authorization_action_root=(
                    registry.authorization.protocol.actions["edit"]
                ),
                authorization_object_root=view_session.root_id,
                authorization_scope_roots=(
                    registry.authorization.personal_view_scope_root,
                    registry.authorization.scope_root,
                ),
                authorization_purpose_root=registry.authorization.purpose_root,
                authorization_classification_root=(
                    registry.authorization.classification_root
                ),
                authorization_audience_root=registry.authorization.audience_root,
                version="0.1.0",
                batch=interaction_batch,
            )
            pending_interactions = True
        else:
            interaction = read_interaction(
                snapshot,
                registry.interaction_protocol,
                interaction_root,
                budget=512,
            )
            actual = (
                interaction.control_root,
                interaction.event_root,
                interaction.target_root,
                interaction.input_roots,
                interaction.action_root,
                interaction.subject_root,
            )
            if actual != expected:
                raise InvalidCell(
                    "%s interaction definition drifted" % family
                )
        interactions[control_root] = interaction_root

    if pending_interactions:
        interaction_batch.commit()
    snapshot = store.snapshot()
    application_members = {
        member.participant_id for member in read_relation(
            snapshot, registry.application_root, budget=100_000
        )
        if member.role_id == registry.roles["member"]
    }
    required = {event_root, capability_root, *interactions.values()}
    missing = tuple(sorted(required - application_members))
    if missing:
        patch = prepare_append_relation_members(
            snapshot,
            registry.application_root,
            tuple((registry.roles["member"], root) for root in missing),
            budget=100_000,
        )
        store.commit(
            snapshot.revision,
            create=patch.create,
            replace=patch.replace,
        )
    return event_root, MappingProxyType(interactions)


def ensure_universal_composition_interactions(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    subject_root: str,
    projection: Mapping[str, object],
) -> tuple[str, Mapping[str, str]]:
    """Bind applicable composition controls to exact graph Interactions."""
    view_session = registry.view_sessions.get(subject_root)
    if view_session is None:
        raise AuthorizationDenied(
            "interaction subject has no provisioned application view"
        )
    return _ensure_universal_toolbar_capability_interactions(
        store,
        registry,
        subject_root,
        projection,
        capability_root=CAPABILITY_COMPOSITION,
        family="composition",
        target_root=view_session.selection_state_root,
    )


