def ensure_universal_event_fact_authority(
    store: CellStore,
    registry: UniversalApplicationRegistry,
) -> tuple[EventFactProtocol, Mapping[str, EventFactSpec]]:
    """Install or verify released numeric-device and submitted-text facts."""
    protocol = bootstrap_event_fact_protocol(
        store, prefix=_EVENT_FACT_PROTOCOL_PREFIX
    )
    specifications: dict[str, EventFactSpec] = {}
    definitions = (
        ("x", "canvas-point-x", 0.0, 1_000_000.0, True),
        ("y", "canvas-point-y", 0.0, 1_000_000.0, True),
        ("pan_x", "canvas-viewport-pan-x", -10_000_000.0, 10_000_000.0, False),
        ("pan_y", "canvas-viewport-pan-y", -10_000_000.0, 10_000_000.0, False),
        ("zoom", "canvas-viewport-zoom", 0.1, 4.0, False),
        (
            "participant_index",
            "relation-participant-index",
            0.0,
            1_000_000.0,
            True,
        ),
        (
            "topology_candidate_index",
            "topology-candidate-index",
            0.0,
            1_000_000.0,
            True,
        ),
    )
    for key, source, minimum, maximum, required in definitions:
        root_id = _EVENT_FACT_ROOTS[key]
        snapshot = store.snapshot()
        if root_id not in snapshot.cells:
            specification = build_event_fact_spec(
                store,
                protocol,
                spec_id=root_id,
                key=key,
                source=source,
                minimum=minimum,
                maximum=maximum,
                required=required,
                released=True,
            )
        else:
            specification = read_event_fact_spec(snapshot, protocol, root_id)
        if (
            specification.key != key
            or specification.source != source
            or specification.value_kind != "number"
            or specification.required is not required
            or specification.minimum != minimum
            or specification.maximum != maximum
            or specification.maximum_bytes is not None
        ):
            raise InvalidCell("canvas-point event-fact authority drifted")
        specifications[key] = specification

    text_root = _EVENT_FACT_ROOTS["submitted_value"]
    snapshot = store.snapshot()
    if text_root not in snapshot.cells:
        text_specification = build_event_fact_spec(
            store,
            protocol,
            spec_id=text_root,
            key="submitted_value",
            source="submitted",
            value_kind="text",
            maximum_bytes=65_536,
            required=False,
            released=True,
        )
    else:
        text_specification = read_event_fact_spec(
            snapshot, protocol, text_root
        )
    if (
        text_specification.key != "submitted_value"
        or text_specification.source != "submitted"
        or text_specification.value_kind != "text"
        or text_specification.required is not False
        or text_specification.minimum is not None
        or text_specification.maximum is not None
        or text_specification.maximum_bytes != 65_536
    ):
        raise InvalidCell("submitted-value event-fact authority drifted")
    specifications["submitted_value"] = text_specification

    snapshot = store.snapshot()
    application_members = {
        member.participant_id for member in read_relation(
            snapshot, registry.application_root, budget=100_000
        )
        if member.role_id == registry.roles["member"]
    }
    required = {
        protocol.root_id,
        CAPABILITY_INSTANTIATE,
        *(spec.root_id for spec in specifications.values()),
    }
    missing = tuple(sorted(required - application_members))
    if missing:
        patch = prepare_append_relation_members(
            snapshot,
            registry.application_root,
            tuple((registry.roles["member"], root) for root in missing),
            budget=100_000,
        )
        store.commit(
            snapshot.revision,
            create=patch.create,
            replace=patch.replace,
        )
    return protocol, MappingProxyType(specifications)


def ensure_universal_property_interactions(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    subject_root: str,
    projection: Mapping[str, object],
) -> tuple[
    Mapping[str, str],
    EventFactProtocol,
    Mapping[str, EventFactSpec],
]:
    """Bind each projected editable property to one exact value Interaction."""
    try:
        view_session = registry.view_sessions[subject_root]
    except KeyError as exc:
        raise AuthorizationDenied(
            "interaction subject has no provisioned application view"
        ) from exc
    projected_properties = projection.get("properties")
    if not isinstance(projected_properties, list):
        raise InvalidCell("property interaction projection is incomplete")
    protocol, specifications = ensure_universal_event_fact_authority(
        store, registry
    )
    submitted_spec = specifications["submitted_value"]
    event_root = "app:interaction-event:change"
    snapshot = store.snapshot()
    expected_event = Cell(event_root, NULL_CELL_ID, NULL_CELL_ID, b"change")
    if event_root not in snapshot.cells:
        store.commit(snapshot.revision, create=(expected_event,))
    elif snapshot.cells[event_root] != expected_event:
        raise InvalidCell("property interaction event identity drifted")

    editable: list[tuple[str, str, tuple[str, ...]]] = []
    batch_controls: dict[str, tuple[tuple[str, str], ...]] = {}
    for row in projected_properties:
        if not isinstance(row, Mapping):
            continue
        if row.get("batch") is True:
            control_root = row.get("relation")
            owners = row.get("owners")
            relation_roots = row.get("relations")
            value_roots = row.get("value_roots")
            label_roots = row.get("label_roots")
            if (
                type(control_root) is not str
                or not control_root
                or not all(isinstance(items, list) for items in (
                    owners, relation_roots, value_roots, label_roots,
                ))
                or any(
                    type(root) is not str or not root
                    for items in (owners, relation_roots, value_roots, label_roots)
                    for root in items
                )
            ):
                raise InvalidCell("batch property control identity is invalid")
            owner_tuple = tuple(owners)
            relation_tuple = tuple(relation_roots)
            value_tuple = tuple(value_roots)
            label_tuple = tuple(label_roots)
            expected_control = _property_batch_control_root(
                subject_root,
                owner_tuple,
                relation_tuple,
                value_tuple,
                label_tuple,
            )
            if control_root != expected_control:
                raise InvalidCell("batch property control identity drifted")
            if row.get("operation") != _PROPERTY_OPERATION_ROOTS["batch-edit"]:
                raise InvalidCell("batch property operation wiring drifted")
            if (
                len(owner_tuple) != len(set(owner_tuple))
                or len(relation_tuple) != len(set(relation_tuple))
                or len(value_tuple) != len(set(value_tuple))
            ):
                raise InvalidCell("batch property participants are duplicated")
            batch_controls[control_root] = _property_batch_control_members(
                registry,
                owner_tuple,
                relation_tuple,
                value_tuple,
                label_tuple,
            )
            if row.get("editable") is True:
                if (
                    row.get("control") != control_root
                    or row.get("event_fact_input") != submitted_spec.root_id
                ):
                    raise InvalidCell("editable batch property wiring drifted")
                editable.append((
                    control_root,
                    control_root,
                    (
                        _PROPERTY_OPERATION_ROOTS["batch-edit"],
                        control_root,
                        submitted_spec.root_id,
                    ),
                ))
            continue
        if row.get("editable") is not True:
            continue
        relation_root = row.get("relation")
        value_root = row.get("value_root")
        if (
            type(relation_root) is not str
            or not relation_root
            or type(value_root) is not str
            or not value_root
        ):
            raise InvalidCell("editable property identity is invalid")
        editable.append((
            relation_root,
            value_root,
            (relation_root, value_root, submitted_spec.root_id),
        ))
    if len(editable) != len({control for control, _target, _inputs in editable}):
        raise InvalidCell("editable property controls are duplicated")

    interactions: dict[str, str] = {}
    batch = CellBatch(store)
    pending = False
    operation_root = _PROPERTY_OPERATION_ROOTS["batch-edit"]
    expected_operation = Cell(
        operation_root, NULL_CELL_ID, NULL_CELL_ID, b"batch-edit"
    )
    current_operation = snapshot.cells.get(operation_root)
    if batch_controls:
        if current_operation is None:
            batch.add(expected_operation)
            pending = True
        elif current_operation != expected_operation:
            raise InvalidCell("batch property operation identity drifted")
    for control_root, expected_members in sorted(batch_controls.items()):
        if control_root not in snapshot.cells:
            batch.relation(expected_members, relation_id=control_root)
            pending = True
            continue
        actual_members = tuple(
            (member.role_id, member.participant_id)
            for member in read_relation(snapshot, control_root, budget=100_000)
        )
        if actual_members != expected_members:
            raise InvalidCell("batch property control relation drifted")
    subject_token = _part(subject_root)
    for control_root, target_root, inputs in sorted(editable):
        token = hashlib.sha256(
            "\0".join((subject_root, control_root, target_root, *inputs)).encode(
                "utf-8"
            )
        ).hexdigest()[:24]
        interaction_root = "app:interaction:edit-value:%s:%s" % (
            subject_token,
            token,
        )
        expected = (
            control_root,
            event_root,
            target_root,
            inputs,
            CAPABILITY_EDIT_VALUE,
            view_session.subject_root,
        )
        snapshot = store.snapshot()
        if interaction_root not in snapshot.cells:
            build_interaction(
                store,
                registry.interaction_protocol,
                interaction_id=interaction_root,
                control_root=control_root,
                event_root=event_root,
                target_root=target_root,
                input_roots=inputs,
                action_root=CAPABILITY_EDIT_VALUE,
                subject_root=view_session.subject_root,
                policy_root=registry.authorization.policy_root,
                authorization_action_root=(
                    registry.authorization.protocol.actions["edit"]
                ),
                authorization_object_root=view_session.root_id,
                authorization_scope_roots=(
                    registry.authorization.personal_view_scope_root,
                    registry.authorization.scope_root,
                ),
                authorization_purpose_root=registry.authorization.purpose_root,
                authorization_classification_root=(
                    registry.authorization.classification_root
                ),
                authorization_audience_root=registry.authorization.audience_root,
                version="0.1.0",
                batch=batch,
            )
            pending = True
        else:
            interaction = read_interaction(
                snapshot,
                registry.interaction_protocol,
                interaction_root,
                budget=512,
            )
            actual = (
                interaction.control_root,
                interaction.event_root,
                interaction.target_root,
                interaction.input_roots,
                interaction.action_root,
                interaction.subject_root,
            )
            if actual != expected:
                raise InvalidCell("property interaction definition drifted")
        interactions[control_root] = interaction_root

    if pending:
        batch.commit()
    snapshot = store.snapshot()
    application_members = {
        member.participant_id for member in read_relation(
            snapshot, registry.application_root, budget=100_000
        )
        if member.role_id == registry.roles["member"]
    }
    required = {
        event_root,
        CAPABILITY_EDIT_VALUE,
        submitted_spec.root_id,
        *((operation_root,) if batch_controls else ()),
        *batch_controls,
        *interactions.values(),
    }
    missing = tuple(sorted(required - application_members))
    if missing:
        patch = prepare_append_relation_members(
            snapshot,
            registry.application_root,
            tuple((registry.roles["member"], root) for root in missing),
            budget=100_000,
        )
        store.commit(
            snapshot.revision,
            create=patch.create,
            replace=patch.replace,
        )
    return MappingProxyType(interactions), protocol, specifications


def ensure_universal_operational_transition_interactions(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    subject_root: str,
    projection: Mapping[str, object],
) -> Mapping[str, str]:
    """Bind currently admitted operational transitions to exact UI controls.

    Evidence-backed transitions are intentionally absent until their evidence
    admission is itself a graph-issued action. A user decision is different:
    the existing state transition path issues its decision evidence from the
    authenticated subject in the same graph mutation.
    """
    try:
        view_session = registry.view_sessions[subject_root]
    except KeyError as exc:
        raise AuthorizationDenied(
            "interaction subject has no provisioned application view"
        ) from exc
    instance_root = projection.get("selected")
    assembly = projection.get("selected_assembly")
    if type(instance_root) is not str or not isinstance(assembly, Mapping):
        return MappingProxyType({})
    operational = assembly.get("operational")
    if not isinstance(operational, Mapping):
        return MappingProxyType({})
    expected_state_root = operational.get("current_state")
    transitions = operational.get("admitted_transitions")
    if type(expected_state_root) is not str or not isinstance(transitions, list):
        raise InvalidCell("operational interaction projection is incomplete")

    definitions: list[tuple[str, str, str]] = []
    for transition in transitions:
        if not isinstance(transition, Mapping):
            raise InvalidCell("operational transition projection is invalid")
        event_root = transition.get("event")
        required_evidence = transition.get("required_evidence_types")
        user_decision = transition.get("user_decision") is True
        control_root = transition.get("control")
        if not isinstance(required_evidence, list):
            raise InvalidCell("operational transition evidence is invalid")
        eligible = not required_evidence or user_decision
        if not eligible:
            if control_root is not None:
                raise InvalidCell(
                    "evidence-gated transition exposes a premature control"
                )
            continue
        if (
            type(event_root) is not str
            or not event_root
            or type(control_root) is not str
            or control_root != _operational_transition_control_root(
                subject_root,
                instance_root,
                event_root,
                expected_state_root,
            )
        ):
            raise InvalidCell("operational transition control drifted")
        definitions.append((control_root, event_root, expected_state_root))
    if len(definitions) != len({item[0] for item in definitions}):
        raise InvalidCell("operational transition controls are duplicated")

    interactions: dict[str, str] = {}
    batch = CellBatch(store)
    pending = False
    subject_token = _part(subject_root)
    for control_root, event_root, expected_state in sorted(definitions):
        snapshot = store.snapshot()
        expected_control = Cell(
            control_root,
            NULL_CELL_ID,
            NULL_CELL_ID,
            b"operational-transition",
        )
        if control_root not in snapshot.cells:
            batch.add(expected_control)
            pending = True
        elif snapshot.cells[control_root] != expected_control:
            raise InvalidCell("operational transition control identity drifted")
        token = hashlib.sha256(
            (
                subject_root + "\0" + instance_root + "\0" + event_root
                + "\0" + expected_state
            ).encode("utf-8")
        ).hexdigest()[:24]
        interaction_root = "app:interaction:operational-transition:%s:%s" % (
            subject_token,
            token,
        )
        inputs = (instance_root, event_root, expected_state)
        expected_interaction = (
            control_root,
            event_root,
            instance_root,
            inputs,
            CAPABILITY_TRANSITION,
            view_session.subject_root,
        )
        if interaction_root not in snapshot.cells:
            build_interaction(
                store,
                registry.interaction_protocol,
                interaction_id=interaction_root,
                control_root=control_root,
                event_root=event_root,
                target_root=instance_root,
                input_roots=inputs,
                action_root=CAPABILITY_TRANSITION,
                subject_root=view_session.subject_root,
                policy_root=registry.authorization.policy_root,
                authorization_action_root=(
                    registry.authorization.protocol.actions["execute"]
                ),
                authorization_object_root=instance_root,
                authorization_scope_roots=(registry.authorization.scope_root,),
                authorization_purpose_root=registry.authorization.purpose_root,
                authorization_classification_root=(
                    registry.authorization.classification_root
                ),
                authorization_audience_root=registry.authorization.audience_root,
                version="0.1.0",
                batch=batch,
            )
            pending = True
        else:
            interaction = read_interaction(
                snapshot,
                registry.interaction_protocol,
                interaction_root,
                budget=512,
            )
            actual = (
                interaction.control_root,
                interaction.event_root,
                interaction.target_root,
                interaction.input_roots,
                interaction.action_root,
                interaction.subject_root,
            )
            if actual != expected_interaction:
                raise InvalidCell("operational transition interaction drifted")
        interactions[control_root] = interaction_root

    if pending:
        batch.commit()
    snapshot = store.snapshot()
    application_members = {
        member.participant_id for member in read_relation(
            snapshot, registry.application_root, budget=100_000
        )
        if member.role_id == registry.roles["member"]
    }
    required = {
        CAPABILITY_TRANSITION,
        *(control for control, _event, _state in definitions),
        *(event for _control, event, _state in definitions),
        *interactions.values(),
    }
    missing = tuple(sorted(required - application_members))
    if missing:
        patch = prepare_append_relation_members(
            snapshot,
            registry.application_root,
            tuple((registry.roles["member"], root) for root in missing),
            budget=100_000,
        )
        store.commit(snapshot.revision, create=patch.create, replace=patch.replace)
    return MappingProxyType(interactions)


def ensure_universal_presentation_interactions(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    subject_root: str,
    projection: Mapping[str, object],
) -> tuple[
    Mapping[str, str],
    EventFactProtocol,
    Mapping[str, EventFactSpec],
]:
    """Bind visible appearance preview/reset controls to exact Interactions."""
    try:
        view_session = registry.view_sessions[subject_root]
    except KeyError as exc:
        raise AuthorizationDenied(
            "interaction subject has no provisioned application view"
        ) from exc
    projected_properties = projection.get("properties")
    if not isinstance(projected_properties, list):
        raise InvalidCell("presentation interaction projection is incomplete")
    protocol, specifications = ensure_universal_event_fact_authority(
        store, registry
    )
    submitted_spec = specifications["submitted_value"]
    events = {
        "preview": "app:interaction-event:change",
        "reset": "app:interaction-event:activate",
    }
    for name, event_root in events.items():
        expected = Cell(
            event_root,
            NULL_CELL_ID,
            NULL_CELL_ID,
            ("change" if name == "preview" else "activate").encode("ascii"),
        )
        snapshot = store.snapshot()
        if event_root not in snapshot.cells:
            store.commit(snapshot.revision, create=(expected,))
        elif snapshot.cells[event_root] != expected:
            raise InvalidCell("presentation interaction event identity drifted")

    definitions: list[
        tuple[str, str, str, str, tuple[str, ...], str]
    ] = []
    for row in projected_properties:
        if not isinstance(row, Mapping) or row.get(
            "presentation_editable"
        ) is not True:
            continue
        relation_root = row.get("relation")
        owner_root = row.get("owner")
        value_root = row.get("value_root")
        preview_control = row.get("presentation_control")
        event_fact_input = row.get("presentation_event_fact_input")
        if any(type(root) is not str or not root for root in (
            relation_root,
            owner_root,
            value_root,
            preview_control,
            event_fact_input,
        )):
            raise InvalidCell("presentation preview identity is invalid")
        if (
            preview_control != _appearance_control_root(
                subject_root,
                relation_root,
                _APPEARANCE_OPERATION_ROOTS["preview"],
            )
            or event_fact_input != submitted_spec.root_id
        ):
            raise InvalidCell("presentation preview control drifted")
        definitions.append((
            preview_control,
            _APPEARANCE_OPERATION_ROOTS["preview"],
            events["preview"],
            owner_root,
            (
                _APPEARANCE_OPERATION_ROOTS["preview"],
                relation_root,
                value_root,
                submitted_spec.root_id,
            ),
            CAPABILITY_EDIT_VALUE,
        ))
        if row.get("presentation_reset") is True:
            reset_control = row.get("presentation_reset_control")
            if (
                type(reset_control) is not str
                or not reset_control
                or reset_control != _appearance_control_root(
                    subject_root,
                    relation_root,
                    _APPEARANCE_OPERATION_ROOTS["reset"],
                )
            ):
                raise InvalidCell("presentation reset control drifted")
            definitions.append((
                reset_control,
                _APPEARANCE_OPERATION_ROOTS["reset"],
                events["reset"],
                owner_root,
                (
                    _APPEARANCE_OPERATION_ROOTS["reset"],
                    relation_root,
                    value_root,
                ),
                CAPABILITY_TRANSITION,
            ))
    configuration = projection.get("configuration")
    if not isinstance(configuration, Mapping):
        raise InvalidCell("theme interaction projection is incomplete")
    personal_asset = configuration.get("personal_asset")
    theme_fields = configuration.get("theme_fields")
    history = configuration.get("history")
    if (
        type(personal_asset) is not str
        or not personal_asset
        or not isinstance(theme_fields, list)
        or not isinstance(history, list)
    ):
        raise InvalidCell("theme interaction identities are invalid")
    for field in theme_fields:
        if not isinstance(field, Mapping):
            raise InvalidCell("theme field interaction is invalid")
        token_root = field.get("token_root")
        control_root = field.get("control")
        event_fact_input = field.get("event_fact_input")
        key = field.get("key")
        if (
            type(key) is not str
            or key not in registry.presentation.theme_roots
            or registry.presentation.theme_roots[key] != token_root
            or type(control_root) is not str
            or not control_root
            or control_root != _appearance_control_root(
                subject_root,
                token_root,
                _APPEARANCE_OPERATION_ROOTS["theme-preview"],
            )
            or event_fact_input != submitted_spec.root_id
        ):
            raise InvalidCell("theme field interaction control drifted")
        definitions.append((
            control_root,
            _APPEARANCE_OPERATION_ROOTS["theme-preview"],
            events["preview"],
            personal_asset,
            (
                _APPEARANCE_OPERATION_ROOTS["theme-preview"],
                personal_asset,
                token_root,
                submitted_spec.root_id,
            ),
            CAPABILITY_EDIT_VALUE,
        ))
    for item in history:
        if not isinstance(item, Mapping):
            raise InvalidCell("theme history interaction is invalid")
        control_root = item.get("restore_control")
        revision_root = item.get("revision")
        if item.get("current") is True:
            if control_root is not None:
                raise InvalidCell("current theme revision has a restore control")
            continue
        if (
            type(revision_root) is not str
            or not revision_root
            or type(control_root) is not str
            or not control_root
            or control_root != _appearance_control_root(
                subject_root,
                revision_root,
                _APPEARANCE_OPERATION_ROOTS["theme-restore"],
            )
        ):
            raise InvalidCell("theme restore interaction control drifted")
        definitions.append((
            control_root,
            _APPEARANCE_OPERATION_ROOTS["theme-restore"],
            events["reset"],
            personal_asset,
            (
                _APPEARANCE_OPERATION_ROOTS["theme-restore"],
                personal_asset,
                revision_root,
            ),
            CAPABILITY_TRANSITION,
        ))
    if len(definitions) != len({item[0] for item in definitions}):
        raise InvalidCell("presentation interaction controls are duplicated")

    interactions: dict[str, str] = {}
    batch = CellBatch(store)
    batched_identities: dict[str, Cell] = {}
    pending = False
    subject_token = _part(subject_root)
    for (
        control_root,
        operation_root,
        event_root,
        target_root,
        inputs,
        capability_root,
    ) in sorted(definitions, key=lambda item: item[0]):
        snapshot = store.snapshot()
        operation_name = next(
            name for name, root in _APPEARANCE_OPERATION_ROOTS.items()
            if root == operation_root
        )
        control = Cell(
            control_root,
            NULL_CELL_ID,
            NULL_CELL_ID,
            operation_name.encode("ascii"),
        )
        operation = Cell(
            operation_root,
            NULL_CELL_ID,
            NULL_CELL_ID,
            operation_name.encode("ascii"),
        )
        for expected in (control, operation):
            existing = snapshot.cells.get(expected.id)
            if existing is None:
                batched = batched_identities.get(expected.id)
                if batched is None:
                    batch.add(expected)
                    batched_identities[expected.id] = expected
                    pending = True
                elif batched != expected:
                    raise InvalidCell(
                        "presentation interaction identity collided"
                    )
            elif existing != expected:
                raise InvalidCell("presentation interaction identity drifted")
        token = hashlib.sha256(
            (subject_root + "\0" + control_root + "\0" + operation_root)
            .encode("utf-8")
        ).hexdigest()[:24]
        interaction_root = "app:interaction:appearance:%s:%s" % (
            subject_token,
            token,
        )
        expected_interaction = (
            control_root,
            event_root,
            target_root,
            inputs,
            capability_root,
            view_session.subject_root,
        )
        if interaction_root not in snapshot.cells:
            build_interaction(
                store,
                registry.interaction_protocol,
                interaction_id=interaction_root,
                control_root=control_root,
                event_root=event_root,
                target_root=target_root,
                input_roots=inputs,
                action_root=capability_root,
                subject_root=view_session.subject_root,
                policy_root=registry.authorization.policy_root,
                authorization_action_root=(
                    registry.authorization.protocol.actions[
                        "edit" if capability_root == CAPABILITY_EDIT_VALUE
                        else "restore"
                    ]
                ),
                authorization_object_root=view_session.root_id,
                authorization_scope_roots=(
                    registry.authorization.personal_view_scope_root,
                    registry.authorization.scope_root,
                ),
                authorization_purpose_root=registry.authorization.purpose_root,
                authorization_classification_root=(
                    registry.authorization.classification_root
                ),
                authorization_audience_root=registry.authorization.audience_root,
                version="0.1.0",
                batch=batch,
            )
            pending = True
        else:
            interaction = read_interaction(
                snapshot,
                registry.interaction_protocol,
                interaction_root,
                budget=512,
            )
            actual = (
                interaction.control_root,
                interaction.event_root,
                interaction.target_root,
                interaction.input_roots,
                interaction.action_root,
                interaction.subject_root,
            )
            if actual != expected_interaction:
                raise InvalidCell("presentation interaction definition drifted")
        interactions[control_root] = interaction_root

    if pending:
        batch.commit()
    snapshot = store.snapshot()
    application_members = {
        member.participant_id for member in read_relation(
            snapshot, registry.application_root, budget=100_000
        )
        if member.role_id == registry.roles["member"]
    }
    required = {
        *events.values(),
        CAPABILITY_EDIT_VALUE,
        CAPABILITY_TRANSITION,
        submitted_spec.root_id,
        *(item[1] for item in definitions),
        *(item[0] for item in definitions),
        *interactions.values(),
    }
    missing = tuple(sorted(required - application_members))
    if missing:
        patch = prepare_append_relation_members(
            snapshot,
            registry.application_root,
            tuple((registry.roles["member"], root) for root in missing),
            budget=100_000,
        )
        store.commit(
            snapshot.revision,
            create=patch.create,
            replace=patch.replace,
        )
    return MappingProxyType(interactions), protocol, specifications


def ensure_universal_interface_value_interactions(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    subject_root: str,
    projection: Mapping[str, object],
) -> tuple[
    Mapping[str, str],
    EventFactProtocol,
    Mapping[str, EventFactSpec],
]:
    """Bind projected editable scalar interfaces to exact value Interactions."""
    try:
        view_session = registry.view_sessions[subject_root]
    except KeyError as exc:
        raise AuthorizationDenied(
            "interaction subject has no provisioned application view"
        ) from exc
    projected_interfaces = projection.get("selected_interfaces")
    if not isinstance(projected_interfaces, list):
        raise InvalidCell("interface-value interaction projection is incomplete")
    protocol, specifications = ensure_universal_event_fact_authority(
        store, registry
    )
    submitted_spec = specifications["submitted_value"]
    event_root = "app:interaction-event:change"
    snapshot = store.snapshot()
    expected_event = Cell(event_root, NULL_CELL_ID, NULL_CELL_ID, b"change")
    if event_root not in snapshot.cells:
        store.commit(snapshot.revision, create=(expected_event,))
    elif snapshot.cells[event_root] != expected_event:
        raise InvalidCell("interface-value interaction event identity drifted")

    editable: list[tuple[str, str, str, str, str | None]] = []
    for interface in projected_interfaces:
        if not isinstance(interface, Mapping) or interface.get("editable") is not True:
            continue
        owner_root = interface.get("owner")
        interface_root = interface.get("id")
        if any(type(root) is not str or not root for root in (
            owner_root, interface_root,
        )):
            raise InvalidCell("editable interface identity is invalid")
        if interface.get("mode") == "connection":
            target_root = interface.get("target")
            control_root = interface.get("control")
            if any(type(root) is not str or not root for root in (
                target_root, control_root,
            )):
                raise InvalidCell("editable interface-value identity is invalid")
            if control_root != _edit_value_control_root(
                subject_root, interface_root, target_root
            ):
                raise InvalidCell("editable interface-value control drifted")
            editable.append((
                control_root, owner_root, interface_root, target_root, None
            ))
        elif interface.get("mode") == "collection":
            items = interface.get("items")
            if not isinstance(items, list):
                raise InvalidCell("editable collection items are invalid")
            for item in items:
                if not isinstance(item, Mapping):
                    raise InvalidCell("editable collection item is invalid")
                incidence_root = item.get("incidence")
                target_root = item.get("value_root")
                control_root = item.get("control")
                if any(type(root) is not str or not root for root in (
                    incidence_root, target_root, control_root,
                )):
                    raise InvalidCell("editable collection identity is invalid")
                if control_root != _edit_value_control_root(
                    subject_root, incidence_root, target_root
                ):
                    raise InvalidCell("editable collection control drifted")
                editable.append((
                    control_root,
                    owner_root,
                    interface_root,
                    target_root,
                    incidence_root,
                ))
    if len(editable) != len({control for control, *_rest in editable}):
        raise InvalidCell("editable interface-value controls are duplicated")

    interactions: dict[str, str] = {}
    batch = CellBatch(store)
    pending = False
    subject_token = _part(subject_root)
    for (
        control_root,
        owner_root,
        interface_root,
        target_root,
        incidence_root,
    ) in sorted(editable, key=lambda item: item[0]):
        snapshot = store.snapshot()
        expected_control = Cell(
            control_root, NULL_CELL_ID, NULL_CELL_ID, b"edit-value"
        )
        if control_root not in snapshot.cells:
            batch.add(expected_control)
            pending = True
        elif snapshot.cells[control_root] != expected_control:
            raise InvalidCell("interface-value control identity drifted")
        token = hashlib.sha256(
            (
                subject_root + "\0" + owner_root + "\0" + interface_root
                + "\0" + target_root + "\0" + (incidence_root or "")
            ).encode("utf-8")
        ).hexdigest()[:24]
        interaction_root = "app:interaction:edit-value:%s:%s" % (
            subject_token,
            token,
        )
        inputs = (
            (owner_root, interface_root, target_root, submitted_spec.root_id)
            if incidence_root is None else (
                owner_root,
                interface_root,
                incidence_root,
                target_root,
                submitted_spec.root_id,
            )
        )
        expected = (
            control_root,
            event_root,
            target_root,
            inputs,
            CAPABILITY_EDIT_VALUE,
            view_session.subject_root,
        )
        if interaction_root not in snapshot.cells:
            build_interaction(
                store,
                registry.interaction_protocol,
                interaction_id=interaction_root,
                control_root=control_root,
                event_root=event_root,
                target_root=target_root,
                input_roots=inputs,
                action_root=CAPABILITY_EDIT_VALUE,
                subject_root=view_session.subject_root,
                policy_root=registry.authorization.policy_root,
                authorization_action_root=(
                    registry.authorization.protocol.actions["edit"]
                ),
                authorization_object_root=view_session.root_id,
                authorization_scope_roots=(
                    registry.authorization.personal_view_scope_root,
                    registry.authorization.scope_root,
                ),
                authorization_purpose_root=registry.authorization.purpose_root,
                authorization_classification_root=(
                    registry.authorization.classification_root
                ),
                authorization_audience_root=registry.authorization.audience_root,
                version="0.1.0",
                batch=batch,
            )
            pending = True
        else:
            interaction = read_interaction(
                snapshot,
                registry.interaction_protocol,
                interaction_root,
                budget=512,
            )
            actual = (
                interaction.control_root,
                interaction.event_root,
                interaction.target_root,
                interaction.input_roots,
                interaction.action_root,
                interaction.subject_root,
            )
            if actual != expected:
                raise InvalidCell("interface-value interaction definition drifted")
        interactions[control_root] = interaction_root

    if pending:
        batch.commit()
    snapshot = store.snapshot()
    application_members = {
        member.participant_id for member in read_relation(
            snapshot, registry.application_root, budget=100_000
        )
        if member.role_id == registry.roles["member"]
    }
    required = {
        event_root,
        CAPABILITY_EDIT_VALUE,
        submitted_spec.root_id,
        *(control for control, *_rest in editable),
        *interactions.values(),
    }
    missing = tuple(sorted(required - application_members))
    if missing:
        patch = prepare_append_relation_members(
            snapshot,
            registry.application_root,
            tuple((registry.roles["member"], root) for root in missing),
            budget=100_000,
        )
        store.commit(
            snapshot.revision,
            create=patch.create,
            replace=patch.replace,
        )
    return MappingProxyType(interactions), protocol, specifications


def ensure_universal_relation_member_interactions(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    subject_root: str,
    projection: Mapping[str, object],
) -> tuple[
    Mapping[str, str],
    EventFactProtocol,
    Mapping[str, EventFactSpec],
]:
    """Bind ordered relation-member controls to exact graph Interactions."""
    try:
        view_session = registry.view_sessions[subject_root]
    except KeyError as exc:
        raise AuthorizationDenied(
            "interaction subject has no provisioned application view"
        ) from exc
    projected_interfaces = projection.get("selected_interfaces")
    if not isinstance(projected_interfaces, list):
        raise InvalidCell("relation-member interaction projection is incomplete")
    protocol, specifications = ensure_universal_event_fact_authority(
        store, registry
    )
    submitted_spec = specifications["submitted_value"]
    participant_spec = specifications["participant_index"]
    event_roots = {
        "activate": "app:interaction-event:activate",
        "change": "app:interaction-event:change",
    }
    for event_name, event_root in event_roots.items():
        expected_event = Cell(
            event_root,
            NULL_CELL_ID,
            NULL_CELL_ID,
            event_name.encode("ascii"),
        )
        snapshot = store.snapshot()
        if event_root not in snapshot.cells:
            store.commit(snapshot.revision, create=(expected_event,))
        elif snapshot.cells[event_root] != expected_event:
            raise InvalidCell(
                "relation-member interaction event identity drifted"
            )

    controls: list[
        tuple[str, str, str, str, str | None, str, str | None, str]
    ] = []
    for interface in projected_interfaces:
        if (
            not isinstance(interface, Mapping)
            or interface.get("editable") is not True
            or interface.get("mode") not in {"collection", "relation-role"}
        ):
            continue
        mode = str(interface["mode"])
        owner_root = interface.get("owner")
        interface_root = interface.get("id")
        target_root = interface.get("target")
        append_control = interface.get("append_control")
        append_fact = interface.get("append_event_fact_input")
        if any(type(root) is not str or not root for root in (
            owner_root,
            interface_root,
            target_root,
            append_control,
            append_fact,
        )):
            raise InvalidCell("collection append interaction identity is invalid")
        append_operation = _RELATION_MEMBER_OPERATION_ROOTS["append"]
        expected_append_fact = (
            submitted_spec.root_id
            if mode == "collection" else participant_spec.root_id
        )
        if append_control != _relation_member_control_root(
            subject_root, interface_root, append_operation
        ) or append_fact != expected_append_fact:
            raise InvalidCell("relation-member append control drifted")
        controls.append((
            append_control,
            owner_root,
            interface_root,
            target_root,
            None,
            append_operation,
            append_fact,
            event_roots["activate"],
        ))
        items = interface.get("items")
        if not isinstance(items, list):
            raise InvalidCell("collection relation-member items are invalid")
        for item in items:
            if not isinstance(item, Mapping):
                raise InvalidCell("collection relation-member item is invalid")
            incidence_root = item.get("incidence")
            if type(incidence_root) is not str or not incidence_root:
                raise InvalidCell("collection incidence identity is invalid")
            item_operations = (
                (
                    ("move-up", "up_control", None, "activate"),
                    ("move-down", "down_control", None, "activate"),
                    ("remove", "remove_control", None, "activate"),
                )
                if mode == "collection" else (
                    (
                        "replace",
                        "replace_control",
                        "replace_event_fact_input",
                        "change",
                    ),
                    ("remove", "remove_control", None, "activate"),
                )
            )
            for name, field, fact_field, event_name in item_operations:
                operation_root = _RELATION_MEMBER_OPERATION_ROOTS[name]
                control_root = item.get(field)
                fact_root = item.get(fact_field) if fact_field else None
                if (
                    type(control_root) is not str
                    or not control_root
                    or control_root != _relation_member_control_root(
                        subject_root, incidence_root, operation_root
                    )
                ):
                    raise InvalidCell(
                        "relation-member item control drifted"
                    )
                if (
                    fact_field is not None
                    and fact_root != participant_spec.root_id
                ):
                    raise InvalidCell(
                        "relation-member item event fact drifted"
                    )
                controls.append((
                    control_root,
                    owner_root,
                    interface_root,
                    target_root,
                    incidence_root,
                    operation_root,
                    fact_root,
                    event_roots[event_name],
                ))
    if len(controls) != len({item[0] for item in controls}):
        raise InvalidCell("relation-member interaction controls are duplicated")

    operation_names = {
        root: name for name, root in _RELATION_MEMBER_OPERATION_ROOTS.items()
    }
    snapshot = store.snapshot()
    missing_operations = []
    for operation_root in sorted({item[5] for item in controls}):
        expected_operation = Cell(
            operation_root,
            NULL_CELL_ID,
            NULL_CELL_ID,
            operation_names[operation_root].encode("ascii"),
        )
        if operation_root not in snapshot.cells:
            missing_operations.append(expected_operation)
        elif snapshot.cells[operation_root] != expected_operation:
            raise InvalidCell("relation-member operation identity drifted")
    if missing_operations:
        store.commit(snapshot.revision, create=tuple(missing_operations))

    interactions: dict[str, str] = {}
    batch = CellBatch(store)
    pending = False
    subject_token = _part(subject_root)
    for (
        control_root,
        owner_root,
        interface_root,
        target_root,
        incidence_root,
        operation_root,
        fact_root,
        event_root,
    ) in sorted(controls, key=lambda item: item[0]):
        snapshot = store.snapshot()
        expected_control = Cell(
            control_root,
            NULL_CELL_ID,
            NULL_CELL_ID,
            operation_names[operation_root].encode("ascii"),
        )
        if control_root not in snapshot.cells:
            batch.add(expected_control)
            pending = True
        elif snapshot.cells[control_root] != expected_control:
            raise InvalidCell("relation-member control identity drifted")
        inputs = (
            (owner_root, interface_root, target_root, operation_root, fact_root)
            if fact_root is not None and incidence_root is None else (
                owner_root,
                interface_root,
                target_root,
                incidence_root,
                operation_root,
                fact_root,
            ) if fact_root is not None else (
                owner_root,
                interface_root,
                target_root,
                incidence_root,
                operation_root,
            )
        )
        token = hashlib.sha256(
            (subject_root + "\0" + "\0".join(inputs)).encode("utf-8")
        ).hexdigest()[:24]
        interaction_root = "app:interaction:relation-members:%s:%s" % (
            subject_token, token
        )
        expected = (
            control_root,
            event_root,
            target_root,
            inputs,
            CAPABILITY_RELATION_MEMBERS,
            view_session.subject_root,
        )
        if interaction_root not in snapshot.cells:
            build_interaction(
                store,
                registry.interaction_protocol,
                interaction_id=interaction_root,
                control_root=control_root,
                event_root=event_root,
                target_root=target_root,
                input_roots=inputs,
                action_root=CAPABILITY_RELATION_MEMBERS,
                subject_root=view_session.subject_root,
                policy_root=registry.authorization.policy_root,
                authorization_action_root=(
                    registry.authorization.protocol.actions["edit"]
                ),
                authorization_object_root=view_session.root_id,
                authorization_scope_roots=(
                    registry.authorization.personal_view_scope_root,
                    registry.authorization.scope_root,
                ),
                authorization_purpose_root=registry.authorization.purpose_root,
                authorization_classification_root=(
                    registry.authorization.classification_root
                ),
                authorization_audience_root=(
                    registry.authorization.audience_root
                ),
                version="0.1.0",
                batch=batch,
            )
            pending = True
        else:
            interaction = read_interaction(
                snapshot,
                registry.interaction_protocol,
                interaction_root,
                budget=512,
            )
            actual = (
                interaction.control_root,
                interaction.event_root,
                interaction.target_root,
                interaction.input_roots,
                interaction.action_root,
                interaction.subject_root,
            )
            if actual != expected:
                raise InvalidCell(
                    "relation-member interaction definition drifted"
                )
        interactions[control_root] = interaction_root

    if pending:
        batch.commit()
    snapshot = store.snapshot()
    application_members = {
        member.participant_id for member in read_relation(
            snapshot, registry.application_root, budget=100_000
        )
        if member.role_id == registry.roles["member"]
    }
    required = {
        *(item[7] for item in controls),
        CAPABILITY_RELATION_MEMBERS,
        *(item[6] for item in controls if item[6] is not None),
        *(item[5] for item in controls),
        *(item[0] for item in controls),
        *interactions.values(),
    }
    missing = tuple(sorted(required - application_members))
    if missing:
        patch = prepare_append_relation_members(
            snapshot,
            registry.application_root,
            tuple((registry.roles["member"], root) for root in missing),
            budget=100_000,
        )
        store.commit(
            snapshot.revision,
            create=patch.create,
            replace=patch.replace,
        )
    return MappingProxyType(interactions), protocol, specifications


def ensure_universal_topology_interactions(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    subject_root: str,
    projection: Mapping[str, object],
) -> tuple[
    Mapping[str, str],
    EventFactProtocol,
    Mapping[str, EventFactSpec],
]:
    """Bind projected connect, detach, and rewire controls to graph Interactions."""
    try:
        view_session = registry.view_sessions[subject_root]
    except KeyError as exc:
        raise AuthorizationDenied(
            "interaction subject has no provisioned application view"
        ) from exc
    protocol, specifications = ensure_universal_event_fact_authority(
        store, registry
    )
    candidate_spec = specifications["topology_candidate_index"]
    event_roots = {
        "connect": "app:interaction-event:pointer-up",
        "disconnect": "app:interaction-event:activate",
        "rewire": "app:interaction-event:change",
    }
    event_names = {
        "connect": "pointer-up",
        "disconnect": "activate",
        "rewire": "change",
    }
    for name, event_root in event_roots.items():
        expected = Cell(
            event_root, NULL_CELL_ID, NULL_CELL_ID,
            event_names[name].encode("ascii"),
        )
        snapshot = store.snapshot()
        if event_root not in snapshot.cells:
            store.commit(snapshot.revision, create=(expected,))
        elif snapshot.cells[event_root] != expected:
            raise InvalidCell("topology interaction event identity drifted")

    operation_names = {
        root: name for name, root in _TOPOLOGY_OPERATION_ROOTS.items()
    }
    snapshot = store.snapshot()
    missing_operations = tuple(
        Cell(root, NULL_CELL_ID, NULL_CELL_ID, name.encode("ascii"))
        for root, name in operation_names.items()
        if root not in snapshot.cells
    )
    for root, name in operation_names.items():
        expected = Cell(root, NULL_CELL_ID, NULL_CELL_ID, name.encode("ascii"))
        if root in snapshot.cells and snapshot.cells[root] != expected:
            raise InvalidCell("topology operation identity drifted")
    if missing_operations:
        store.commit(snapshot.revision, create=missing_operations)

    controls: list[tuple[str, str, tuple[str, ...], str, str]] = []
    nodes = projection.get("nodes")
    wires = projection.get("wires")
    if not isinstance(nodes, list) or not isinstance(wires, list):
        raise InvalidCell("topology interaction projection is incomplete")
    for node in nodes:
        if not isinstance(node, Mapping):
            raise InvalidCell("topology node projection is invalid")
        for port in node.get("ports", ()):
            if not isinstance(port, Mapping) or not port.get("connect_control"):
                continue
            control_root = str(port["connect_control"])
            operation_root = _TOPOLOGY_OPERATION_ROOTS["connect"]
            inputs = (
                operation_root,
                str(node["id"]),
                str(port["id"]),
                candidate_spec.root_id,
            )
            if control_root != _topology_control_root(
                subject_root, str(port["id"]), operation_root
            ):
                raise InvalidCell("topology connect control drifted")
            controls.append((
                control_root,
                registry.canvas_root,
                inputs,
                event_roots["connect"],
                "connect",
            ))
    for wire in wires:
        if (
            not isinstance(wire, Mapping)
            or wire.get("nary") is True
            or wire.get("selected") is not True
        ):
            continue
        relation_root = str(wire["id"])
        disconnect_control = wire.get("disconnect_control")
        disconnect_operation = _TOPOLOGY_OPERATION_ROOTS["disconnect"]
        if (
            type(disconnect_control) is not str
            or disconnect_control != _topology_control_root(
                subject_root, relation_root, disconnect_operation
            )
        ):
            raise InvalidCell("topology disconnect control drifted")
        controls.append((
            disconnect_control,
            relation_root,
            (disconnect_operation, relation_root),
            event_roots["disconnect"],
            "disconnect",
        ))
        for side in ("source", "target"):
            incidence_root = wire.get(side + "_incidence")
            control_root = wire.get(side + "_rewire_control")
            if incidence_root is None or control_root is None:
                continue
            operation_root = _TOPOLOGY_OPERATION_ROOTS["rewire"]
            if control_root != _topology_control_root(
                subject_root, str(incidence_root), operation_root
            ):
                raise InvalidCell("topology rewire control drifted")
            controls.append((
                str(control_root),
                relation_root,
                (
                    operation_root,
                    relation_root,
                    str(incidence_root),
                    candidate_spec.root_id,
                ),
                event_roots["rewire"],
                "rewire",
            ))
    if len(controls) != len({item[0] for item in controls}):
        raise InvalidCell("topology interaction controls are duplicated")

    interactions: dict[str, str] = {}
    batch = CellBatch(store)
    pending = False
    subject_token = _part(subject_root)
    for control_root, target_root, inputs, event_root, operation in sorted(
        controls, key=lambda item: item[0]
    ):
        snapshot = store.snapshot()
        expected_control = Cell(
            control_root, NULL_CELL_ID, NULL_CELL_ID, operation.encode("ascii")
        )
        if control_root not in snapshot.cells:
            batch.add(expected_control)
            pending = True
        elif snapshot.cells[control_root] != expected_control:
            raise InvalidCell("topology control identity drifted")
        token = hashlib.sha256(
            (subject_root + "\0" + "\0".join(inputs)).encode("utf-8")
        ).hexdigest()[:24]
        interaction_root = "app:interaction:topology:%s:%s" % (
            subject_token, token
        )
        expected = (
            control_root,
            event_root,
            target_root,
            inputs,
            CAPABILITY_TOPOLOGY,
            view_session.subject_root,
        )
        if interaction_root not in snapshot.cells:
            build_interaction(
                store,
                registry.interaction_protocol,
                interaction_id=interaction_root,
                control_root=control_root,
                event_root=event_root,
                target_root=target_root,
                input_roots=inputs,
                action_root=CAPABILITY_TOPOLOGY,
                subject_root=view_session.subject_root,
                policy_root=registry.authorization.policy_root,
                authorization_action_root=(
                    registry.authorization.protocol.actions["connect"]
                ),
                authorization_object_root=view_session.root_id,
                authorization_scope_roots=(
                    registry.authorization.personal_view_scope_root,
                    registry.authorization.scope_root,
                ),
                authorization_purpose_root=registry.authorization.purpose_root,
                authorization_classification_root=(
                    registry.authorization.classification_root
                ),
                authorization_audience_root=registry.authorization.audience_root,
                version="0.1.0",
                batch=batch,
            )
            pending = True
        else:
            interaction = read_interaction(
                snapshot,
                registry.interaction_protocol,
                interaction_root,
                budget=512,
            )
            actual = (
                interaction.control_root,
                interaction.event_root,
                interaction.target_root,
                interaction.input_roots,
                interaction.action_root,
                interaction.subject_root,
            )
            if actual != expected:
                raise InvalidCell("topology interaction definition drifted")
        interactions[control_root] = interaction_root
    if pending:
        batch.commit()

    snapshot = store.snapshot()
    application_members = {
        member.participant_id for member in read_relation(
            snapshot, registry.application_root, budget=100_000
        )
        if member.role_id == registry.roles["member"]
    }
    required = {
        CAPABILITY_TOPOLOGY,
        candidate_spec.root_id,
        *event_roots.values(),
        *_TOPOLOGY_OPERATION_ROOTS.values(),
        *(item[0] for item in controls),
        *interactions.values(),
    }
    missing = tuple(sorted(required - application_members))
    if missing:
        patch = prepare_append_relation_members(
            snapshot,
            registry.application_root,
            tuple((registry.roles["member"], root) for root in missing),
            budget=100_000,
        )
        store.commit(
            snapshot.revision, create=patch.create, replace=patch.replace
        )
    return MappingProxyType(interactions), protocol, specifications


def ensure_universal_instantiation_interactions(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    subject_root: str,
    projection: Mapping[str, object],
) -> tuple[
    str,
    Mapping[str, str],
    EventFactProtocol,
    Mapping[str, EventFactSpec],
]:
    """Bind ordinary catalogue definitions to exact placement Interactions."""
    try:
        view_session = registry.view_sessions[subject_root]
    except KeyError as exc:
        raise AuthorizationDenied(
            "interaction subject has no provisioned application view"
        ) from exc
    catalogue = projection.get("catalog")
    scope = projection.get("scope")
    if not isinstance(catalogue, list) or not isinstance(scope, Mapping):
        raise InvalidCell("instantiation interaction projection is incomplete")
    target_root = scope.get("current")
    if type(target_root) is not str or not target_root:
        raise InvalidCell("instantiation interaction target is invalid")
    controls = tuple(
        item.get("id") for item in catalogue
        if isinstance(item, Mapping)
        and item.get("composition_contract") is None
        and type(item.get("id")) is str
    )
    primitive = projection.get("primitive")
    if isinstance(primitive, Mapping) and primitive.get("visible") is True:
        primitive_root = primitive.get("id")
        if type(primitive_root) is not str or primitive_root != registry.primitive_root:
            raise InvalidCell("instantiation primitive control is invalid")
        controls = (*controls, primitive_root)
    if len(controls) != len(set(controls)):
        raise InvalidCell("instantiation interaction controls are duplicated")

    protocol, specifications = ensure_universal_event_fact_authority(
        store, registry
    )
    event_root = "app:interaction-event:place"
    snapshot = store.snapshot()
    expected_event = Cell(event_root, NULL_CELL_ID, NULL_CELL_ID, b"place")
    if event_root not in snapshot.cells:
        store.commit(snapshot.revision, create=(expected_event,))
    elif snapshot.cells[event_root] != expected_event:
        raise InvalidCell("instantiation interaction event identity drifted")

    interactions: dict[str, str] = {}
    interaction_batch = CellBatch(store)
    pending = False
    subject_token = _part(subject_root)
    for definition_root in sorted(controls):
        token = hashlib.sha256(
            (subject_root + "\0" + target_root + "\0" + definition_root).encode(
                "utf-8"
            )
        ).hexdigest()[:24]
        interaction_root = "app:interaction:instantiate:%s:%s" % (
            subject_token, token
        )
        inputs = (
            definition_root,
            *(
                specifications[key].root_id
                for key in _CANVAS_POINT_FACT_KEYS
            ),
        )
        expected = (
            definition_root,
            event_root,
            target_root,
            inputs,
            CAPABILITY_INSTANTIATE,
            view_session.subject_root,
        )
        snapshot = store.snapshot()
        if interaction_root not in snapshot.cells:
            build_interaction(
                store,
                registry.interaction_protocol,
                interaction_id=interaction_root,
                control_root=definition_root,
                event_root=event_root,
                target_root=target_root,
                input_roots=inputs,
                action_root=CAPABILITY_INSTANTIATE,
                subject_root=view_session.subject_root,
                policy_root=registry.authorization.policy_root,
                authorization_action_root=(
                    registry.authorization.protocol.actions["edit"]
                ),
                authorization_object_root=view_session.root_id,
                authorization_scope_roots=(
                    registry.authorization.personal_view_scope_root,
                    registry.authorization.scope_root,
                ),
                authorization_purpose_root=registry.authorization.purpose_root,
                authorization_classification_root=(
                    registry.authorization.classification_root
                ),
                authorization_audience_root=registry.authorization.audience_root,
                version="0.1.0",
                batch=interaction_batch,
            )
            pending = True
        else:
            interaction = read_interaction(
                snapshot,
                registry.interaction_protocol,
                interaction_root,
                budget=512,
            )
            actual = (
                interaction.control_root,
                interaction.event_root,
                interaction.target_root,
                interaction.input_roots,
                interaction.action_root,
                interaction.subject_root,
            )
            if actual != expected:
                raise InvalidCell("instantiation interaction definition drifted")
        interactions[definition_root] = interaction_root

    if pending:
        interaction_batch.commit()
    snapshot = store.snapshot()
    application_members = {
        member.participant_id for member in read_relation(
            snapshot, registry.application_root, budget=100_000
        )
        if member.role_id == registry.roles["member"]
    }
    required = {event_root, *interactions.values()}
    missing = tuple(sorted(required - application_members))
    if missing:
        patch = prepare_append_relation_members(
            snapshot,
            registry.application_root,
            tuple((registry.roles["member"], root) for root in missing),
            budget=100_000,
        )
        store.commit(
            snapshot.revision,
            create=patch.create,
            replace=patch.replace,
        )
    return (
        event_root,
        MappingProxyType(interactions),
        protocol,
        specifications,
    )


def ensure_universal_relation_composer_interactions(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    subject_root: str,
    projection: Mapping[str, object],
    *,
    authentication_context: object | None = None,
) -> tuple[
    Mapping[str, str],
    EventFactProtocol,
    Mapping[str, EventFactSpec],
]:
    """Bind every projected relation-draft control to graph-held arguments."""
    try:
        view_session = registry.view_sessions[subject_root]
    except KeyError as exc:
        raise AuthorizationDenied(
            "interaction subject has no provisioned application view"
        ) from exc
    catalog = projection.get("catalog")
    if not isinstance(catalog, list):
        raise InvalidCell("relation-composer interaction catalog is invalid")
    protocol, specifications = ensure_universal_event_fact_authority(
        store, registry
    )
    events = {
        "activate": "app:interaction-event:activate",
        "change": "app:interaction-event:change",
        "place": "app:interaction-event:place",
    }
    event_atoms = {"activate": b"activate", "change": b"change", "place": b"place"}
    operation_by_root = {
        root: operation
        for operation, root in _RELATION_COMPOSER_OPERATION_ROOTS.items()
    }

    bindings: list[tuple[str, str, tuple[str, ...]]] = []
    point_roots = tuple(
        specifications[key].root_id for key in _CANVAS_POINT_FACT_KEYS
    )
    participant_index_root = specifications["participant_index"].root_id
    for definition in catalog:
        if not isinstance(definition, Mapping):
            raise InvalidCell("relation-composer catalog entry is invalid")
        definition_root = definition.get("id")
        if definition.get("composition_contract") is None:
            continue
        if type(definition_root) is not str or not definition_root:
            raise InvalidCell("relation-composer definition identity is invalid")
        bindings.append((
            definition_root,
            events["place"],
            (
                _RELATION_COMPOSER_OPERATION_ROOTS["position"],
                definition_root,
                *point_roots,
            ),
        ))

    selected = projection.get("selected_definition")
    composer = selected.get("composer") if isinstance(selected, Mapping) else None
    if composer is not None:
        if not isinstance(composer, Mapping):
            raise InvalidCell("relation-composer projection is invalid")
        definition_root = composer.get("definition")
        if (
            type(definition_root) is not str
            or selected.get("id") != definition_root
            or composer.get("position_control") != definition_root
        ):
            raise InvalidCell("relation-composer projection authority drifted")
        if composer.get("draft") is None:
            composer, _revision = update_universal_relation_composer(
                store,
                registry,
                definition_root,
                "initialize",
                mutation_route="/api/universal/interaction",
                authentication_context=authentication_context,
            )
        roles = composer.get("roles")
        if not isinstance(roles, (list, tuple)):
            raise InvalidCell("relation-composer roles are invalid")
        for role in roles:
            if not isinstance(role, Mapping):
                raise InvalidCell("relation-composer role is invalid")
            role_root = role.get("role")
            add_control = role.get("add_control")
            if type(role_root) is not str or type(add_control) is not str:
                raise InvalidCell("relation-composer role control is invalid")
            if role.get("can_add") is True:
                bindings.append((
                    add_control,
                    events["activate"],
                    (
                        _RELATION_COMPOSER_OPERATION_ROOTS["add"],
                        definition_root,
                        role_root,
                    ),
                ))
            entries = role.get("entries")
            if not isinstance(entries, (list, tuple)):
                raise InvalidCell("relation-composer entries are invalid")
            for entry in entries:
                if not isinstance(entry, Mapping):
                    raise InvalidCell("relation-composer entry is invalid")
                entry_root = entry.get("id")
                remove_control = entry.get("remove_control")
                select_control = entry.get("select_control")
                if any(type(root) is not str or not root for root in (
                    entry_root, remove_control, select_control,
                )):
                    raise InvalidCell("relation-composer entry control is invalid")
                if entry.get("remove_disabled") is not True:
                    bindings.append((
                        remove_control,
                        events["activate"],
                        (
                            _RELATION_COMPOSER_OPERATION_ROOTS["remove"],
                            definition_root,
                            role_root,
                            entry_root,
                        ),
                    ))
                choices = entry.get("choices")
                if not isinstance(choices, (list, tuple)):
                    raise InvalidCell("relation-composer choices are invalid")
                choice_roots = []
                for choice in choices:
                    if not isinstance(choice, Mapping):
                        raise InvalidCell("relation-composer choice is invalid")
                    participant_root = choice.get("id")
                    if type(participant_root) is not str or not participant_root:
                        raise InvalidCell(
                            "relation-composer choice identity is invalid"
                        )
                    choice_roots.append(participant_root)
                bindings.append((
                    select_control,
                    events["change"],
                    (
                        _RELATION_COMPOSER_OPERATION_ROOTS["select"],
                        definition_root,
                        role_root,
                        entry_root,
                        participant_index_root,
                        *choice_roots,
                    ),
                ))
        draft_root = composer.get("draft")
        create_control = composer.get("create_control")
        if type(create_control) is not str or not create_control:
            raise InvalidCell("relation-composer create control is invalid")
        if composer.get("complete") is True and type(draft_root) is str:
            bindings.append((
                create_control,
                events["activate"],
                (
                    _RELATION_COMPOSER_OPERATION_ROOTS["create"],
                    definition_root,
                    draft_root,
                ),
            ))

    control_roots = tuple(control for control, _event, _inputs in bindings)
    if len(control_roots) != len(set(control_roots)):
        raise InvalidCell("relation-composer interaction controls overlap")
    snapshot = store.snapshot()
    batch = CellBatch(store)
    pending = False
    for name, root in _RELATION_COMPOSER_OPERATION_ROOTS.items():
        expected = Cell(root, NULL_CELL_ID, NULL_CELL_ID, name.encode("ascii"))
        current = snapshot.cells.get(root)
        if current is None:
            batch.add(expected)
            pending = True
        elif current != expected or operation_by_root.get(root) != name:
            raise InvalidCell("relation-composer operation identity drifted")
    for name, root in events.items():
        expected = Cell(root, NULL_CELL_ID, NULL_CELL_ID, event_atoms[name])
        current = snapshot.cells.get(root)
        if current is None:
            batch.add(expected)
            pending = True
        elif current != expected:
            raise InvalidCell("relation-composer event identity drifted")
    definition_roots = {
        definition.get("id") for definition in catalog
        if isinstance(definition, Mapping)
        and definition.get("composition_contract") is not None
    }
    for control_root in control_roots:
        if control_root in definition_roots:
            continue
        expected = Cell(
            control_root, NULL_CELL_ID, NULL_CELL_ID, b"relation-control"
        )
        current = snapshot.cells.get(control_root)
        if current is None:
            batch.add(expected)
            pending = True
        elif current != expected:
            raise InvalidCell("relation-composer control identity drifted")

    interactions: dict[str, str] = {}
    subject_token = _part(subject_root)
    for control_root, event_root, inputs in sorted(bindings):
        token = hashlib.sha256("\0".join((
            subject_root, control_root, event_root, *inputs,
        )).encode("utf-8")).hexdigest()[:24]
        interaction_root = "app:interaction:relation-composer:%s:%s" % (
            subject_token, token,
        )
        expected = (
            control_root,
            event_root,
            view_session.root_id,
            inputs,
            CAPABILITY_COMPOSITION,
            view_session.subject_root,
        )
        if interaction_root not in snapshot.cells:
            build_interaction(
                store,
                registry.interaction_protocol,
                interaction_id=interaction_root,
                control_root=control_root,
                event_root=event_root,
                target_root=view_session.root_id,
                input_roots=inputs,
                action_root=CAPABILITY_COMPOSITION,
                subject_root=view_session.subject_root,
                policy_root=registry.authorization.policy_root,
                authorization_action_root=(
                    registry.authorization.protocol.actions["edit"]
                ),
                authorization_object_root=view_session.root_id,
                authorization_scope_roots=(
                    registry.authorization.personal_view_scope_root,
                    registry.authorization.scope_root,
                ),
                authorization_purpose_root=registry.authorization.purpose_root,
                authorization_classification_root=(
                    registry.authorization.classification_root
                ),
                authorization_audience_root=registry.authorization.audience_root,
                version="0.1.0",
                batch=batch,
            )
            pending = True
        else:
            interaction = read_interaction(
                snapshot,
                registry.interaction_protocol,
                interaction_root,
                budget=512,
            )
            actual = (
                interaction.control_root,
                interaction.event_root,
                interaction.target_root,
                interaction.input_roots,
                interaction.action_root,
                interaction.subject_root,
            )
            if actual != expected:
                raise InvalidCell(
                    "relation-composer interaction definition drifted"
                )
        interactions[control_root] = interaction_root
    if pending:
        batch.commit()

    snapshot = store.snapshot()
    application_members = {
        member.participant_id for member in read_relation(
            snapshot, registry.application_root, budget=100_000
        )
        if member.role_id == registry.roles["member"]
    }
    required = {
        *events.values(),
        *_RELATION_COMPOSER_OPERATION_ROOTS.values(),
        *control_roots,
        *interactions.values(),
    }
    missing = tuple(sorted(required - application_members))
    if missing:
        patch = prepare_append_relation_members(
            snapshot,
            registry.application_root,
            tuple((registry.roles["member"], root) for root in missing),
            budget=100_000,
        )
        store.commit(
            snapshot.revision,
            create=patch.create,
            replace=patch.replace,
        )
    return MappingProxyType(interactions), protocol, specifications


@dataclass(frozen=True, slots=True)
class _PreparedSelectionTransition:
    focus_root: str
    create: tuple[Cell, ...]
    replace: tuple[Cell, ...]


def _prepare_selection_transition(
    snapshot: Snapshot,
    registry: UniversalApplicationRegistry,
    view_session: ApplicationViewSession,
    ordered: tuple[str, ...],
    primary_root: str,
    *,
    reason_root: str = _FOCUS_REASON_GESTURE,
    consent_evidence_root: str | None = None,
    pending_roots: tuple[str, ...] = (),
    scope_root: str | None = None,
) -> _PreparedSelectionTransition:
    selected = set(ordered)
    replacements: dict[str, Cell] = {}
    selection_members = read_relation(
        snapshot, view_session.selection_state_root, budget=100_000
    )
    for member in selection_members:
        root_id, incidence_id = member.participant_id, member.incidence_id
        incidence = snapshot.cells[incidence_id]
        role_id = (
            registry.roles["selected"] if root_id in selected
            else registry.roles["available"]
        )
        if incidence.link0 != role_id:
            replacements[incidence.id] = Cell(
                incidence.id, role_id, incidence.link1, incidence.atom
            )

    focus_pointer = snapshot.cells[view_session.focus_incidence]
    current = read_focus(
        snapshot, registry.attention_protocol, focus_pointer.link1
    )
    if (
        current.session_root != view_session.root_id
        or current.state_root != registry.attention_protocol.state("active")
    ):
        raise InvalidCell("view Properties focus pointer is not active")
    focus_selection = ordered if ordered else (primary_root,)
    if scope_root is None:
        scope_root = _read_view_scope_trail(
            snapshot, registry, view_session
        )[-1]
    if (
        current.actor_root == view_session.subject_root
        and current.scope_root == scope_root
        and current.selected_roots == focus_selection
        and current.primary_root == primary_root
    ):
        return _PreparedSelectionTransition(
            current.root_id, (), tuple(replacements.values())
        )

    transition = prepare_accepted_focus_transition(
        snapshot,
        registry.attention_protocol,
        focus_id="app:focus:%s" % uuid.uuid4().hex,
        actor_root=view_session.subject_root,
        session_root=view_session.root_id,
        scope_root=scope_root,
        selected_roots=focus_selection,
        primary_root=primary_root,
        origin="user",
        reason_roots=(reason_root,),
        attention_roots=(),
        authority_root=registry.authorization.policy_root,
        consent_evidence_root=(
            consent_evidence_root or view_session.root_id
        ),
        created_at=datetime.now(timezone.utc).isoformat(),
        pending_roots=pending_roots,
    )
    for cell in transition.replace:
        replacements[cell.id] = cell
    replacements[focus_pointer.id] = Cell(
        focus_pointer.id,
        focus_pointer.link0,
        transition.root_id,
        focus_pointer.atom,
    )
    return _PreparedSelectionTransition(
        transition.root_id,
        transition.create,
        tuple(replacements.values()),
    )


def edit_universal_property(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    relation_root: str,
    value: str,
    *,
    mutation_route: str = "/api/universal/interaction",
    authentication_context: object | None = None,
) -> str:
    snapshot = store.snapshot()
    view_session, context = _view_session_for_context(
        registry, authentication_context
    )
    encoded = value.encode("utf-8")
    _authorize(
        snapshot,
        registry,
        "catalog.configure",
        object_root=relation_root,
        authentication_context=context,
        resource_usage={"max-atom-bytes": (0, len(encoded))},
    )
    _, _, property_roots = _session_canvas_roots(
        snapshot, registry, view_session
    )
    allowed = set(property_roots)
    if relation_root not in allowed:
        raise InvalidCell("property relation is outside the application lens")
    members = read_relation(snapshot, relation_root, budget=64)
    if any(member.role_id == registry.roles["read-only"] for member in members):
        raise InvalidCell("read-only graph property cannot be edited")
    label_root = _one_for_role(members, registry.roles["label"])
    if label_root is not None and _text(snapshot, label_root) == "color":
        raise InvalidCell(
            "presentation color requires a personal WIP binding"
        )
    value_roots = tuple(
        member.participant_id for member in members
        if member.role_id == registry.roles["value"]
    )
    if len(value_roots) != 1:
        raise InvalidCell("property relation requires one value participant")
    value_root = value_roots[0]
    current = snapshot.cells[value_root]
    _commit_universal_user_change(
        store,
        registry,
        view_session,
        context,
        snapshot,
        route=mutation_route,
        command_name="catalog.configure",
        authorization_scope_root=relation_root,
        replace=(Cell(current.id, current.link0, current.link1, encoded),),
    )
    return value_root


def edit_universal_property_batch(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    relation_roots: Iterable[str],
    value: str,
    *,
    mutation_route: str = "/api/universal/interaction",
    authentication_context: object | None = None,
) -> tuple[str, ...]:
    """Edit one common property across the exact active selection atomically."""
    relations = tuple(relation_roots)
    if len(relations) < 2 or len(relations) != len(set(relations)):
        raise InvalidCell("batch property edit requires unique property relations")
    if type(value) is not str:
        raise InvalidCell("batch property value must be text")

    snapshot = store.snapshot()
    view_session, context = _view_session_for_context(
        registry, authentication_context
    )
    encoded = value.encode("utf-8")
    _, _, property_roots = _session_canvas_roots(
        snapshot, registry, view_session
    )
    allowed = set(property_roots)
    selection_members = read_relation(
        snapshot, view_session.selection_state_root, budget=100_000
    )
    selected_owners = {
        member.participant_id for member in selection_members
        if member.role_id == registry.roles["selected"]
    }
    if len(selected_owners) < 2:
        raise InvalidCell("batch property edit requires an active multi-selection")

    owner_roots: list[str] = []
    value_roots: list[str] = []
    label_values: list[str] = []
    for relation_root in relations:
        if relation_root not in allowed:
            raise InvalidCell("property relation is outside the application lens")
        _authorize(
            snapshot,
            registry,
            "catalog.configure",
            object_root=relation_root,
            authentication_context=context,
            resource_usage={"max-atom-bytes": (0, len(encoded))},
        )
        members = read_relation(snapshot, relation_root, budget=64)
        if any(
            member.role_id == registry.roles["read-only"]
            for member in members
        ):
            raise InvalidCell("read-only graph property cannot be batch edited")
        owner_root = _one_for_role(members, registry.roles["owner"])
        label_root = _one_for_role(members, registry.roles["label"])
        value_root = _one_for_role(members, registry.roles["value"])
        if any(root is None for root in (owner_root, label_root, value_root)):
            raise InvalidCell("batch property relation is incomplete")
        label = _text(snapshot, label_root).strip()
        if label.casefold() == "color":
            raise InvalidCell(
                "presentation color requires a personal WIP binding"
            )
        owner_roots.append(owner_root)
        value_roots.append(value_root)
        label_values.append(label.casefold())

    if set(owner_roots) != selected_owners or len(owner_roots) != len(
        selected_owners
    ):
        raise InvalidCell("batch property relations differ from active selection")
    if len(set(owner_roots)) != len(owner_roots):
        raise InvalidCell("batch property owner is duplicated")
    if len(set(value_roots)) != len(value_roots):
        raise InvalidCell("batch property value identity is shared")
    if len(set(label_values)) != 1 or not label_values[0]:
        raise InvalidCell("batch property labels are not common")

    replacements = tuple(
        Cell(root, snapshot.cells[root].link0, snapshot.cells[root].link1, encoded)
        for root in value_roots
    )
    _commit_universal_user_change(
        store,
        registry,
        view_session,
        context,
        snapshot,
        route=mutation_route,
        command_name="catalog.configure",
        authorization_scope_root=relations[0],
        additional_authorization_scope_roots=relations[1:],
        replace=replacements,
    )
    return tuple(value_roots)


def create_universal_property(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    owner_root: str,
    label: str,
    value: str,
    *,
    authentication_context: object | None = None,
    leased_projection: Mapping[str, object] | None = None,
) -> tuple[str, int]:
    """Compose one visible owner/value/label property in one WIP commit."""
    if type(owner_root) is not str or not owner_root:
        raise InvalidCell("property owner must be one exact Cell identity")
    if type(label) is not str or type(value) is not str:
        raise InvalidCell("property label and value must be text")
    normalized_label = label.strip()
    label_bytes = normalized_label.encode("utf-8")
    value_bytes = value.encode("utf-8")
    if not normalized_label:
        raise InvalidCell("property label must be non-empty")
    if len(label_bytes) > 512 or len(value_bytes) > 65_536:
        raise InvalidCell("property text exceeds its bounded interface")

    snapshot = store.dense_snapshot()
    view_session, context = _view_session_for_context(
        registry, authentication_context
    )
    if leased_projection is None:
        visible_roots, _, _ = _session_canvas_roots(
            snapshot, registry, view_session
        )
        if owner_root not in visible_roots:
            raise InvalidCell("property owner is outside the active canvas")
    else:
        authoring = leased_projection.get("authoring")
        if (
            leased_projection.get("revision") != snapshot.revision
            or leased_projection.get("application_root")
            != registry.application_root
            or leased_projection.get("canvas_root") != registry.canvas_root
            or leased_projection.get("selected") != owner_root
            or not isinstance(authoring, Mapping)
            or authoring.get("add_property") is not True
            or authoring.get("owner") != owner_root
        ):
            raise InvalidCell("leased property authoring projection is invalid")

    binding = _require_resource_audience_authority(
        snapshot,
        registry,
        view_session.subject_root,
        (owner_root,),
    )[owner_root]
    _binding_root, lifecycle_root, signed_owner_root, _release_root = binding
    lifecycle = registry.standard_library.lifecycle_protocol
    actor_root = registry.authorization.broker.resolve(context).subject_root
    if lifecycle_root != lifecycle.states["wip"]:
        raise InvalidCell("properties can be added only to WIP resources")
    if actor_root not in (
        signed_owner_root, registry.authorization.subject_root
    ):
        raise InvalidCell("property owner is outside this subject's authority")

    if leased_projection is None:
        _all_roots, _all_relations, all_property_roots = _canvas_roots(
            snapshot, registry
        )
    else:
        all_property_roots = tuple(
            member.participant_id
            for member in read_relation(
                snapshot,
                view_session.properties_lens_root,
                budget=100_000,
            )
            if member.role_id == registry.roles["scope"]
        )
    existing_labels = {
        _text(snapshot, row.label_root).strip().casefold()
        for row in _property_index(
            snapshot, registry, all_property_roots
        ).get(owner_root, ())
    }
    if normalized_label.casefold() in existing_labels:
        raise InvalidCell("property label already exists on this Cell")

    _authorize(
        snapshot,
        registry,
        "catalog.configure",
        object_root=owner_root,
        authentication_context=context,
        resource_usage={
            "max-atom-bytes": (0, len(label_bytes) + len(value_bytes)),
            "max-collection-items": (len(existing_labels), 1),
        },
    )
    lens_roots = (
        [view_session.properties_lens_root]
        if leased_projection is not None else []
    )
    for candidate_view in registry.view_sessions.values():
        if (
            leased_projection is not None
            and candidate_view.root_id == view_session.root_id
        ):
            continue
        candidate_visible, _, _ = _session_canvas_roots(
            snapshot, registry, candidate_view
        )
        if owner_root in candidate_visible:
            lens_roots.append(candidate_view.properties_lens_root)
    if view_session.properties_lens_root not in lens_roots:
        raise InvalidCell("active Properties lens does not expose its owner")
    candidate = compose_relation_form_submission(
        snapshot,
        registry.relation_form_protocol,
        registry.relation_contract_protocol,
        registry.relation_form_roots["property"],
        {"label": normalized_label, "value": value},
        {
            "selected": owner_root,
            "properties-lenses": tuple(dict.fromkeys(lens_roots)),
        },
        budget=100_000,
    )
    reference = PropertyRef(
        candidate.relation_root,
        candidate.input_participants["value"],
        candidate.input_participants["label"],
    )
    create = list(candidate.create)
    replacements = {cell.id: cell for cell in candidate.replace}
    pending_ids = [cell.id for cell in create]
    if (
        len(pending_ids) != len(set(pending_ids))
        or any(root_id in snapshot.cells for root_id in pending_ids)
    ):
        raise InvalidCell("property creation produced invalid Cell identities")
    revision = _commit_universal_user_change(
        store,
        registry,
        view_session,
        context,
        snapshot,
        route="/api/universal/interaction",
        command_name="catalog.configure",
        authorization_scope_root=owner_root,
        create=tuple(create),
        replace=tuple(replacements.values()),
    )
    return reference.relation_root, revision


def _admit_universal_relation_form_request(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    *,
    form_root: str,
    control_binding_root: str,
    operation_root: str,
    submitted: Mapping[str, str],
    authentication_context: object | None = None,
) -> tuple[RelationFormBinding, str, Mapping[str, str], object]:
    """Resolve one browser form request entirely against released graph authority."""
    if (
        type(form_root) is not str
        or type(control_binding_root) is not str
        or type(operation_root) is not str
        or not isinstance(submitted, Mapping)
        or any(type(key) is not str or type(value) is not str
               for key, value in submitted.items())
    ):
        raise InvalidCell("relation-form request has an invalid shape")
    snapshot = store.snapshot()
    if form_root not in registry.relation_form_roots.values():
        raise InvalidCell("relation-form request is outside the released catalog")
    form = read_relation_form_binding(
        snapshot, registry.relation_form_protocol, form_root
    )
    if (
        operation_root != form.operation_root
        or operation_root != CAPABILITY_RELATION_FORM
    ):
        raise InvalidCell("relation-form operation is not the released capability")
    expected_control_binding = registry.control_binding_roots.get(
        form.control_root
    )
    if expected_control_binding != control_binding_root:
        raise InvalidCell("relation-form control binding is not released")
    control_binding = project_control_binding(
        snapshot, registry.control_binding_protocol, control_binding_root
    )
    if (
        control_binding.control_root != form.control_root
        or control_binding.capability_root != CAPABILITY_RELATION_FORM
        or control_binding.arguments.get("form") != form.root_id
    ):
        raise InvalidCell("relation-form control authority drifted")
    expected_fields = {
        spec.key for spec in form.input_specs if spec.source == "submitted"
    }
    if set(submitted) != expected_fields:
        raise InvalidCell("relation-form submission fields do not match authority")

    view_session, context = _view_session_for_context(
        registry, authentication_context
    )
    lens_members = read_relation(
        snapshot, view_session.properties_lens_root, budget=100_000
    )
    focus_root = _one_for_role(lens_members, registry.roles["focus"])
    if focus_root is None:
        raise InvalidCell("active relation-form view has no focus")
    focus = read_focus(snapshot, registry.attention_protocol, focus_root)
    if (
        focus.session_root != view_session.root_id
        or focus.actor_root != view_session.subject_root
        or focus.state_root != registry.attention_protocol.state("active")
    ):
        raise InvalidCell("relation-form focus is not the active session focus")
    selected = {
        member.participant_id
        for member in read_relation(
            snapshot, view_session.selection_state_root, budget=100_000
        )
        if member.role_id == registry.roles["selected"]
    }
    if focus.primary_root not in selected:
        raise InvalidCell("relation-form focus is outside the active selection")
    return form, focus.primary_root, MappingProxyType(dict(submitted)), context


def submit_universal_property_relation_form(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    *,
    form_root: str,
    control_binding_root: str,
    operation_root: str,
    submitted: Mapping[str, str],
    authentication_context: object | None = None,
    leased_projection: Mapping[str, object] | None = None,
) -> tuple[str, int]:
    """Submit the Property assembly through its released visual form graph."""
    form, owner_root, values, context = _admit_universal_relation_form_request(
        store,
        registry,
        form_root=form_root,
        control_binding_root=control_binding_root,
        operation_root=operation_root,
        submitted=submitted,
        authentication_context=authentication_context,
    )
    if form.root_id != registry.relation_form_roots["property"]:
        raise InvalidCell("Property endpoint requires the released Property form")
    return create_universal_property(
        store,
        registry,
        owner_root,
        values["label"],
        values["value"],
        authentication_context=context,
        leased_projection=leased_projection,
    )


def create_universal_interfaces(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    specifications: tuple[tuple[str, str, str, str], ...],
    *,
    mutation_route: str = "/api/universal/interaction",
    authentication_context: object | None = None,
    leased_projection: Mapping[str, object] | None = None,
) -> tuple[tuple[str, ...], int]:
    """Compose and register a bounded interface batch under one graph check."""
    if (
        type(specifications) is not tuple
        or not specifications
        or len(specifications) > 256
    ):
        raise InvalidCell("interface batch must be a non-empty bounded tuple")
    normalized = []
    for specification in specifications:
        if type(specification) is not tuple or len(specification) != 4:
            raise InvalidCell("interface specification has an invalid shape")
        owner_root, name, presentation_root, contract_root = specification
        if any(
            type(value) is not str or not value
            for value in (owner_root, presentation_root, contract_root)
        ) or type(name) is not str:
            raise InvalidCell(
                "interface owner, name, presentation, and contract require exact values"
            )
        normalized_name = name.strip()
        name_bytes = normalized_name.encode("utf-8")
        if not normalized_name:
            raise InvalidCell("interface name must be non-empty")
        if len(name_bytes) > 512:
            raise InvalidCell("interface name exceeds its bounded interface")
        normalized.append((
            owner_root, normalized_name, name_bytes,
            presentation_root, contract_root,
        ))

    snapshot = store.dense_snapshot()
    view_session, context = _view_session_for_context(
        registry, authentication_context
    )
    if leased_projection is None:
        visible_roots, _, _ = _session_canvas_roots(
            snapshot, registry, view_session
        )
        if any(item[0] not in visible_roots for item in normalized):
            raise InvalidCell("interface owner is outside the active canvas")
    else:
        authoring = leased_projection.get("authoring")
        owner_roots = tuple(dict.fromkeys(item[0] for item in normalized))
        if (
            leased_projection.get("revision") != snapshot.revision
            or leased_projection.get("application_root")
            != registry.application_root
            or leased_projection.get("canvas_root") != registry.canvas_root
            or len(owner_roots) != 1
            or leased_projection.get("selected") != owner_roots[0]
            or not isinstance(authoring, Mapping)
            or authoring.get("add_interface") is not True
            or authoring.get("owner") != owner_roots[0]
        ):
            raise InvalidCell("leased interface authoring projection is invalid")
        visible_roots = owner_roots

    bindings = _require_resource_audience_authority(
        snapshot,
        registry,
        view_session.subject_root,
        tuple(dict.fromkeys(item[0] for item in normalized)),
    )
    lifecycle = registry.standard_library.lifecycle_protocol
    actor_root = registry.authorization.broker.resolve(context).subject_root
    for owner_root in dict.fromkeys(item[0] for item in normalized):
        _binding_root, lifecycle_root, signed_owner_root, _release_root = (
            bindings[owner_root]
        )
        if lifecycle_root != lifecycle.states["wip"]:
            raise InvalidCell("interfaces can be added only to WIP resources")
        if actor_root not in (
            signed_owner_root, registry.authorization.subject_root
        ):
            raise InvalidCell(
                "interface owner is outside this subject's authority"
            )

    if leased_projection is None:
        registered = _registered_canvas_interfaces(snapshot, registry)
        presentation_sides = {
            str(interface["presentation_root"]): str(interface["side"])
            for interface in registered
        }
        admitted_contracts = {registry.assembly_protocol.root_id}
        admitted_contracts.update(
            str(interface["contract_root"]) for interface in registered
        )
        for visible_root in visible_roots:
            assembly = _instance_projection(snapshot, registry, visible_root)
            admitted_contracts.update(
                str(interface["contract_root"])
                for interface in (assembly or {}).get("interfaces", ())
                if interface.get("contract_root") in snapshot.cells
            )
    else:
        projected_interfaces = leased_projection.get("selected_interfaces")
        presentations = authoring.get("interface_presentations")
        contracts = authoring.get("interface_contracts")
        if (
            not isinstance(projected_interfaces, list)
            or not isinstance(presentations, list)
            or not isinstance(contracts, list)
            or any(not isinstance(item, Mapping)
                   for item in (*projected_interfaces, *presentations, *contracts))
        ):
            raise InvalidCell("leased interface catalog projection is invalid")
        registered = tuple(projected_interfaces)
        presentation_sides = {
            str(item["id"]): str(item["side"])
            for item in presentations
            if type(item.get("id")) is str
            and item.get("side") in ("source", "target")
        }
        admitted_contracts = {
            str(item["id"])
            for item in contracts
            if type(item.get("id")) is str
            and item.get("id") in snapshot.cells
        }
    pending_names = set()
    interfaces = []
    create: dict[str, Cell] = {}
    replace: dict[str, Cell] = {}
    staged = snapshot
    for owner_root, normalized_name, name_bytes, presentation_root, contract_root in normalized:
        side = presentation_sides.get(presentation_root)
        if side is None:
            raise InvalidCell("interface presentation is outside the allowlist")
        if contract_root not in admitted_contracts or contract_root not in snapshot.cells:
            raise InvalidCell("interface contract is outside the allowlist")
        owner_interfaces = tuple(
            interface for interface in registered
            if interface["owner"] == owner_root
        )
        key = (owner_root, side, normalized_name.casefold())
        if key in pending_names or any(
            interface["side"] == side
            and str(interface["name"]).strip().casefold()
            == normalized_name.casefold()
            for interface in owner_interfaces
        ):
            raise InvalidCell("interface name already exists on this side")
        pending_names.add(key)
        _authorize(
            snapshot,
            registry,
            "catalog.configure",
            object_root=owner_root,
            authentication_context=context,
            resource_usage={
                "max-atom-bytes": (0, len(name_bytes)),
                "max-collection-items": (len(owner_interfaces), 1),
            },
        )
        candidate = compose_relation_form_submission(
            staged,
            registry.relation_form_protocol,
            registry.relation_contract_protocol,
            registry.relation_form_roots["interface"],
            {
                "name": normalized_name,
                "presentation": presentation_root,
                "contract": contract_root,
            },
            {"selected": owner_root},
            budget=100_000,
        )
        interfaces.append(candidate.relation_root)
        for cell in candidate.create:
            if cell.id in staged.cells or cell.id in create:
                raise InvalidCell("interface creation produced duplicate Cells")
            create[cell.id] = cell
        for cell in candidate.replace:
            if cell.id in create:
                create[cell.id] = cell
                continue
            previous = replace.get(cell.id)
            if previous is not None and previous != staged.cells.get(cell.id):
                raise InvalidCell("interface creation patches conflict")
            replace[cell.id] = cell
        staged_candidate = overlay_read_snapshot(
            snapshot,
            create=tuple(create.values()),
            replace=tuple(replace.values()),
        )
        staged = Snapshot(snapshot.revision, staged_candidate.cells)
    create_cells = tuple(create.values())
    replace_cells = tuple(replace.values())
    create_ids = tuple(cell.id for cell in create_cells)
    if (
        len(create_ids) != len(set(create_ids))
        or any(root_id in snapshot.cells for root_id in create_ids)
    ):
        raise InvalidCell("interface creation produced invalid Cell identities")
    revision = _commit_universal_user_change(
        store,
        registry,
        view_session,
        context,
        snapshot,
        route=mutation_route,
        command_name="catalog.configure",
        authorization_scope_root=normalized[0][0],
        additional_authorization_scope_roots=tuple(
            owner_root for owner_root, *_ in normalized[1:]
        ),
        create=create_cells,
        replace=replace_cells,
    )
    return tuple(interfaces), revision


def create_universal_interface(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    owner_root: str,
    name: str,
    presentation_root: str,
    contract_root: str,
    *,
    authentication_context: object | None = None,
    leased_projection: Mapping[str, object] | None = None,
) -> tuple[str, int]:
    """Compose and register one visible connection interface atomically."""
    roots, revision = create_universal_interfaces(
        store,
        registry,
        ((owner_root, name, presentation_root, contract_root),),
        authentication_context=authentication_context,
        leased_projection=leased_projection,
    )
    return roots[0], revision


def submit_universal_interface_relation_form(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    *,
    form_root: str,
    control_binding_root: str,
    operation_root: str,
    submitted: Mapping[str, str],
    authentication_context: object | None = None,
    leased_projection: Mapping[str, object] | None = None,
) -> tuple[str, int]:
    """Submit the Interface assembly through its released visual form graph."""
    form, owner_root, values, context = _admit_universal_relation_form_request(
        store,
        registry,
        form_root=form_root,
        control_binding_root=control_binding_root,
        operation_root=operation_root,
        submitted=submitted,
        authentication_context=authentication_context,
    )
    if form.root_id != registry.relation_form_roots["interface"]:
        raise InvalidCell("Interface endpoint requires the released Interface form")
    return create_universal_interface(
        store,
        registry,
        owner_root,
        values["name"],
        values["presentation"],
        values["contract"],
        authentication_context=context,
        leased_projection=leased_projection,
    )


def submit_universal_relation_form_interaction(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    projection_broker: InteractionProjectionBroker,
    projection_handle: object,
    *,
    interaction_root: str,
    control_root: str,
    event_root: str,
    event_facts: object,
    expected_revision: int,
    projected_canvas: Mapping[str, object] | None = None,
    authentication_context: object | None = None,
) -> tuple[str, int]:
    """Admit graph-declared form facts through the universal interaction lease."""
    if type(event_facts) is not list or any(
        not isinstance(item, Mapping)
        or set(item) != {"input", "value"}
        or type(item.get("input")) is not str
        or type(item.get("value")) is not str
        for item in event_facts
    ):
        raise InvalidCell("interaction event facts have an invalid shape")
    fact_pairs = tuple(
        (item["input"], item["value"]) for item in event_facts
    )
    if len(fact_pairs) != len({root for root, _value in fact_pairs}):
        raise InvalidCell("interaction event facts repeat an input identity")

    context = _active_authentication_context(
        registry.authorization, authentication_context
    )
    operation_roots = (CAPABILITY_RELATION_FORM,)
    admission = admit_interaction(
        store,
        registry.interaction_protocol,
        registry.transaction_protocol,
        registry.rule_protocol,
        registry.authorization.protocol,
        registry.authorization.broker,
        context,
        projection_broker,
        projection_handle,
        interaction_root=interaction_root,
        control_root=control_root,
        event_root=event_root,
        expected_revision=expected_revision,
        admitted_nontransaction_action_roots=operation_roots,
        budget=100_000,
    )
    interaction = admission.interaction
    projection = _interaction_canvas_at_revision(
        store, registry, context, expected_revision, projected_canvas
    )
    matching_forms = []
    snapshot = store.dense_snapshot()
    for form_root in registry.relation_form_roots.values():
        candidate = read_relation_form_binding(
            snapshot, registry.relation_form_protocol, form_root
        )
        submitted_specs = tuple(
            spec for spec in candidate.input_specs
            if spec.source == "submitted"
        )
        if (
            candidate.control_root == interaction.control_root
            and candidate.operation_root == interaction.action_root
            and interaction.input_roots
            == (candidate.root_id, *(spec.root_id for spec in submitted_specs))
        ):
            matching_forms.append((candidate, submitted_specs))
    if len(matching_forms) != 1:
        raise InvalidCell(
            "interaction does not resolve one released relation-form contract"
        )
    form, submitted_specs = matching_forms[0]
    expected_fact_roots = {spec.root_id for spec in submitted_specs}
    if {root for root, _value in fact_pairs} != expected_fact_roots:
        raise InvalidCell(
            "interaction event facts do not match the released input contract"
        )
    facts_by_root = dict(fact_pairs)
    submitted = {
        spec.key: facts_by_root[spec.root_id] for spec in submitted_specs
    }
    control_binding_root = registry.control_binding_roots.get(form.control_root)
    if control_binding_root is None:
        raise InvalidCell("relation-form interaction control is not released")

    if form.root_id == registry.relation_form_roots["property"]:
        return submit_universal_property_relation_form(
            store,
            registry,
            form_root=form.root_id,
            control_binding_root=control_binding_root,
            operation_root=form.operation_root,
            submitted=submitted,
            authentication_context=context,
            leased_projection=projection,
        )
    if form.root_id == registry.relation_form_roots["interface"]:
        return submit_universal_interface_relation_form(
            store,
            registry,
            form_root=form.root_id,
            control_binding_root=control_binding_root,
            operation_root=form.operation_root,
            submitted=submitted,
            authentication_context=context,
            leased_projection=projection,
        )
    raise InvalidCell(
        "released relation-form interaction has no admitted application assembly"
    )


def _interaction_canvas_at_revision(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    context: object,
    expected_revision: int,
    projected_canvas: Mapping[str, object] | None,
) -> Mapping[str, object]:
    """Reuse only the exact canvas projection that minted this interaction lease."""
    if projected_canvas is None:
        return project_universal_canvas(
            store, registry, authentication_context=context
        )
    if (
        store.revision != expected_revision
        or projected_canvas.get("revision") != expected_revision
        or projected_canvas.get("application_root") != registry.application_root
        or projected_canvas.get("canvas_root") != registry.canvas_root
    ):
        raise InvalidCell("interaction canvas projection is not the leased revision")
    return projected_canvas


@with_relation_projection_scope
@with_catalog_verification_scope
def submit_universal_scope_interaction(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    projection_broker: InteractionProjectionBroker,
    projection_handle: object,
    *,
    interaction_root: str,
    control_root: str,
    event_root: str,
    expected_revision: int,
    projected_canvas: Mapping[str, object] | None = None,
    authentication_context: object | None = None,
) -> UniversalScopeExecution:
    """Execute one graph-wired scope destination through its exact lease."""
    context = _active_authentication_context(
        registry.authorization, authentication_context
    )
    operation_root = CAPABILITY_SCOPE
    admission = admit_interaction(
        store,
        registry.interaction_protocol,
        registry.transaction_protocol,
        registry.rule_protocol,
        registry.authorization.protocol,
        registry.authorization.broker,
        context,
        projection_broker,
        projection_handle,
        interaction_root=interaction_root,
        control_root=control_root,
        event_root=event_root,
        expected_revision=expected_revision,
        admitted_nontransaction_action_roots=(operation_root,),
        budget=100_000,
    )
    interaction = admission.interaction
    view_session, _ = _view_session_for_context(registry, context)
    if (
        interaction.action_root != operation_root
        or interaction.target_root != view_session.scope_trail_root
        or len(interaction.input_roots) != 2
    ):
        raise InvalidCell("scope interaction authority is invalid")
    current_root, target_root = interaction.input_roots
    projection = _interaction_canvas_at_revision(
        store, registry, context, expected_revision, projected_canvas
    )
    if projection["scope"]["current"] != current_root:
        raise InvalidCell("scope interaction current root drifted")
    targets = _project_scope_interaction_targets(projection)
    if targets.get(control_root) != target_root:
        raise InvalidCell("scope interaction destination is not projected")
    return _set_universal_scope_execution(
        store,
        registry,
        target_root,
        expected_revision=expected_revision,
        projected_canvas=projection,
        authentication_context=context,
    )


def submit_universal_inspector_lens_interaction(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    projection_broker: InteractionProjectionBroker,
    projection_handle: object,
    *,
    interaction_root: str,
    control_root: str,
    event_root: str,
    expected_revision: int,
    projected_canvas: Mapping[str, object] | None = None,
    authentication_context: object | None = None,
) -> int:
    """Execute one graph-wired inspector lens through its exact lease."""
    context = _active_authentication_context(
        registry.authorization, authentication_context
    )
    operation_root = CAPABILITY_VIEW_SECTION
    admission = admit_interaction(
        store,
        registry.interaction_protocol,
        registry.transaction_protocol,
        registry.rule_protocol,
        registry.authorization.protocol,
        registry.authorization.broker,
        context,
        projection_broker,
        projection_handle,
        interaction_root=interaction_root,
        control_root=control_root,
        event_root=event_root,
        expected_revision=expected_revision,
        admitted_nontransaction_action_roots=(operation_root,),
        budget=100_000,
    )
    interaction = admission.interaction
    view_session, _ = _view_session_for_context(registry, context)
    if (
        interaction.action_root != operation_root
        or interaction.target_root != view_session.inspector_lens_binding_root
        or len(interaction.input_roots) != 2
    ):
        raise InvalidCell("inspector lens interaction authority is invalid")
    current_root, target_root = interaction.input_roots
    projection = _interaction_canvas_at_revision(
        store, registry, context, expected_revision, projected_canvas
    )
    inspector = projection.get("inspector")
    if not isinstance(inspector, Mapping) or inspector.get("active") != current_root:
        raise InvalidCell("inspector lens interaction current root drifted")
    projected_lenses = inspector.get("lenses")
    if not isinstance(projected_lenses, list):
        raise InvalidCell("inspector lens interaction projection is invalid")
    admitted_targets = {
        lens.get("id") for lens in projected_lenses
        if isinstance(lens, Mapping) and type(lens.get("id")) is str
    }
    if control_root != target_root or target_root not in admitted_targets:
        raise InvalidCell("inspector lens interaction destination is not projected")
    return set_universal_inspector_lens(
        store,
        registry,
        target_root,
        expected_revision=expected_revision,
        projected_canvas=projection,
        authentication_context=context,
    )


def submit_universal_composition_interaction(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    projection_broker: InteractionProjectionBroker,
    projection_handle: object,
    *,
    interaction_root: str,
    control_root: str,
    event_root: str,
    expected_revision: int,
    event_facts: object | None = None,
    projected_canvas: Mapping[str, object] | None = None,
    authentication_context: object | None = None,
) -> UniversalControlExecution:
    """Execute one applicable graph-held composition control lease."""
    context = _active_authentication_context(
        registry.authorization, authentication_context
    )
    admission = admit_interaction(
        store,
        registry.interaction_protocol,
        registry.transaction_protocol,
        registry.rule_protocol,
        registry.authorization.protocol,
        registry.authorization.broker,
        context,
        projection_broker,
        projection_handle,
        interaction_root=interaction_root,
        control_root=control_root,
        event_root=event_root,
        expected_revision=expected_revision,
        admitted_nontransaction_action_roots=(CAPABILITY_COMPOSITION,),
        budget=100_000,
    )
    interaction = admission.interaction
    view_session, _ = _view_session_for_context(registry, context)
    if interaction.action_root != CAPABILITY_COMPOSITION:
        raise InvalidCell("composition interaction authority is invalid")
    if interaction.target_root == view_session.selection_state_root:
        if event_facts is not None or len(interaction.input_roots) != 1:
            raise InvalidCell("composition interaction authority is invalid")
        binding_root = interaction.input_roots[0]
        projection = _interaction_canvas_at_revision(
            store, registry, context, expected_revision, projected_canvas
        )
        controls = projection["configuration"]["design_system"][
            "control_catalog"
        ]["controls"]
        candidates = tuple(
            control for control in controls
            if control.get("owner") == control_root
            and control.get("zone") == "canvas-toolbar"
            and control.get("applicable") is True
            and control.get("activation", {}).get("capability")
            == CAPABILITY_COMPOSITION
            and control.get("activation", {}).get("binding") == binding_root
        )
        if len(candidates) != 1:
            raise InvalidCell("composition interaction control is not projected")
        return execute_universal_control(
            store,
            registry,
            binding_root,
            expected_revision=expected_revision,
            projected_canvas=projection,
            authentication_context=context,
        )
    if interaction.target_root != view_session.root_id:
        raise InvalidCell("composition interaction target is invalid")
    inputs = interaction.input_roots
    if len(inputs) < 2:
        raise InvalidCell("relation-composer interaction inputs are incomplete")
    operation_by_root = {
        root: operation
        for operation, root in _RELATION_COMPOSER_OPERATION_ROOTS.items()
    }
    operation_root = inputs[0]
    operation = operation_by_root.get(operation_root)
    if operation is None:
        raise InvalidCell("relation-composer operation is not admitted")
    definition_root = inputs[1]
    projection = _interaction_canvas_at_revision(
        store, registry, context, expected_revision, projected_canvas
    )
    selected = projection.get("selected_definition")
    composer = selected.get("composer") if isinstance(selected, Mapping) else None
    if (
        not isinstance(composer, Mapping)
        or selected.get("id") != definition_root
        or composer.get("definition") != definition_root
    ):
        raise InvalidCell("relation-composer control is not currently projected")

    if operation == "position":
        protocol, specifications = ensure_universal_event_fact_authority(
            store, registry
        )
        expected_specs = tuple(
            specifications[key].root_id for key in _CANVAS_POINT_FACT_KEYS
        )
        if (
            control_root != composer.get("position_control")
            or inputs != (operation_root, definition_root, *expected_specs)
            or event_facts is None
        ):
            raise InvalidCell("relation-composer position authority is invalid")
        values = validate_event_fact_values(
            store.snapshot(), protocol, expected_specs, event_facts
        )
        _composer, revision = update_universal_relation_composer(
            store,
            registry,
            definition_root,
            "position",
            x=values["x"],
            y=values["y"],
            mutation_route="/api/universal/interaction",
            authentication_context=context,
        )
        return UniversalControlExecution(
            operation_root,
            control_root,
            CAPABILITY_COMPOSITION,
            revision,
        )
    if operation != "select" and event_facts is not None:
        raise InvalidCell("relation-composer control carries undeclared event facts")

    roles = composer.get("roles")
    if not isinstance(roles, (list, tuple)):
        raise InvalidCell("relation-composer projected roles are invalid")
    role_root = inputs[2] if len(inputs) >= 3 else None
    role = next((
        item for item in roles
        if isinstance(item, Mapping) and item.get("role") == role_root
    ), None)
    created_root = None
    if operation == "add":
        if (
            len(inputs) != 3
            or role is None
            or role.get("can_add") is not True
            or role.get("add_control") != control_root
        ):
            raise InvalidCell("relation-composer add authority is invalid")
        _composer, revision = update_universal_relation_composer(
            store,
            registry,
            definition_root,
            "add",
            role_root=role_root,
            mutation_route="/api/universal/interaction",
            authentication_context=context,
        )
    elif operation in {"remove", "select"}:
        if (
            (operation == "remove" and len(inputs) != 4)
            or (operation == "select" and len(inputs) < 5)
        ):
            raise InvalidCell("relation-composer entry authority is invalid")
        entry_root = inputs[3]
        entries = role.get("entries") if isinstance(role, Mapping) else None
        entry = next((
            item for item in entries
            if isinstance(item, Mapping) and item.get("id") == entry_root
        ), None) if isinstance(entries, (list, tuple)) else None
        if entry is None:
            raise InvalidCell("relation-composer entry is not projected")
        if operation == "remove":
            if (
                entry.get("remove_disabled") is True
                or entry.get("remove_control") != control_root
            ):
                raise InvalidCell("relation-composer remove authority is invalid")
            _composer, revision = update_universal_relation_composer(
                store,
                registry,
                definition_root,
                "remove",
                role_root=role_root,
                entry_root=entry_root,
                mutation_route="/api/universal/interaction",
                authentication_context=context,
            )
        else:
            protocol, specifications = ensure_universal_event_fact_authority(
                store, registry
            )
            participant_spec = specifications["participant_index"]
            projected_choices = entry.get("choices")
            if not isinstance(projected_choices, (list, tuple)):
                raise InvalidCell("relation-composer choices are not projected")
            choice_roots = tuple(
                item.get("id") for item in projected_choices
                if isinstance(item, Mapping)
            )
            if (
                len(choice_roots) != len(projected_choices)
                or inputs[4] != participant_spec.root_id
                or inputs[5:] != choice_roots
                or event_facts is None
                or entry.get("select_control") != control_root
            ):
                raise InvalidCell("relation-composer select authority is invalid")
            values = validate_event_fact_values(
                store.snapshot(),
                protocol,
                (participant_spec.root_id,),
                event_facts,
            )
            participant_index = values["participant_index"]
            if (
                not float(participant_index).is_integer()
                or participant_index < 0
                or participant_index > len(choice_roots)
            ):
                raise InvalidCell(
                    "relation-composer participant index is outside its choices"
                )
            submitted_participant = (
                None
                if int(participant_index) == 0
                else choice_roots[int(participant_index) - 1]
            )
            _composer, revision = update_universal_relation_composer(
                store,
                registry,
                definition_root,
                "select",
                role_root=role_root,
                entry_root=entry_root,
                participant_root=submitted_participant,
                mutation_route="/api/universal/interaction",
                authentication_context=context,
            )
    elif operation == "create":
        if (
            len(inputs) != 3
            or role is not None
            or composer.get("draft") != inputs[2]
            or composer.get("create_control") != control_root
            or composer.get("complete") is not True
            or composer.get("x") is None
            or composer.get("y") is None
        ):
            raise InvalidCell("relation-composer create authority is invalid")
        created_root, revision = instantiate_universal_relation_composer(
            store,
            registry,
            definition_root,
            mutation_route="/api/universal/interaction",
            authentication_context=context,
        )
    else:
        raise InvalidCell("relation-composer operation is not admitted")
    return UniversalControlExecution(
        operation_root,
        control_root,
        CAPABILITY_COMPOSITION,
        revision,
        created_root,
    )


