def submit_universal_edit_value_interaction(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    projection_broker: InteractionProjectionBroker,
    projection_handle: object,
    *,
    interaction_root: str,
    control_root: str,
    event_root: str,
    event_facts: object,
    expected_revision: int,
    projected_canvas: Mapping[str, object] | None = None,
    authentication_context: object | None = None,
) -> UniversalControlExecution:
    """Replace one projected scalar value through its exact graph lease."""
    context = _active_authentication_context(
        registry.authorization, authentication_context
    )
    admission = admit_interaction(
        store,
        registry.interaction_protocol,
        registry.transaction_protocol,
        registry.rule_protocol,
        registry.authorization.protocol,
        registry.authorization.broker,
        context,
        projection_broker,
        projection_handle,
        interaction_root=interaction_root,
        control_root=control_root,
        event_root=event_root,
        expected_revision=expected_revision,
        admitted_nontransaction_action_roots=(CAPABILITY_EDIT_VALUE,),
        budget=100_000,
    )
    interaction = admission.interaction
    if interaction.action_root != CAPABILITY_EDIT_VALUE:
        raise InvalidCell("edit-value interaction authority is invalid")
    protocol, specifications = ensure_universal_event_fact_authority(
        store, registry
    )
    submitted_spec = specifications["submitted_value"]
    projection = _interaction_canvas_at_revision(
        store, registry, context, expected_revision, projected_canvas
    )
    inputs = interaction.input_roots
    property_candidate = None
    batch_property_candidate = None
    presentation_candidate = None
    theme_candidate = None
    interface_candidate = None
    collection_candidate = None
    value_root = None
    submitted_spec_root = inputs[-1] if inputs else None
    if len(inputs) == 3 and inputs[0] == _PROPERTY_OPERATION_ROOTS["batch-edit"]:
        _operation_root, batch_control_root, submitted_spec_root = inputs
        projected_properties = projection.get("properties")
        if not isinstance(projected_properties, list):
            raise InvalidCell("batch property interaction projection is incomplete")
        candidates = tuple(
            row for row in projected_properties
            if isinstance(row, Mapping)
            and row.get("batch") is True
            and row.get("relation") == batch_control_root
            and row.get("control") == control_root
            and row.get("event_fact_input") == submitted_spec_root
            and row.get("editable") is True
        )
        if len(candidates) == 1:
            candidate = candidates[0]
            owners = candidate.get("owners")
            relation_roots = candidate.get("relations")
            value_roots = candidate.get("value_roots")
            label_roots = candidate.get("label_roots")
            if not all(isinstance(items, list) for items in (
                owners, relation_roots, value_roots, label_roots,
            )):
                raise InvalidCell("batch property participants are incomplete")
            expected_members = _property_batch_control_members(
                registry,
                tuple(owners),
                tuple(relation_roots),
                tuple(value_roots),
                tuple(label_roots),
            )
            actual_members = tuple(
                (member.role_id, member.participant_id)
                for member in read_relation(
                    store.snapshot(), batch_control_root, budget=100_000
                )
            )
            if actual_members != expected_members:
                raise InvalidCell("batch property control relation drifted")
            batch_property_candidate = candidate
        value_root = batch_control_root
    elif len(inputs) == 3:
        relation_root, value_root, submitted_spec_root = inputs
        projected_properties = projection.get("properties")
        if not isinstance(projected_properties, list):
            raise InvalidCell("property interaction projection is incomplete")
        candidates = tuple(
            row for row in projected_properties
            if isinstance(row, Mapping)
            and row.get("relation") == relation_root
            and row.get("value_root") == value_root
            and row.get("control") == control_root
            and row.get("event_fact_input") == submitted_spec_root
            and row.get("editable") is True
        )
        if len(candidates) == 1:
            property_candidate = candidates[0]
    elif len(inputs) == 4:
        if inputs[0] == _APPEARANCE_OPERATION_ROOTS["preview"]:
            (
                _operation_root,
                relation_root,
                value_root,
                submitted_spec_root,
            ) = inputs
            projected_properties = projection.get("properties")
            if not isinstance(projected_properties, list):
                raise InvalidCell(
                    "presentation interaction projection is incomplete"
                )
            candidates = tuple(
                row for row in projected_properties
                if isinstance(row, Mapping)
                and row.get("relation") == relation_root
                and row.get("value_root") == value_root
                and row.get("presentation_control") == control_root
                and row.get("presentation_event_fact_input")
                == submitted_spec_root
                and row.get("presentation_editable") is True
                and row.get("owner") == interaction.target_root
            )
            if len(candidates) == 1:
                presentation_candidate = candidates[0]
        elif inputs[0] == _APPEARANCE_OPERATION_ROOTS["theme-preview"]:
            (
                _operation_root,
                personal_asset,
                token_root,
                submitted_spec_root,
            ) = inputs
            configuration = projection.get("configuration")
            theme_fields = (
                configuration.get("theme_fields")
                if isinstance(configuration, Mapping) else None
            )
            if not isinstance(theme_fields, list):
                raise InvalidCell("theme interaction projection is incomplete")
            candidates = tuple(
                field for field in theme_fields
                if isinstance(field, Mapping)
                and field.get("token_root") == token_root
                and field.get("control") == control_root
                and field.get("event_fact_input") == submitted_spec_root
                and personal_asset == configuration.get("personal_asset")
                and interaction.target_root == personal_asset
            )
            if len(candidates) == 1:
                theme_candidate = candidates[0]
        else:
            owner_root, interface_root, value_root, submitted_spec_root = inputs
            projected_interfaces = projection.get("selected_interfaces")
            if not isinstance(projected_interfaces, list):
                raise InvalidCell(
                    "interface-value interaction projection is incomplete"
                )
            candidates = tuple(
                interface for interface in projected_interfaces
                if isinstance(interface, Mapping)
                and interface.get("owner") == owner_root
                and interface.get("id") == interface_root
                and interface.get("target") == value_root
                and interface.get("control") == control_root
                and interface.get("event_fact_input") == submitted_spec_root
                and interface.get("editable") is True
                and interface.get("mode") == "connection"
            )
            if len(candidates) == 1:
                interface_candidate = candidates[0]
    elif len(inputs) == 5:
        (
            owner_root,
            interface_root,
            incidence_root,
            value_root,
            submitted_spec_root,
        ) = inputs
        projected_interfaces = projection.get("selected_interfaces")
        if not isinstance(projected_interfaces, list):
            raise InvalidCell("collection interaction projection is incomplete")
        candidates = []
        for interface in projected_interfaces:
            if (
                not isinstance(interface, Mapping)
                or interface.get("owner") != owner_root
                or interface.get("id") != interface_root
                or interface.get("editable") is not True
                or interface.get("mode") != "collection"
            ):
                continue
            items = interface.get("items")
            if not isinstance(items, list):
                continue
            for item in items:
                if (
                    isinstance(item, Mapping)
                    and item.get("incidence") == incidence_root
                    and item.get("value_root") == value_root
                    and item.get("control") == control_root
                    and item.get("event_fact_input") == submitted_spec_root
                ):
                    candidates.append((interface, item))
        if len(candidates) == 1:
            collection_candidate = candidates[0]
    if (
        submitted_spec_root != submitted_spec.root_id
        or interaction.target_root != (
            presentation_candidate.get("owner")
            if presentation_candidate is not None else (
                projection["configuration"].get("personal_asset")
                if theme_candidate is not None else value_root
            )
        )
        or sum(candidate is not None for candidate in (
            property_candidate,
            batch_property_candidate,
            presentation_candidate,
            theme_candidate,
            interface_candidate,
            collection_candidate,
        )) != 1
    ):
        raise InvalidCell("edit-value interaction wiring is invalid")
    values = validate_event_fact_values(
        store.snapshot(),
        protocol,
        (submitted_spec_root,),
        event_facts,
    )
    value = values["submitted_value"]
    if type(value) is not str:
        raise InvalidCell("edit-value interaction value is not text")
    if theme_candidate is not None:
        configuration = projection["configuration"]
        personal_wip_heads = configuration.get("personal_wip_heads")
        if (
            not isinstance(personal_wip_heads, list)
            or len(personal_wip_heads) != 1
            or type(personal_wip_heads[0]) is not str
        ):
            raise InvalidCell("theme preview requires one personal WIP head")
        preview_universal_theme(
            store,
            registry,
            {str(theme_candidate["key"]): value},
            base_revision_root=personal_wip_heads[0],
            authentication_context=context,
        )
    elif presentation_candidate is not None:
        preview_universal_presentation_color(
            store,
            registry,
            str(presentation_candidate["owner"]),
            value,
            base_revision_root=(
                str(presentation_candidate["presentation_revision"])
                if presentation_candidate.get("presentation_revision")
                else None
            ),
            authentication_context=context,
        )
    elif property_candidate is not None:
        edited_root = edit_universal_property(
            store,
            registry,
            str(property_candidate["relation"]),
            value,
            mutation_route="/api/universal/interaction",
            authentication_context=context,
        )
        if edited_root != value_root:
            raise InvalidCell("property interaction edited an unexpected value")
    elif batch_property_candidate is not None:
        edited_roots = edit_universal_property_batch(
            store,
            registry,
            tuple(batch_property_candidate["relations"]),
            value,
            mutation_route="/api/universal/interaction",
            authentication_context=context,
        )
        if edited_roots != tuple(batch_property_candidate["value_roots"]):
            raise InvalidCell("batch property interaction edited unexpected values")
    elif interface_candidate is not None:
        revision = edit_universal_interface_value(
            store,
            registry,
            str(interface_candidate["owner"]),
            str(interface_candidate["id"]),
            value,
            mutation_route="/api/universal/interaction",
            authentication_context=context,
        )
        if revision != store.revision:
            raise InvalidCell("interface interaction revision drifted")
    else:
        collection_interface, collection_item = collection_candidate
        revision = edit_universal_interface_collection(
            store,
            registry,
            str(collection_interface["owner"]),
            str(collection_interface["id"]),
            "edit",
            value=value,
            incidence_id=str(collection_item["incidence"]),
            mutation_route="/api/universal/interaction",
            authentication_context=context,
        )
        if revision != store.revision:
            raise InvalidCell("collection interaction revision drifted")
    return UniversalControlExecution(
        CAPABILITY_EDIT_VALUE,
        control_root,
        CAPABILITY_EDIT_VALUE,
        store.revision,
    )


def submit_universal_transition_interaction(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    projection_broker: InteractionProjectionBroker,
    projection_handle: object,
    *,
    interaction_root: str,
    control_root: str,
    event_root: str,
    expected_revision: int,
    event_facts: object | None = None,
    projected_canvas: Mapping[str, object] | None = None,
    authentication_context: object | None = None,
) -> UniversalControlExecution:
    """Execute one graph-declared state transition from its current lease."""
    context = _active_authentication_context(
        registry.authorization, authentication_context
    )
    admission = admit_interaction(
        store,
        registry.interaction_protocol,
        registry.transaction_protocol,
        registry.rule_protocol,
        registry.authorization.protocol,
        registry.authorization.broker,
        context,
        projection_broker,
        projection_handle,
        interaction_root=interaction_root,
        control_root=control_root,
        event_root=event_root,
        expected_revision=expected_revision,
        admitted_nontransaction_action_roots=(CAPABILITY_TRANSITION,),
        budget=100_000,
    )
    interaction = admission.interaction
    if interaction.action_root != CAPABILITY_TRANSITION or event_facts is not None:
        raise InvalidCell("transition interaction authority is invalid")
    projection = _interaction_canvas_at_revision(
        store, registry, context, expected_revision, projected_canvas
    )
    if len(interaction.input_roots) == 3 and interaction.input_roots[0] not in (
        _APPEARANCE_OPERATION_ROOTS["reset"],
        _APPEARANCE_OPERATION_ROOTS["theme-restore"],
    ):
        instance_root, transition_event_root, expected_state_root = (
            interaction.input_roots
        )
        assembly = projection.get("selected_assembly")
        if (
            interaction.target_root != instance_root
            or projection.get("selected") != instance_root
            or not isinstance(assembly, Mapping)
            or not isinstance(assembly.get("operational"), Mapping)
        ):
            raise InvalidCell("operational transition interaction target is invalid")
        operational = assembly["operational"]
        candidates = tuple(
            item for item in operational.get("admitted_transitions", ())
            if isinstance(item, Mapping)
            and item.get("event") == transition_event_root
            and item.get("control") == control_root
            and operational.get("current_state") == expected_state_root
            and (
                not item.get("required_evidence_types")
                or item.get("user_decision") is True
            )
        )
        if len(candidates) != 1:
            raise InvalidCell("operational transition interaction wiring is invalid")
        transition_universal_operational_state(
            store,
            registry,
            instance_root,
            transition_event_root,
            expected_state_root,
            authentication_context=context,
        )
        return UniversalControlExecution(
            CAPABILITY_TRANSITION,
            control_root,
            CAPABILITY_TRANSITION,
            store.revision,
        )
    if (
        len(interaction.input_roots) != 3
        or interaction.input_roots[0] not in (
            _APPEARANCE_OPERATION_ROOTS["reset"],
            _APPEARANCE_OPERATION_ROOTS["theme-restore"],
        )
    ):
        raise InvalidCell("transition interaction authority is invalid")
    operation_root, authority_root, value_root = interaction.input_roots
    if operation_root == _APPEARANCE_OPERATION_ROOTS["reset"]:
        properties = projection.get("properties")
        if not isinstance(properties, list):
            raise InvalidCell("transition interaction projection is incomplete")
        candidates = tuple(
            row for row in properties
            if isinstance(row, Mapping)
            and row.get("relation") == authority_root
            and row.get("value_root") == value_root
            and row.get("owner") == interaction.target_root
            and row.get("presentation_reset") is True
            and row.get("presentation_reset_control") == control_root
        )
        if len(candidates) != 1:
            raise InvalidCell("transition interaction wiring is invalid")
        candidate = candidates[0]
        reset_universal_presentation_color(
            store,
            registry,
            str(candidate["owner"]),
            base_revision_root=(
                str(candidate["presentation_revision"])
                if candidate.get("presentation_revision") else None
            ),
            authentication_context=context,
        )
    else:
        configuration = projection.get("configuration")
        if (
            not isinstance(configuration, Mapping)
            or configuration.get("personal_asset") != authority_root
            or interaction.target_root != authority_root
        ):
            raise InvalidCell("theme restore target is invalid")
        history = configuration.get("history")
        if not isinstance(history, list):
            raise InvalidCell("theme restore history is invalid")
        candidates = tuple(
            item for item in history
            if isinstance(item, Mapping)
            and item.get("revision") == value_root
            and item.get("current") is False
            and item.get("restore_control") == control_root
        )
        personal_wip_heads = configuration.get("personal_wip_heads")
        if (
            len(candidates) != 1
            or not isinstance(personal_wip_heads, list)
            or len(personal_wip_heads) != 1
            or type(personal_wip_heads[0]) is not str
        ):
            raise InvalidCell("theme restore interaction wiring is invalid")
        restore_universal_theme_revision(
            store,
            registry,
            value_root,
            base_revision_root=personal_wip_heads[0],
            authentication_context=context,
        )
    return UniversalControlExecution(
        CAPABILITY_TRANSITION,
        control_root,
        CAPABILITY_TRANSITION,
        store.revision,
    )


def submit_universal_relation_member_interaction(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    projection_broker: InteractionProjectionBroker,
    projection_handle: object,
    *,
    interaction_root: str,
    control_root: str,
    event_root: str,
    event_facts: object | None,
    expected_revision: int,
    projected_canvas: Mapping[str, object] | None = None,
    authentication_context: object | None = None,
) -> UniversalControlExecution:
    """Apply one exact ordered relation-member operation from its graph lease."""
    context = _active_authentication_context(
        registry.authorization, authentication_context
    )
    admission = admit_interaction(
        store,
        registry.interaction_protocol,
        registry.transaction_protocol,
        registry.rule_protocol,
        registry.authorization.protocol,
        registry.authorization.broker,
        context,
        projection_broker,
        projection_handle,
        interaction_root=interaction_root,
        control_root=control_root,
        event_root=event_root,
        expected_revision=expected_revision,
        admitted_nontransaction_action_roots=(
            CAPABILITY_RELATION_MEMBERS,
        ),
        budget=100_000,
    )
    interaction = admission.interaction
    if interaction.action_root != CAPABILITY_RELATION_MEMBERS:
        raise InvalidCell("relation-member interaction authority is invalid")
    inputs = interaction.input_roots
    if len(inputs) == 5:
        owner_root, interface_root, target_root, fourth_root, fifth_root = inputs
        sixth_root = None
    elif len(inputs) == 6:
        (
            owner_root,
            interface_root,
            target_root,
            fourth_root,
            fifth_root,
            sixth_root,
        ) = inputs
    else:
        raise InvalidCell("relation-member interaction wiring is invalid")
    projection = _interaction_canvas_at_revision(
        store, registry, context, expected_revision, projected_canvas
    )
    projected_interfaces = projection.get("selected_interfaces")
    if not isinstance(projected_interfaces, list):
        raise InvalidCell("relation-member interaction projection is incomplete")
    candidates = tuple(
        interface for interface in projected_interfaces
        if isinstance(interface, Mapping)
        and interface.get("owner") == owner_root
        and interface.get("id") == interface_root
        and interface.get("target") == target_root
        and interface.get("editable") is True
        and interface.get("mode") in {"collection", "relation-role"}
    )
    if len(candidates) != 1 or interaction.target_root != target_root:
        raise InvalidCell("relation-member interaction target drifted")
    interface = candidates[0]
    protocol, specifications = ensure_universal_event_fact_authority(
        store, registry
    )
    submitted_spec = specifications["submitted_value"]
    participant_spec = specifications["participant_index"]
    mode = str(interface["mode"])
    operation_by_root = {
        root: name for name, root in _RELATION_MEMBER_OPERATION_ROOTS.items()
    }
    append_operation = _RELATION_MEMBER_OPERATION_ROOTS["append"]
    if len(inputs) == 5 and fourth_root == append_operation:
        expected_spec = (
            submitted_spec if mode == "collection" else participant_spec
        )
        if (
            fifth_root != expected_spec.root_id
            or interface.get("append_control") != control_root
            or interface.get("append_event_fact_input") != fifth_root
            or control_root != _relation_member_control_root(
                admission.interaction.subject_root,
                interface_root,
                append_operation,
            )
        ):
            raise InvalidCell("relation-member append wiring is invalid")
        values = validate_event_fact_values(
            store.snapshot(),
            protocol,
            (expected_spec.root_id,),
            event_facts,
        )
        if mode == "collection":
            value = values["submitted_value"]
            if type(value) is not str:
                raise InvalidCell("collection append value is not text")
        else:
            raw_index = values["participant_index"]
            choices = interface.get("choices")
            if (
                type(raw_index) not in (int, float)
                or int(raw_index) != raw_index
                or not isinstance(choices, list)
                or int(raw_index) < 0
                or int(raw_index) >= len(choices)
            ):
                raise InvalidCell(
                    "relation-member participant index is invalid"
                )
            value = str(choices[int(raw_index)]["id"])
        revision = edit_universal_interface_collection(
            store,
            registry,
            owner_root,
            interface_root,
            "append",
            value=value,
            mutation_route="/api/universal/interaction",
            authentication_context=context,
        )
        operation_root = append_operation
    elif len(inputs) == 6:
        incidence_root = fourth_root
        operation_root = fifth_root
        if (
            mode != "relation-role"
            or operation_root
            != _RELATION_MEMBER_OPERATION_ROOTS["replace"]
            or sixth_root != participant_spec.root_id
        ):
            raise InvalidCell("relation-member replace wiring is invalid")
        items = interface.get("items")
        if not isinstance(items, list):
            raise InvalidCell("relation-member item projection is invalid")
        candidates = tuple(
            item for item in items
            if isinstance(item, Mapping)
            and item.get("incidence") == incidence_root
            and item.get("replace_control") == control_root
            and item.get("replace_event_fact_input") == sixth_root
        )
        if len(candidates) != 1 or control_root != _relation_member_control_root(
            interaction.subject_root, incidence_root, operation_root
        ):
            raise InvalidCell("relation-member replace control drifted")
        values = validate_event_fact_values(
            store.snapshot(),
            protocol,
            (participant_spec.root_id,),
            event_facts,
        )
        raw_index = values["participant_index"]
        choices = interface.get("choices")
        if (
            type(raw_index) not in (int, float)
            or int(raw_index) != raw_index
            or not isinstance(choices, list)
            or int(raw_index) < 0
            or int(raw_index) >= len(choices)
        ):
            raise InvalidCell("relation-member participant index is invalid")
        revision = edit_universal_interface_collection(
            store,
            registry,
            owner_root,
            interface_root,
            "edit",
            incidence_id=incidence_root,
            value=str(choices[int(raw_index)]["id"]),
            mutation_route="/api/universal/interaction",
            authentication_context=context,
        )
    else:
        incidence_root = fourth_root
        operation_root = fifth_root
        operation = operation_by_root.get(operation_root)
        admitted = (
            {"remove", "move-up", "move-down"}
            if mode == "collection" else {"remove"}
        )
        if operation not in admitted:
            raise InvalidCell("relation-member operation is not admitted")
        if event_facts not in (None, []):
            raise InvalidCell(
                "relation-member action carries undeclared event facts"
            )
        items = interface.get("items")
        if not isinstance(items, list):
            raise InvalidCell("relation-member item projection is invalid")
        indexes = [
            index for index, item in enumerate(items)
            if isinstance(item, Mapping)
            and item.get("incidence") == incidence_root
            and item.get({
                "remove": "remove_control",
                "move-up": "up_control",
                "move-down": "down_control",
            }[operation]) == control_root
        ]
        if len(indexes) != 1 or control_root != _relation_member_control_root(
            admission.interaction.subject_root,
            incidence_root,
            operation_root,
        ):
            raise InvalidCell("relation-member item control drifted")
        index = indexes[0]
        if operation == "remove":
            revision = edit_universal_interface_collection(
                store,
                registry,
                owner_root,
                interface_root,
                "remove",
                incidence_id=incidence_root,
                mutation_route="/api/universal/interaction",
                authentication_context=context,
            )
        else:
            swap = index - 1 if operation == "move-up" else index + 1
            if swap < 0 or swap >= len(items):
                raise InvalidCell("relation-member move is outside the list")
            order = [str(item["incidence"]) for item in items]
            order[index], order[swap] = order[swap], order[index]
            revision = edit_universal_interface_collection(
                store,
                registry,
                owner_root,
                interface_root,
                "reorder",
                incidence_order=tuple(order),
                mutation_route="/api/universal/interaction",
                authentication_context=context,
            )
    if revision != store.revision:
        raise InvalidCell("relation-member interaction revision drifted")
    return UniversalControlExecution(
        operation_root,
        control_root,
        CAPABILITY_RELATION_MEMBERS,
        revision,
    )


def _bounded_projected_choice(
    choices: object,
    raw_index: object,
    *,
    label: str,
) -> Mapping[str, object]:
    if (
        type(raw_index) not in (int, float)
        or int(raw_index) != raw_index
        or not isinstance(choices, list)
        or int(raw_index) < 0
        or int(raw_index) >= len(choices)
    ):
        raise InvalidCell("%s index is invalid" % label)
    choice = choices[int(raw_index)]
    if not isinstance(choice, Mapping):
        raise InvalidCell("%s is invalid" % label)
    return choice


def submit_universal_topology_interaction(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    projection_broker: InteractionProjectionBroker,
    projection_handle: object,
    *,
    interaction_root: str,
    control_root: str,
    event_root: str,
    event_facts: object | None,
    expected_revision: int,
    projected_canvas: Mapping[str, object] | None = None,
    authentication_context: object | None = None,
) -> UniversalControlExecution:
    """Execute one graph-issued topology operation against its current candidates."""
    context = _active_authentication_context(
        registry.authorization, authentication_context
    )
    admission = admit_interaction(
        store,
        registry.interaction_protocol,
        registry.transaction_protocol,
        registry.rule_protocol,
        registry.authorization.protocol,
        registry.authorization.broker,
        context,
        projection_broker,
        projection_handle,
        interaction_root=interaction_root,
        control_root=control_root,
        event_root=event_root,
        expected_revision=expected_revision,
        admitted_nontransaction_action_roots=(CAPABILITY_TOPOLOGY,),
        budget=100_000,
    )
    interaction = admission.interaction
    if interaction.action_root != CAPABILITY_TOPOLOGY:
        raise InvalidCell("topology interaction authority is invalid")
    inputs = interaction.input_roots
    if not inputs:
        raise InvalidCell("topology interaction wiring is invalid")
    operation_by_root = {
        root: name for name, root in _TOPOLOGY_OPERATION_ROOTS.items()
    }
    operation_root = inputs[0]
    operation = operation_by_root.get(operation_root)
    if operation is None:
        raise InvalidCell("topology interaction operation is not admitted")
    projection = _interaction_canvas_at_revision(
        store, registry, context, expected_revision, projected_canvas
    )
    protocol, specifications = ensure_universal_event_fact_authority(
        store, registry
    )
    candidate_spec = specifications["topology_candidate_index"]
    created_root = None

    if operation == "connect":
        if len(inputs) != 4 or inputs[3] != candidate_spec.root_id:
            raise InvalidCell("topology connect wiring is invalid")
        _operation, source_root, source_interface, _fact = inputs
        candidates = tuple(
            port
            for node in projection.get("nodes", ())
            if isinstance(node, Mapping) and node.get("id") == source_root
            for port in node.get("ports", ())
            if isinstance(port, Mapping)
            and port.get("id") == source_interface
            and port.get("connect_control") == control_root
        )
        if (
            len(candidates) != 1
            or interaction.target_root != registry.canvas_root
        ):
            raise InvalidCell("topology connect control is not projected")
        choices = candidates[0].get("connect_choices")
        values = validate_event_fact_values(
            store.snapshot(),
            protocol,
            (candidate_spec.root_id,),
            event_facts,
        )
        choice = _bounded_projected_choice(
            choices, values["topology_candidate_index"],
            label="topology connect candidate",
        )
        created_root, revision = connect_universal_roots(
            store,
            registry,
            source_root,
            str(choice["owner"]),
            source_interface=source_interface,
            target_interface=str(choice["id"]),
            mutation_route="/api/universal/interaction",
            authentication_context=context,
            leased_projection=projection,
        )
    elif operation == "disconnect":
        if len(inputs) != 2 or event_facts not in (None, []):
            raise InvalidCell("topology disconnect wiring is invalid")
        relation_root = inputs[1]
        candidates = tuple(
            wire for wire in projection.get("wires", ())
            if isinstance(wire, Mapping)
            and wire.get("id") == relation_root
            and wire.get("nary") is False
            and wire.get("disconnect_control") == control_root
        )
        if len(candidates) != 1 or interaction.target_root != relation_root:
            raise InvalidCell("topology disconnect control is not projected")
        revision = disconnect_universal_connection(
            store,
            registry,
            relation_root,
            mutation_route="/api/universal/interaction",
            authentication_context=context,
        )
    else:
        if len(inputs) != 4 or inputs[3] != candidate_spec.root_id:
            raise InvalidCell("topology rewire wiring is invalid")
        _operation, relation_root, incidence_root, _fact = inputs
        matches = []
        for wire in projection.get("wires", ()):
            if (
                not isinstance(wire, Mapping)
                or wire.get("id") != relation_root
                or wire.get("nary") is not False
            ):
                continue
            for side in ("source", "target"):
                if (
                    wire.get(side + "_incidence") == incidence_root
                    and wire.get(side + "_rewire_control") == control_root
                ):
                    matches.append((wire, side))
        if len(matches) != 1 or interaction.target_root != relation_root:
            raise InvalidCell("topology rewire control is not projected")
        wire, side = matches[0]
        values = validate_event_fact_values(
            store.snapshot(),
            protocol,
            (candidate_spec.root_id,),
            event_facts,
        )
        choice = _bounded_projected_choice(
            wire.get(side + "_rewire_choices"),
            values["topology_candidate_index"],
            label="topology rewire candidate",
        )
        revision = rewire_universal_connection(
            store,
            registry,
            incidence_root,
            str(choice["id"]),
            mutation_route="/api/universal/interaction",
            authentication_context=context,
        )
    if revision != store.revision:
        raise InvalidCell("topology interaction revision drifted")
    return UniversalControlExecution(
        operation_root,
        control_root,
        CAPABILITY_TOPOLOGY,
        revision,
        created_root,
    )


def submit_universal_instantiation_interaction(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    projection_broker: InteractionProjectionBroker,
    projection_handle: object,
    *,
    interaction_root: str,
    control_root: str,
    event_root: str,
    event_facts: object,
    expected_revision: int,
    viewport: Mapping[str, float] | None = None,
    projected_canvas: Mapping[str, object] | None = None,
    authentication_context: object | None = None,
) -> tuple[str, int]:
    """Create one graph-selected catalogue assembly from bounded point facts."""
    context = _active_authentication_context(
        registry.authorization, authentication_context
    )
    admission = admit_interaction(
        store,
        registry.interaction_protocol,
        registry.transaction_protocol,
        registry.rule_protocol,
        registry.authorization.protocol,
        registry.authorization.broker,
        context,
        projection_broker,
        projection_handle,
        interaction_root=interaction_root,
        control_root=control_root,
        event_root=event_root,
        expected_revision=expected_revision,
        admitted_nontransaction_action_roots=(CAPABILITY_INSTANTIATE,),
        budget=100_000,
    )
    interaction = admission.interaction
    projected = _interaction_canvas_at_revision(
        store, registry, context, expected_revision, projected_canvas
    )
    projected_scope = projected.get("scope")
    if not isinstance(projected_scope, Mapping):
        raise InvalidCell("instantiation projection scope is missing")
    scope_root = projected_scope.get("current")
    if type(scope_root) is not str or not scope_root:
        raise InvalidCell("instantiation projection scope is invalid")
    if (
        interaction.action_root != CAPABILITY_INSTANTIATE
        or interaction.target_root != scope_root
        or interaction.control_root != control_root
        or len(interaction.input_roots) != 6
        or interaction.input_roots[0] != control_root
    ):
        raise InvalidCell("instantiation interaction authority is invalid")
    definition_root = interaction.input_roots[0]
    candidates = tuple(
        item for item in projected.get("catalog", ())
        if isinstance(item, Mapping)
        and item.get("id") == definition_root
        and item.get("composition_contract") is None
    )
    primitive = projected.get("primitive")
    is_visible_primitive = (
        isinstance(primitive, Mapping)
        and primitive.get("visible") is True
        and primitive.get("id") == definition_root
    )
    library_members = read_relation(
        store.snapshot(), registry.library_root, budget=100_000
    )
    is_library_seed = any(
        member.role_id == registry.roles["seed"]
        and member.participant_id == definition_root
        for member in library_members
    )
    if is_visible_primitive != is_library_seed:
        raise InvalidCell("primitive instantiation graph authority drifted")
    if len(candidates) + int(is_visible_primitive) != 1:
        raise InvalidCell(
            "instantiation interaction control has no unique library authority"
        )
    protocol, specifications = ensure_universal_event_fact_authority(
        store, registry
    )
    expected_specs = tuple(
        specifications[key].root_id for key in _CANVAS_POINT_FACT_KEYS
    )
    if interaction.input_roots[1:] != expected_specs:
        raise InvalidCell("instantiation interaction input contract drifted")
    values = validate_event_fact_values(
        store.snapshot(), protocol, expected_specs, event_facts
    )
    viewport_keys = {"pan_x", "pan_y", "zoom"}
    supplied_viewport_keys = viewport_keys.intersection(values)
    if supplied_viewport_keys and supplied_viewport_keys != viewport_keys:
        raise InvalidCell("instantiation viewport facts must be complete")
    event_viewport = (
        {key: values[key] for key in ("pan_x", "pan_y", "zoom")}
        if supplied_viewport_keys else None
    )
    if viewport is not None:
        raise InvalidCell("instantiation viewport must come from event facts")
    if is_visible_primitive:
        label = primitive.get("label")
        if type(label) is not str or not label.strip():
            raise InvalidCell("primitive instantiation label is invalid")
        return instantiate_universal_primitive(
            store,
            registry,
            x=values["x"],
            y=values["y"],
            title=label,
            atom="",
            viewport=event_viewport,
            mutation_route="/api/universal/interaction",
            authentication_context=context,
            leased_scope_root=scope_root,
        )
    return instantiate_universal_definition(
        store,
        registry,
        definition_root,
        x=values["x"],
        y=values["y"],
        viewport=event_viewport,
        mutation_route="/api/universal/interaction",
        authentication_context=context,
        leased_scope_root=scope_root,
    )


def edit_universal_cell_atom(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    root_id: str,
    atom: bytes,
    *,
    authentication_context: object | None = None,
) -> int:
    """Raw floor editing is not part of the normal composer authority."""
    _authorize(
        store.snapshot(),
        registry,
        "floor.edit",
        object_root=root_id,
        authentication_context=authentication_context,
    )
    raise InvalidCell("raw floor editing is unavailable")


def move_universal_root(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    root_id: str,
    x: float,
    y: float,
    *,
    authentication_context: object | None = None,
) -> int:
    snapshot = store.dense_snapshot()
    view_session, context = _view_session_for_context(
        registry, authentication_context
    )
    _authorize(
        snapshot,
        registry,
        "canvas.arrange",
        object_root=root_id,
        authentication_context=context,
    )
    visible_roots, _, property_roots = _session_canvas_roots(
        snapshot, registry, view_session
    )
    if root_id not in visible_roots:
        raise InvalidCell("canvas root has no wired position properties")
    rows = _rows_by_label(
        snapshot,
        _property_index(snapshot, registry, property_roots).get(root_id, ()),
    )
    if "position_x" not in rows or "position_y" not in rows:
        raise InvalidCell("canvas root has no wired position properties")
    replacements = []
    for name, value in (("position_x", x), ("position_y", y)):
        root = rows[name].value_root
        current = snapshot.cells[root]
        replacements.append(Cell(current.id, current.link0, current.link1, _atom(value)))
    return _commit_universal_user_change(
        store,
        registry,
        view_session,
        context,
        snapshot,
        route="/api/universal/move",
        command_name="canvas.arrange",
        authorization_scope_root=root_id,
        replace=replacements,
    )


def set_universal_viewport(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    *,
    pan_x: float,
    pan_y: float,
    zoom: float,
    authentication_context: object | None = None,
) -> int:
    return apply_universal_canvas_gesture(
        store,
        registry,
        viewport={"pan_x": pan_x, "pan_y": pan_y, "zoom": zoom},
        authentication_context=authentication_context,
    )


def _authorize_universal_compensation(
    snapshot: Snapshot,
    registry: UniversalApplicationRegistry,
    view_session: ApplicationViewSession,
    context: object,
    *,
    direction: str,
) -> None:
    """Re-evaluate the original graph-held capability before compensation."""
    state = history_state(
        snapshot,
        registry.change_history_protocol,
        view_session.action_history_root,
    )
    if direction == "undo":
        original_root = state.undo_root
    elif direction == "redo":
        original_root = state.redo_root
    else:
        raise InvalidCell("unknown compensation direction")
    if original_root is None:
        raise Conflict("nothing to %s" % direction)
    original = read_change_transaction(
        snapshot, registry.change_history_protocol, original_root
    )
    actor_root = registry.authorization.broker.resolve(context).subject_root
    if (
        original.actor_root != actor_root
        or original.session_root != view_session.root_id
    ):
        raise Conflict("change belongs to another actor or view session")
    if original.authority_root is None or not original.scope_roots:
        raise Conflict("change lacks compensation authority evidence")
    command_name = next((
        name for name, root in registry.composer_protocol.commands.items()
        if root == original.authority_root
    ), None)
    if command_name is None:
        raise InvalidCell("change compensation authority is not recognized")
    for scope_root in original.scope_roots:
        _authorize(
            snapshot,
            registry,
            command_name,
            object_root=scope_root,
            interface_root=original.interface_root,
            authentication_context=context,
        )


def undo_universal_change(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    *,
    authentication_context: object | None = None,
) -> int:
    """Append a conflict-safe compensation for this view's latest edit."""
    snapshot = store.snapshot()
    view_session, context = _view_session_for_context(
        registry, authentication_context
    )
    _authorize_universal_compensation(
        snapshot, registry, view_session, context, direction="undo"
    )
    operation_root = _HISTORY_OPERATION_ROOTS["undo"]
    if operation_root not in snapshot.cells:
        raise InvalidCell("undo control binding has no graph authority")
    actor_root = registry.authorization.broker.resolve(context).subject_root
    return undo_last_change(
        store,
        registry.change_history_protocol,
        history_root=view_session.action_history_root,
        actor_root=actor_root,
        session_root=view_session.root_id,
        operation_root=operation_root,
    ).revision


def redo_universal_change(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    *,
    authentication_context: object | None = None,
) -> int:
    """Append a conflict-safe reapplication for this view's latest undo."""
    snapshot = store.snapshot()
    view_session, context = _view_session_for_context(
        registry, authentication_context
    )
    _authorize_universal_compensation(
        snapshot, registry, view_session, context, direction="redo"
    )
    operation_root = _HISTORY_OPERATION_ROOTS["redo"]
    if operation_root not in snapshot.cells:
        raise InvalidCell("redo control binding has no graph authority")
    actor_root = registry.authorization.broker.resolve(context).subject_root
    return redo_last_change(
        store,
        registry.change_history_protocol,
        history_root=view_session.action_history_root,
        actor_root=actor_root,
        session_root=view_session.root_id,
        operation_root=operation_root,
    ).revision


def execute_universal_control(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    binding_root: str,
    *,
    expected_revision: int,
    projected_canvas: Mapping[str, object] | None = None,
    authentication_context: object | None = None,
) -> UniversalControlExecution:
    """Execute one applicable semantic toolbar binding from graph authority."""
    snapshot = store.snapshot()
    if snapshot.revision != expected_revision:
        raise Conflict(
            "expected revision %s, current revision is %s"
            % (expected_revision, snapshot.revision)
        )
    context = _active_authentication_context(
        registry.authorization, authentication_context
    )
    projection = _interaction_canvas_at_revision(
        store, registry, context, expected_revision, projected_canvas
    )
    controls = projection["configuration"]["design_system"][
        "control_catalog"
    ]["controls"]
    candidates = tuple(
        control for control in controls
        if control["activation"]["binding"] == binding_root
    )
    if len(candidates) != 1:
        raise InvalidCell("control binding is outside the projected catalogue")
    control = candidates[0]
    if control["zone"] != "canvas-toolbar":
        raise InvalidCell("control binding is outside the canvas toolbar")
    if not control["applicable"]:
        raise InvalidCell("control binding is not currently applicable")

    activation = control["activation"]
    capability_root = activation["capability"]
    arguments = dict(activation["arguments"])
    created_root = None
    if capability_root == CAPABILITY_COMPOSITION:
        operation = arguments.get("operation")
        if arguments != {"operation": operation}:
            raise InvalidCell("composition control arguments are not admitted")
        if operation == "group":
            created_root, revision = group_universal_selection(
                store,
                registry,
                projected_canvas=projection,
                authentication_context=authentication_context,
            )
        elif operation == "ungroup":
            revision = ungroup_universal_composition(
                store,
                registry,
                str(projection["selected"]),
                projected_canvas=projection,
                authentication_context=authentication_context,
            )
        else:
            raise InvalidCell("composition control operation is not admitted")
    elif capability_root == CAPABILITY_HISTORY:
        operation = arguments.get("operation")
        if arguments != {"operation": operation}:
            raise InvalidCell("history control arguments are not admitted")
        if operation == "undo":
            revision = undo_universal_change(
                store,
                registry,
                authentication_context=authentication_context,
            )
        elif operation == "redo":
            revision = redo_universal_change(
                store,
                registry,
                authentication_context=authentication_context,
            )
        else:
            raise InvalidCell("history control operation is not admitted")
    else:
        raise InvalidCell(
            "control capability is not an admitted semantic toolbar operation"
        )
    return UniversalControlExecution(
        binding_root,
        str(control["owner"]),
        str(capability_root),
        revision,
        created_root,
    )


@_with_canvas_interface_projection_scope
@with_relation_projection_scope
@with_catalog_verification_scope
def apply_universal_canvas_gesture(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    *,
    roots: tuple[str, ...] | list[str] | None = None,
    focus_root: str | None = None,
    positions: Mapping[str, Mapping[str, float]] | None = None,
    viewport: Mapping[str, float] | None = None,
    consent_evidence_root: str | None = None,
    authentication_context: object | None = None,
    leased_projection: Mapping[str, object] | None = None,
) -> int:
    """Publish one complete local canvas gesture in one Store revision."""
    snapshot = store.dense_snapshot()
    verify_released_catalog_stable(
        store,
        snapshot,
        registry.assembly_protocol,
        registry.standard_library.catalog_root,
    )
    authority = registry.authorization
    authority_snapshot = verify_relationship_authority_snapshot(
        snapshot,
        authority.identity_protocol,
        authority.relationship_broker,
        now=time.time(),
    )
    view_session, context = _view_session_for_context(
        registry, authentication_context
    )
    is_shared_edit = bool(positions)
    _authorize(
        snapshot,
        registry,
        "canvas.arrange" if is_shared_edit else "canvas.select",
        object_root=(registry.canvas_root if is_shared_edit
                     else view_session.root_id),
        authentication_context=context,
        resource_lineage_roots=(
            () if is_shared_edit else (
                registry.authorization.personal_view_scope_root,
            )
        ),
        authority_snapshot=authority_snapshot,
    )
    replacements: dict[str, Cell] = {}

    if roots is not None:
        ordered = tuple(dict.fromkeys(roots))
        if leased_projection is None:
            (
                visible_roots,
                relation_roots,
                _property_roots,
                scope_trail,
            ) = _session_canvas_roots(
                snapshot,
                registry,
                view_session,
                authority_snapshot=authority_snapshot,
                include_trail=True,
            )
        else:
            raw_nodes = leased_projection.get("nodes")
            raw_wires = leased_projection.get("wires")
            raw_scope = leased_projection.get("scope")
            raw_authorization = leased_projection.get("authorization")
            if (
                leased_projection.get("revision") != snapshot.revision
                or leased_projection.get("application_root")
                != registry.application_root
                or leased_projection.get("canvas_root") != registry.canvas_root
                or type(raw_nodes) is not list
                or type(raw_wires) is not list
                or not isinstance(raw_scope, Mapping)
                or not isinstance(raw_authorization, Mapping)
                or raw_authorization.get("subject")
                != view_session.subject_root
            ):
                raise InvalidCell(
                    "canvas gesture projection is not the exact view revision"
                )
            raw_trail = raw_scope.get("trail")
            if (
                type(raw_trail) is not list
                or any(
                    not isinstance(item, Mapping)
                    or type(item.get("root")) is not str
                    for item in raw_trail
                )
            ):
                raise InvalidCell("canvas gesture scope projection is invalid")
            scope_trail = tuple(item["root"] for item in raw_trail)
            if (
                scope_trail
                != _read_view_scope_trail_structure(
                    snapshot, registry, view_session
                )
                or raw_scope.get("current") != scope_trail[-1]
            ):
                raise InvalidCell("canvas gesture scope projection drifted")
            visible_roots = tuple(
                str(node["id"])
                for node in raw_nodes
                if isinstance(node, Mapping)
                and type(node.get("id")) is str
            )
            relation_roots = tuple(dict.fromkeys(
                str(wire["id"])
                for wire in raw_wires
                if isinstance(wire, Mapping)
                and type(wire.get("id")) is str
            ))
            if (
                len(visible_roots) != len(raw_nodes)
                or len(visible_roots) != len(set(visible_roots))
            ):
                raise InvalidCell(
                    "canvas gesture projection has invalid visible roots"
                )
        visible = set(visible_roots)
        if any(root_id not in visible for root_id in ordered):
            raise InvalidCell("canvas gesture selects a root outside the active lens")
        if focus_root is None:
            if ordered:
                focus_root = ordered[-1]
            else:
                focus_pointer_root = _one_for_role(
                    read_relation(snapshot, view_session.properties_lens_root),
                    registry.roles["focus"],
                )
                focus_root = read_focus(
                    snapshot,
                    registry.attention_protocol,
                    focus_pointer_root,
                ).primary_root
        if focus_root not in visible:
            exposed_relation_roots = _relation_backed_canvas_roots(
                snapshot, registry, visible_roots
            )
            visible_interface_roots = _visible_canvas_interface_roots(
                snapshot, registry, visible_roots
            )
            definitions = {
                item["id"] for item in _project_standard_catalog(
                    store, snapshot, registry
                )
            }
            identity = registry.authorization.broker.resolve(context)
            authority_focus_roots = set(
                _inspectable_authority_relationship_roots(
                    snapshot,
                    registry,
                    identity.subject_root,
                    authority_snapshot=authority_snapshot,
                )
            )
            browser_session_focus_roots = set(
                _inspectable_browser_session_roots(
                    snapshot, registry, identity.subject_root
                )
            )
            view_focus_roots = set(_inspectable_view_focus_roots(
                snapshot, registry, view_session
            ))
            focus_pointer_root = _one_for_role(
                read_relation(snapshot, view_session.properties_lens_root),
                registry.roles["focus"],
            )
            current_focus_root = read_focus(
                snapshot,
                registry.attention_protocol,
                focus_pointer_root,
            ).primary_root
            direct_founder_navigation = (
                identity.subject_root == registry.authorization.subject_root
                and _is_direct_relation_participant(
                    snapshot, current_focus_root, focus_root
                )
            )
            if (focus_root not in relation_roots
                    and focus_root not in exposed_relation_roots
                    and focus_root not in visible_interface_roots
                    and focus_root not in definitions
                    and focus_root not in authority_focus_roots
                    and focus_root not in browser_session_focus_roots
                    and focus_root not in view_focus_roots
                    and not (
                        identity.subject_root
                        == registry.authorization.subject_root
                        and focus_root in registry.core_value_obligation_roots
                    )
                    and not direct_founder_navigation
                    and focus_root not in (
                        registry.primitive_root,
                        view_session.settings_root,
                        view_session.root_id,
                    )):
                raise InvalidCell(
                    "canvas gesture focus is outside the active lens"
                )
        selection_transition = _prepare_selection_transition(
            snapshot,
            registry,
            view_session,
            ordered,
            focus_root,
            consent_evidence_root=consent_evidence_root,
            scope_root=scope_trail[-1],
        )
        replacements.update({
            cell.id: cell for cell in selection_transition.replace
        })
    else:
        selection_transition = _PreparedSelectionTransition("", (), ())

    if positions:
        _, _, property_roots = _session_canvas_roots(
            snapshot,
            registry,
            view_session,
            authority_snapshot=authority_snapshot,
        )
        property_index = _property_index(snapshot, registry, property_roots)
        for root_id, point in positions.items():
            position_rows = _rows_by_label(
                snapshot, property_index.get(root_id, ())
            )
            if (
                "position_x" not in position_rows
                or "position_y" not in position_rows
            ):
                raise InvalidCell(
                    "canvas gesture moves a root without position wires"
                )
            for name, key in (("position_x", "x"), ("position_y", "y")):
                value = float(point[key])
                if not math.isfinite(value):
                    raise InvalidCell("canvas position must be finite")
                value_root = position_rows[name].value_root
                current = snapshot.cells[value_root]
                replacements[value_root] = Cell(
                    current.id, current.link0, current.link1, _atom(value)
                )

    if viewport is not None:
        values = {
            "pan_x": float(viewport["pan_x"]),
            "pan_y": float(viewport["pan_y"]),
            "zoom": float(viewport["zoom"]),
        }
        if not all(math.isfinite(value) for value in values.values()):
            raise InvalidCell("canvas viewport values must be finite")
        if not 0.1 <= values["zoom"] <= 4.0:
            raise InvalidCell("canvas zoom is outside the supported range")
        for name, value in values.items():
            value_root = view_session.viewport_properties[name].value_root
            current = snapshot.cells[value_root]
            replacements[value_root] = Cell(
                current.id, current.link0, current.link1, _atom(value)
            )

    if not replacements and not selection_transition.create:
        return snapshot.revision
    if positions:
        return _commit_universal_user_change(
            store,
            registry,
            view_session,
            context,
            snapshot,
            route="/api/universal/gesture",
            command_name="canvas.arrange",
            authorization_scope_root=registry.canvas_root,
            create=selection_transition.create,
            replace=replacements.values(),
        )
    return store.commit(
        snapshot.revision,
        create=selection_transition.create,
        replace=replacements.values(),
    )


def rewire_universal_connection(
    store: CellStore,
    registry: UniversalApplicationRegistry,
    incidence_id: str,
    participant_id: str,
    *,
    mutation_route: str = "/api/universal/interaction",
    authentication_context: object | None = None,
) -> int:
    if type(mutation_route) is not str or not mutation_route.startswith("/"):
        raise InvalidCell("connection mutation route must be an absolute path")
    snapshot = store.dense_snapshot()
    view_session, context = _view_session_for_context(
        registry, authentication_context
    )
    _authorize(
        snapshot,
        registry,
        "catalog.connect",
        object_root=incidence_id,
        authentication_context=authentication_context,
    )
    if participant_id not in snapshot.cells:
        raise InvalidCell("connection participant is missing")
    visible_roots, relation_roots, _ = _session_canvas_roots(
        snapshot, registry, view_session
    )
    members_by_incidence = {
        member.incidence_id: (relation_root, member)
        for relation_root in relation_roots
        for member in read_relation(snapshot, relation_root, budget=256)
    }
    matched = members_by_incidence.get(incidence_id)
    if matched is None:
        raise InvalidCell("connection is outside the active canvas lens")
    relation_root, member = matched
    if member.role_id not in (registry.roles["source"], registry.roles["target"]):
        raise InvalidCell("only relation endpoints may be rewired")
    side = "source" if member.role_id == registry.roles["source"] else "target"
    previous_owner, previous_interface = _canvas_endpoint(
        snapshot, registry, member, visible_roots
    )
    if previous_owner not in visible_roots or previous_interface is None:
        raise InvalidCell("existing connection endpoint is not a visible interface")
    normalized = participant_id
    if participant_id in visible_roots:
        registered = tuple(
            interface for interface in _registered_canvas_interfaces(
                snapshot, registry
            )
            if interface["owner"] == participant_id
            and interface["side"] == side
        )
        if len(registered) == 1:
            normalized = str(registered[0]["id"])
        elif len(registered) > 1:
            raise InvalidCell(
                "%s node requires one selected %s interface"
                % (side, side)
            )
        elif side == "target":
            assembly = _instance_projection(snapshot, registry, participant_id)
            interfaces = [
                interface for interface in (assembly or {}).get("interfaces", [])
                if interface["mode"] == "connection"
            ]
            if len(interfaces) != 1:
                raise InvalidCell(
                    "target node requires one selected connection interface"
                )
            normalized = interfaces[0]["id"]
        else:
            raise InvalidCell("source node has no declared source interface")
    if _is_derived_composition_interface(snapshot, registry, normalized):
        raise InvalidCell(
            "derived composition boundaries cannot be rewired directly"
        )

    candidate = member.__class__(
        member.incidence_id, member.role_id, normalized
    )
    owner, interface = _canvas_endpoint(
        snapshot, registry, candidate, visible_roots
    )
    if owner not in visible_roots or interface is None:
        raise InvalidCell("connection endpoint is not a declared visible interface")
    relation_members = read_relation(snapshot, relation_root, budget=256)
    other_role = (
        registry.roles["target"]
        if side == "source" else registry.roles["source"]
    )
    other_members = tuple(
        item for item in relation_members if item.role_id == other_role
    )
    if len(other_members) != 1:
        raise InvalidCell("connection has an invalid opposite endpoint")
    other_owner, other_interface = _canvas_endpoint(
        snapshot, registry, other_members[0], visible_roots
    )
    if other_owner not in visible_roots or other_interface is None:
        raise InvalidCell("opposite connection endpoint is not a visible interface")
    candidate_contract = _interface_contract_root(
        snapshot, registry.assembly_protocol, normalized
    )
    other_contract = _interface_contract_root(
        snapshot,
        registry.assembly_protocol,
        other_members[0].participant_id,
    )
    source_contract, target_contract = (
        (candidate_contract, other_contract)
        if side == "source" else (other_contract, candidate_contract)
    )
    if not _interface_contracts_compatible(
        registry.assembly_protocol, source_contract, target_contract
    ):
        raise InvalidCell("connection interface contracts are incompatible")
    if normalized == member.participant_id:
        return snapshot.revision

    create: list[Cell] = []
    replacements: dict[str, Cell] = {
        incidence_id: Cell(
            incidence_id,
            member.role_id,
            normalized,
            snapshot.cells[incidence_id].atom,
        )
    }
    if _is_domain_public_interface(
        snapshot, registry.assembly_protocol, member.participant_id
    ):
        previous_members = read_relation(
            snapshot, member.participant_id, budget=100_000
        )
        detach_ids = tuple(
            item.incidence_id for item in previous_members
            if (
                item.role_id == registry.roles["seed"]
                and item.participant_id == relation_root
            ) or (
                item.role_id == registry.roles["authority"]
                and item.participant_id == incidence_id
            )
        )
        if len(detach_ids) != 2:
            raise InvalidCell("public interface membership is inconsistent")
        removal = prepare_remove_relation_members(
            snapshot,
            member.participant_id,
            detach_ids,
            budget=100_000,
        )
        for cell in removal.replace:
            replacements[cell.id] = cell
    if _is_domain_public_interface(
        snapshot, registry.assembly_protocol, normalized
    ):
        next_members = read_relation(snapshot, normalized, budget=100_000)
        if any(
            item.role_id == registry.roles["seed"]
            and item.participant_id == relation_root
            for item in next_members
        ) or any(
            item.role_id == registry.roles["authority"]
            and item.participant_id == incidence_id
            for item in next_members
        ):
            raise InvalidCell("public interface already owns this incidence")
        addition = prepare_append_relation_members(
            snapshot,
            normalized,
            (
                (registry.roles["seed"], relation_root),
                (registry.roles["authority"], incidence_id),
            ),
            budget=100_000,
        )
        create.extend(addition.create)
        for cell in addition.replace:
            replacements[cell.id] = cell

    if side == "source":
        binding_incidence = _assembly_connection_binding_incidence(
            snapshot,
            registry,
            other_owner,
            other_members[0].participant_id,
        )
        if binding_incidence is not None:
            binding = snapshot.cells[binding_incidence]
            if binding.link1 != previous_owner:
                raise InvalidCell(
                    "connection input binding differs from its visible source"
                )
            replacements[binding_incidence] = Cell(
                binding.id, binding.link0, owner, binding.atom
            )
    else:
        previous_binding_incidence = _assembly_connection_binding_incidence(
            snapshot, registry, previous_owner, member.participant_id
        )
        next_binding_incidence = _assembly_connection_binding_incidence(
            snapshot, registry, owner, normalized
        )
        if previous_binding_incidence is not None:
            previous_binding = snapshot.cells[previous_binding_incidence]
            if previous_binding.link1 != other_owner:
                raise InvalidCell(
                    "connection input binding differs from its visible source"
                )
            original_binding = _connection_binding_before_creation(
                store, relation_root, previous_binding_incidence
            )
            replacements[previous_binding_incidence] = Cell(
                previous_binding.id,
                previous_binding.link0,
                original_binding.link1,
                previous_binding.atom,
            )
        if next_binding_incidence is not None:
            if any(
                relation_id != relation_root
                and any(
                    endpoint.role_id == registry.roles["target"]
                    and endpoint.participant_id == normalized
                    for endpoint in read_relation(
                        snapshot, relation_id, budget=256
                    )
                )
                for relation_id in relation_roots
            ):
                raise InvalidCell("target interface already has a connection")
            next_binding = snapshot.cells[next_binding_incidence]
            replacements[next_binding_incidence] = Cell(
                next_binding.id,
                next_binding.link0,
                other_owner,
                next_binding.atom,
            )
    return _commit_universal_user_change(
        store,
        registry,
        view_session,
        context,
        snapshot,
        route=mutation_route,
        command_name="catalog.connect",
        authorization_scope_root=incidence_id,
        create=create,
        replace=tuple(replacements.values()),
    )


